-- Supabase/Postgres schema starter for replacing Apps Script + Google Sheets
-- Run this in Supabase SQL Editor.

create extension if not exists pgcrypto;
create schema if not exists app;

create type app.warehouse as enum ('IL', 'MS');
create type app.box_status as enum ('ORDERED', 'IN_STOCK', 'CHECKED_OUT', 'ZEROED', 'RETIRED');
create type app.allocation_status as enum ('ACTIVE', 'FULFILLED', 'CANCELLED');
create type app.film_order_status as enum ('FILM_ORDER', 'FILM_ON_THE_WAY', 'FULFILLED', 'CANCELLED');
create type app.job_lifecycle_status as enum ('ACTIVE', 'CANCELLED');

create table if not exists app.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  created_at timestamptz not null default now()
);

create table if not exists app.organization_members (
  org_id uuid not null references app.organizations(id) on delete cascade,
  user_id uuid not null,
  role text not null check (role in ('owner', 'admin', 'member')),
  created_at timestamptz not null default now(),
  primary key (org_id, user_id)
);

create table if not exists app.film_catalog (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  film_key text not null,
  manufacturer text not null,
  film_name text not null,
  sq_ft_weight_lbs_per_sq_ft numeric(12,8),
  default_core_type text,
  source_width_in numeric(10,4),
  source_initial_feet integer,
  source_initial_weight_lbs numeric(12,2),
  source_box_id text,
  notes text not null default '',
  updated_at timestamptz not null default now(),
  unique (org_id, film_key)
);

create table if not exists app.boxes (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  box_id text not null,
  warehouse app.warehouse not null,
  manufacturer text not null,
  film_name text not null,
  width_in numeric(10,4) not null check (width_in > 0),
  initial_feet integer not null check (initial_feet >= 0),
  feet_available integer not null check (feet_available >= 0),
  lot_run text not null default '',
  status app.box_status not null,
  order_date date not null,
  received_date date,
  initial_weight_lbs numeric(12,2),
  last_roll_weight_lbs numeric(12,2),
  last_weighed_date date,
  film_key text not null,
  core_type text not null default '',
  core_weight_lbs numeric(12,4),
  lf_weight_lbs_per_ft numeric(12,6),
  purchase_cost numeric(12,2),
  notes text not null default '',
  has_ever_been_checked_out boolean not null default false,
  last_checkout_job text not null default '',
  last_checkout_date date,
  zeroed_date date,
  zeroed_reason text not null default '',
  zeroed_by text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (org_id, box_id),
  check (feet_available <= initial_feet)
);

create table if not exists app.jobs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  job_number text not null,
  warehouse app.warehouse not null,
  sections text,
  due_date date,
  lifecycle_status app.job_lifecycle_status not null default 'ACTIVE',
  notes text not null default '',
  created_at timestamptz not null default now(),
  created_by text not null default '',
  updated_at timestamptz not null default now(),
  updated_by text not null default '',
  unique (org_id, job_number)
);

create table if not exists app.job_requirements (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  job_id uuid not null references app.jobs(id) on delete cascade,
  manufacturer text not null,
  film_name text not null,
  width_in numeric(10,4) not null check (width_in > 0),
  required_feet integer not null check (required_feet > 0),
  notes text not null default '',
  created_at timestamptz not null default now(),
  created_by text not null default '',
  updated_at timestamptz not null default now(),
  updated_by text not null default ''
);

create table if not exists app.film_orders (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  film_order_id text not null,
  job_id uuid references app.jobs(id) on delete set null,
  job_number text not null,
  warehouse app.warehouse not null,
  manufacturer text not null,
  film_name text not null,
  width_in numeric(10,4) not null check (width_in > 0),
  requested_feet integer not null check (requested_feet >= 0),
  covered_feet integer not null default 0 check (covered_feet >= 0),
  ordered_feet integer not null default 0 check (ordered_feet >= 0),
  remaining_to_order_feet integer not null default 0 check (remaining_to_order_feet >= 0),
  job_date date,
  crew_leader text not null default '',
  status app.film_order_status not null,
  source_box_id text not null default '',
  resolved_at timestamptz,
  resolved_by text not null default '',
  notes text not null default '',
  created_at timestamptz not null default now(),
  created_by text not null default '',
  unique (org_id, film_order_id)
);

create table if not exists app.allocations (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  allocation_id text not null,
  box_id text not null,
  job_id uuid references app.jobs(id) on delete set null,
  job_number text not null,
  warehouse app.warehouse not null,
  job_date date,
  allocated_feet integer not null check (allocated_feet > 0),
  status app.allocation_status not null,
  created_at timestamptz not null default now(),
  created_by text not null default '',
  resolved_at timestamptz,
  resolved_by text not null default '',
  notes text not null default '',
  crew_leader text not null default '',
  film_order_id text not null default '',
  unique (org_id, allocation_id)
);

create table if not exists app.film_order_box_links (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  link_id text not null,
  film_order_id text not null,
  box_id text not null,
  ordered_feet integer not null check (ordered_feet >= 0),
  auto_allocated_feet integer not null default 0 check (auto_allocated_feet >= 0),
  created_at timestamptz not null default now(),
  created_by text not null default '',
  unique (org_id, link_id)
);

create table if not exists app.audit_log (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  log_id text not null,
  action text not null,
  box_id text not null,
  before_state jsonb,
  after_state jsonb,
  actor text not null,
  notes text not null default '',
  created_at timestamptz not null default now(),
  unique (org_id, log_id)
);

create table if not exists app.roll_weight_log (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  log_id text not null,
  box_id text not null,
  warehouse app.warehouse not null,
  manufacturer text not null,
  film_name text not null,
  width_in numeric(10,4) not null,
  job_number text not null default '',
  checked_out_at timestamptz,
  checked_out_by text not null default '',
  checked_out_weight_lbs numeric(12,2),
  checked_in_at timestamptz,
  checked_in_by text not null default '',
  checked_in_weight_lbs numeric(12,2),
  weight_delta_lbs numeric(12,2),
  feet_before integer not null default 0,
  feet_after integer not null default 0,
  notes text not null default '',
  unique (org_id, log_id)
);

create index if not exists idx_boxes_org_warehouse_status on app.boxes (org_id, warehouse, status);
create index if not exists idx_boxes_org_film on app.boxes (org_id, manufacturer, film_name, width_in);
create index if not exists idx_boxes_org_updated_at on app.boxes (org_id, updated_at desc);
create index if not exists idx_allocations_org_job_number on app.allocations (org_id, job_number);
create index if not exists idx_allocations_org_box_id on app.allocations (org_id, box_id);
create index if not exists idx_allocations_org_film_order_id on app.allocations (org_id, film_order_id);
create index if not exists idx_film_orders_org_job_number on app.film_orders (org_id, job_number);
create index if not exists idx_film_orders_org_status on app.film_orders (org_id, status);
create index if not exists idx_film_order_links_org_film_order_id on app.film_order_box_links (org_id, film_order_id);
create index if not exists idx_jobs_org_due_date on app.jobs (org_id, due_date desc);
create index if not exists idx_requirements_org_job_id on app.job_requirements (org_id, job_id);
create index if not exists idx_audit_log_org_created_at on app.audit_log (org_id, created_at desc);
create index if not exists idx_roll_weight_org_box_id on app.roll_weight_log (org_id, box_id);

create or replace function app.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists trg_boxes_set_updated_at on app.boxes;
create trigger trg_boxes_set_updated_at
before update on app.boxes
for each row
execute function app.set_updated_at();

drop trigger if exists trg_jobs_set_updated_at on app.jobs;
create trigger trg_jobs_set_updated_at
before update on app.jobs
for each row
execute function app.set_updated_at();

drop trigger if exists trg_job_requirements_set_updated_at on app.job_requirements;
create trigger trg_job_requirements_set_updated_at
before update on app.job_requirements
for each row
execute function app.set_updated_at();

create or replace function app.is_org_member(target_org_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from app.organization_members m
    where m.org_id = target_org_id
      and m.user_id = auth.uid()
  );
$$;

alter table app.organizations enable row level security;
alter table app.organization_members enable row level security;
alter table app.film_catalog enable row level security;
alter table app.boxes enable row level security;
alter table app.jobs enable row level security;
alter table app.job_requirements enable row level security;
alter table app.film_orders enable row level security;
alter table app.allocations enable row level security;
alter table app.film_order_box_links enable row level security;
alter table app.audit_log enable row level security;
alter table app.roll_weight_log enable row level security;

create policy orgs_read on app.organizations
for select using (app.is_org_member(id));

create policy members_read on app.organization_members
for select using (app.is_org_member(org_id));
create policy members_write on app.organization_members
for all using (app.is_org_member(org_id)) with check (app.is_org_member(org_id));

create policy film_catalog_rw on app.film_catalog
for all using (app.is_org_member(org_id)) with check (app.is_org_member(org_id));

create policy boxes_rw on app.boxes
for all using (app.is_org_member(org_id)) with check (app.is_org_member(org_id));

create policy jobs_rw on app.jobs
for all using (app.is_org_member(org_id)) with check (app.is_org_member(org_id));

create policy requirements_rw on app.job_requirements
for all using (app.is_org_member(org_id)) with check (app.is_org_member(org_id));

create policy film_orders_rw on app.film_orders
for all using (app.is_org_member(org_id)) with check (app.is_org_member(org_id));

create policy allocations_rw on app.allocations
for all using (app.is_org_member(org_id)) with check (app.is_org_member(org_id));

create policy film_order_links_rw on app.film_order_box_links
for all using (app.is_org_member(org_id)) with check (app.is_org_member(org_id));

create policy audit_log_rw on app.audit_log
for all using (app.is_org_member(org_id)) with check (app.is_org_member(org_id));

create policy roll_weight_rw on app.roll_weight_log
for all using (app.is_org_member(org_id)) with check (app.is_org_member(org_id));

-- Raw CSV import support for migrating legacy Google Sheets exports into app.*
-- Run this after 0001_supabase_inventory_schema.sql.
--
-- Workflow:
-- 1. Import legacy CSVs into the import.*_raw tables below.
-- 2. Run: select import.load_inventory_from_staging('<org_uuid>');
-- 3. Optional cleanup: select import.clear_staging();

create schema if not exists import;

create table if not exists import.film_data_raw (
  "FilmKey" text,
  "Manufacturer" text,
  "FilmName" text,
  "SqFtWeightLbsPerSqFt" text,
  "DefaultCoreType" text,
  "SourceWidthIn" text,
  "SourceInitialFeet" text,
  "SourceInitialWeightLbs" text,
  "UpdatedAt" text,
  "SourceBoxId" text,
  "Notes" text
);

create table if not exists import.boxes_raw (
  "BoxID" text,
  "Manufacturer" text,
  "FilmName" text,
  "WidthIn" text,
  "InitialFeet" text,
  "FeetAvailable" text,
  "LotRun" text,
  "Status" text,
  "OrderDate" text,
  "ReceivedDate" text,
  "InitialWeightLbs" text,
  "LastRollWeightLbs" text,
  "LastWeighedDate" text,
  "FilmKey" text,
  "CoreType" text,
  "CoreWeightLbs" text,
  "LfWeightLbsPerFt" text,
  "PurchaseCost" text,
  "Notes" text,
  "HasEverBeenCheckedOut" text,
  "LastCheckoutJob" text,
  "LastCheckoutDate" text,
  "ZeroedDate" text,
  "ZeroedReason" text,
  "ZeroedBy" text
);

create table if not exists import.allocations_raw (
  "AllocationID" text,
  "BoxID" text,
  "Warehouse" text,
  "JobNumber" text,
  "JobDate" text,
  "AllocatedFeet" text,
  "Status" text,
  "CreatedAt" text,
  "CreatedBy" text,
  "ResolvedAt" text,
  "ResolvedBy" text,
  "Notes" text,
  "CrewLeader" text,
  "FilmOrderID" text
);

create table if not exists import.film_orders_raw (
  "FilmOrderID" text,
  "JobNumber" text,
  "Warehouse" text,
  "Manufacturer" text,
  "FilmName" text,
  "WidthIn" text,
  "RequestedFeet" text,
  "CoveredFeet" text,
  "OrderedFeet" text,
  "RemainingToOrderFeet" text,
  "JobDate" text,
  "CrewLeader" text,
  "Status" text,
  "SourceBoxID" text,
  "CreatedAt" text,
  "CreatedBy" text,
  "ResolvedAt" text,
  "ResolvedBy" text,
  "Notes" text
);

create table if not exists import.film_order_box_links_raw (
  "LinkID" text,
  "FilmOrderID" text,
  "BoxID" text,
  "OrderedFeet" text,
  "AutoAllocatedFeet" text,
  "CreatedAt" text,
  "CreatedBy" text
);

create table if not exists import.jobs_raw (
  "JobNumber" text,
  "Warehouse" text,
  "Sections" text,
  "DueDate" text,
  "LifecycleStatus" text,
  "CreatedAt" text,
  "CreatedBy" text,
  "UpdatedAt" text,
  "UpdatedBy" text,
  "Notes" text
);

create table if not exists import.job_requirements_raw (
  "RequirementID" text,
  "JobNumber" text,
  "Manufacturer" text,
  "FilmName" text,
  "WidthIn" text,
  "RequiredFeet" text,
  "CreatedAt" text,
  "CreatedBy" text,
  "UpdatedAt" text,
  "UpdatedBy" text,
  "Notes" text
);

create table if not exists import.audit_log_raw (
  "LogID" text,
  "Date" text,
  "Action" text,
  "BoxID" text,
  "Before" text,
  "After" text,
  "User" text,
  "Notes" text
);

create table if not exists import.roll_weight_log_raw (
  "LogID" text,
  "BoxID" text,
  "Warehouse" text,
  "Manufacturer" text,
  "FilmName" text,
  "WidthIn" text,
  "JobNumber" text,
  "CheckedOutAt" text,
  "CheckedOutBy" text,
  "CheckedOutWeightLbs" text,
  "CheckedInAt" text,
  "CheckedInBy" text,
  "CheckedInWeightLbs" text,
  "WeightDeltaLbs" text,
  "FeetBefore" text,
  "FeetAfter" text,
  "Notes" text
);

create or replace function import.to_bool(value text)
returns boolean
language sql
immutable
as $$
  select lower(trim(coalesce(value, ''))) in ('true', '1', 'yes', 'y');
$$;

create or replace function import.clear_staging()
returns void
language plpgsql
as $$
begin
  truncate table
    import.film_data_raw,
    import.boxes_raw,
    import.allocations_raw,
    import.film_orders_raw,
    import.film_order_box_links_raw,
    import.jobs_raw,
    import.job_requirements_raw,
    import.audit_log_raw,
    import.roll_weight_log_raw;
end;
$$;

create or replace function import.load_inventory_from_staging(target_org_id uuid)
returns void
language plpgsql
as $$
begin
  if not exists (
    select 1
    from app.organizations
    where id = target_org_id
  ) then
    raise exception 'Organization % does not exist in app.organizations', target_org_id;
  end if;

  delete from app.audit_log where org_id = target_org_id;
  delete from app.roll_weight_log where org_id = target_org_id;
  delete from app.film_order_box_links where org_id = target_org_id;
  delete from app.allocations where org_id = target_org_id;
  delete from app.film_orders where org_id = target_org_id;
  delete from app.job_requirements where org_id = target_org_id;
  delete from app.jobs where org_id = target_org_id;
  delete from app.boxes where org_id = target_org_id;
  delete from app.film_catalog where org_id = target_org_id;

  insert into app.film_catalog (
    id,
    org_id,
    film_key,
    manufacturer,
    film_name,
    sq_ft_weight_lbs_per_sq_ft,
    default_core_type,
    source_width_in,
    source_initial_feet,
    source_initial_weight_lbs,
    source_box_id,
    notes,
    updated_at
  )
  select
    gen_random_uuid(),
    target_org_id,
    coalesce(nullif(trim("FilmKey"), ''), upper(trim("Manufacturer")) || '|' || upper(trim("FilmName"))),
    trim("Manufacturer"),
    trim("FilmName"),
    nullif(trim("SqFtWeightLbsPerSqFt"), '')::numeric(12, 8),
    coalesce(nullif(trim("DefaultCoreType"), ''), ''),
    nullif(trim("SourceWidthIn"), '')::numeric(10, 4),
    nullif(trim("SourceInitialFeet"), '')::integer,
    nullif(trim("SourceInitialWeightLbs"), '')::numeric(12, 2),
    coalesce(trim("SourceBoxId"), ''),
    coalesce(trim("Notes"), ''),
    coalesce(nullif(trim("UpdatedAt"), '')::timestamptz, now())
  from import.film_data_raw
  where coalesce(trim("Manufacturer"), '') <> ''
    and coalesce(trim("FilmName"), '') <> '';

  insert into app.boxes (
    id,
    org_id,
    box_id,
    warehouse,
    manufacturer,
    film_name,
    width_in,
    initial_feet,
    feet_available,
    lot_run,
    status,
    order_date,
    received_date,
    initial_weight_lbs,
    last_roll_weight_lbs,
    last_weighed_date,
    film_key,
    core_type,
    core_weight_lbs,
    lf_weight_lbs_per_ft,
    purchase_cost,
    notes,
    has_ever_been_checked_out,
    last_checkout_job,
    last_checkout_date,
    zeroed_date,
    zeroed_reason,
    zeroed_by
  )
  select
    gen_random_uuid(),
    target_org_id,
    trim("BoxID"),
    case when upper(left(trim("BoxID"), 1)) = 'M' then 'MS' else 'IL' end::app.warehouse,
    trim("Manufacturer"),
    trim("FilmName"),
    nullif(trim("WidthIn"), '')::numeric(10, 4),
    nullif(trim("InitialFeet"), '')::integer,
    coalesce(nullif(trim("FeetAvailable"), '')::integer, 0),
    coalesce(trim("LotRun"), ''),
    (
      case
        when upper(trim(coalesce("Status", ''))) in ('ORDERED', 'IN_STOCK', 'CHECKED_OUT', 'ZEROED', 'RETIRED')
          then upper(trim("Status"))
        when nullif(trim("ReceivedDate"), '') is not null and nullif(trim("ReceivedDate"), '')::date <= current_date
          then 'IN_STOCK'
        else 'ORDERED'
      end
    )::app.box_status,
    nullif(trim("OrderDate"), '')::date,
    nullif(trim("ReceivedDate"), '')::date,
    nullif(trim("InitialWeightLbs"), '')::numeric(12, 2),
    nullif(trim("LastRollWeightLbs"), '')::numeric(12, 2),
    nullif(trim("LastWeighedDate"), '')::date,
    coalesce(nullif(trim("FilmKey"), ''), upper(trim("Manufacturer")) || '|' || upper(trim("FilmName"))),
    coalesce(nullif(trim("CoreType"), ''), ''),
    nullif(trim("CoreWeightLbs"), '')::numeric(12, 4),
    nullif(trim("LfWeightLbsPerFt"), '')::numeric(12, 6),
    nullif(trim("PurchaseCost"), '')::numeric(12, 2),
    coalesce(trim("Notes"), ''),
    import.to_bool("HasEverBeenCheckedOut"),
    coalesce(trim("LastCheckoutJob"), ''),
    nullif(trim("LastCheckoutDate"), '')::date,
    nullif(trim("ZeroedDate"), '')::date,
    coalesce(trim("ZeroedReason"), ''),
    coalesce(trim("ZeroedBy"), '')
  from import.boxes_raw
  where coalesce(trim("BoxID"), '') <> '';

  insert into app.jobs (
    id,
    org_id,
    job_number,
    warehouse,
    sections,
    due_date,
    lifecycle_status,
    notes,
    created_at,
    created_by,
    updated_at,
    updated_by
  )
  select
    gen_random_uuid(),
    target_org_id,
    trim("JobNumber"),
    coalesce(nullif(upper(trim("Warehouse")), ''), 'IL')::app.warehouse,
    nullif(trim("Sections"), ''),
    nullif(trim("DueDate"), '')::date,
    case when upper(trim(coalesce("LifecycleStatus", ''))) = 'CANCELLED' then 'CANCELLED' else 'ACTIVE' end::app.job_lifecycle_status,
    coalesce(trim("Notes"), ''),
    coalesce(nullif(trim("CreatedAt"), '')::timestamptz, now()),
    coalesce(trim("CreatedBy"), ''),
    coalesce(nullif(trim("UpdatedAt"), '')::timestamptz, now()),
    coalesce(trim("UpdatedBy"), '')
  from import.jobs_raw
  where coalesce(trim("JobNumber"), '') <> '';

  insert into app.job_requirements (
    id,
    org_id,
    job_id,
    manufacturer,
    film_name,
    width_in,
    required_feet,
    notes,
    created_at,
    created_by,
    updated_at,
    updated_by
  )
  select
    gen_random_uuid(),
    target_org_id,
    j.id,
    trim(r."Manufacturer"),
    trim(r."FilmName"),
    nullif(trim(r."WidthIn"), '')::numeric(10, 4),
    nullif(trim(r."RequiredFeet"), '')::integer,
    coalesce(trim(r."Notes"), ''),
    coalesce(nullif(trim(r."CreatedAt"), '')::timestamptz, now()),
    coalesce(trim(r."CreatedBy"), ''),
    coalesce(nullif(trim(r."UpdatedAt"), '')::timestamptz, now()),
    coalesce(trim(r."UpdatedBy"), '')
  from import.job_requirements_raw r
  join app.jobs j
    on j.org_id = target_org_id
   and j.job_number = trim(r."JobNumber")
  where coalesce(trim(r."JobNumber"), '') <> '';

  insert into app.film_orders (
    id,
    org_id,
    film_order_id,
    job_id,
    job_number,
    warehouse,
    manufacturer,
    film_name,
    width_in,
    requested_feet,
    covered_feet,
    ordered_feet,
    remaining_to_order_feet,
    job_date,
    crew_leader,
    status,
    source_box_id,
    resolved_at,
    resolved_by,
    notes,
    created_at,
    created_by
  )
  select
    gen_random_uuid(),
    target_org_id,
    trim(r."FilmOrderID"),
    j.id,
    trim(r."JobNumber"),
    coalesce(nullif(upper(trim(r."Warehouse")), ''), 'IL')::app.warehouse,
    trim(r."Manufacturer"),
    trim(r."FilmName"),
    nullif(trim(r."WidthIn"), '')::numeric(10, 4),
    nullif(trim(r."RequestedFeet"), '')::integer,
    coalesce(nullif(trim(r."CoveredFeet"), '')::integer, 0),
    coalesce(nullif(trim(r."OrderedFeet"), '')::integer, 0),
    coalesce(nullif(trim(r."RemainingToOrderFeet"), '')::integer, 0),
    nullif(trim(r."JobDate"), '')::date,
    coalesce(trim(r."CrewLeader"), ''),
    case
      when upper(trim(coalesce(r."Status", ''))) = 'FILM_ON_THE_WAY' then 'FILM_ON_THE_WAY'
      when upper(trim(coalesce(r."Status", ''))) = 'FULFILLED' then 'FULFILLED'
      when upper(trim(coalesce(r."Status", ''))) = 'CANCELLED' then 'CANCELLED'
      else 'FILM_ORDER'
    end::app.film_order_status,
    coalesce(trim(r."SourceBoxID"), ''),
    nullif(trim(r."ResolvedAt"), '')::timestamptz,
    coalesce(trim(r."ResolvedBy"), ''),
    coalesce(trim(r."Notes"), ''),
    coalesce(nullif(trim(r."CreatedAt"), '')::timestamptz, now()),
    coalesce(trim(r."CreatedBy"), '')
  from import.film_orders_raw r
  left join app.jobs j
    on j.org_id = target_org_id
   and j.job_number = trim(r."JobNumber")
  where coalesce(trim(r."FilmOrderID"), '') <> '';

  insert into app.film_order_box_links (
    id,
    org_id,
    link_id,
    film_order_id,
    box_id,
    ordered_feet,
    auto_allocated_feet,
    created_at,
    created_by
  )
  select
    gen_random_uuid(),
    target_org_id,
    trim("LinkID"),
    trim("FilmOrderID"),
    trim("BoxID"),
    coalesce(nullif(trim("OrderedFeet"), '')::integer, 0),
    coalesce(nullif(trim("AutoAllocatedFeet"), '')::integer, 0),
    coalesce(nullif(trim("CreatedAt"), '')::timestamptz, now()),
    coalesce(trim("CreatedBy"), '')
  from import.film_order_box_links_raw
  where coalesce(trim("LinkID"), '') <> '';

  insert into app.allocations (
    id,
    org_id,
    allocation_id,
    box_id,
    job_id,
    job_number,
    warehouse,
    job_date,
    allocated_feet,
    status,
    created_at,
    created_by,
    resolved_at,
    resolved_by,
    notes,
    crew_leader,
    film_order_id
  )
  select
    gen_random_uuid(),
    target_org_id,
    trim(r."AllocationID"),
    trim(r."BoxID"),
    j.id,
    trim(r."JobNumber"),
    coalesce(nullif(upper(trim(r."Warehouse")), ''), 'IL')::app.warehouse,
    nullif(trim(r."JobDate"), '')::date,
    nullif(trim(r."AllocatedFeet"), '')::integer,
    case
      when upper(trim(coalesce(r."Status", ''))) = 'FULFILLED' then 'FULFILLED'
      when upper(trim(coalesce(r."Status", ''))) = 'CANCELLED' then 'CANCELLED'
      else 'ACTIVE'
    end::app.allocation_status,
    coalesce(nullif(trim(r."CreatedAt"), '')::timestamptz, now()),
    coalesce(trim(r."CreatedBy"), ''),
    nullif(trim(r."ResolvedAt"), '')::timestamptz,
    coalesce(trim(r."ResolvedBy"), ''),
    coalesce(trim(r."Notes"), ''),
    coalesce(trim(r."CrewLeader"), ''),
    coalesce(trim(r."FilmOrderID"), '')
  from import.allocations_raw r
  left join app.jobs j
    on j.org_id = target_org_id
   and j.job_number = trim(r."JobNumber")
  where coalesce(trim(r."AllocationID"), '') <> '';

  insert into app.audit_log (
    id,
    org_id,
    log_id,
    action,
    box_id,
    before_state,
    after_state,
    actor,
    notes,
    created_at
  )
  select
    gen_random_uuid(),
    target_org_id,
    trim("LogID"),
    trim("Action"),
    trim("BoxID"),
    case
      when lower(trim(coalesce("Before", ''))) in ('', 'null') then null
      else trim("Before")::jsonb
    end,
    case
      when lower(trim(coalesce("After", ''))) in ('', 'null') then null
      else trim("After")::jsonb
    end,
    coalesce(trim("User"), ''),
    coalesce(trim("Notes"), ''),
    coalesce(nullif(trim("Date"), '')::timestamptz, now())
  from import.audit_log_raw
  where coalesce(trim("LogID"), '') <> '';

  insert into app.roll_weight_log (
    id,
    org_id,
    log_id,
    box_id,
    warehouse,
    manufacturer,
    film_name,
    width_in,
    job_number,
    checked_out_at,
    checked_out_by,
    checked_out_weight_lbs,
    checked_in_at,
    checked_in_by,
    checked_in_weight_lbs,
    weight_delta_lbs,
    feet_before,
    feet_after,
    notes
  )
  select
    gen_random_uuid(),
    target_org_id,
    trim("LogID"),
    trim("BoxID"),
    coalesce(nullif(upper(trim("Warehouse")), ''), 'IL')::app.warehouse,
    trim("Manufacturer"),
    trim("FilmName"),
    nullif(trim("WidthIn"), '')::numeric(10, 4),
    coalesce(trim("JobNumber"), ''),
    nullif(trim("CheckedOutAt"), '')::timestamptz,
    coalesce(trim("CheckedOutBy"), ''),
    nullif(trim("CheckedOutWeightLbs"), '')::numeric(12, 2),
    nullif(trim("CheckedInAt"), '')::timestamptz,
    coalesce(trim("CheckedInBy"), ''),
    nullif(trim("CheckedInWeightLbs"), '')::numeric(12, 2),
    nullif(trim("WeightDeltaLbs"), '')::numeric(12, 2),
    coalesce(nullif(trim("FeetBefore"), '')::integer, 0),
    coalesce(nullif(trim("FeetAfter"), '')::integer, 0),
    coalesce(trim("Notes"), '')
  from import.roll_weight_log_raw
  where coalesce(trim("LogID"), '') <> '';
end;
$$;

create schema if not exists app_api;

create index if not exists idx_allocations_org_upper_job_number
  on app.allocations (org_id, upper(job_number));

create index if not exists idx_film_orders_org_upper_job_number
  on app.film_orders (org_id, upper(job_number));

create index if not exists idx_film_order_links_org_box_id
  on app.film_order_box_links (org_id, box_id);

create index if not exists idx_audit_log_org_box_created_at
  on app.audit_log (org_id, box_id, created_at desc);

create or replace function app_api.raise_http(p_status integer, p_message text)
returns void
language plpgsql
as $$
begin
  raise exception using
    message = p_message,
    detail = format('status=%s', p_status);
end;
$$;

create or replace function app_api.trim_text(p_value text)
returns text
language sql
immutable
as $$
  select btrim(coalesce(p_value, ''));
$$;

create or replace function app_api.today_date()
returns date
language sql
stable
as $$
  select (now() at time zone 'utc')::date;
$$;

create or replace function app_api.create_log_id()
returns text
language plpgsql
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_suffix text := lpad(floor(random() * 1000)::text, 3, '0');
begin
  return to_char(v_now at time zone 'utc', 'YYYYMMDDHH24MISSMS') || '-' || v_suffix;
end;
$$;

create or replace function app_api.require_org_member(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  if auth.uid() is null then
    perform app_api.raise_http(401, 'Authenticated session is required.');
  end if;

  if p_org_id is null then
    perform app_api.raise_http(400, 'Organization is required.');
  end if;

  if not exists (
    select 1
    from app.organization_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  ) then
    perform app_api.raise_http(403, 'You do not have access to this inventory workspace.');
  end if;
end;
$$;

create or replace function app_api.normalize_core_type(p_value text, p_allow_blank boolean default false)
returns text
language plpgsql
immutable
as $$
declare
  v_trimmed text := app_api.trim_text(p_value);
  v_normalized text := lower(v_trimmed);
begin
  if v_trimmed = '' then
    if p_allow_blank then
      return '';
    end if;

    perform app_api.raise_http(400, 'CoreType is required.');
  end if;

  if v_normalized = 'white' then
    return 'White';
  end if;

  if v_normalized = 'red' then
    return 'Red';
  end if;

  if v_normalized = 'cardboard' then
    return 'Cardboard';
  end if;

  perform app_api.raise_http(400, 'CoreType must be White, Red, or Cardboard.');
  return '';
end;
$$;

create or replace function app_api.derive_core_weight_lbs(p_core_type text, p_width_in numeric)
returns numeric
language sql
immutable
as $$
  select round(
    (
      case app_api.normalize_core_type(p_core_type, false)
        when 'White' then 2::numeric
        when 'Red' then 1.85::numeric
        else 2.05::numeric
      end / 72::numeric
    ) * p_width_in,
    4
  );
$$;

create or replace function app_api.derive_lf_weight_lbs_per_ft(p_sq_ft_weight numeric, p_width_in numeric)
returns numeric
language sql
immutable
as $$
  select round(p_sq_ft_weight * (p_width_in / 12::numeric), 6);
$$;

create or replace function app_api.derive_initial_weight_lbs(
  p_lf_weight numeric,
  p_initial_feet integer,
  p_core_weight numeric
)
returns numeric
language sql
immutable
as $$
  select round((p_lf_weight * p_initial_feet) + p_core_weight, 2);
$$;

create or replace function app_api.derive_sqft_weight_lbs_per_sqft(
  p_initial_weight numeric,
  p_core_weight numeric,
  p_width_in numeric,
  p_initial_feet integer
)
returns numeric
language plpgsql
immutable
as $$
declare
  v_area_sq_ft numeric := (p_width_in / 12::numeric) * p_initial_feet;
  v_film_only_weight numeric := p_initial_weight - p_core_weight;
begin
  if v_area_sq_ft <= 0 then
    perform app_api.raise_http(
      400,
      'WidthIn and InitialFeet must be greater than zero to derive film weight.'
    );
  end if;

  if v_film_only_weight < 0 then
    perform app_api.raise_http(
      400,
      'InitialWeightLbs must be greater than or equal to the derived core weight.'
    );
  end if;

  return round(v_film_only_weight / v_area_sq_ft, 8);
end;
$$;

create or replace function app_api.derive_feet_available_from_roll_weight(
  p_last_roll_weight numeric,
  p_core_weight numeric,
  p_lf_weight numeric,
  p_initial_feet integer
)
returns integer
language plpgsql
immutable
as $$
declare
  v_raw_feet numeric;
  v_floored integer;
begin
  if p_lf_weight is null or p_lf_weight <= 0 then
    perform app_api.raise_http(
      400,
      'LfWeightLbsPerFt must be greater than zero to calculate FeetAvailable.'
    );
  end if;

  v_raw_feet := (p_last_roll_weight - p_core_weight) / p_lf_weight;
  if v_raw_feet <= 0 then
    return 0;
  end if;

  v_floored := floor(v_raw_feet);
  if v_floored > p_initial_feet then
    return p_initial_feet;
  end if;

  return greatest(v_floored, 0);
end;
$$;

create or replace function app_api.public_box_json(p_box app.boxes)
returns jsonb
language sql
stable
as $$
  select jsonb_build_object(
    'boxId', coalesce(p_box.box_id, ''),
    'warehouse', coalesce(p_box.warehouse::text, ''),
    'manufacturer', coalesce(p_box.manufacturer, ''),
    'filmName', coalesce(p_box.film_name, ''),
    'widthIn', p_box.width_in,
    'initialFeet', p_box.initial_feet,
    'feetAvailable', p_box.feet_available,
    'lotRun', coalesce(p_box.lot_run, ''),
    'status', coalesce(p_box.status::text, 'ORDERED'),
    'orderDate', coalesce(to_char(p_box.order_date, 'YYYY-MM-DD'), ''),
    'receivedDate', coalesce(to_char(p_box.received_date, 'YYYY-MM-DD'), ''),
    'initialWeightLbs', p_box.initial_weight_lbs,
    'lastRollWeightLbs', p_box.last_roll_weight_lbs,
    'lastWeighedDate', coalesce(to_char(p_box.last_weighed_date, 'YYYY-MM-DD'), ''),
    'filmKey', upper(coalesce(p_box.film_key, '')),
    'coreType', coalesce(p_box.core_type, ''),
    'coreWeightLbs', p_box.core_weight_lbs,
    'lfWeightLbsPerFt', p_box.lf_weight_lbs_per_ft,
    'purchaseCost', p_box.purchase_cost,
    'notes', coalesce(p_box.notes, ''),
    'hasEverBeenCheckedOut', p_box.has_ever_been_checked_out,
    'lastCheckoutJob', coalesce(p_box.last_checkout_job, ''),
    'lastCheckoutDate', coalesce(to_char(p_box.last_checkout_date, 'YYYY-MM-DD'), ''),
    'zeroedDate', coalesce(to_char(p_box.zeroed_date, 'YYYY-MM-DD'), ''),
    'zeroedReason', coalesce(p_box.zeroed_reason, ''),
    'zeroedBy', coalesce(p_box.zeroed_by, '')
