as $$
declare
  v_result jsonb;
begin
  perform app_api.require_org_member(p_org_id);

  select coalesce(
    jsonb_agg(to_jsonb(a) order by a.created_at desc, a.allocation_id desc),
    '[]'::jsonb
  )
  into v_result
  from app.allocations a
  where a.org_id = p_org_id
    and a.status = 'ACTIVE';

  return v_result;
end;
$$;

