select app_api.grant_execute_if_exists('public.api_request_username_change(uuid, text, jsonb)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_list_username_change_requests(uuid, text)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_approve_username_change_request(uuid, text, jsonb)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_deny_username_change_request(uuid, text, jsonb)', 'authenticated');

create or replace function app_api.member_permissions_for_user_json(p_org_id uuid, p_user_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, app, app_api
as $$
  select jsonb_build_object(
    'inventory', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'inventory'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'inventory'), true)),
      coalesce((select a.write_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'inventory'), coalesce((select g.write_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'inventory'), true))
    ),
    'allocations', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'allocations'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'allocations'), true)),
      coalesce((select a.write_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'allocations'), coalesce((select g.write_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'allocations'), true))
    ),
    'jobs', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'jobs'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'jobs'), true)),
      coalesce((select a.write_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'jobs'), coalesce((select g.write_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'jobs'), true))
    ),
    'film_orders', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'film_orders'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'film_orders'), true)),
      coalesce((select a.write_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'film_orders'), coalesce((select g.write_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'film_orders'), true))
    ),
    'activity_history', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'activity_history'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'activity_history'), true)),
      coalesce((select a.write_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'activity_history'), coalesce((select g.write_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'activity_history'), true))
    ),
    'reports', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'reports'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'reports'), true)),
      coalesce((select a.write_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'reports'), coalesce((select g.write_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'reports'), true))
    ),
    'access_management', app_api.feature_access_json(false, false)
  );
$$;

create or replace function app_api.require_effective_feature_access(
  p_org_id uuid,
  p_feature_area text,
  p_access_mode text
)
returns void
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_role text;
  v_allowed boolean := false;
begin
  if app_api.trim_text(p_access_mode) not in ('read', 'write') then
    perform app_api.raise_http(400, 'Feature access mode must be read or write.');
  end if;

  v_role := app_api.require_org_member_approved(p_org_id);
  perform app_api.ensure_general_feature_permissions(p_org_id, 'feature-access-check');

  if v_role = 'owner' then
    return;
  end if;

  if v_role = 'member' then
    if p_feature_area = 'access_management' then
      perform app_api.raise_http(403, 'Feature access denied.');
    end if;

    if p_feature_area <> all(app_api.member_feature_areas()) then
      perform app_api.raise_http(400, 'Unsupported feature area.');
    end if;

    select
      case
        when p_access_mode = 'read' then coalesce(a.read_enabled, g.read_enabled, false)
        else coalesce(a.write_enabled, g.write_enabled, false)
      end
    into v_allowed
    from app.general_feature_permissions g
    left join app.admin_feature_permissions a
      on a.org_id = g.org_id
     and a.admin_user_id = auth.uid()
     and a.feature_area = g.feature_area
    where g.org_id = p_org_id
      and g.feature_area = p_feature_area;
  elsif v_role = 'admin' then
    if p_feature_area <> all(app_api.admin_feature_areas()) then
      perform app_api.raise_http(400, 'Unsupported feature area.');
    end if;

    perform app_api.ensure_admin_feature_permissions(
      p_org_id,
      auth.uid(),
      true,
      'feature-access-check'
    );

    select
      case
        when p_access_mode = 'read' then a.read_enabled
        else a.write_enabled
      end
    into v_allowed
    from app.admin_feature_permissions a
    where a.org_id = p_org_id
      and a.admin_user_id = auth.uid()
      and a.feature_area = p_feature_area;
  else
    perform app_api.raise_http(403, 'Feature access denied.');
  end if;

  if not coalesce(v_allowed, false) then
    perform app_api.raise_http(403, 'Feature access denied.');
  end if;
end;
$$;

create or replace function public.api_get_auth_context(p_org_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_user_id uuid := auth.uid();
  v_role text;
  v_email text := app_api.trim_text(auth.jwt()->>'email');
  v_name text := '';
  v_request app.access_requests;
  v_inserted_count integer := 0;
  v_permissions jsonb := '{}'::jsonb;
  v_pending_count integer := 0;
  v_owner_in_app_opt_in boolean := true;
  v_is_admin_console_allowed boolean := false;
begin
  if v_user_id is null then
    perform app_api.raise_http(401, 'Authenticated session is required.');
  end if;

  if p_org_id is null then
    perform app_api.raise_http(400, 'Organization is required.');
  end if;

  v_name := app_api.trim_text(
    coalesce(
      nullif(auth.jwt()->'user_metadata'->>'full_name', ''),
      nullif(auth.jwt()->'user_metadata'->>'name', '')
    )
  );

  if v_name = '' then
    v_name := app_api.derive_display_name_from_email(v_email);
  end if;

  perform app_api.ensure_general_feature_permissions(p_org_id, 'auth-context-bootstrap');

  select m.role
  into v_role
  from app.organization_members m
  where m.org_id = p_org_id
    and m.user_id = v_user_id;

  if v_role is null then
    select *
    into v_request
    from app.access_requests r
    where r.org_id = p_org_id
      and r.user_id = v_user_id;

    if found and v_request.status = 'denied' then
      return jsonb_build_object(
        'orgId', p_org_id,
        'accessStatus', 'denied',
        'role', '',
        'permissions', '{}'::jsonb,
        'isAdminConsoleAllowed', false,
        'pendingRequestCreated', false,
        'pendingCount', 0,
        'receivesInAppNotifications', false,
        'email', v_email
      );
    end if;

    if not found then
      insert into app.access_requests (
        org_id,
        user_id,
        status,
        requested_at,
        requested_by_email,
        requested_by_name
      )
      values (
        p_org_id,
        v_user_id,
        'pending',
        now(),
        v_email,
        v_name
      )
      on conflict (org_id, user_id) do nothing;

      get diagnostics v_inserted_count = row_count;
    end if;

    return jsonb_build_object(
      'orgId', p_org_id,
      'accessStatus', 'pending',
      'role', '',
      'permissions', '{}'::jsonb,
      'isAdminConsoleAllowed', false,
      'pendingRequestCreated', v_inserted_count > 0,
      'pendingCount', 0,
      'receivesInAppNotifications', false,
      'email', v_email
    );
  end if;

  perform app_api.require_org_member_approved(p_org_id);

  if v_role = 'owner' then
    perform app_api.ensure_owner_notification_preference(
      p_org_id,
      v_user_id,
      'auth-context-owner-bootstrap'
    );
    select p.in_app_opt_in
    into v_owner_in_app_opt_in
    from app.owner_notification_preferences p
    where p.org_id = p_org_id
      and p.owner_user_id = v_user_id;
    v_owner_in_app_opt_in := coalesce(v_owner_in_app_opt_in, true);
    v_permissions := jsonb_build_object(
      'inventory', app_api.feature_access_json(true, true),
      'allocations', app_api.feature_access_json(true, true),
      'jobs', app_api.feature_access_json(true, true),
      'film_orders', app_api.feature_access_json(true, true),
      'activity_history', app_api.feature_access_json(true, true),
      'reports', app_api.feature_access_json(true, true),
      'access_management', app_api.feature_access_json(true, true)
    );
    v_is_admin_console_allowed := true;
  elsif v_role = 'admin' then
    perform app_api.ensure_admin_feature_permissions(
      p_org_id,
      v_user_id,
      true,
      'auth-context-admin-bootstrap'
    );
    v_permissions := app_api.admin_permissions_json(p_org_id, v_user_id);
    v_is_admin_console_allowed := coalesce((v_permissions->'access_management'->>'write')::boolean, false);
    v_owner_in_app_opt_in := false;
  else
    v_permissions := app_api.member_permissions_for_user_json(p_org_id, v_user_id);
    v_is_admin_console_allowed := false;
    v_owner_in_app_opt_in := false;
  end if;

  if v_role = 'admin' or (v_role = 'owner' and v_owner_in_app_opt_in) then
    select count(*)
    into v_pending_count
    from app.access_requests r
    where r.org_id = p_org_id
      and r.status = 'pending';
  end if;

  return jsonb_build_object(
    'orgId', p_org_id,
    'accessStatus', 'approved',
    'role', v_role,
    'permissions', coalesce(v_permissions, '{}'::jsonb),
    'isAdminConsoleAllowed', v_is_admin_console_allowed,
    'pendingRequestCreated', false,
    'pendingCount', coalesce(v_pending_count, 0),
    'receivesInAppNotifications', (v_role = 'admin') or (v_role = 'owner' and v_owner_in_app_opt_in),
    'email', v_email
  );
end;
$$;

create or replace function public.api_get_user_feature_permissions(
  p_org_id uuid,
  p_user_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_actor_role text;
  v_target_role text;
begin
  v_actor_role := app_api.require_org_admin_or_owner(p_org_id);
  if v_actor_role = 'admin' then
    perform app_api.require_effective_feature_access(p_org_id, 'access_management', 'read');
  end if;

  if p_user_id is null then
    perform app_api.raise_http(400, 'userId is required.');
  end if;

  select m.role
  into v_target_role
  from app.organization_members m
  where m.org_id = p_org_id
    and m.user_id = p_user_id;

  if v_target_role is null then
    perform app_api.raise_http(404, 'Target user is not an organization member.');
  end if;

  if v_target_role = 'owner' then
    return jsonb_build_object(
      'inventory', app_api.feature_access_json(true, true),
      'allocations', app_api.feature_access_json(true, true),
      'jobs', app_api.feature_access_json(true, true),
      'film_orders', app_api.feature_access_json(true, true),
      'activity_history', app_api.feature_access_json(true, true),
      'reports', app_api.feature_access_json(true, true),
      'access_management', app_api.feature_access_json(true, true)
    );
  end if;

  if v_target_role = 'admin' then
    perform app_api.ensure_admin_feature_permissions(p_org_id, p_user_id, true, 'read-user-feature-permissions');
    return app_api.admin_permissions_json(p_org_id, p_user_id);
  end if;

  perform app_api.ensure_general_feature_permissions(p_org_id, 'read-user-feature-permissions');
  return app_api.member_permissions_for_user_json(p_org_id, p_user_id);
end;
$$;

create or replace function public.api_update_user_feature_permissions(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_actor_role text;
  v_target_user_id uuid := nullif(app_api.trim_text(p_payload->>'userId'), '')::uuid;
  v_target_role text;
  v_feature text;
  v_read text;
  v_write text;
begin
  v_actor_role := app_api.require_org_admin_or_owner(p_org_id);
  if v_actor_role = 'admin' then
    perform app_api.require_effective_feature_access(p_org_id, 'access_management', 'write');
  end if;

  if v_target_user_id is null then
    perform app_api.raise_http(400, 'userId is required.');
  end if;

  select m.role
  into v_target_role
  from app.organization_members m
  where m.org_id = p_org_id
    and m.user_id = v_target_user_id
  for update;

  if v_target_role is null then
    perform app_api.raise_http(404, 'Target user is not an organization member.');
  end if;

  if v_target_role <> 'member' then
    perform app_api.raise_http(400, 'Only member accounts can be changed from this page.');
  end if;

  perform app_api.ensure_general_feature_permissions(p_org_id, app_api.trim_text(p_actor));

  foreach v_feature in array app_api.member_feature_areas() loop
    if not ((p_payload->'permissions') ? v_feature) then
      continue;
    end if;

    v_read := lower(app_api.trim_text((p_payload->'permissions'->v_feature)->>'read'));
    v_write := lower(app_api.trim_text((p_payload->'permissions'->v_feature)->>'write'));

    insert into app.admin_feature_permissions (
      org_id,
      admin_user_id,
      feature_area,
      read_enabled,
      write_enabled,
      updated_at,
      updated_by
    )
    values (
      p_org_id,
      v_target_user_id,
      v_feature,
      coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = v_feature), true),
      coalesce((select g.write_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = v_feature), true),
      now(),
      app_api.trim_text(p_actor)
    )
    on conflict (org_id, admin_user_id, feature_area) do nothing;

    update app.admin_feature_permissions a
    set
      read_enabled = case when v_read in ('true', 'false') then v_read::boolean else a.read_enabled end,
      write_enabled = case when v_write in ('true', 'false') then v_write::boolean else a.write_enabled end,
      updated_at = now(),
      updated_by = app_api.trim_text(p_actor)
    where a.org_id = p_org_id
      and a.admin_user_id = v_target_user_id
      and a.feature_area = v_feature;
  end loop;

  delete from app.admin_feature_permissions a
  where a.org_id = p_org_id
    and a.admin_user_id = v_target_user_id
    and a.feature_area = 'access_management';

  return app_api.member_permissions_for_user_json(p_org_id, v_target_user_id);
end;
$$;

select app_api.grant_execute_if_exists('public.api_get_user_feature_permissions(uuid, uuid)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_update_user_feature_permissions(uuid, text, jsonb)', 'authenticated');

alter table app.jobs
  add column if not exists crew_leader text not null default '';

with job_metadata as (
  select
    x.org_id,
    x.job_number,
    min(x.job_date) as job_date,
    min(x.crew_leader) as crew_leader
  from (
    select
      a.org_id,
      a.job_number,
      a.job_date,
      nullif(a.crew_leader, '') as crew_leader
    from app.allocations a
    union all
    select
      f.org_id,
      f.job_number,
      f.job_date,
      nullif(f.crew_leader, '') as crew_leader
    from app.film_orders f
  ) x
  group by x.org_id, x.job_number
)
update app.jobs j
set
  due_date = coalesce(j.due_date, m.job_date),
  crew_leader = coalesce(nullif(j.crew_leader, ''), m.crew_leader, '')
from job_metadata m
where j.org_id = m.org_id
  and j.job_number = m.job_number;

create or replace function app_api.save_job(p_job app.jobs)
returns app.jobs
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_row app.jobs;
begin
  insert into app.jobs (
    id,
    org_id,
    job_number,
    warehouse,
    sections,
    due_date,
    crew_leader,
    lifecycle_status,
    notes,
    created_at,
    created_by,
    updated_at,
    updated_by
  )
  values (
    coalesce(p_job.id, gen_random_uuid()),
    p_job.org_id,
    p_job.job_number,
    p_job.warehouse,
    p_job.sections,
    p_job.due_date,
    coalesce(p_job.crew_leader, ''),
    p_job.lifecycle_status,
    coalesce(p_job.notes, ''),
    coalesce(p_job.created_at, now()),
    coalesce(p_job.created_by, ''),
    coalesce(p_job.updated_at, now()),
    coalesce(p_job.updated_by, '')
  )
  on conflict (org_id, job_number) do update set
    warehouse = excluded.warehouse,
    sections = excluded.sections,
    due_date = excluded.due_date,
    crew_leader = excluded.crew_leader,
    lifecycle_status = excluded.lifecycle_status,
    notes = excluded.notes,
    updated_at = excluded.updated_at,
    updated_by = excluded.updated_by
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function public.api_jobs_create(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_now timestamptz := now();
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and j.job_number = app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number')
  for update;

  if not found then
    v_job.id := gen_random_uuid();
    v_job.created_at := v_now;
    v_job.created_by := app_api.trim_text(p_actor);
  end if;

  v_job.org_id := p_org_id;
  v_job.job_number := app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number');
  v_job.warehouse := app_api.require_warehouse(p_payload->>'warehouse', 'Warehouse');
  v_job.sections := app_api.normalize_job_sections(p_payload->>'sections');
  v_job.due_date := nullif(app_api.trim_text(p_payload->>'dueDate'), '')::date;
  v_job.crew_leader := app_api.trim_text(p_payload->>'crewLeader');
  v_job.lifecycle_status := app_api.normalize_job_lifecycle_status(p_payload->>'lifecycleStatus');
  v_job.notes := app_api.trim_text(p_payload->>'notes');
  v_job.updated_at := v_now;
  v_job.updated_by := app_api.trim_text(p_actor);

  v_job := app_api.save_job(v_job);
  perform app_api.replace_job_requirements(p_org_id, v_job, p_payload->'requirements', p_actor, v_now);

  return jsonb_build_object(
    'jobNumber', v_job.job_number,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_jobs_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_now timestamptz := now();
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and j.job_number = app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number')
  for update;

  if not found then
    v_job.id := gen_random_uuid();
    v_job.org_id := p_org_id;
    v_job.job_number := app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number');
    v_job.warehouse := coalesce(
      nullif(upper(app_api.trim_text(p_payload->>'warehouse')), '')::app.warehouse,
      'IL'::app.warehouse
    );
    v_job.sections := null;
    v_job.due_date := null;
    v_job.crew_leader := '';
    v_job.lifecycle_status := 'ACTIVE';
    v_job.notes := '';
    v_job.created_at := v_now;
    v_job.created_by := app_api.trim_text(p_actor);
  end if;

  if p_payload ? 'warehouse' then
    v_job.warehouse := app_api.require_warehouse(p_payload->>'warehouse', 'Warehouse');
  end if;
  if p_payload ? 'sections' then
    v_job.sections := app_api.normalize_job_sections(p_payload->>'sections');
  end if;
  if p_payload ? 'dueDate' then
    v_job.due_date := nullif(app_api.trim_text(p_payload->>'dueDate'), '')::date;
  end if;
  if p_payload ? 'crewLeader' then
    v_job.crew_leader := app_api.trim_text(p_payload->>'crewLeader');
  end if;
  if p_payload ? 'lifecycleStatus' then
    v_job.lifecycle_status := app_api.normalize_job_lifecycle_status(p_payload->>'lifecycleStatus');
  end if;
  if p_payload ? 'notes' then
    v_job.notes := app_api.trim_text(p_payload->>'notes');
  end if;

  v_job.updated_at := v_now;
  v_job.updated_by := app_api.trim_text(p_actor);
  v_job := app_api.save_job(v_job);
  perform app_api.replace_job_requirements(p_org_id, v_job, p_payload->'requirements', p_actor, v_now);

  return jsonb_build_object(
    'jobNumber', v_job.job_number,
    'warnings', '[]'::jsonb
  );
end;
$$;

do $$
begin
  alter type app.job_lifecycle_status add value if not exists 'COMPLETED';
exception
  when duplicate_object then
    null;
end;
$$;

create or replace function app_api.normalize_job_lifecycle_status(p_value text)
returns app.job_lifecycle_status
language plpgsql
immutable
as $$
begin
  return case
    when upper(app_api.trim_text(p_value)) = 'CANCELLED' then 'CANCELLED'::app.job_lifecycle_status
    when upper(app_api.trim_text(p_value)) = 'COMPLETED' then 'COMPLETED'::app.job_lifecycle_status
    else 'ACTIVE'::app.job_lifecycle_status
  end;
end;
$$;

create or replace function app_api.build_box_from_payload(
  p_org_id uuid,
  p_payload jsonb,
  p_existing_box_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_box app.boxes;
  v_film_data app.film_catalog;
  v_warnings text[] := array[]::text[];
  v_box_id text;
  v_manufacturer text;
  v_film_name text;
  v_width_in numeric;
  v_initial_feet integer;
  v_order_date date;
  v_received_date date;
  v_feet_available_input text;
  v_feet_available integer;
  v_film_key text;
  v_initial_weight_input numeric;
  v_last_roll_weight_input numeric;
  v_last_weighed_date_input date;
  v_core_type_input text;
  v_existing_core_type text;
  v_resolved_initial_weight numeric;
  v_resolved_last_roll_weight numeric;
  v_resolved_last_weighed_date date;
  v_resolved_core_type text;
  v_resolved_core_weight numeric;
  v_resolved_lf_weight numeric;
  v_effective_sq_ft_weight numeric;
  v_active_allocated_feet integer := 0;
  v_is_first_receipt boolean := false;
  v_weight_changed boolean := false;
begin
  if p_existing_box_id is not null then
    select *
    into v_existing
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id = app_api.trim_text(p_existing_box_id)
    for update;

    if not found then
      perform app_api.raise_http(404, 'Box not found.');
    end if;
  end if;

  v_box_id := coalesce(v_existing.box_id, app_api.require_text(p_payload->>'boxId', 'BoxID'));
  v_manufacturer := app_api.require_text(p_payload->>'manufacturer', 'Manufacturer');
  v_film_name := app_api.require_text(p_payload->>'filmName', 'FilmName');
  v_width_in := nullif(app_api.trim_text(p_payload->>'widthIn'), '')::numeric;
  v_initial_feet := floor(nullif(app_api.trim_text(p_payload->>'initialFeet'), '')::numeric);
  v_order_date := nullif(app_api.trim_text(p_payload->>'orderDate'), '')::date;
  v_received_date := nullif(app_api.trim_text(p_payload->>'receivedDate'), '')::date;
  v_feet_available_input := app_api.trim_text(p_payload->>'feetAvailable');
  v_film_key := upper(coalesce(nullif(app_api.trim_text(p_payload->>'filmKey'), ''), upper(v_manufacturer) || '|' || upper(v_film_name)));
  v_initial_weight_input := nullif(app_api.trim_text(p_payload->>'initialWeightLbs'), '')::numeric;
  v_last_roll_weight_input := nullif(app_api.trim_text(p_payload->>'lastRollWeightLbs'), '')::numeric;
  v_last_weighed_date_input := nullif(app_api.trim_text(p_payload->>'lastWeighedDate'), '')::date;
  v_core_type_input := app_api.normalize_core_type(p_payload->>'coreType', true);
  v_existing_core_type := coalesce(app_api.normalize_core_type(v_existing.core_type, true), '');

  if v_width_in is null or v_width_in <= 0 then
    perform app_api.raise_http(400, 'WidthIn must be greater than zero.');
  end if;

  if v_initial_feet is null or v_initial_feet < 0 then
    perform app_api.raise_http(400, 'InitialFeet must be zero or greater.');
  end if;

  if v_order_date is null then
    perform app_api.raise_http(400, 'OrderDate is required.');
  end if;

  if v_existing.received_date is not null and v_received_date is null then
    perform app_api.raise_http(400, 'ReceivedDate cannot be cleared after a box has been received.');
  end if;

  if v_feet_available_input = '' then
    v_feet_available := coalesce(v_existing.feet_available, app_api.derive_add_feet_available(v_initial_feet, v_received_date));
  else
    v_feet_available := floor(v_feet_available_input::numeric);
    if v_feet_available < 0 then
      v_feet_available := 0;
      v_warnings := app_api.push_warning(v_warnings, 'FeetAvailable was clamped to 0.');
    end if;
  end if;

  v_resolved_initial_weight := v_initial_weight_input;
  v_resolved_last_roll_weight := v_last_roll_weight_input;
  v_resolved_last_weighed_date := v_last_weighed_date_input;
  v_resolved_core_type := coalesce(nullif(v_core_type_input, ''), v_existing_core_type, '');
  v_resolved_core_weight := v_existing.core_weight_lbs;
  v_resolved_lf_weight := v_existing.lf_weight_lbs_per_ft;

  if v_received_date is not null then
    if v_initial_feet <= 0 then
      perform app_api.raise_http(400, 'InitialFeet must be greater than zero for received boxes.');
    end if;

    select *
    into v_film_data
    from app.film_catalog f
    where f.org_id = p_org_id
      and f.film_key = v_film_key
    for update;

    if v_resolved_core_type = '' then
      v_resolved_core_type := app_api.normalize_core_type(v_film_data.default_core_type, true);
    end if;

    if v_film_data.sq_ft_weight_lbs_per_sq_ft is not null then
      if v_resolved_core_type = '' then
        perform app_api.raise_http(400, 'CoreType is required before this film can be received.');
      end if;

      v_effective_sq_ft_weight := v_film_data.sq_ft_weight_lbs_per_sq_ft;
      v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_width_in);

      if v_initial_weight_input is not null then
        v_effective_sq_ft_weight := app_api.derive_sqft_weight_lbs_per_sqft(
          v_initial_weight_input,
          v_resolved_core_weight,
          v_width_in,
          v_initial_feet
        );
        v_resolved_initial_weight := round(v_initial_weight_input, 2);
      else
        v_resolved_initial_weight := app_api.derive_initial_weight_lbs(
          app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in),
          v_initial_feet,
          v_resolved_core_weight
        );
        v_warnings := app_api.push_warning(v_warnings, 'Initial and last roll weights were auto-filled from FILM DATA.');
      end if;

      v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
    else
      if v_resolved_core_type = '' then
        perform app_api.raise_http(400, 'CoreType is required the first time a received film is saved.');
      end if;

      if v_initial_weight_input is null and v_existing.initial_weight_lbs is null then
        perform app_api.raise_http(400, 'InitialWeightLbs is required the first time a received film is saved.');
      end if;

      v_resolved_initial_weight := coalesce(v_initial_weight_input, v_existing.initial_weight_lbs);
      v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_width_in);
      v_effective_sq_ft_weight := app_api.derive_sqft_weight_lbs_per_sqft(
        v_resolved_initial_weight,
        v_resolved_core_weight,
        v_width_in,
        v_initial_feet
      );
      v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
      perform app_api.save_film_catalog(
        p_org_id,
        v_film_key,
        v_manufacturer,
        v_film_name,
        v_effective_sq_ft_weight,
        v_resolved_core_type,
        v_width_in,
        v_initial_feet,
        v_resolved_initial_weight,
        v_box_id,
        coalesce(v_film_data.notes, '')
      );
      v_warnings := app_api.push_warning(v_warnings, format('FILM DATA was created from the first received weight for %s.', v_film_key));
    end if;

    if v_resolved_last_roll_weight is null then
      v_resolved_last_roll_weight := coalesce(v_existing.last_roll_weight_lbs, v_resolved_initial_weight);
    end if;
    if v_resolved_last_weighed_date is null then
      v_resolved_last_weighed_date := coalesce(v_existing.last_weighed_date, v_received_date);
    end if;

    if v_film_data.id is not null and (coalesce(v_film_data.default_core_type, '') = '' or coalesce(v_film_data.default_core_type, '') <> v_resolved_core_type) then
      perform app_api.save_film_catalog(
        p_org_id,
        v_film_key,
        coalesce(v_film_data.manufacturer, v_manufacturer),
        coalesce(v_film_data.film_name, v_film_name),
        coalesce(v_film_data.sq_ft_weight_lbs_per_sq_ft, v_effective_sq_ft_weight),
        v_resolved_core_type,
        coalesce(v_film_data.source_width_in, v_width_in),
        coalesce(v_film_data.source_initial_feet, v_initial_feet),
        coalesce(v_film_data.source_initial_weight_lbs, v_resolved_initial_weight),
        coalesce(v_film_data.source_box_id, v_box_id),
        coalesce(v_film_data.notes, '')
      );
      v_warnings := app_api.push_warning(v_warnings, 'FILM DATA was updated with the selected core type.');
    end if;

    select coalesce(sum(a.allocated_feet), 0)::integer
    into v_active_allocated_feet
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_box_id
      and a.status = 'ACTIVE';

    v_is_first_receipt := v_existing.received_date is null;
    v_weight_changed := v_existing.last_roll_weight_lbs is distinct from v_resolved_last_roll_weight;

    if v_is_first_receipt then
      v_feet_available := greatest(v_initial_feet - v_active_allocated_feet, 0);
    elsif v_weight_changed then
      v_feet_available := greatest(
        app_api.derive_feet_available_from_roll_weight(
          v_resolved_last_roll_weight,
          v_resolved_core_weight,
          v_resolved_lf_weight,
          v_initial_feet
        ) - v_active_allocated_feet,
        0
      );
    else
      v_feet_available := least(greatest(coalesce(v_existing.feet_available, v_feet_available), 0), v_initial_feet);
    end if;
  else
    v_resolved_initial_weight := null;
    v_resolved_last_roll_weight := null;
    v_resolved_last_weighed_date := null;
    v_resolved_core_type := '';
    v_resolved_core_weight := null;
    v_resolved_lf_weight := null;
  end if;

  v_box.id := v_existing.id;
  v_box.org_id := p_org_id;
  v_box.box_id := v_box_id;
  v_box.warehouse := app_api.determine_warehouse_from_box_id(v_box_id);
  v_box.manufacturer := v_manufacturer;
  v_box.film_name := v_film_name;
  v_box.width_in := v_width_in;
  v_box.initial_feet := v_initial_feet;
  v_box.feet_available := v_feet_available;
  v_box.lot_run := app_api.trim_text(p_payload->>'lotRun');
  v_box.status := case
    when v_existing.status in ('CHECKED_OUT', 'ZEROED', 'RETIRED') then v_existing.status
    else app_api.derive_lifecycle_status(v_received_date)
  end;
  v_box.order_date := v_order_date;
  v_box.received_date := v_received_date;
  v_box.initial_weight_lbs := v_resolved_initial_weight;
  v_box.last_roll_weight_lbs := v_resolved_last_roll_weight;
  v_box.last_weighed_date := v_resolved_last_weighed_date;
  v_box.film_key := v_film_key;
  v_box.core_type := v_resolved_core_type;
  v_box.core_weight_lbs := v_resolved_core_weight;
  v_box.lf_weight_lbs_per_ft := v_resolved_lf_weight;
  v_box.purchase_cost := nullif(app_api.trim_text(p_payload->>'purchaseCost'), '')::numeric;
  v_box.notes := app_api.trim_text(p_payload->>'notes');
  v_box.has_ever_been_checked_out := coalesce(v_existing.has_ever_been_checked_out, false);
  v_box.last_checkout_job := coalesce(v_existing.last_checkout_job, '');
  v_box.last_checkout_date := v_existing.last_checkout_date;
  v_box.zeroed_date := null;
  v_box.zeroed_reason := '';
  v_box.zeroed_by := '';

  return jsonb_build_object(
    'box', to_jsonb(v_box),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function public.api_boxes_delete(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_box app.boxes;
  v_active_allocation_count integer := 0;
  v_link_count integer := 0;
  v_log_id text;
  v_reason text := coalesce(nullif(app_api.trim_text(p_payload->>'reason'), ''), 'Deleted from box details.');
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_box
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_box.status = 'CHECKED_OUT' then
    perform app_api.raise_http(400, 'Checked-out boxes cannot be deleted. Check the box in or zero it out first.');
  end if;

  select count(*)
  into v_active_allocation_count
  from app.allocations a
  where a.org_id = p_org_id
    and a.box_id = v_box.box_id
    and a.status = 'ACTIVE';

  if v_active_allocation_count > 0 then
    perform app_api.raise_http(400, 'Boxes with active allocations cannot be deleted. Resolve the allocations first.');
  end if;

  select count(*)
  into v_link_count
  from app.film_order_box_links l
  where l.org_id = p_org_id
    and l.box_id = v_box.box_id;

  if v_link_count > 0 then
    perform app_api.raise_http(400, 'Boxes linked to film orders cannot be deleted. Resolve the linked film order first.');
  end if;

  perform app_api.delete_box(p_org_id, v_box.box_id);
  v_log_id := app_api.append_audit_entry(
    p_org_id,
    'DELETE_BOX',
    v_box.box_id,
    app_api.public_box_json(v_box),
    null,
    p_actor,
    v_reason
  );

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', '[]'::jsonb
  );
end;
$$;

grant execute on function public.api_boxes_delete(uuid, text, jsonb) to service_role;

create or replace function app_api.normalize_core_type(p_value text, p_allow_blank boolean default false)
returns text
language plpgsql
immutable
as $$
declare
  v_trimmed text := app_api.trim_text(p_value);
  v_normalized text := lower(v_trimmed);
begin
  if v_trimmed = '' then
    if p_allow_blank then
      return '';
    end if;

    perform app_api.raise_http(400, 'CoreType is required.');
  end if;

  if v_normalized = 'white' then
    return 'White';
  end if;

  if v_normalized = 'red' then
    return 'Red';
  end if;

  if v_normalized = 'cardboard' then
    return 'Cardboard';
  end if;

  if v_normalized in ('thick cardboard', 'thick-cardboard', 'thick_cardboard', 'thickcardboard') then
    return 'Thick Cardboard';
  end if;

  perform app_api.raise_http(400, 'CoreType must be White, Red, Cardboard, or Thick Cardboard.');
  return '';
end;
$$;

create or replace function app_api.derive_core_weight_lbs(p_core_type text, p_width_in numeric)
returns numeric
language sql
immutable
as $$
  select round(
    (
      case app_api.normalize_core_type(p_core_type, false)
        when 'White' then 2::numeric
        when 'Red' then 1.85::numeric
        when 'Cardboard' then 2.05::numeric
        when 'Thick Cardboard' then 6.15::numeric
      end / 72::numeric
    ) * p_width_in,
    4
  );
$$;

create or replace function app_api.normalize_core_type(p_value text, p_allow_blank boolean default false)
returns text
language plpgsql
immutable
as $$
declare
  v_trimmed text := app_api.trim_text(p_value);
  v_normalized text := lower(v_trimmed);
begin
  if v_trimmed = '' then
    if p_allow_blank then
      return '';
    end if;

    perform app_api.raise_http(400, 'CoreType is required.');
  end if;

  if v_normalized = 'white' then
    return 'White';
  end if;

  if v_normalized = 'red' then
    return 'Red';
  end if;

  if v_normalized = 'cardboard' then
    return 'Cardboard';
  end if;

  if v_normalized in ('thick cardboard', 'thick-cardboard', 'thick_cardboard', 'thickcardboard') then
    return 'Thick Cardboard';
  end if;

  if v_normalized in (
    'security 1/4" cardboard',
    'security 1/4 cardboard',
    'security 1-4" cardboard',
    'security 1-4 cardboard'
  ) then
    return 'SECURITY 1/4" Cardboard';
  end if;

  perform app_api.raise_http(
    400,
    'CoreType must be White, Red, Cardboard, Thick Cardboard, or SECURITY 1/4" Cardboard.'
  );
  return '';
end;
$$;

create or replace function app_api.derive_core_weight_lbs(p_core_type text, p_width_in numeric)
returns numeric
language sql
immutable
as $$
  select round(
    (
      case app_api.normalize_core_type(p_core_type, false)
        when 'White' then 2::numeric
        when 'Red' then 1.85::numeric
        when 'Cardboard' then 2.05::numeric
        when 'Thick Cardboard' then 6.15::numeric
        when 'SECURITY 1/4" Cardboard' then 11.6::numeric
      end / 72::numeric
    ) * p_width_in,
    4
  );
$$;

create or replace function app_api.normalize_core_type(p_value text, p_allow_blank boolean default false)
returns text
language plpgsql
immutable
as $$
declare
  v_trimmed text := app_api.trim_text(p_value);
  v_normalized text := lower(v_trimmed);
begin
  if v_trimmed = '' then
    if p_allow_blank then
      return '';
    end if;

    perform app_api.raise_http(400, 'CoreType is required.');
  end if;

  if v_normalized in ('white', 'white plastic', 'whiteplastic') then
    return 'White plastic';
  end if;

  if v_normalized in ('red', 'red plastic', 'redplastic') then
    return 'Red plastic';
  end if;

  if v_normalized in ('cardboard', 'cardboard 1/8"', 'cardboard 1/8', 'cardboard 1-8"', 'cardboard 1-8') then
    return 'Cardboard 1/8"';
  end if;

  if v_normalized in (
    'thick cardboard',
    'thick-cardboard',
    'thick_cardboard',
    'thickcardboard',
    'cardboard 3/4"',
    'cardboard 3/4',
    'cardboard 3-4"',
    'cardboard 3-4'
  ) then
    return 'Cardboard 3/4"';
  end if;

  if v_normalized in (
    'security 1/4" cardboard',
    'security 1/4 cardboard',
    'security 1-4" cardboard',
    'security 1-4 cardboard'
  ) then
    return 'SECURITY 1/4" Cardboard';
  end if;

  perform app_api.raise_http(
    400,
    'CoreType must be White plastic, Red plastic, Cardboard 1/8", Cardboard 3/4", or SECURITY 1/4" Cardboard.'
  );
  return '';
end;
$$;

create or replace function app_api.derive_core_weight_lbs(p_core_type text, p_width_in numeric)
returns numeric
language sql
immutable
as $$
  select round(
    (
      case app_api.normalize_core_type(p_core_type, false)
        when 'White plastic' then 2::numeric
        when 'Red plastic' then 1.85::numeric
        when 'Cardboard 1/8"' then 2.05::numeric
        when 'Cardboard 3/4"' then 6.15::numeric
        when 'SECURITY 1/4" Cardboard' then 11.6::numeric
      end / 72::numeric
    ) * p_width_in,
    4
  );
$$;

update app.boxes
set core_type = case
  when lower(app_api.trim_text(core_type)) in ('white', 'white plastic', 'whiteplastic') then 'White plastic'
  when lower(app_api.trim_text(core_type)) in ('red', 'red plastic', 'redplastic') then 'Red plastic'
  when lower(app_api.trim_text(core_type)) in ('cardboard', 'cardboard 1/8"', 'cardboard 1/8', 'cardboard 1-8"', 'cardboard 1-8') then 'Cardboard 1/8"'
  when lower(app_api.trim_text(core_type)) in ('thick cardboard', 'thick-cardboard', 'thick_cardboard', 'thickcardboard', 'cardboard 3/4"', 'cardboard 3/4', 'cardboard 3-4"', 'cardboard 3-4') then 'Cardboard 3/4"'
  when lower(app_api.trim_text(core_type)) in ('security 1/4" cardboard', 'security 1/4 cardboard', 'security 1-4" cardboard', 'security 1-4 cardboard') then 'SECURITY 1/4" Cardboard'
  else core_type
end
where lower(app_api.trim_text(core_type)) in (
  'white',
  'white plastic',
  'whiteplastic',
  'red',
  'red plastic',
  'redplastic',
  'cardboard',
  'cardboard 1/8"',
  'cardboard 1/8',
  'cardboard 1-8"',
  'cardboard 1-8',
  'thick cardboard',
  'thick-cardboard',
  'thick_cardboard',
  'thickcardboard',
  'cardboard 3/4"',
  'cardboard 3/4',
  'cardboard 3-4"',
  'cardboard 3-4',
  'security 1/4" cardboard',
  'security 1/4 cardboard',
  'security 1-4" cardboard',
  'security 1-4 cardboard'
);

do $$
begin
  if to_regclass('app.film_data') is not null then
    update app.film_data
    set default_core_type = case
      when lower(app_api.trim_text(default_core_type)) in ('white', 'white plastic', 'whiteplastic') then 'White plastic'
      when lower(app_api.trim_text(default_core_type)) in ('red', 'red plastic', 'redplastic') then 'Red plastic'
      when lower(app_api.trim_text(default_core_type)) in ('cardboard', 'cardboard 1/8"', 'cardboard 1/8', 'cardboard 1-8"', 'cardboard 1-8') then 'Cardboard 1/8"'
      when lower(app_api.trim_text(default_core_type)) in ('thick cardboard', 'thick-cardboard', 'thick_cardboard', 'thickcardboard', 'cardboard 3/4"', 'cardboard 3/4', 'cardboard 3-4"', 'cardboard 3-4') then 'Cardboard 3/4"'
      when lower(app_api.trim_text(default_core_type)) in ('security 1/4" cardboard', 'security 1/4 cardboard', 'security 1-4" cardboard', 'security 1-4 cardboard') then 'SECURITY 1/4" Cardboard'
      else default_core_type
    end
    where lower(app_api.trim_text(default_core_type)) in (
      'white',
      'white plastic',
      'whiteplastic',
      'red',
      'red plastic',
      'redplastic',
      'cardboard',
      'cardboard 1/8"',
      'cardboard 1/8',
      'cardboard 1-8"',
      'cardboard 1-8',
      'thick cardboard',
      'thick-cardboard',
      'thick_cardboard',
      'thickcardboard',
      'cardboard 3/4"',
      'cardboard 3/4',
      'cardboard 3-4"',
      'cardboard 3-4',
      'security 1/4" cardboard',
      'security 1/4 cardboard',
      'security 1-4" cardboard',
      'security 1-4 cardboard'
    );
  end if;
end;
$$;


create table if not exists app.warehouses (
  org_id uuid not null references app.organizations(id) on delete cascade,
  code text not null,
  name text not null,
  box_id_prefix text not null default '',
  created_at timestamptz not null default now(),
  created_by text not null default '',
  updated_at timestamptz not null default now(),
  updated_by text not null default '',
  primary key (org_id, code)
);

alter table app.warehouses
  drop constraint if exists warehouses_code_format;
alter table app.warehouses
  add constraint warehouses_code_format check (
    code = upper(btrim(code))
    and code ~ '^[A-Z0-9]{2,8}$'
  );

alter table app.warehouses
  drop constraint if exists warehouses_name_format;
alter table app.warehouses
  add constraint warehouses_name_format check (
    btrim(name) <> ''
    and length(name) <= 80
  );

alter table app.warehouses
  drop constraint if exists warehouses_box_id_prefix_format;
alter table app.warehouses
  add constraint warehouses_box_id_prefix_format check (
    box_id_prefix = upper(btrim(box_id_prefix))
    and (box_id_prefix = '' or box_id_prefix ~ '^[A-Z0-9]{1,4}$')
  );

create unique index if not exists idx_warehouses_org_name_ci
  on app.warehouses (org_id, lower(name));

create unique index if not exists idx_warehouses_org_box_prefix_nonblank
  on app.warehouses (org_id, box_id_prefix)
  where box_id_prefix <> '';

create or replace function app_api.ensure_default_warehouses_for_org(
  p_org_id uuid,
  p_actor text default 'system'
)
returns void
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  if p_org_id is null then
    return;
  end if;

  insert into app.warehouses (
    org_id,
    code,
    name,
    box_id_prefix,
    created_by,
    updated_by
  )
  values
    (p_org_id, 'IL', 'Wauconda Illinois', '', app_api.trim_text(p_actor), app_api.trim_text(p_actor)),
    (p_org_id, 'MS', 'Ridgeland Mississippi', 'M', app_api.trim_text(p_actor), app_api.trim_text(p_actor))
  on conflict (org_id, code) do update set
    name = excluded.name,
    box_id_prefix = excluded.box_id_prefix,
    updated_at = now(),
    updated_by = excluded.updated_by;
end;
$$;

create or replace function app_api.seed_default_warehouses_for_new_org()
returns trigger
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  perform app_api.ensure_default_warehouses_for_org(new.id, 'org-bootstrap');
  return new;
end;
$$;

drop trigger if exists trg_seed_default_warehouses on app.organizations;
create trigger trg_seed_default_warehouses
after insert on app.organizations
for each row
execute function app_api.seed_default_warehouses_for_new_org();

do $$
declare
  v_org app.organizations;
begin
  for v_org in
    select *
    from app.organizations
  loop
    perform app_api.ensure_default_warehouses_for_org(v_org.id, 'migration-0017');
  end loop;
end;
$$;

