create or replace function import.warehouse_prefix_v2_preflight(target_org_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, app, import, app_api
as $$
declare
  v_rename_candidates integer := 0;
  v_duplicate_target_box_ids integer := 0;
  v_existing_target_collisions integer := 0;
  v_legacy_warehouse_rows integer := 0;
  v_total_boxes integer := 0;
  v_collision_sample text := '';
begin
  if target_org_id is null then
    raise exception 'target_org_id is required';
  end if;

  if not exists (select 1 from app.organizations o where o.id = target_org_id) then
    raise exception 'Organization % does not exist in app.organizations', target_org_id;
  end if;

  drop table if exists pg_temp.tmp_prefix_v2_box_map;
  create temporary table tmp_prefix_v2_box_map (
    old_box_id text primary key,
    new_box_id text not null
  ) on commit drop;

  insert into tmp_prefix_v2_box_map (old_box_id, new_box_id)
  select
    b.box_id,
    case
      when b.box_id like 'IL-%' then 'IL1-' || substr(b.box_id, 4)
      when b.box_id ~ '^M[0-9A-Z]+$' then 'MS1-' || substr(b.box_id, 2)
      else b.box_id
    end as new_box_id
  from app.boxes b
  where b.org_id = target_org_id
    and (
      b.box_id like 'IL-%'
      or b.box_id ~ '^M[0-9A-Z]+$'
    );

  select count(*) into v_rename_candidates from tmp_prefix_v2_box_map;

  select count(*)
  into v_duplicate_target_box_ids
  from (
    select m.new_box_id
    from tmp_prefix_v2_box_map m
    group by m.new_box_id
    having count(*) > 1
  ) d;

  select count(*)
  into v_existing_target_collisions
  from tmp_prefix_v2_box_map m
  join app.boxes b
    on b.org_id = target_org_id
   and b.box_id = m.new_box_id
   and b.box_id <> m.old_box_id;

  select count(*)
  into v_legacy_warehouse_rows
  from app.warehouses w
  where w.org_id = target_org_id
    and w.code in ('IL', 'MS');

  select count(*)
  into v_total_boxes
  from app.boxes b
  where b.org_id = target_org_id;

  if v_duplicate_target_box_ids > 0 or v_existing_target_collisions > 0 then
    select string_agg(format('%s->%s', x.old_box_id, x.new_box_id), ', ')
    into v_collision_sample
    from (
      select m.old_box_id, m.new_box_id
      from tmp_prefix_v2_box_map m
      left join app.boxes b
        on b.org_id = target_org_id
       and b.box_id = m.new_box_id
       and b.box_id <> m.old_box_id
      where b.box_id is not null
         or m.new_box_id in (
           select m2.new_box_id
           from tmp_prefix_v2_box_map m2
           group by m2.new_box_id
           having count(*) > 1
         )
      order by m.old_box_id
      limit 20
    ) x;
  end if;

  return jsonb_build_object(
    'org_id', target_org_id,
    'total_boxes', v_total_boxes,
    'rename_candidates', v_rename_candidates,
    'alias_rows_to_create', v_rename_candidates,
    'legacy_warehouse_rows', v_legacy_warehouse_rows,
    'duplicate_target_box_ids', v_duplicate_target_box_ids,
    'existing_target_collisions', v_existing_target_collisions,
    'collision_sample', coalesce(v_collision_sample, '')
  );
end;
$$;

create or replace function import.migrate_org_warehouse_prefix_v2(
  target_org_id uuid,
  actor text default 'migration',
  alias_days integer default 90
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, import, app_api
as $$
declare
  v_preflight jsonb;
  v_rename_count integer := 0;
  v_alias_upserted integer := 0;
  v_boxes_warehouse_updated integer := 0;
  v_jobs_warehouse_updated integer := 0;
  v_film_orders_warehouse_updated integer := 0;
  v_allocations_warehouse_updated integer := 0;
  v_roll_log_warehouse_updated integer := 0;
  v_allocations_box_updated integer := 0;
  v_links_box_updated integer := 0;
  v_roll_box_updated integer := 0;
  v_audit_box_updated integer := 0;
  v_film_orders_source_updated integer := 0;
  v_film_catalog_source_updated integer := 0;
  v_boxes_box_id_updated integer := 0;
  v_deleted_legacy_warehouses integer := 0;
begin
  if target_org_id is null then
    raise exception 'target_org_id is required';
  end if;

  if alias_days is null or alias_days <= 0 then
    raise exception 'alias_days must be greater than zero';
  end if;

  v_preflight := import.warehouse_prefix_v2_preflight(target_org_id);
  if coalesce((v_preflight->>'duplicate_target_box_ids')::integer, 0) > 0
     or coalesce((v_preflight->>'existing_target_collisions')::integer, 0) > 0 then
    raise exception
      'Warehouse Prefix V2 migration blocked by BoxID collisions. Sample: %',
      nullif(v_preflight->>'collision_sample', '');
  end if;

  drop table if exists pg_temp.tmp_prefix_v2_box_map;
  create temporary table tmp_prefix_v2_box_map (
    old_box_id text primary key,
    new_box_id text not null
  ) on commit drop;

  insert into tmp_prefix_v2_box_map (old_box_id, new_box_id)
  select
    b.box_id,
    case
      when b.box_id like 'IL-%' then 'IL1-' || substr(b.box_id, 4)
      when b.box_id ~ '^M[0-9A-Z]+$' then 'MS1-' || substr(b.box_id, 2)
      else b.box_id
    end as new_box_id
  from app.boxes b
  where b.org_id = target_org_id
    and (
      b.box_id like 'IL-%'
      or b.box_id ~ '^M[0-9A-Z]+$'
    );

  select count(*) into v_rename_count from tmp_prefix_v2_box_map;

  insert into app.warehouses (
    org_id,
    code,
    name,
    box_id_prefix,
    created_by,
    updated_by
  )
  values
    (target_org_id, 'IL1', 'Wauconda IL1', 'IL1', app_api.trim_text(actor), app_api.trim_text(actor)),
    (target_org_id, 'MS1', 'Ridgeland MS1', 'MS1', app_api.trim_text(actor), app_api.trim_text(actor))
  on conflict (org_id, code) do update set
    name = excluded.name,
    box_id_prefix = excluded.box_id_prefix,
    updated_at = now(),
    updated_by = excluded.updated_by;

  update app.boxes b
  set warehouse = case
      when b.warehouse = 'IL' then 'IL1'
      when b.warehouse = 'MS' then 'MS1'
      else b.warehouse
    end
  where b.org_id = target_org_id
    and b.warehouse in ('IL', 'MS');
  get diagnostics v_boxes_warehouse_updated = row_count;

  update app.jobs j
  set warehouse = case
      when j.warehouse = 'IL' then 'IL1'
      when j.warehouse = 'MS' then 'MS1'
      else j.warehouse
    end
  where j.org_id = target_org_id
    and j.warehouse in ('IL', 'MS');
  get diagnostics v_jobs_warehouse_updated = row_count;

  update app.film_orders f
  set warehouse = case
      when f.warehouse = 'IL' then 'IL1'
      when f.warehouse = 'MS' then 'MS1'
      else f.warehouse
    end
  where f.org_id = target_org_id
    and f.warehouse in ('IL', 'MS');
  get diagnostics v_film_orders_warehouse_updated = row_count;

  update app.allocations a
  set warehouse = case
      when a.warehouse = 'IL' then 'IL1'
      when a.warehouse = 'MS' then 'MS1'
      else a.warehouse
    end
  where a.org_id = target_org_id
    and a.warehouse in ('IL', 'MS');
  get diagnostics v_allocations_warehouse_updated = row_count;

  update app.roll_weight_log r
  set warehouse = case
      when r.warehouse = 'IL' then 'IL1'
      when r.warehouse = 'MS' then 'MS1'
      else r.warehouse
    end
  where r.org_id = target_org_id
    and r.warehouse in ('IL', 'MS');
  get diagnostics v_roll_log_warehouse_updated = row_count;

  update app.allocations a
  set box_id = m.new_box_id
  from tmp_prefix_v2_box_map m
  where a.org_id = target_org_id
    and a.box_id = m.old_box_id;
  get diagnostics v_allocations_box_updated = row_count;

  update app.film_order_box_links l
  set box_id = m.new_box_id
  from tmp_prefix_v2_box_map m
  where l.org_id = target_org_id
    and l.box_id = m.old_box_id;
  get diagnostics v_links_box_updated = row_count;

  update app.roll_weight_log r
  set box_id = m.new_box_id
  from tmp_prefix_v2_box_map m
  where r.org_id = target_org_id
    and r.box_id = m.old_box_id;
  get diagnostics v_roll_box_updated = row_count;

  update app.audit_log a
  set box_id = m.new_box_id
  from tmp_prefix_v2_box_map m
  where a.org_id = target_org_id
    and a.box_id = m.old_box_id;
  get diagnostics v_audit_box_updated = row_count;

  update app.film_orders f
  set source_box_id = m.new_box_id
  from tmp_prefix_v2_box_map m
  where f.org_id = target_org_id
    and f.source_box_id = m.old_box_id;
  get diagnostics v_film_orders_source_updated = row_count;

  update app.film_catalog f
  set source_box_id = m.new_box_id,
      updated_at = now()
  from tmp_prefix_v2_box_map m
  where f.org_id = target_org_id
    and f.source_box_id = m.old_box_id;
  get diagnostics v_film_catalog_source_updated = row_count;

  update app.boxes b
  set box_id = m.new_box_id,
      updated_at = now()
  from tmp_prefix_v2_box_map m
  where b.org_id = target_org_id
    and b.box_id = m.old_box_id;
  get diagnostics v_boxes_box_id_updated = row_count;

  insert into app.box_id_aliases (
    org_id,
    old_box_id,
    canonical_box_id,
    expires_at,
    created_by,
    updated_by
  )
  select
    target_org_id,
    m.old_box_id,
    m.new_box_id,
    now() + make_interval(days => alias_days),
    app_api.trim_text(actor),
    app_api.trim_text(actor)
  from tmp_prefix_v2_box_map m
  on conflict (org_id, old_box_id) do update set
    canonical_box_id = excluded.canonical_box_id,
    expires_at = excluded.expires_at,
    updated_at = now(),
    updated_by = excluded.updated_by;
  get diagnostics v_alias_upserted = row_count;

  delete from app.warehouses w
  where w.org_id = target_org_id
    and w.code in ('IL', 'MS')
    and not exists (
      select 1 from app.boxes b where b.org_id = w.org_id and b.warehouse = w.code
    )
    and not exists (
      select 1 from app.jobs j where j.org_id = w.org_id and j.warehouse = w.code
    )
    and not exists (
      select 1 from app.film_orders f where f.org_id = w.org_id and f.warehouse = w.code
    )
    and not exists (
      select 1 from app.allocations a where a.org_id = w.org_id and a.warehouse = w.code
    )
    and not exists (
      select 1 from app.roll_weight_log r where r.org_id = w.org_id and r.warehouse = w.code
    );
  get diagnostics v_deleted_legacy_warehouses = row_count;

  return jsonb_build_object(
    'org_id', target_org_id,
    'alias_days', alias_days,
    'preflight', v_preflight,
    'rename_candidates', v_rename_count,
    'aliases_upserted', v_alias_upserted,
    'warehouse_updates', jsonb_build_object(
      'boxes', v_boxes_warehouse_updated,
      'jobs', v_jobs_warehouse_updated,
      'film_orders', v_film_orders_warehouse_updated,
      'allocations', v_allocations_warehouse_updated,
      'roll_weight_log', v_roll_log_warehouse_updated
    ),
    'box_id_updates', jsonb_build_object(
      'boxes', v_boxes_box_id_updated,
      'allocations', v_allocations_box_updated,
      'film_order_box_links', v_links_box_updated,
      'roll_weight_log', v_roll_box_updated,
      'audit_log', v_audit_box_updated,
      'film_orders_source_box_id', v_film_orders_source_updated,
      'film_catalog_source_box_id', v_film_catalog_source_updated
    ),
    'deleted_legacy_warehouses', v_deleted_legacy_warehouses
  );
end;
$$;

create or replace function import.canonical_box_id(
  target_org_id uuid,
  warehouse_code text,
  raw_box_id text
)
returns text
language plpgsql
stable
security definer
set search_path = public, app, import
as $$
declare
  v_box_id text := upper(btrim(coalesce(raw_box_id, '')));
  v_warehouse text := upper(btrim(coalesce(warehouse_code, '')));
  v_prefix text := '';
begin
  if v_box_id = '' then
    return '';
  end if;

  -- Canonical v2 prefix format.
  if v_box_id ~ '^[A-Z]{2}[1-9][0-9]*-.+' then
    return v_box_id;
  end if;

  -- Legacy IL and legacy M forms.
  if v_box_id like 'IL-%' then
    return 'IL1-' || substr(v_box_id, 4);
  end if;

  if v_box_id ~ '^M[0-9A-Z]+$' then
    return 'MS1-' || substr(v_box_id, 2);
  end if;

  -- Preserve other already-prefixed forms.
  if v_box_id ~ '^[A-Z0-9]{2,8}-.+' then
    return v_box_id;
  end if;

  if target_org_id is not null and v_warehouse <> '' then
    select coalesce(w.box_id_prefix, '')
    into v_prefix
    from app.warehouses w
    where w.org_id = target_org_id
      and w.code = v_warehouse
    limit 1;
  end if;

  if v_prefix <> '' then
    return v_prefix || '-' || v_box_id;
  end if;

  if v_warehouse = 'IL' then
    return 'IL1-' || v_box_id;
  end if;

  if v_warehouse = 'MS' then
    return 'MS1-' || v_box_id;
  end if;

  return v_box_id;
end;
$$;

-- Normalize trailing-letter BoxIDs (e.g., IL1-3194A -> IL1-3194)
-- and block future writes that reintroduce that format.

create or replace function app_api.normalize_box_id_trailing_letters(
  p_box_id text,
  p_field_name text default 'BoxID'
)
returns text
language plpgsql
immutable
set search_path = public, app, app_api
as $$
declare
  v_box_id text := upper(app_api.require_text(p_box_id, p_field_name));
begin
  if v_box_id ~ '^[A-Z]{2}[1-9][0-9]*-[0-9]+[A-Z]+$' then
    return regexp_replace(v_box_id, '^([A-Z]{2}[1-9][0-9]*-[0-9]+)[A-Z]+$', '\1');
  end if;
  return v_box_id;
end;
$$;

create or replace function app_api.resolve_box_id_alias(
  p_org_id uuid,
  p_box_id text,
  p_reference_time timestamptz default now()
)
returns text
language plpgsql
stable
security definer
set search_path = public, app, app_api
as $$
declare
  v_input text := app_api.normalize_box_id_trailing_letters(p_box_id, 'BoxID');
  v_resolved text;
begin
  if p_org_id is null then
    perform app_api.raise_http(400, 'Organization is required.');
  end if;

  select a.canonical_box_id
  into v_resolved
  from app.box_id_aliases a
  where a.org_id = p_org_id
    and a.old_box_id = v_input
    and a.expires_at >= coalesce(p_reference_time, now())
  order by a.expires_at desc
  limit 1;

  return coalesce(v_resolved, v_input);
end;
$$;

create or replace function public.api_acl_boxes_add(p_org_id uuid, p_actor text, p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_box_id text;
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'write');
  v_box_id := app_api.normalize_box_id_trailing_letters(
    app_api.require_text(v_payload->>'boxId', 'BoxID'),
    'BoxID'
  );
  v_payload := jsonb_set(v_payload, '{boxId}', to_jsonb(v_box_id), true);
  return public.api_boxes_add(p_org_id, p_actor, v_payload);
end;
$$;

create or replace function import.canonical_box_id(
  target_org_id uuid,
  warehouse_code text,
  raw_box_id text
)
returns text
language plpgsql
security definer
set search_path = public, app, import, app_api
as $$
declare
  v_box_id text := upper(btrim(coalesce(raw_box_id, '')));
  v_warehouse text := upper(btrim(coalesce(warehouse_code, '')));
  v_prefix text := '';
begin
  if v_box_id = '' then
    raise exception 'BoxID is required';
  end if;

  if v_box_id like 'IL-%' then
    v_box_id := 'IL1-' || substr(v_box_id, 4);
  elsif v_box_id ~ '^M[0-9A-Z]+$' then
    v_box_id := 'MS1-' || substr(v_box_id, 2);
  end if;

  v_box_id := app_api.normalize_box_id_trailing_letters(v_box_id, 'BoxID');

  if v_box_id ~ '^[A-Z]{2}[1-9][0-9]*-.+' then
    return v_box_id;
  end if;

  if v_box_id ~ '^[A-Z0-9]{2,8}-.+' then
    return v_box_id;
  end if;

  if target_org_id is not null and v_warehouse <> '' then
    select coalesce(w.box_id_prefix, '')
    into v_prefix
    from app.warehouses w
    where w.org_id = target_org_id
      and w.code = v_warehouse
    limit 1;
  end if;

  if v_prefix <> '' then
    return app_api.normalize_box_id_trailing_letters(v_prefix || '-' || v_box_id, 'BoxID');
  end if;

  if v_warehouse = 'IL' then
    return app_api.normalize_box_id_trailing_letters('IL1-' || v_box_id, 'BoxID');
  end if;

  if v_warehouse = 'MS' then
    return app_api.normalize_box_id_trailing_letters('MS1-' || v_box_id, 'BoxID');
  end if;

  return v_box_id;
end;
$$;

alter table app.boxes
  drop constraint if exists boxes_no_trailing_letter_suffix;
alter table app.boxes
  add constraint boxes_no_trailing_letter_suffix check (
    box_id !~ '^[A-Z]{2}[1-9][0-9]*-[0-9]+[A-Z]+$'
  ) not valid;

-- Canonicalize legacy manufacturer aliases in lookup-key paths.
-- This keeps requirement matching stable even when legacy labels are submitted.

create or replace function app_api.canonical_manufacturer_label(p_value text)
returns text
language sql
immutable
as $$
  select
    case lower(app_api.normalize_collapsed_catalog_label(p_value))
      when '3m' then '3M Solar'
      when 'avery' then 'Avery Dennison'
      when 'solar guard' then 'Solar Gard'
      else app_api.normalize_collapsed_catalog_label(p_value)
    end;
$$;

create or replace function app_api.normalize_catalog_manufacturer_lookup_key(p_value text)
returns text
language sql
immutable
as $$
  select lower(app_api.canonical_manufacturer_label(p_value));
$$;

create or replace function app_api.normalize_job_requirement_lookup_key(
  p_manufacturer text,
  p_film_name text,
  p_width_in numeric
)
returns text
language sql
immutable
as $$
  select app_api.normalize_catalog_manufacturer_lookup_key(p_manufacturer)
    || '|' || app_api.normalize_catalog_lookup_key(p_film_name)
    || '|' || round(coalesce(p_width_in, 0)::numeric, 4)::text;
$$;

create or replace function app_api.requirement_rows_from_payload(p_requirements jsonb)
returns table (
  manufacturer text,
  film_name text,
  width_in numeric,
  required_feet integer
)
language plpgsql
stable
as $$
declare
  v_value jsonb;
  v_width_in numeric;
  v_required_feet integer;
begin
  if p_requirements is not null and jsonb_typeof(p_requirements) = 'array' then
    for v_value in
      select value
      from jsonb_array_elements(p_requirements)
    loop
      perform app_api.require_text(v_value->>'manufacturer', 'Requirements[].Manufacturer');
      perform app_api.require_text(v_value->>'filmName', 'Requirements[].FilmName');
      v_width_in := nullif(app_api.trim_text(v_value->>'widthIn'), '')::numeric;
      v_required_feet := floor(nullif(app_api.trim_text(v_value->>'requiredFeet'), '')::numeric);

      if v_width_in is null or v_width_in <= 0 then
        perform app_api.raise_http(400, 'Requirements[].WidthIn must be greater than zero.');
      end if;

      if v_required_feet is null or v_required_feet <= 0 then
        perform app_api.raise_http(400, 'Requirements[].RequiredFeet must be greater than zero.');
      end if;
    end loop;
  end if;

  return query
  with normalized as (
    select
      app_api.canonical_manufacturer_label(value->>'manufacturer') as manufacturer,
      app_api.normalize_collapsed_catalog_label(value->>'filmName') as film_name,
      (nullif(app_api.trim_text(value->>'widthIn'), '')::numeric) as width_in,
      floor(nullif(app_api.trim_text(value->>'requiredFeet'), '')::numeric)::integer as required_feet
    from jsonb_array_elements(
      case
        when p_requirements is null or jsonb_typeof(p_requirements) <> 'array' then '[]'::jsonb
        else p_requirements
      end
    )
  )
  select
    n.manufacturer,
    n.film_name,
    n.width_in,
    sum(n.required_feet)::integer as required_feet
  from normalized n
  group by n.manufacturer, n.film_name, n.width_in
  order by lower(n.manufacturer), lower(n.film_name), n.width_in;
end;
$$;

-- Extend canonical manufacturer aliases so Fasara is normalized to 3M Fasara.

create or replace function app_api.canonical_manufacturer_label(p_value text)
returns text
language sql
immutable
as $$
  select
    case lower(app_api.normalize_collapsed_catalog_label(p_value))
      when '3m' then '3M Solar'
      when 'fasara' then '3M Fasara'
      when '3m fasara' then '3M Fasara'
      when 'avery' then 'Avery Dennison'
      when 'solar guard' then 'Solar Gard'
      else app_api.normalize_collapsed_catalog_label(p_value)
    end;
$$;

-- Film-name canonical alias storage + ACL read helper.
-- Supports write-time canonicalization without forcing clients to submit only canonical labels.

create table if not exists app.film_name_aliases (
  org_id uuid not null references app.organizations(id) on delete cascade,
  manufacturer_lookup_key text not null,
  old_film_name_lookup_key text not null,
  canonical_film_name text not null,
  created_at timestamptz not null default now(),
  created_by text not null default '',
  updated_at timestamptz not null default now(),
  updated_by text not null default '',
  primary key (org_id, manufacturer_lookup_key, old_film_name_lookup_key)
);

alter table app.film_name_aliases
  drop constraint if exists film_name_aliases_lookup_keys_not_blank;
alter table app.film_name_aliases
  add constraint film_name_aliases_lookup_keys_not_blank check (
    manufacturer_lookup_key = lower(btrim(manufacturer_lookup_key))
    and old_film_name_lookup_key = lower(btrim(old_film_name_lookup_key))
    and btrim(manufacturer_lookup_key) <> ''
    and btrim(old_film_name_lookup_key) <> ''
  );

alter table app.film_name_aliases
  drop constraint if exists film_name_aliases_canonical_not_blank;
alter table app.film_name_aliases
  add constraint film_name_aliases_canonical_not_blank check (
    app_api.normalize_catalog_lookup_key(canonical_film_name) <> ''
    and app_api.normalize_catalog_lookup_key(canonical_film_name) <> old_film_name_lookup_key
  );

create index if not exists idx_film_name_aliases_org_manufacturer
  on app.film_name_aliases (org_id, manufacturer_lookup_key);

create index if not exists idx_film_name_aliases_org_canonical
  on app.film_name_aliases (org_id, manufacturer_lookup_key, lower(canonical_film_name));

create or replace function app_api.resolve_canonical_film_name(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns text
language plpgsql
stable
security definer
set search_path = public, app, app_api
as $$
declare
  v_manufacturer_lookup_key text := app_api.normalize_catalog_manufacturer_lookup_key(p_manufacturer);
  v_film_name_lookup_key text := app_api.normalize_catalog_lookup_key(p_film_name);
  v_canonical text;
begin
  select a.canonical_film_name
  into v_canonical
  from app.film_name_aliases a
  where a.org_id = p_org_id
    and a.manufacturer_lookup_key = v_manufacturer_lookup_key
    and a.old_film_name_lookup_key = v_film_name_lookup_key
  limit 1;

  if v_canonical is not null then
    return app_api.normalize_collapsed_catalog_label(v_canonical);
  end if;

  return app_api.normalize_collapsed_catalog_label(p_film_name);
end;
$$;

create or replace function public.api_acl_list_film_name_aliases(p_org_id uuid)
returns table (
  manufacturer_lookup_key text,
  old_film_name_lookup_key text,
  canonical_film_name text
)
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'read');

  return query
  select
    a.manufacturer_lookup_key,
    a.old_film_name_lookup_key,
    a.canonical_film_name
  from app.film_name_aliases a
  where a.org_id = p_org_id
  order by a.manufacturer_lookup_key, a.old_film_name_lookup_key;
end;
$$;

select app_api.grant_execute_if_exists('public.api_acl_list_film_name_aliases(uuid)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_list_film_name_aliases(uuid)', 'service_role');

-- Dedicated caulk inventory subsystem (separate from film boxes).
