select app_api.grant_execute_if_exists('public.api_acl_caulk_mutate_stock(uuid, text, jsonb)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_caulk_transfer_stock(uuid, text, jsonb)', 'service_role');

-- Adds first-class allocation kind support and extra-allocation payload handling.

do $$
begin
  if not exists (
    select 1
    from pg_type t
    join pg_namespace n on n.oid = t.typnamespace
    where n.nspname = 'app'
      and t.typname = 'allocation_kind'
  ) then
    create type app.allocation_kind as enum ('REQUIREMENT', 'EXTRA');
  end if;
end
$$;

alter table app.allocations
  add column if not exists allocation_kind app.allocation_kind not null default 'REQUIREMENT';

update app.allocations
set allocation_kind = 'REQUIREMENT'
where allocation_kind is null;

create or replace function app_api.save_allocation(p_allocation app.allocations)
returns app.allocations
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_row app.allocations;
begin
  insert into app.allocations (
    id,
    org_id,
    allocation_id,
    box_id,
    job_id,
    job_number,
    warehouse,
    job_date,
    allocated_feet,
    status,
    created_at,
    created_by,
    resolved_at,
    resolved_by,
    notes,
    crew_leader,
    film_order_id,
    allocation_kind
  )
  values (
    coalesce(p_allocation.id, gen_random_uuid()),
    p_allocation.org_id,
    p_allocation.allocation_id,
    p_allocation.box_id,
    p_allocation.job_id,
    p_allocation.job_number,
    p_allocation.warehouse,
    p_allocation.job_date,
    p_allocation.allocated_feet,
    p_allocation.status,
    coalesce(p_allocation.created_at, now()),
    coalesce(p_allocation.created_by, ''),
    p_allocation.resolved_at,
    coalesce(p_allocation.resolved_by, ''),
    coalesce(p_allocation.notes, ''),
    coalesce(p_allocation.crew_leader, ''),
    coalesce(p_allocation.film_order_id, ''),
    coalesce(p_allocation.allocation_kind, 'REQUIREMENT'::app.allocation_kind)
  )
  on conflict (org_id, allocation_id) do update set
    box_id = excluded.box_id,
    job_id = excluded.job_id,
    job_number = excluded.job_number,
    warehouse = excluded.warehouse,
    job_date = excluded.job_date,
    allocated_feet = excluded.allocated_feet,
    status = excluded.status,
    created_at = excluded.created_at,
    created_by = excluded.created_by,
    resolved_at = excluded.resolved_at,
    resolved_by = excluded.resolved_by,
    notes = excluded.notes,
    crew_leader = excluded.crew_leader,
    film_order_id = excluded.film_order_id,
    allocation_kind = excluded.allocation_kind
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function app_api.create_allocation(
  p_org_id uuid,
  p_box app.boxes,
  p_job_context jsonb,
  p_allocated_feet integer,
  p_actor text,
  p_film_order_id text default '',
  p_allocation_kind text default 'REQUIREMENT'
)
returns app.allocations
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_allocation app.allocations;
  v_kind text := upper(app_api.trim_text(p_allocation_kind));
begin
  if v_kind = '' then
    v_kind := 'REQUIREMENT';
  end if;

  if v_kind not in ('REQUIREMENT', 'EXTRA') then
    perform app_api.raise_http(400, 'Allocation kind must be REQUIREMENT or EXTRA.');
  end if;

  v_allocation.id := gen_random_uuid();
  v_allocation.org_id := p_org_id;
  v_allocation.allocation_id := app_api.create_log_id();
  v_allocation.box_id := p_box.box_id;
  v_allocation.job_id := app_api.get_or_resolve_job_id(p_org_id, p_job_context->>'jobNumber');
  v_allocation.job_number := p_job_context->>'jobNumber';
  v_allocation.warehouse := p_box.warehouse;
  v_allocation.job_date := nullif(app_api.trim_text(p_job_context->>'jobDate'), '')::date;
  v_allocation.allocated_feet := p_allocated_feet;
  v_allocation.status := 'ACTIVE';
  v_allocation.created_at := now();
  v_allocation.created_by := app_api.trim_text(p_actor);
  v_allocation.resolved_at := null;
  v_allocation.resolved_by := '';
  v_allocation.notes := '';
  v_allocation.crew_leader := coalesce(p_job_context->>'crewLeader', '');
  v_allocation.film_order_id := app_api.trim_text(p_film_order_id);
  v_allocation.allocation_kind := v_kind::app.allocation_kind;

  return app_api.save_allocation(v_allocation);
end;
$$;

create or replace function public.api_allocations_apply(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_source app.boxes;
  v_candidate app.boxes;
  v_job_context jsonb;
  v_requested_feet integer := coalesce(floor(nullif(app_api.trim_text(p_payload->>'requestedFeet'), '')::numeric), 0);
  v_requested_width_in numeric := nullif(app_api.trim_text(p_payload->>'requestedWidthIn'), '')::numeric;
  v_remaining integer;
  v_source_suggested integer := 0;
  v_cross_warehouse boolean := coalesce((p_payload->>'crossWarehouse')::boolean, false);
  v_selected_box_ids text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'selectedSuggestionBoxIds', '[]'::jsonb))),
    array[]::text[]
  );
  v_extra_allocations jsonb := coalesce(p_payload->'extraAllocations', '[]'::jsonb);
  v_extra_entry jsonb;
  v_extra_box_id text;
  v_extra_feet integer;
  v_extra_processed_box_ids text[] := array[]::text[];
  v_allocation app.allocations;
  v_allocation_ids text[] := array[]::text[];
  v_film_order app.film_orders;
  v_conflict_count integer;
  v_job_warehouse text;
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_org_member(p_org_id);

  if v_requested_feet < 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be zero or greater.');
  end if;

  if coalesce(jsonb_typeof(v_extra_allocations), '') not in ('', 'array') then
    perform app_api.raise_http(400, 'extraAllocations must be an array.');
  end if;

  select *
  into v_source
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_source.status <> 'IN_STOCK' then
    perform app_api.raise_http(400, 'Only in-stock boxes can be allocated.');
  end if;

  if v_requested_width_in is null or v_requested_width_in <= 0 then
    v_requested_width_in := v_source.width_in;
  end if;

  if v_source.width_in < v_requested_width_in then
    perform app_api.raise_http(400, 'Source box width must meet or exceed the requested width.');
  end if;

  v_job_context := app_api.resolve_job_context(
    p_org_id,
    p_payload->>'jobNumber',
    p_payload->>'jobDate',
    p_payload->>'crewLeader'
  );

  if v_requested_feet > 0 then
    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_source.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count = 0 then
      v_source_suggested := least(v_source.feet_available, v_requested_feet);
    end if;
  end if;

  v_remaining := greatest(v_requested_feet - v_source_suggested, 0);

  if v_source_suggested > 0 then
    v_allocation := app_api.create_allocation(
      p_org_id,
      v_source,
      v_job_context,
      v_source_suggested,
      p_actor,
      '',
      'REQUIREMENT'
    );
    v_source.feet_available := greatest(v_source.feet_available - v_source_suggested, 0);
    v_source := app_api.save_box(v_source);
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end if;

  for v_candidate in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id <> v_source.box_id
      and b.status = 'IN_STOCK'
      and b.feet_available > 0
      and b.manufacturer = v_source.manufacturer
      and b.film_name = v_source.film_name
      and b.width_in = v_source.width_in
      and (v_cross_warehouse or b.warehouse = v_source.warehouse)
    order by coalesce(b.received_date, b.order_date, '9999-12-31'::date), b.box_id
    for update
  loop
    exit when v_remaining <= 0;

    if coalesce(array_length(v_selected_box_ids, 1), 0) > 0 and array_position(v_selected_box_ids, v_candidate.box_id) is null then
      continue;
    end if;

    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_candidate.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count > 0 then
      continue;
    end if;

    v_allocation := app_api.create_allocation(
      p_org_id,
      v_candidate,
      v_job_context,
      least(v_candidate.feet_available, v_remaining),
      p_actor,
      '',
      'REQUIREMENT'
    );
    v_candidate.feet_available := greatest(v_candidate.feet_available - v_allocation.allocated_feet, 0);
    perform app_api.save_box(v_candidate);
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
    v_remaining := v_remaining - v_allocation.allocated_feet;
  end loop;

  if coalesce(jsonb_typeof(v_extra_allocations), '') = 'array' then
    for v_extra_entry in
      select value
      from jsonb_array_elements(v_extra_allocations)
    loop
      if coalesce(jsonb_typeof(v_extra_entry), '') <> 'object' then
        perform app_api.raise_http(400, 'Each extra allocation entry must be an object.');
      end if;

      v_extra_box_id := app_api.require_text(v_extra_entry->>'boxId', 'extraAllocations[].boxId');
      v_extra_feet := floor(nullif(app_api.trim_text(v_extra_entry->>'allocatedFeet'), '')::numeric);

      if v_extra_feet is null or v_extra_feet <= 0 then
        perform app_api.raise_http(400, format('Extra allocation for box %s must be greater than zero.', v_extra_box_id));
      end if;

      if array_position(v_extra_processed_box_ids, v_extra_box_id) is not null then
        perform app_api.raise_http(400, format('Duplicate extra allocation entry for box %s.', v_extra_box_id));
      end if;

      select *
      into v_candidate
      from app.boxes b
      where b.org_id = p_org_id
        and b.box_id = v_extra_box_id
      for update;

      if not found then
        perform app_api.raise_http(404, format('Box not found: %s', v_extra_box_id));
      end if;

      if v_candidate.status <> 'IN_STOCK' then
        perform app_api.raise_http(400, format('Box %s is no longer allocatable.', v_candidate.box_id));
      end if;

      if v_candidate.manufacturer <> v_source.manufacturer
        or v_candidate.film_name <> v_source.film_name
        or v_candidate.width_in < v_requested_width_in then
        perform app_api.raise_http(
          400,
          format(
            'Extra box %s must match film and meet the requested width for this allocation.',
            v_candidate.box_id
          )
        );
      end if;

      if v_candidate.feet_available < v_extra_feet then
        perform app_api.raise_http(400, format('Box %s no longer has enough available LF.', v_candidate.box_id));
      end if;

      v_allocation := app_api.create_allocation(
        p_org_id,
        v_candidate,
        v_job_context,
        v_extra_feet,
        p_actor,
        '',
        'EXTRA'
      );
      v_candidate.feet_available := greatest(v_candidate.feet_available - v_extra_feet, 0);
      perform app_api.save_box(v_candidate);
      v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
      v_extra_processed_box_ids := array_append(v_extra_processed_box_ids, v_extra_box_id);
    end loop;
  end if;

  if v_requested_feet = 0 and coalesce(array_length(v_extra_processed_box_ids, 1), 0) = 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be greater than zero unless extraAllocations are provided.');
  end if;

  if v_remaining > 0 then
    if app_api.trim_text(p_payload->>'jobWarehouse') <> '' then
      v_job_warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'jobWarehouse', 'Job warehouse');
    else
      v_job_warehouse := v_source.warehouse;
    end if;

    v_film_order.id := gen_random_uuid();
    v_film_order.org_id := p_org_id;
    v_film_order.film_order_id := app_api.create_log_id();
    v_film_order.job_id := app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber');
    v_film_order.job_number := v_job_context->>'jobNumber';
    v_film_order.warehouse := v_job_warehouse;
    v_film_order.manufacturer := v_source.manufacturer;
    v_film_order.film_name := v_source.film_name;
    v_film_order.width_in := v_source.width_in;
    v_film_order.requested_feet := v_remaining;
    v_film_order.covered_feet := 0;
    v_film_order.ordered_feet := 0;
    v_film_order.remaining_to_order_feet := v_remaining;
    v_film_order.job_date := nullif(v_job_context->>'jobDate', '')::date;
    v_film_order.crew_leader := coalesce(v_job_context->>'crewLeader', '');
    v_film_order.status := 'FILM_ORDER';
    v_film_order.source_box_id := v_source.box_id;
    v_film_order.resolved_at := null;
    v_film_order.resolved_by := '';
    v_film_order.notes := format('Created from a shortage while trying to allocate %s LF.', v_requested_feet);
    v_film_order.created_at := now();
    v_film_order.created_by := app_api.trim_text(p_actor);
    v_film_order := app_api.save_film_order(v_film_order);
    v_warnings := app_api.push_warning(
      v_warnings,
      format('Film Order %s was created for the remaining %s LF.', v_film_order.film_order_id, v_remaining)
    );
  end if;

  return jsonb_build_object(
    'allocationIds', to_jsonb(v_allocation_ids),
    'filmOrderId', coalesce(v_film_order.film_order_id, ''),
    'remainingUncoveredFeet', greatest(v_remaining, 0),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function app_api.public_allocation_json(p_entry app.allocations)
returns jsonb
language sql
stable
as $$
  select jsonb_build_object(
    'allocationId', coalesce(p_entry.allocation_id, ''),
    'boxId', coalesce(p_entry.box_id, ''),
    'warehouse', coalesce(p_entry.warehouse::text, ''),
    'jobNumber', coalesce(p_entry.job_number, ''),
    'jobDate', coalesce(to_char(p_entry.job_date, 'YYYY-MM-DD'), ''),
    'crewLeader', coalesce(p_entry.crew_leader, ''),
    'allocatedFeet', p_entry.allocated_feet,
    'allocationKind', coalesce(p_entry.allocation_kind::text, 'REQUIREMENT'),
    'status', coalesce(p_entry.status::text, 'ACTIVE'),
    'createdAt', coalesce(to_char(p_entry.created_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), ''),
    'createdBy', coalesce(p_entry.created_by, ''),
    'resolvedAt', coalesce(to_char(p_entry.resolved_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), ''),
    'resolvedBy', coalesce(p_entry.resolved_by, ''),
    'filmOrderId', coalesce(p_entry.film_order_id, ''),
    'notes', coalesce(p_entry.notes, '')
  );
$$;

create or replace function app_api.member_permissions_for_user_json(p_org_id uuid, p_user_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, app, app_api
as $$
  select jsonb_build_object(
    'inventory', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'inventory'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'inventory'), true)),
      false
    ),
    'allocations', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'allocations'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'allocations'), true)),
      false
    ),
    'jobs', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'jobs'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'jobs'), true)),
      false
    ),
    'film_orders', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'film_orders'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'film_orders'), true)),
      false
    ),
    'activity_history', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'activity_history'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'activity_history'), true)),
      false
    ),
    'reports', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'reports'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'reports'), true)),
      false
    ),
    'access_management', app_api.feature_access_json(false, false)
  );
$$;

create or replace function app_api.require_effective_feature_access(
  p_org_id uuid,
  p_feature_area text,
  p_access_mode text
)
returns void
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_role text;
  v_allowed boolean := false;
begin
  if app_api.trim_text(p_access_mode) not in ('read', 'write') then
    perform app_api.raise_http(400, 'Feature access mode must be read or write.');
  end if;

  v_role := app_api.require_org_member_approved(p_org_id);
  perform app_api.ensure_general_feature_permissions(p_org_id, 'feature-access-check');

  if v_role = 'owner' then
    return;
  end if;

  if v_role = 'member' then
    if p_feature_area = 'access_management' then
      perform app_api.raise_http(403, 'Feature access denied.');
    end if;

    if p_feature_area <> all(app_api.member_feature_areas()) then
      perform app_api.raise_http(400, 'Unsupported feature area.');
    end if;

    if p_access_mode = 'write' then
      perform app_api.raise_http(403, 'Feature access denied.');
    end if;

    select coalesce(a.read_enabled, g.read_enabled, false)
    into v_allowed
    from app.general_feature_permissions g
    left join app.admin_feature_permissions a
      on a.org_id = g.org_id
     and a.admin_user_id = auth.uid()
     and a.feature_area = g.feature_area
    where g.org_id = p_org_id
      and g.feature_area = p_feature_area;
  elsif v_role = 'admin' then
    if p_feature_area <> all(app_api.admin_feature_areas()) then
      perform app_api.raise_http(400, 'Unsupported feature area.');
    end if;

    perform app_api.ensure_admin_feature_permissions(
      p_org_id,
      auth.uid(),
      true,
      'feature-access-check'
    );

    select
      case
        when p_access_mode = 'read' then a.read_enabled
        else a.write_enabled
      end
    into v_allowed
    from app.admin_feature_permissions a
    where a.org_id = p_org_id
      and a.admin_user_id = auth.uid()
      and a.feature_area = p_feature_area;
  else
    perform app_api.raise_http(403, 'Feature access denied.');
  end if;

  if not coalesce(v_allowed, false) then
    perform app_api.raise_http(403, 'Feature access denied.');
  end if;
end;
$$;

create or replace function public.api_update_user_feature_permissions(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_actor_role text;
  v_target_user_id uuid := nullif(app_api.trim_text(p_payload->>'userId'), '')::uuid;
  v_target_role text;
  v_feature text;
  v_read text;
begin
  v_actor_role := app_api.require_org_admin_or_owner(p_org_id);
  if v_actor_role = 'admin' then
    perform app_api.require_effective_feature_access(p_org_id, 'access_management', 'write');
  end if;

  if v_target_user_id is null then
    perform app_api.raise_http(400, 'userId is required.');
  end if;

  select m.role
  into v_target_role
  from app.organization_members m
  where m.org_id = p_org_id
    and m.user_id = v_target_user_id
  for update;

  if v_target_role is null then
    perform app_api.raise_http(404, 'Target user is not an organization member.');
  end if;

  if v_target_role <> 'member' then
    perform app_api.raise_http(400, 'Only member accounts can be changed from this page.');
  end if;

  perform app_api.ensure_general_feature_permissions(p_org_id, app_api.trim_text(p_actor));

  foreach v_feature in array app_api.member_feature_areas() loop
    if not ((p_payload->'permissions') ? v_feature) then
      continue;
    end if;

    v_read := lower(app_api.trim_text((p_payload->'permissions'->v_feature)->>'read'));

    insert into app.admin_feature_permissions (
      org_id,
      admin_user_id,
      feature_area,
      read_enabled,
      write_enabled,
      updated_at,
      updated_by
    )
    values (
      p_org_id,
      v_target_user_id,
      v_feature,
      coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = v_feature), true),
      false,
      now(),
      app_api.trim_text(p_actor)
    )
    on conflict (org_id, admin_user_id, feature_area) do nothing;

    update app.admin_feature_permissions a
    set
      read_enabled = case when v_read in ('true', 'false') then v_read::boolean else a.read_enabled end,
      write_enabled = false,
      updated_at = now(),
      updated_by = app_api.trim_text(p_actor)
    where a.org_id = p_org_id
      and a.admin_user_id = v_target_user_id
      and a.feature_area = v_feature;
  end loop;

  delete from app.admin_feature_permissions a
  where a.org_id = p_org_id
    and a.admin_user_id = v_target_user_id
    and a.feature_area = 'access_management';

  return app_api.member_permissions_for_user_json(p_org_id, v_target_user_id);
end;
$$;

update app.admin_feature_permissions a
set
  write_enabled = false,
  updated_at = now(),
  updated_by = '0027_member_read_only_permissions'
from app.organization_members m
where m.org_id = a.org_id
  and m.user_id = a.admin_user_id
  and m.role = 'member'
  and a.feature_area = any(app_api.member_feature_areas())
  and a.write_enabled is distinct from false;

delete from app.admin_feature_permissions a
using app.organization_members m
where m.org_id = a.org_id
  and m.user_id = a.admin_user_id
  and m.role = 'member'
  and a.feature_area = 'access_management';

create or replace function app_api.member_permissions_for_user_json(p_org_id uuid, p_user_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, app, app_api
as $$
  select jsonb_build_object(
    'inventory', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'inventory'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'inventory'), true)),
      false
    ),
    'allocations', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'allocations'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'allocations'), true)),
      false
    ),
    'jobs', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'jobs'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'jobs'), true)),
      false
    ),
    'film_orders', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'film_orders'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'film_orders'), true)),
      false
    ),
    'activity_history', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'activity_history'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'activity_history'), true)),
      false
    ),
    'reports', app_api.feature_access_json(
      coalesce((select a.read_enabled from app.admin_feature_permissions a where a.org_id = p_org_id and a.admin_user_id = p_user_id and a.feature_area = 'reports'), coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = 'reports'), true)),
      false
    ),
    'access_management', app_api.feature_access_json(false, false)
  );
$$;

create or replace function public.api_update_user_feature_permissions(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_actor_role text;
  v_target_user_id uuid := nullif(app_api.trim_text(p_payload->>'userId'), '')::uuid;
  v_target_role text;
  v_feature text;
  v_permissions jsonb;
  v_feature_payload jsonb;
  v_read text;
  v_read_enabled boolean;
  v_has_updates boolean := false;
begin
  v_actor_role := app_api.require_org_admin_or_owner(p_org_id);
  if v_actor_role = 'admin' then
    perform app_api.require_effective_feature_access(p_org_id, 'access_management', 'write');
  end if;

  if jsonb_typeof(coalesce(p_payload, 'null'::jsonb)) <> 'object' then
    perform app_api.raise_http(400, 'Payload must be a JSON object.');
  end if;

  if v_target_user_id is null then
    perform app_api.raise_http(400, 'userId is required.');
  end if;

  v_permissions := p_payload->'permissions';
  if jsonb_typeof(coalesce(v_permissions, 'null'::jsonb)) <> 'object' then
    perform app_api.raise_http(400, 'permissions must be an object keyed by feature area.');
  end if;

  select m.role
  into v_target_role
  from app.organization_members m
  where m.org_id = p_org_id
    and m.user_id = v_target_user_id
  for update;

  if v_target_role is null then
    perform app_api.raise_http(404, 'Target user is not an organization member.');
  end if;

  if v_target_role <> 'member' then
    perform app_api.raise_http(400, 'Only member accounts can be changed from this page.');
  end if;

  perform app_api.ensure_general_feature_permissions(p_org_id, app_api.trim_text(p_actor));

  foreach v_feature in array app_api.member_feature_areas() loop
    if not (v_permissions ? v_feature) then
      continue;
    end if;

    v_feature_payload := v_permissions->v_feature;
    if jsonb_typeof(coalesce(v_feature_payload, 'null'::jsonb)) <> 'object' then
      perform app_api.raise_http(400, format('permissions.%s must be an object.', v_feature));
    end if;

    v_read := lower(app_api.trim_text(v_feature_payload->>'read'));
    if v_read not in ('true', 'false') then
      perform app_api.raise_http(400, format('permissions.%s.read must be true or false.', v_feature));
    end if;
    v_read_enabled := (v_read = 'true');

    insert into app.admin_feature_permissions (
      org_id,
      admin_user_id,
      feature_area,
      read_enabled,
      write_enabled,
      updated_at,
      updated_by
    )
    values (
      p_org_id,
      v_target_user_id,
      v_feature,
      coalesce((select g.read_enabled from app.general_feature_permissions g where g.org_id = p_org_id and g.feature_area = v_feature), true),
      false,
      now(),
      app_api.trim_text(p_actor)
    )
    on conflict (org_id, admin_user_id, feature_area) do nothing;

    update app.admin_feature_permissions a
    set
      read_enabled = v_read_enabled,
      write_enabled = false,
      updated_at = now(),
      updated_by = app_api.trim_text(p_actor)
    where a.org_id = p_org_id
      and a.admin_user_id = v_target_user_id
      and a.feature_area = v_feature;

    v_has_updates := true;
  end loop;

  if not v_has_updates then
    perform app_api.raise_http(400, 'permissions must include at least one member feature entry.');
  end if;

  delete from app.admin_feature_permissions a
  where a.org_id = p_org_id
    and a.admin_user_id = v_target_user_id
    and a.feature_area = 'access_management';

  return app_api.member_permissions_for_user_json(p_org_id, v_target_user_id);
end;
$$;

update app.admin_feature_permissions a
set
  write_enabled = false,
  updated_at = now(),
  updated_by = '0028_member_permission_persistence_guardrails'
from app.organization_members m
where m.org_id = a.org_id
  and m.user_id = a.admin_user_id
  and m.role = 'member'
  and a.feature_area = any(app_api.member_feature_areas())
  and a.write_enabled is distinct from false;

delete from app.admin_feature_permissions a
using app.organization_members m
where m.org_id = a.org_id
  and m.user_id = a.admin_user_id
  and m.role = 'member'
  and a.feature_area = 'access_management';

-- Ensure cancelled jobs do not retain lingering film orders.
create or replace function public.api_film_orders_cancel(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job_number text := app_api.require_text(p_payload->>'jobNumber', 'JobNumber');
  v_reason text := coalesce(nullif(app_api.trim_text(p_payload->>'reason'), ''), 'Job cancelled.');
  v_entry app.allocations;
  v_order app.film_orders;
  v_box app.boxes;
  v_released_by_box jsonb := '{}'::jsonb;
  v_released_count integer := 0;
  v_affected_box_count integer := 0;
  v_deleted_film_order_count integer := 0;
begin
  perform app_api.require_org_member(p_org_id);

  for v_entry in
    select *
    from app.allocations a
    where a.org_id = p_org_id
      and upper(a.job_number) = upper(v_job_number)
      and a.status = 'ACTIVE'
    for update
  loop
    v_released_by_box := jsonb_set(
      v_released_by_box,
      array[v_entry.box_id],
      to_jsonb(coalesce((v_released_by_box->>v_entry.box_id)::integer, 0) + v_entry.allocated_feet),
      true
    );
    v_entry.status := 'CANCELLED';
    v_entry.resolved_at := now();
    v_entry.resolved_by := app_api.trim_text(p_actor);
    v_entry.notes := v_reason;
    perform app_api.save_allocation(v_entry);
    v_released_count := v_released_count + 1;
  end loop;

  for v_box in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and v_released_by_box ? b.box_id
    for update
  loop
    if v_box.status not in ('ZEROED', 'RETIRED') then
      v_box.feet_available := v_box.feet_available + coalesce((v_released_by_box->>v_box.box_id)::integer, 0);
      perform app_api.save_box(v_box);
    end if;
    v_affected_box_count := v_affected_box_count + 1;
  end loop;

  for v_order in
    select *
    from app.film_orders f
    where f.org_id = p_org_id
      and upper(f.job_number) = upper(v_job_number)
    for update
  loop
    perform app_api.delete_film_order_links_by_film_order_id(p_org_id, v_order.film_order_id);
    perform app_api.delete_film_order(p_org_id, v_order.film_order_id);
    v_deleted_film_order_count := v_deleted_film_order_count + 1;
  end loop;

  update app.jobs
  set lifecycle_status = 'CANCELLED',
      updated_at = now(),
      updated_by = app_api.trim_text(p_actor)
  where org_id = p_org_id
    and job_number = v_job_number;

  return jsonb_build_object(
    'jobNumber', v_job_number,
    'warnings', jsonb_build_array(
      format(
        'Cancelled job %s. Released %s active allocation%s across %s box%s and deleted %s film order%s.',
        v_job_number,
        v_released_count,
        case when v_released_count = 1 then '' else 's' end,
        v_affected_box_count,
        case when v_affected_box_count = 1 then '' else 'es' end,
        v_deleted_film_order_count,
        case when v_deleted_film_order_count = 1 then '' else 's' end
      )
    )
  );
end;
$$;

-- Adds caulk job requirements, job allocations, and checkout/checkin workflow.

do $$
begin
  create type app.caulk_job_allocation_status as enum ('ACTIVE', 'CANCELLED');
exception
  when duplicate_object then
    null;
end;
$$;

do $$
begin
  create type app.caulk_job_checkout_status as enum ('OPEN', 'CLOSED');
exception
  when duplicate_object then
    null;
end;
$$;

create table if not exists app.job_caulk_requirements (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  job_id uuid not null references app.jobs(id) on delete cascade,
  product_id uuid not null,
  required_tubes integer not null,
  notes text not null default '',
  created_at timestamptz not null default now(),
  created_by text not null default '',
  updated_at timestamptz not null default now(),
  updated_by text not null default '',
  unique (org_id, job_id, product_id),
  foreign key (org_id, product_id) references app.caulk_products(org_id, id) on delete restrict
);

alter table app.job_caulk_requirements
  drop constraint if exists job_caulk_requirements_required_tubes_positive;
alter table app.job_caulk_requirements
  add constraint job_caulk_requirements_required_tubes_positive
  check (required_tubes > 0);

create index if not exists idx_job_caulk_requirements_org_job
  on app.job_caulk_requirements (org_id, job_id);

create table if not exists app.caulk_job_allocations (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  caulk_allocation_id text not null,
  job_id uuid references app.jobs(id) on delete set null,
  job_number text not null,
  requirement_id uuid references app.job_caulk_requirements(id) on delete set null,
  product_id uuid not null,
  warehouse text not null,
  allocated_tubes integer not null,
  reserved_tubes_remaining integer not null,
  checked_out_tubes_total integer not null default 0,
  returned_unused_tubes_total integer not null default 0,
  used_tubes_total integer not null default 0,
  overage_tubes_total integer not null default 0,
  status app.caulk_job_allocation_status not null default 'ACTIVE',
  created_at timestamptz not null default now(),
  created_by text not null default '',
  updated_at timestamptz not null default now(),
  updated_by text not null default '',
  resolved_at timestamptz,
  resolved_by text not null default '',
  notes text not null default '',
  unique (org_id, caulk_allocation_id),
  foreign key (org_id, product_id) references app.caulk_products(org_id, id) on delete restrict,
  foreign key (org_id, warehouse) references app.warehouses(org_id, code) on delete restrict
);

alter table app.caulk_job_allocations
  drop constraint if exists caulk_job_allocations_allocated_tubes_positive;
alter table app.caulk_job_allocations
  add constraint caulk_job_allocations_allocated_tubes_positive
  check (allocated_tubes > 0);

alter table app.caulk_job_allocations
  drop constraint if exists caulk_job_allocations_reserved_non_negative;
alter table app.caulk_job_allocations
  add constraint caulk_job_allocations_reserved_non_negative
  check (reserved_tubes_remaining >= 0 and reserved_tubes_remaining <= allocated_tubes);

alter table app.caulk_job_allocations
  drop constraint if exists caulk_job_allocations_totals_non_negative;
alter table app.caulk_job_allocations
  add constraint caulk_job_allocations_totals_non_negative
  check (
    checked_out_tubes_total >= 0
    and returned_unused_tubes_total >= 0
    and used_tubes_total >= 0
    and overage_tubes_total >= 0
    and checked_out_tubes_total >= returned_unused_tubes_total + used_tubes_total
  );

create index if not exists idx_caulk_job_allocations_org_job
  on app.caulk_job_allocations (org_id, upper(job_number));

create index if not exists idx_caulk_job_allocations_org_status
  on app.caulk_job_allocations (org_id, status, updated_at desc);

create table if not exists app.caulk_job_checkouts (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  caulk_checkout_id text not null,
  caulk_allocation_id uuid not null references app.caulk_job_allocations(id) on delete cascade,
  job_number text not null,
  product_id uuid not null,
  warehouse text not null,
  checkout_tubes integer not null,
  overage_tubes integer not null default 0,
  status app.caulk_job_checkout_status not null default 'OPEN',
  checked_out_at timestamptz not null default now(),
  checked_out_by text not null default '',
  checked_in_at timestamptz,
  checked_in_by text not null default '',
  unused_tubes integer not null default 0,
  used_tubes integer not null default 0,
  notes text not null default '',
  unique (org_id, caulk_checkout_id),
  foreign key (org_id, product_id) references app.caulk_products(org_id, id) on delete restrict,
  foreign key (org_id, warehouse) references app.warehouses(org_id, code) on delete restrict
);

alter table app.caulk_job_checkouts
  drop constraint if exists caulk_job_checkouts_checkout_positive;
alter table app.caulk_job_checkouts
  add constraint caulk_job_checkouts_checkout_positive
  check (checkout_tubes > 0 and overage_tubes >= 0);

alter table app.caulk_job_checkouts
  drop constraint if exists caulk_job_checkouts_totals_valid;
alter table app.caulk_job_checkouts
  add constraint caulk_job_checkouts_totals_valid
  check (
    unused_tubes >= 0
    and used_tubes >= 0
    and checkout_tubes >= unused_tubes + used_tubes
    and (
      (status = 'OPEN' and checked_in_at is null and unused_tubes = 0 and used_tubes = 0)
      or (status = 'CLOSED' and checked_in_at is not null and checkout_tubes = unused_tubes + used_tubes)
    )
  );

create index if not exists idx_caulk_job_checkouts_org_job
  on app.caulk_job_checkouts (org_id, upper(job_number), checked_out_at desc);

create index if not exists idx_caulk_job_checkouts_org_allocation
  on app.caulk_job_checkouts (org_id, caulk_allocation_id, status, checked_out_at desc);

alter table app.caulk_transactions
  drop constraint if exists caulk_transactions_action_valid;
alter table app.caulk_transactions
  add constraint caulk_transactions_action_valid
  check (
    action in (
      'RECEIVE',
      'USE',
      'ADJUST',
      'TRANSFER_OUT',
      'TRANSFER_IN',
      'BACKFILL_MIGRATE',
      'JOB_ALLOCATE',
      'JOB_ALLOCATE_EDIT_INC',
      'JOB_ALLOCATE_EDIT_DEC',
      'JOB_CHECKOUT_OVERAGE',
      'JOB_CHECKIN_UNUSED',
      'JOB_ALLOCATION_CANCEL_RETURN'
    )
  );

create or replace function app_api.caulk_apply_stock_delta(
  p_org_id uuid,
  p_actor text,
  p_product_id uuid,
  p_warehouse text,
  p_action text,
  p_delta_tubes integer,
  p_reason text,
  p_transfer_id text default '',
  p_source_box_id text default '',
  p_notes text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_actor text := app_api.trim_text(p_actor);
  v_action text := upper(app_api.trim_text(p_action));
  v_reason text := app_api.trim_text(p_reason);
  v_warehouse text := app_api.caulk_require_warehouse(p_org_id, p_warehouse);
  v_product app.caulk_products;
  v_manufacturer app.caulk_manufacturers;
  v_stock app.caulk_stock;
  v_before integer := 0;
  v_after integer := 0;
  v_transaction_id text := app_api.caulk_create_transaction_id();
begin
  if p_delta_tubes is null or p_delta_tubes = 0 then
    perform app_api.raise_http(400, 'DeltaTubes must be a non-zero integer.');
  end if;

  if v_action not in (
    'RECEIVE',
    'USE',
    'ADJUST',
    'TRANSFER_OUT',
    'TRANSFER_IN',
    'BACKFILL_MIGRATE',
    'JOB_ALLOCATE',
    'JOB_ALLOCATE_EDIT_INC',
    'JOB_ALLOCATE_EDIT_DEC',
    'JOB_CHECKOUT_OVERAGE',
    'JOB_CHECKIN_UNUSED',
    'JOB_ALLOCATION_CANCEL_RETURN'
  ) then
    perform app_api.raise_http(400, 'Unsupported caulk stock action.');
  end if;

  select *
  into v_product
  from app.caulk_products p
  where p.org_id = p_org_id
    and p.id = p_product_id
  limit 1;

  if not found then
    perform app_api.raise_http(400, 'Product was not found for this organization.');
  end if;

  select *
  into v_manufacturer
  from app.caulk_manufacturers m
  where m.org_id = p_org_id
    and m.id = v_product.manufacturer_id
  limit 1;

  if not found then
    perform app_api.raise_http(400, 'Manufacturer for product was not found.');
  end if;

  insert into app.caulk_stock (
    org_id,
    product_id,
    warehouse,
    tubes_on_hand,
    updated_by
  )
  values (
    p_org_id,
    p_product_id,
    v_warehouse,
    0,
    v_actor
  )
  on conflict (org_id, product_id, warehouse) do nothing;

  select *
  into v_stock
  from app.caulk_stock s
  where s.org_id = p_org_id
    and s.product_id = p_product_id
    and s.warehouse = v_warehouse
  for update;

  v_before := coalesce(v_stock.tubes_on_hand, 0);
  v_after := v_before + p_delta_tubes;

  if v_after < 0 then
    perform app_api.raise_http(400, format('Insufficient stock. Requested delta would move tubes below zero (%s).', v_after));
  end if;

  update app.caulk_stock s
  set
    tubes_on_hand = v_after,
    updated_at = now(),
    updated_by = v_actor
  where s.org_id = p_org_id
    and s.product_id = p_product_id
    and s.warehouse = v_warehouse;

  insert into app.caulk_transactions (
    org_id,
    transaction_id,
    product_id,
    warehouse,
    action,
    delta_tubes,
    resulting_tubes_on_hand,
    tubes_per_case,
    reason,
    notes,
    transfer_id,
    source_box_id,
    created_by
  )
  values (
    p_org_id,
    v_transaction_id,
    p_product_id,
    v_warehouse,
    v_action,
    p_delta_tubes,
    v_after,
    v_product.tubes_per_case,
    v_reason,
    app_api.trim_text(p_notes),
    app_api.trim_text(p_transfer_id),
    app_api.trim_text(p_source_box_id),
    v_actor
  );

  return jsonb_build_object(
    'transactionId', v_transaction_id,
    'productId', v_product.id,
    'manufacturer', v_manufacturer.name,
    'productName', v_product.name,
    'productCode', v_product.code,
    'warehouse', v_warehouse,
    'action', v_action,
    'deltaTubes', p_delta_tubes,
    'tubesPerCase', v_product.tubes_per_case,
    'tubesBefore', v_before,
    'tubesOnHand', v_after,
    'casesOnHand', floor(v_after::numeric / v_product.tubes_per_case::numeric)::integer,
    'looseTubes', mod(v_after, v_product.tubes_per_case)
  );
end;
$$;

create or replace function app_api.caulk_requirement_rows_from_payload(p_requirements jsonb)
returns table (
  product_id uuid,
  required_tubes integer
)
language plpgsql
stable
as $$
declare
  v_value jsonb;
  v_product_id uuid;
  v_required_tubes integer;
begin
  if p_requirements is not null and jsonb_typeof(p_requirements) = 'array' then
    for v_value in
      select value
      from jsonb_array_elements(p_requirements)
    loop
      v_product_id := nullif(app_api.trim_text(v_value->>'productId'), '')::uuid;
      v_required_tubes := floor(nullif(app_api.trim_text(v_value->>'requiredTubes'), '')::numeric);

      if v_product_id is null then
        perform app_api.raise_http(400, 'caulkRequirements[].productId is required.');
      end if;

      if v_required_tubes is null or v_required_tubes <= 0 then
        perform app_api.raise_http(400, 'caulkRequirements[].requiredTubes must be greater than zero.');
      end if;
    end loop;
  end if;

  return query
  with normalized as (
    select
      (nullif(app_api.trim_text(value->>'productId'), '')::uuid) as product_id,
      floor(nullif(app_api.trim_text(value->>'requiredTubes'), '')::numeric)::integer as required_tubes
    from jsonb_array_elements(
      case
        when p_requirements is null or jsonb_typeof(p_requirements) <> 'array' then '[]'::jsonb
        else p_requirements
      end
    )
  )
  select
    n.product_id,
    sum(n.required_tubes)::integer as required_tubes
  from normalized n
  group by n.product_id;
end;
$$;

create or replace function app_api.replace_job_caulk_requirements(
  p_org_id uuid,
  p_job app.jobs,
  p_requirements jsonb,
  p_actor text,
  p_now timestamptz
)
returns void
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_requirement record;
begin
  delete from app.job_caulk_requirements
  where org_id = p_org_id
    and job_id = p_job.id;

  for v_requirement in
    select *
    from app_api.caulk_requirement_rows_from_payload(p_requirements)
  loop
    insert into app.job_caulk_requirements (
      id,
      org_id,
      job_id,
      product_id,
      required_tubes,
      notes,
      created_at,
      created_by,
      updated_at,
      updated_by
    )
    values (
      gen_random_uuid(),
      p_org_id,
      p_job.id,
      v_requirement.product_id,
      v_requirement.required_tubes,
      '',
      p_now,
      app_api.trim_text(p_actor),
      p_now,
      app_api.trim_text(p_actor)
    );
  end loop;
end;
$$;

create or replace function public.api_jobs_create(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_now timestamptz := now();
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and j.job_number = app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number')
  for update;

  if not found then
    v_job.id := gen_random_uuid();
    v_job.created_at := v_now;
    v_job.created_by := app_api.trim_text(p_actor);
  end if;

  v_job.org_id := p_org_id;
  v_job.job_number := app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number');
  v_job.warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'warehouse', 'Warehouse');
  v_job.sections := app_api.normalize_job_sections(p_payload->>'sections');
  v_job.due_date := nullif(app_api.trim_text(p_payload->>'dueDate'), '')::date;
  v_job.crew_leader := app_api.trim_text(p_payload->>'crewLeader');
  v_job.lifecycle_status := app_api.normalize_job_lifecycle_status(p_payload->>'lifecycleStatus');
  v_job.notes := app_api.trim_text(p_payload->>'notes');
  v_job.updated_at := v_now;
  v_job.updated_by := app_api.trim_text(p_actor);

  v_job := app_api.save_job(v_job);
  perform app_api.replace_job_requirements(p_org_id, v_job, p_payload->'requirements', p_actor, v_now);
  perform app_api.replace_job_caulk_requirements(p_org_id, v_job, p_payload->'caulkRequirements', p_actor, v_now);

  return jsonb_build_object(
    'jobNumber', v_job.job_number,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_jobs_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_now timestamptz := now();
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and j.job_number = app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number')
  for update;

  if not found then
    v_job.id := gen_random_uuid();
    v_job.org_id := p_org_id;
    v_job.job_number := app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number');
    v_job.warehouse := coalesce(
      case
        when app_api.trim_text(p_payload->>'warehouse') <> ''
          then app_api.require_org_warehouse(p_org_id, p_payload->>'warehouse', 'Warehouse')
        else null
      end,
      (
        select w.code
        from app.warehouses w
        where w.org_id = p_org_id
          and w.box_id_prefix = ''
        order by case when w.code = 'IL' then 0 else 1 end, w.code
        limit 1
      ),
      (
        select w.code
        from app.warehouses w
        where w.org_id = p_org_id
        order by w.code
        limit 1
      )
    );
    if v_job.warehouse is null then
      perform app_api.raise_http(400, 'No warehouse is configured for this organization.');
    end if;
    v_job.sections := null;
    v_job.due_date := null;
    v_job.crew_leader := '';
    v_job.lifecycle_status := 'ACTIVE';
    v_job.notes := '';
    v_job.created_at := v_now;
    v_job.created_by := app_api.trim_text(p_actor);
  end if;

  if p_payload ? 'warehouse' then
    v_job.warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'warehouse', 'Warehouse');
  end if;
  if p_payload ? 'sections' then
    v_job.sections := app_api.normalize_job_sections(p_payload->>'sections');
  end if;
  if p_payload ? 'dueDate' then
    v_job.due_date := nullif(app_api.trim_text(p_payload->>'dueDate'), '')::date;
  end if;
  if p_payload ? 'crewLeader' then
    v_job.crew_leader := app_api.trim_text(p_payload->>'crewLeader');
  end if;
  if p_payload ? 'lifecycleStatus' then
    v_job.lifecycle_status := app_api.normalize_job_lifecycle_status(p_payload->>'lifecycleStatus');
  end if;
  if p_payload ? 'notes' then
    v_job.notes := app_api.trim_text(p_payload->>'notes');
  end if;

  v_job.updated_at := v_now;
  v_job.updated_by := app_api.trim_text(p_actor);
  v_job := app_api.save_job(v_job);
  perform app_api.replace_job_requirements(p_org_id, v_job, p_payload->'requirements', p_actor, v_now);
  perform app_api.replace_job_caulk_requirements(p_org_id, v_job, p_payload->'caulkRequirements', p_actor, v_now);

  return jsonb_build_object(
    'jobNumber', v_job.job_number,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function app_api.require_active_job_for_caulk(
  p_org_id uuid,
  p_job_number text
)
returns app.jobs
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
begin
  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and j.job_number = app_api.require_job_number_digits(p_job_number, 'Job ID number')
  for update;

  if not found then
    perform app_api.raise_http(404, format('Job %s was not found.', app_api.trim_text(p_job_number)));
  end if;

  if app_api.normalize_job_lifecycle_status(v_job.lifecycle_status::text) <> 'ACTIVE'::app.job_lifecycle_status then
    perform app_api.raise_http(400, format('Job %s is closed and cannot receive caulk allocations.', v_job.job_number));
  end if;

  return v_job;
end;
$$;

create or replace function app_api.cancel_active_caulk_allocations_for_job(
  p_org_id uuid,
  p_actor text,
  p_job_number text,
  p_reason text,
  p_fail_on_open_checkouts boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_entry app.caulk_job_allocations;
  v_actor text := app_api.trim_text(p_actor);
  v_job_number text := app_api.require_job_number_digits(p_job_number, 'Job ID number');
  v_reason text := coalesce(nullif(app_api.trim_text(p_reason), ''), format('Cancelled job %s.', v_job_number));
  v_open_checkout_count integer := 0;
  v_cancelled_count integer := 0;
  v_released_reserved_tubes integer := 0;
begin
  select count(*)
  into v_open_checkout_count
  from app.caulk_job_checkouts c
  join app.caulk_job_allocations a
    on a.id = c.caulk_allocation_id
   and a.org_id = c.org_id
  where c.org_id = p_org_id
    and upper(c.job_number) = upper(v_job_number)
    and c.status = 'OPEN'
    and a.status = 'ACTIVE';

  if p_fail_on_open_checkouts and v_open_checkout_count > 0 then
    perform app_api.raise_http(
      400,
      format(
        'Job %s cannot be closed while %s caulk checkout%s remain open.',
        v_job_number,
        v_open_checkout_count,
        case when v_open_checkout_count = 1 then '' else 's' end
      )
    );
  end if;

  for v_entry in
    select *
    from app.caulk_job_allocations a
    where a.org_id = p_org_id
      and upper(a.job_number) = upper(v_job_number)
      and a.status = 'ACTIVE'
    for update
  loop
    if v_entry.reserved_tubes_remaining > 0 then
      perform app_api.caulk_apply_stock_delta(
        p_org_id,
        v_actor,
        v_entry.product_id,
        v_entry.warehouse,
        'JOB_ALLOCATION_CANCEL_RETURN',
        v_entry.reserved_tubes_remaining,
        v_reason,
        '',
        v_entry.caulk_allocation_id,
        v_reason
      );
      v_released_reserved_tubes := v_released_reserved_tubes + v_entry.reserved_tubes_remaining;
    end if;

    update app.caulk_job_allocations
    set
      status = 'CANCELLED',
      reserved_tubes_remaining = 0,
      resolved_at = now(),
      resolved_by = v_actor,
      notes = v_reason,
      updated_at = now(),
      updated_by = v_actor
    where id = v_entry.id
      and org_id = p_org_id;

    v_cancelled_count := v_cancelled_count + 1;
  end loop;

  return jsonb_build_object(
    'jobNumber', v_job_number,
    'openCheckoutCount', v_open_checkout_count,
    'cancelledAllocationCount', v_cancelled_count,
    'releasedReservedTubes', v_released_reserved_tubes
  );
end;
$$;

create or replace function public.api_acl_jobs_cancel_caulk_allocations(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  perform app_api.require_effective_feature_access(p_org_id, 'jobs', 'write');

  return app_api.cancel_active_caulk_allocations_for_job(
    p_org_id,
    p_actor,
    p_payload->>'jobNumber',
    coalesce(nullif(app_api.trim_text(p_payload->>'reason'), ''), 'Job completed.'),
    true
  );
end;
$$;

create or replace function public.api_acl_list_job_caulk_requirements_by_job(
  p_org_id uuid,
  p_job_number text
)
returns table (
  requirement_id uuid,
  job_number text,
  product_id uuid,
  manufacturer_id uuid,
  manufacturer text,
  product_name text,
  product_code text,
  tubes_per_case integer,
  required_tubes integer,
  notes text,
  updated_at timestamptz
)
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  perform app_api.require_org_member(p_org_id);

  return query
  select
    r.id,
    j.job_number,
    r.product_id,
    p.manufacturer_id,
    m.name,
    p.name,
    p.code,
    p.tubes_per_case,
    r.required_tubes,
    r.notes,
    r.updated_at
  from app.job_caulk_requirements r
  join app.jobs j
    on j.id = r.job_id
   and j.org_id = r.org_id
  join app.caulk_products p
    on p.id = r.product_id
   and p.org_id = r.org_id
  join app.caulk_manufacturers m
    on m.id = p.manufacturer_id
   and m.org_id = p.org_id
  where r.org_id = p_org_id
    and upper(j.job_number) = upper(app_api.require_job_number_digits(p_job_number, 'Job ID number'))
  order by lower(m.name), lower(p.name), lower(p.code);
end;
$$;

create or replace function public.api_acl_list_caulk_job_allocations_by_job(
  p_org_id uuid,
  p_job_number text
)
returns table (
  caulk_allocation_id text,
  requirement_id uuid,
  product_id uuid,
  manufacturer_id uuid,
  manufacturer text,
  product_name text,
  product_code text,
  tubes_per_case integer,
  warehouse text,
  allocated_tubes integer,
  reserved_tubes_remaining integer,
  checked_out_tubes_total integer,
  returned_unused_tubes_total integer,
  used_tubes_total integer,
  overage_tubes_total integer,
  outstanding_checkout_tubes integer,
  open_checkout_count integer,
  status text,
  created_at timestamptz,
  created_by text,
  updated_at timestamptz,
  updated_by text,
  resolved_at timestamptz,
  resolved_by text,
  notes text
)
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  perform app_api.require_org_member(p_org_id);

  return query
  with open_counts as (
    select
      c.caulk_allocation_id,
      count(*)::integer as open_checkout_count
    from app.caulk_job_checkouts c
    where c.org_id = p_org_id
      and c.status = 'OPEN'
    group by c.caulk_allocation_id
  )
  select
    a.caulk_allocation_id,
    a.requirement_id,
    a.product_id,
    p.manufacturer_id,
    m.name,
    p.name,
    p.code,
    p.tubes_per_case,
    a.warehouse,
    a.allocated_tubes,
    a.reserved_tubes_remaining,
    a.checked_out_tubes_total,
    a.returned_unused_tubes_total,
    a.used_tubes_total,
    a.overage_tubes_total,
    greatest(a.checked_out_tubes_total - a.returned_unused_tubes_total - a.used_tubes_total, 0)::integer,
    coalesce(o.open_checkout_count, 0),
    a.status::text,
    a.created_at,
    a.created_by,
    a.updated_at,
    a.updated_by,
    a.resolved_at,
    a.resolved_by,
    a.notes
  from app.caulk_job_allocations a
  join app.caulk_products p
    on p.id = a.product_id
   and p.org_id = a.org_id
  join app.caulk_manufacturers m
    on m.id = p.manufacturer_id
   and m.org_id = p.org_id
  left join open_counts o
    on o.caulk_allocation_id = a.id
  where a.org_id = p_org_id
    and upper(a.job_number) = upper(app_api.require_job_number_digits(p_job_number, 'Job ID number'))
  order by a.created_at desc, a.caulk_allocation_id desc;
end;
$$;

