create or replace function public.api_acl_allocations_caulk_add(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_product app.caulk_products;
  v_requirement app.job_caulk_requirements;
  v_allocation app.caulk_job_allocations;
  v_allocation_id text := app_api.create_log_id();
  v_job_number text := app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number');
  v_requirement_id uuid := nullif(app_api.trim_text(p_payload->>'requirementId'), '')::uuid;
  v_product_id uuid := nullif(app_api.trim_text(p_payload->>'productId'), '')::uuid;
  v_warehouse text := app_api.caulk_require_warehouse(p_org_id, p_payload->>'warehouse');
  v_allocated_tubes integer := floor(nullif(app_api.trim_text(p_payload->>'allocatedTubes'), '')::numeric);
  v_actor text := app_api.trim_text(p_actor);
  v_notes text := app_api.trim_text(p_payload->>'notes');
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  if v_product_id is null then
    perform app_api.raise_http(400, 'productId is required.');
  end if;

  if v_allocated_tubes is null or v_allocated_tubes <= 0 then
    perform app_api.raise_http(400, 'allocatedTubes must be greater than zero.');
  end if;

  v_job := app_api.require_active_job_for_caulk(p_org_id, v_job_number);

  select *
  into v_product
  from app.caulk_products p
  where p.org_id = p_org_id
    and p.id = v_product_id
  limit 1;

  if not found then
    perform app_api.raise_http(400, 'Product was not found.');
  end if;

  if v_requirement_id is not null then
    select *
    into v_requirement
    from app.job_caulk_requirements r
    where r.org_id = p_org_id
      and r.id = v_requirement_id
      and r.job_id = v_job.id
    for update;

    if not found then
      perform app_api.raise_http(400, 'RequirementId was not found for this job.');
    end if;
  end if;

  perform app_api.caulk_apply_stock_delta(
    p_org_id,
    v_actor,
    v_product.id,
    v_warehouse,
    'JOB_ALLOCATE',
    -v_allocated_tubes,
    format('Allocated caulk to job %s.', v_job.job_number),
    '',
    v_allocation_id,
    v_notes
  );

  insert into app.caulk_job_allocations (
    id,
    org_id,
    caulk_allocation_id,
    job_id,
    job_number,
    requirement_id,
    product_id,
    warehouse,
    allocated_tubes,
    reserved_tubes_remaining,
    checked_out_tubes_total,
    returned_unused_tubes_total,
    used_tubes_total,
    overage_tubes_total,
    status,
    created_at,
    created_by,
    updated_at,
    updated_by,
    notes
  )
  values (
    gen_random_uuid(),
    p_org_id,
    v_allocation_id,
    v_job.id,
    v_job.job_number,
    v_requirement_id,
    v_product.id,
    v_warehouse,
    v_allocated_tubes,
    v_allocated_tubes,
    0,
    0,
    0,
    0,
    'ACTIVE',
    now(),
    v_actor,
    now(),
    v_actor,
    v_notes
  )
  returning * into v_allocation;

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_acl_allocations_caulk_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_allocation app.caulk_job_allocations;
  v_actor text := app_api.trim_text(p_actor);
  v_caulk_allocation_id text := app_api.require_text(p_payload->>'caulkAllocationId', 'CaulkAllocationId');
  v_next_product_id uuid;
  v_next_warehouse text;
  v_next_allocated_tubes integer;
  v_delta integer;
  v_notes text;
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.caulk_allocation_id = v_caulk_allocation_id
  for update;

  if not found then
    perform app_api.raise_http(404, format('Caulk allocation %s was not found.', v_caulk_allocation_id));
  end if;

  if v_allocation.status <> 'ACTIVE' then
    perform app_api.raise_http(400, format('Caulk allocation %s is not active.', v_caulk_allocation_id));
  end if;

  perform app_api.require_active_job_for_caulk(p_org_id, v_allocation.job_number);

  v_next_product_id := coalesce(nullif(app_api.trim_text(p_payload->>'productId'), '')::uuid, v_allocation.product_id);
  v_next_warehouse := case
    when p_payload ? 'warehouse' then app_api.caulk_require_warehouse(p_org_id, p_payload->>'warehouse')
    else v_allocation.warehouse
  end;
  v_next_allocated_tubes := case
    when p_payload ? 'allocatedTubes' then floor(nullif(app_api.trim_text(p_payload->>'allocatedTubes'), '')::numeric)
    else v_allocation.allocated_tubes
  end;
  v_notes := case
    when p_payload ? 'notes' then app_api.trim_text(p_payload->>'notes')
    else v_allocation.notes
  end;

  if v_next_allocated_tubes is null or v_next_allocated_tubes <= 0 then
    perform app_api.raise_http(400, 'allocatedTubes must be greater than zero.');
  end if;

  if v_allocation.checked_out_tubes_total > 0 then
    if v_next_product_id <> v_allocation.product_id or v_next_warehouse <> v_allocation.warehouse then
      perform app_api.raise_http(400, 'Product and warehouse cannot be changed after checkout starts.');
    end if;
    if v_next_allocated_tubes < v_allocation.allocated_tubes then
      perform app_api.raise_http(400, 'allocatedTubes can only increase after checkout starts.');
    end if;
  end if;

  if v_next_product_id <> v_allocation.product_id or v_next_warehouse <> v_allocation.warehouse then
    if v_allocation.checked_out_tubes_total > 0 then
      perform app_api.raise_http(400, 'Product and warehouse cannot be changed after checkout starts.');
    end if;

    if v_allocation.reserved_tubes_remaining > 0 then
      perform app_api.caulk_apply_stock_delta(
        p_org_id,
        v_actor,
        v_allocation.product_id,
        v_allocation.warehouse,
        'JOB_ALLOCATE_EDIT_DEC',
        v_allocation.reserved_tubes_remaining,
        format('Edited caulk allocation %s.', v_allocation.caulk_allocation_id),
        '',
        v_allocation.caulk_allocation_id,
        'Released prior reserved tubes during edit.'
      );
    end if;

    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_next_product_id,
      v_next_warehouse,
      'JOB_ALLOCATE_EDIT_INC',
      -v_next_allocated_tubes,
      format('Edited caulk allocation %s.', v_allocation.caulk_allocation_id),
      '',
      v_allocation.caulk_allocation_id,
      'Reserved tubes for updated product/warehouse.'
    );

    update app.caulk_job_allocations
    set
      product_id = v_next_product_id,
      warehouse = v_next_warehouse,
      allocated_tubes = v_next_allocated_tubes,
      reserved_tubes_remaining = v_next_allocated_tubes,
      notes = v_notes,
      updated_at = now(),
      updated_by = v_actor
    where id = v_allocation.id
      and org_id = p_org_id;
  else
    v_delta := v_next_allocated_tubes - v_allocation.allocated_tubes;

    if v_delta > 0 then
      perform app_api.caulk_apply_stock_delta(
        p_org_id,
        v_actor,
        v_allocation.product_id,
        v_allocation.warehouse,
        'JOB_ALLOCATE_EDIT_INC',
        -v_delta,
        format('Increased caulk allocation %s.', v_allocation.caulk_allocation_id),
        '',
        v_allocation.caulk_allocation_id,
        v_notes
      );
    elsif v_delta < 0 then
      if abs(v_delta) > v_allocation.reserved_tubes_remaining then
        perform app_api.raise_http(400, 'allocatedTubes cannot drop below already checked-out amount.');
      end if;
      perform app_api.caulk_apply_stock_delta(
        p_org_id,
        v_actor,
        v_allocation.product_id,
        v_allocation.warehouse,
        'JOB_ALLOCATE_EDIT_DEC',
        abs(v_delta),
        format('Reduced caulk allocation %s.', v_allocation.caulk_allocation_id),
        '',
        v_allocation.caulk_allocation_id,
        v_notes
      );
    end if;

    update app.caulk_job_allocations
    set
      allocated_tubes = v_next_allocated_tubes,
      reserved_tubes_remaining = greatest(v_allocation.reserved_tubes_remaining + v_delta, 0),
      notes = v_notes,
      updated_at = now(),
      updated_by = v_actor
    where id = v_allocation.id
      and org_id = p_org_id;
  end if;

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_acl_allocations_caulk_checkout(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_allocation app.caulk_job_allocations;
  v_checkout_id text := app_api.create_log_id();
  v_actor text := app_api.trim_text(p_actor);
  v_caulk_allocation_id text := app_api.require_text(p_payload->>'caulkAllocationId', 'CaulkAllocationId');
  v_checkout_tubes integer := floor(nullif(app_api.trim_text(p_payload->>'checkoutTubes'), '')::numeric);
  v_consume_reserved integer;
  v_overage integer;
  v_notes text := app_api.trim_text(p_payload->>'notes');
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  if v_checkout_tubes is null or v_checkout_tubes <= 0 then
    perform app_api.raise_http(400, 'checkoutTubes must be greater than zero.');
  end if;

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.caulk_allocation_id = v_caulk_allocation_id
  for update;

  if not found then
    perform app_api.raise_http(404, format('Caulk allocation %s was not found.', v_caulk_allocation_id));
  end if;

  if v_allocation.status <> 'ACTIVE' then
    perform app_api.raise_http(400, format('Caulk allocation %s is not active.', v_caulk_allocation_id));
  end if;

  perform app_api.require_active_job_for_caulk(p_org_id, v_allocation.job_number);

  v_consume_reserved := least(v_checkout_tubes, v_allocation.reserved_tubes_remaining);
  v_overage := greatest(v_checkout_tubes - v_consume_reserved, 0);

  if v_overage > 0 then
    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_allocation.product_id,
      v_allocation.warehouse,
      'JOB_CHECKOUT_OVERAGE',
      -v_overage,
      format('Over-checkout on caulk allocation %s.', v_allocation.caulk_allocation_id),
      '',
      v_allocation.caulk_allocation_id,
      v_notes
    );
  end if;

  insert into app.caulk_job_checkouts (
    id,
    org_id,
    caulk_checkout_id,
    caulk_allocation_id,
    job_number,
    product_id,
    warehouse,
    checkout_tubes,
    overage_tubes,
    status,
    checked_out_at,
    checked_out_by,
    notes
  )
  values (
    gen_random_uuid(),
    p_org_id,
    v_checkout_id,
    v_allocation.id,
    v_allocation.job_number,
    v_allocation.product_id,
    v_allocation.warehouse,
    v_checkout_tubes,
    v_overage,
    'OPEN',
    now(),
    v_actor,
    v_notes
  );

  update app.caulk_job_allocations
  set
    reserved_tubes_remaining = greatest(v_allocation.reserved_tubes_remaining - v_consume_reserved, 0),
    checked_out_tubes_total = v_allocation.checked_out_tubes_total + v_checkout_tubes,
    overage_tubes_total = v_allocation.overage_tubes_total + v_overage,
    updated_at = now(),
    updated_by = v_actor
  where id = v_allocation.id
    and org_id = p_org_id;

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'caulkCheckoutId', v_checkout_id,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_acl_allocations_caulk_checkin(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_checkout app.caulk_job_checkouts;
  v_allocation app.caulk_job_allocations;
  v_actor text := app_api.trim_text(p_actor);
  v_caulk_checkout_id text := app_api.require_text(p_payload->>'caulkCheckoutId', 'CaulkCheckoutId');
  v_unused_tubes integer := floor(nullif(app_api.trim_text(p_payload->>'unusedTubes'), '')::numeric);
  v_used_tubes integer;
  v_notes text := app_api.trim_text(p_payload->>'notes');
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  if v_unused_tubes is null or v_unused_tubes < 0 then
    perform app_api.raise_http(400, 'unusedTubes must be zero or greater.');
  end if;

  select *
  into v_checkout
  from app.caulk_job_checkouts c
  where c.org_id = p_org_id
    and c.caulk_checkout_id = v_caulk_checkout_id
  for update;

  if not found then
    perform app_api.raise_http(404, format('Caulk checkout %s was not found.', v_caulk_checkout_id));
  end if;

  if v_checkout.status <> 'OPEN' then
    perform app_api.raise_http(400, format('Caulk checkout %s is already closed.', v_caulk_checkout_id));
  end if;

  if v_unused_tubes > v_checkout.checkout_tubes then
    perform app_api.raise_http(400, 'unusedTubes cannot exceed checkoutTubes.');
  end if;

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.id = v_checkout.caulk_allocation_id
  for update;

  if not found then
    perform app_api.raise_http(404, 'Parent caulk allocation was not found.');
  end if;

  if v_allocation.status <> 'ACTIVE' then
    perform app_api.raise_http(400, 'Parent caulk allocation is no longer active.');
  end if;

  v_used_tubes := v_checkout.checkout_tubes - v_unused_tubes;

  if v_unused_tubes > 0 then
    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_allocation.product_id,
      v_allocation.warehouse,
      'JOB_CHECKIN_UNUSED',
      v_unused_tubes,
      format('Checked in unused caulk from allocation %s.', v_allocation.caulk_allocation_id),
      '',
      v_allocation.caulk_allocation_id,
      v_notes
    );
  end if;

  update app.caulk_job_checkouts
  set
    status = 'CLOSED',
    checked_in_at = now(),
    checked_in_by = v_actor,
    unused_tubes = v_unused_tubes,
    used_tubes = v_used_tubes,
    notes = v_notes
  where id = v_checkout.id
    and org_id = p_org_id;

  update app.caulk_job_allocations
  set
    returned_unused_tubes_total = v_allocation.returned_unused_tubes_total + v_unused_tubes,
    used_tubes_total = v_allocation.used_tubes_total + v_used_tubes,
    updated_at = now(),
    updated_by = v_actor
  where id = v_allocation.id
    and org_id = p_org_id;

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'caulkCheckoutId', v_checkout.caulk_checkout_id,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_acl_allocations_caulk_remove(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_allocation app.caulk_job_allocations;
  v_open_checkout_count integer := 0;
  v_actor text := app_api.trim_text(p_actor);
  v_caulk_allocation_id text := app_api.require_text(p_payload->>'caulkAllocationId', 'CaulkAllocationId');
  v_reason text := coalesce(nullif(app_api.trim_text(p_payload->>'reason'), ''), format('Removed from job %s.', app_api.trim_text(p_payload->>'jobNumber')));
  v_released_reserved_tubes integer := 0;
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.caulk_allocation_id = v_caulk_allocation_id
  for update;

  if not found then
    perform app_api.raise_http(404, format('Caulk allocation %s was not found.', v_caulk_allocation_id));
  end if;

  if v_allocation.status <> 'ACTIVE' then
    perform app_api.raise_http(400, format('Caulk allocation %s is not active.', v_caulk_allocation_id));
  end if;

  select count(*)
  into v_open_checkout_count
  from app.caulk_job_checkouts c
  where c.org_id = p_org_id
    and c.caulk_allocation_id = v_allocation.id
    and c.status = 'OPEN';

  if v_open_checkout_count > 0 then
    perform app_api.raise_http(
      400,
      format('Caulk allocation %s has %s open checkout%s. Check in first.', v_caulk_allocation_id, v_open_checkout_count, case when v_open_checkout_count = 1 then '' else 's' end)
    );
  end if;

  if v_allocation.reserved_tubes_remaining > 0 then
    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_allocation.product_id,
      v_allocation.warehouse,
      'JOB_ALLOCATION_CANCEL_RETURN',
      v_allocation.reserved_tubes_remaining,
      v_reason,
      '',
      v_allocation.caulk_allocation_id,
      v_reason
    );
    v_released_reserved_tubes := v_allocation.reserved_tubes_remaining;
  end if;

  update app.caulk_job_allocations
  set
    status = 'CANCELLED',
    reserved_tubes_remaining = 0,
    resolved_at = now(),
    resolved_by = v_actor,
    notes = v_reason,
    updated_at = now(),
    updated_by = v_actor
  where id = v_allocation.id
    and org_id = p_org_id;

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'releasedReservedTubes', v_released_reserved_tubes,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_film_orders_cancel(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job_number text := app_api.require_text(p_payload->>'jobNumber', 'JobNumber');
  v_reason text := coalesce(nullif(app_api.trim_text(p_payload->>'reason'), ''), 'Job cancelled.');
  v_entry app.allocations;
  v_order app.film_orders;
  v_box app.boxes;
  v_released_by_box jsonb := '{}'::jsonb;
  v_released_count integer := 0;
  v_affected_box_count integer := 0;
  v_deleted_film_order_count integer := 0;
  v_caulk_result jsonb;
  v_caulk_cancelled_count integer := 0;
  v_caulk_released_reserved_tubes integer := 0;
begin
  perform app_api.require_org_member(p_org_id);

  v_caulk_result := app_api.cancel_active_caulk_allocations_for_job(
    p_org_id,
    p_actor,
    v_job_number,
    v_reason,
    true
  );
  v_caulk_cancelled_count := coalesce((v_caulk_result->>'cancelledAllocationCount')::integer, 0);
  v_caulk_released_reserved_tubes := coalesce((v_caulk_result->>'releasedReservedTubes')::integer, 0);

  for v_entry in
    select *
    from app.allocations a
    where a.org_id = p_org_id
      and upper(a.job_number) = upper(v_job_number)
      and a.status = 'ACTIVE'
    for update
  loop
    v_released_by_box := jsonb_set(
      v_released_by_box,
      array[v_entry.box_id],
      to_jsonb(coalesce((v_released_by_box->>v_entry.box_id)::integer, 0) + v_entry.allocated_feet),
      true
    );
    v_entry.status := 'CANCELLED';
    v_entry.resolved_at := now();
    v_entry.resolved_by := app_api.trim_text(p_actor);
    v_entry.notes := v_reason;
    perform app_api.save_allocation(v_entry);
    v_released_count := v_released_count + 1;
  end loop;

  for v_box in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and v_released_by_box ? b.box_id
    for update
  loop
    if v_box.status not in ('ZEROED', 'RETIRED') then
      v_box.feet_available := v_box.feet_available + coalesce((v_released_by_box->>v_box.box_id)::integer, 0);
      perform app_api.save_box(v_box);
    end if;
    v_affected_box_count := v_affected_box_count + 1;
  end loop;

  for v_order in
    select *
    from app.film_orders f
    where f.org_id = p_org_id
      and upper(f.job_number) = upper(v_job_number)
    for update
  loop
    perform app_api.delete_film_order_links_by_film_order_id(p_org_id, v_order.film_order_id);
    perform app_api.delete_film_order(p_org_id, v_order.film_order_id);
    v_deleted_film_order_count := v_deleted_film_order_count + 1;
  end loop;

  update app.jobs
  set lifecycle_status = 'CANCELLED',
      updated_at = now(),
      updated_by = app_api.trim_text(p_actor)
  where org_id = p_org_id
    and job_number = v_job_number;

  return jsonb_build_object(
    'jobNumber', v_job_number,
    'warnings', jsonb_build_array(
      format(
        'Cancelled job %s. Released %s active film allocation%s across %s box%s, released %s reserved caulk tube%s across %s caulk allocation%s, and deleted %s film order%s.',
        v_job_number,
        v_released_count,
        case when v_released_count = 1 then '' else 's' end,
        v_affected_box_count,
        case when v_affected_box_count = 1 then '' else 'es' end,
        v_caulk_released_reserved_tubes,
        case when v_caulk_released_reserved_tubes = 1 then '' else 's' end,
        v_caulk_cancelled_count,
        case when v_caulk_cancelled_count = 1 then '' else 's' end,
        v_deleted_film_order_count,
        case when v_deleted_film_order_count = 1 then '' else 's' end
      )
    )
  );
end;
$$;

select app_api.grant_execute_if_exists('public.api_acl_jobs_cancel_caulk_allocations(uuid, text, jsonb)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_list_job_caulk_requirements_by_job(uuid, text)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_list_caulk_job_allocations_by_job(uuid, text)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_list_caulk_job_checkouts_by_job(uuid, text)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_add(uuid, text, jsonb)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_update(uuid, text, jsonb)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_checkout(uuid, text, jsonb)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_checkin(uuid, text, jsonb)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_remove(uuid, text, jsonb)', 'authenticated');

select app_api.grant_execute_if_exists('public.api_acl_jobs_cancel_caulk_allocations(uuid, text, jsonb)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_list_job_caulk_requirements_by_job(uuid, text)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_list_caulk_job_allocations_by_job(uuid, text)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_list_caulk_job_checkouts_by_job(uuid, text)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_add(uuid, text, jsonb)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_update(uuid, text, jsonb)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_checkout(uuid, text, jsonb)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_checkin(uuid, text, jsonb)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_remove(uuid, text, jsonb)', 'service_role');

-- Adds per-box price-per-linear-foot support for film asset valuation.

alter table app.boxes
  add column if not exists price_per_lf numeric(12,4);

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conrelid = 'app.boxes'::regclass
      and conname = 'boxes_price_per_lf_non_negative'
  ) then
    alter table app.boxes
      add constraint boxes_price_per_lf_non_negative
      check (price_per_lf is null or price_per_lf >= 0);
  end if;
end
$$;

alter table import.boxes_raw
  add column if not exists "PricePerLf" text;

create or replace function app_api.public_box_json(p_box app.boxes)
returns jsonb
language sql
stable
as $$
  select jsonb_build_object(
    'boxId', coalesce(p_box.box_id, ''),
    'warehouse', coalesce(p_box.warehouse::text, ''),
    'manufacturer', coalesce(p_box.manufacturer, ''),
    'filmName', coalesce(p_box.film_name, ''),
    'widthIn', p_box.width_in,
    'initialFeet', p_box.initial_feet,
    'feetAvailable', p_box.feet_available,
    'lotRun', coalesce(p_box.lot_run, ''),
    'status', coalesce(p_box.status::text, 'ORDERED'),
    'orderDate', coalesce(to_char(p_box.order_date, 'YYYY-MM-DD'), ''),
    'receivedDate', coalesce(to_char(p_box.received_date, 'YYYY-MM-DD'), ''),
    'initialWeightLbs', p_box.initial_weight_lbs,
    'lastRollWeightLbs', p_box.last_roll_weight_lbs,
    'lastWeighedDate', coalesce(to_char(p_box.last_weighed_date, 'YYYY-MM-DD'), ''),
    'filmKey', upper(coalesce(p_box.film_key, '')),
    'coreType', coalesce(p_box.core_type, ''),
    'coreWeightLbs', p_box.core_weight_lbs,
    'lfWeightLbsPerFt', p_box.lf_weight_lbs_per_ft,
    'purchaseCost', p_box.purchase_cost,
    'pricePerLf', p_box.price_per_lf,
    'notes', coalesce(p_box.notes, ''),
    'hasEverBeenCheckedOut', p_box.has_ever_been_checked_out,
    'lastCheckoutJob', coalesce(p_box.last_checkout_job, ''),
    'lastCheckoutDate', coalesce(to_char(p_box.last_checkout_date, 'YYYY-MM-DD'), ''),
    'zeroedDate', coalesce(to_char(p_box.zeroed_date, 'YYYY-MM-DD'), ''),
    'zeroedReason', coalesce(p_box.zeroed_reason, ''),
    'zeroedBy', coalesce(p_box.zeroed_by, '')
  );
$$;

create or replace function app_api.save_box(p_box app.boxes)
returns app.boxes
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_row app.boxes;
begin
  insert into app.boxes (
    id,
    org_id,
    box_id,
    warehouse,
    manufacturer,
    film_name,
    width_in,
    initial_feet,
    feet_available,
    lot_run,
    status,
    order_date,
    received_date,
    initial_weight_lbs,
    last_roll_weight_lbs,
    last_weighed_date,
    film_key,
    core_type,
    core_weight_lbs,
    lf_weight_lbs_per_ft,
    price_per_lf,
    purchase_cost,
    notes,
    has_ever_been_checked_out,
    last_checkout_job,
    last_checkout_date,
    zeroed_date,
    zeroed_reason,
    zeroed_by
  )
  values (
    coalesce(p_box.id, gen_random_uuid()),
    p_box.org_id,
    p_box.box_id,
    p_box.warehouse,
    p_box.manufacturer,
    p_box.film_name,
    p_box.width_in,
    p_box.initial_feet,
    p_box.feet_available,
    coalesce(p_box.lot_run, ''),
    p_box.status,
    p_box.order_date,
    p_box.received_date,
    p_box.initial_weight_lbs,
    p_box.last_roll_weight_lbs,
    p_box.last_weighed_date,
    p_box.film_key,
    coalesce(p_box.core_type, ''),
    p_box.core_weight_lbs,
    p_box.lf_weight_lbs_per_ft,
    p_box.price_per_lf,
    p_box.purchase_cost,
    coalesce(p_box.notes, ''),
    coalesce(p_box.has_ever_been_checked_out, false),
    coalesce(p_box.last_checkout_job, ''),
    p_box.last_checkout_date,
    p_box.zeroed_date,
    coalesce(p_box.zeroed_reason, ''),
    coalesce(p_box.zeroed_by, '')
  )
  on conflict (org_id, box_id) do update set
    warehouse = excluded.warehouse,
    manufacturer = excluded.manufacturer,
    film_name = excluded.film_name,
    width_in = excluded.width_in,
    initial_feet = excluded.initial_feet,
    feet_available = excluded.feet_available,
    lot_run = excluded.lot_run,
    status = excluded.status,
    order_date = excluded.order_date,
    received_date = excluded.received_date,
    initial_weight_lbs = excluded.initial_weight_lbs,
    last_roll_weight_lbs = excluded.last_roll_weight_lbs,
    last_weighed_date = excluded.last_weighed_date,
    film_key = excluded.film_key,
    core_type = excluded.core_type,
    core_weight_lbs = excluded.core_weight_lbs,
    lf_weight_lbs_per_ft = excluded.lf_weight_lbs_per_ft,
    price_per_lf = excluded.price_per_lf,
    purchase_cost = excluded.purchase_cost,
    notes = excluded.notes,
    has_ever_been_checked_out = excluded.has_ever_been_checked_out,
    last_checkout_job = excluded.last_checkout_job,
    last_checkout_date = excluded.last_checkout_date,
    zeroed_date = excluded.zeroed_date,
    zeroed_reason = excluded.zeroed_reason,
    zeroed_by = excluded.zeroed_by
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function app_api.build_box_from_payload(
  p_org_id uuid,
  p_payload jsonb,
  p_existing_box_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_box app.boxes;
  v_film_data app.film_catalog;
  v_warnings text[] := array[]::text[];
  v_box_id text;
  v_manufacturer text;
  v_film_name text;
  v_width_in numeric;
  v_initial_feet integer;
  v_order_date date;
  v_received_date date;
  v_feet_available_input text;
  v_feet_available integer;
  v_film_key text;
  v_initial_weight_input numeric;
  v_last_roll_weight_input numeric;
  v_last_weighed_date_input date;
  v_core_type_input text;
  v_existing_core_type text;
  v_resolved_initial_weight numeric;
  v_resolved_last_roll_weight numeric;
  v_resolved_last_weighed_date date;
  v_resolved_core_type text;
  v_resolved_core_weight numeric;
  v_resolved_lf_weight numeric;
  v_effective_sq_ft_weight numeric;
  v_active_allocated_feet integer := 0;
  v_is_first_receipt boolean := false;
  v_weight_changed boolean := false;
  v_resolved_warehouse text;
begin
  if p_existing_box_id is not null then
    select *
    into v_existing
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id = app_api.trim_text(p_existing_box_id)
    for update;

    if not found then
      perform app_api.raise_http(404, 'Box not found.');
    end if;
  end if;

  v_box_id := coalesce(v_existing.box_id, app_api.require_text(p_payload->>'boxId', 'BoxID'));
  v_manufacturer := app_api.require_text(p_payload->>'manufacturer', 'Manufacturer');
  v_film_name := app_api.require_text(p_payload->>'filmName', 'FilmName');
  v_width_in := nullif(app_api.trim_text(p_payload->>'widthIn'), '')::numeric;
  v_initial_feet := floor(nullif(app_api.trim_text(p_payload->>'initialFeet'), '')::numeric);
  v_order_date := nullif(app_api.trim_text(p_payload->>'orderDate'), '')::date;
  v_received_date := nullif(app_api.trim_text(p_payload->>'receivedDate'), '')::date;
  v_feet_available_input := app_api.trim_text(p_payload->>'feetAvailable');
  v_film_key := upper(coalesce(nullif(app_api.trim_text(p_payload->>'filmKey'), ''), upper(v_manufacturer) || '|' || upper(v_film_name)));
  v_initial_weight_input := nullif(app_api.trim_text(p_payload->>'initialWeightLbs'), '')::numeric;
  v_last_roll_weight_input := nullif(app_api.trim_text(p_payload->>'lastRollWeightLbs'), '')::numeric;
  v_last_weighed_date_input := nullif(app_api.trim_text(p_payload->>'lastWeighedDate'), '')::date;
  v_core_type_input := app_api.normalize_core_type(p_payload->>'coreType', true);
  v_existing_core_type := coalesce(app_api.normalize_core_type(v_existing.core_type, true), '');
  v_resolved_warehouse := app_api.resolve_warehouse_from_box_id(p_org_id, v_box_id);

  if v_width_in is null or v_width_in <= 0 then
    perform app_api.raise_http(400, 'WidthIn must be greater than zero.');
  end if;

  if v_initial_feet is null or v_initial_feet < 0 then
    perform app_api.raise_http(400, 'InitialFeet must be zero or greater.');
  end if;

  if v_order_date is null then
    perform app_api.raise_http(400, 'OrderDate is required.');
  end if;

  if v_existing.received_date is not null and v_received_date is null then
    perform app_api.raise_http(400, 'ReceivedDate cannot be cleared after a box has been received.');
  end if;

  if v_feet_available_input = '' then
    v_feet_available := coalesce(v_existing.feet_available, app_api.derive_add_feet_available(v_initial_feet, v_received_date));
  else
    v_feet_available := floor(v_feet_available_input::numeric);
    if v_feet_available < 0 then
      v_feet_available := 0;
      v_warnings := app_api.push_warning(v_warnings, 'FeetAvailable was clamped to 0.');
    end if;
  end if;

  v_resolved_initial_weight := v_initial_weight_input;
  v_resolved_last_roll_weight := v_last_roll_weight_input;
  v_resolved_last_weighed_date := v_last_weighed_date_input;
  v_resolved_core_type := coalesce(nullif(v_core_type_input, ''), v_existing_core_type, '');
  v_resolved_core_weight := v_existing.core_weight_lbs;
  v_resolved_lf_weight := v_existing.lf_weight_lbs_per_ft;

  if v_received_date is not null then
    if v_initial_feet <= 0 then
      perform app_api.raise_http(400, 'InitialFeet must be greater than zero for received boxes.');
    end if;

    select *
    into v_film_data
    from app.film_catalog f
    where f.org_id = p_org_id
      and f.film_key = v_film_key
    for update;

    if v_resolved_core_type = '' then
      v_resolved_core_type := app_api.normalize_core_type(v_film_data.default_core_type, true);
    end if;

    if v_film_data.sq_ft_weight_lbs_per_sq_ft is not null then
      if v_resolved_core_type = '' then
        perform app_api.raise_http(400, 'CoreType is required before this film can be received.');
      end if;

      v_effective_sq_ft_weight := v_film_data.sq_ft_weight_lbs_per_sq_ft;
      v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_width_in);

      if v_initial_weight_input is not null then
        v_effective_sq_ft_weight := app_api.derive_sqft_weight_lbs_per_sqft(
          v_initial_weight_input,
          v_resolved_core_weight,
          v_width_in,
          v_initial_feet
        );
        v_resolved_initial_weight := round(v_initial_weight_input, 2);
      else
        v_resolved_initial_weight := app_api.derive_initial_weight_lbs(
          app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in),
          v_initial_feet,
          v_resolved_core_weight
        );
        v_warnings := app_api.push_warning(v_warnings, 'Initial and last roll weights were auto-filled from FILM DATA.');
      end if;

      v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
    else
      if v_resolved_core_type = '' then
        perform app_api.raise_http(400, 'CoreType is required the first time a received film is saved.');
      end if;

      if v_initial_weight_input is null and v_existing.initial_weight_lbs is null then
        perform app_api.raise_http(400, 'InitialWeightLbs is required the first time a received film is saved.');
      end if;

      v_resolved_initial_weight := coalesce(v_initial_weight_input, v_existing.initial_weight_lbs);
      v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_width_in);
      v_effective_sq_ft_weight := app_api.derive_sqft_weight_lbs_per_sqft(
        v_resolved_initial_weight,
        v_resolved_core_weight,
        v_width_in,
        v_initial_feet
      );
      v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
      perform app_api.save_film_catalog(
        p_org_id,
        v_film_key,
        v_manufacturer,
        v_film_name,
        v_effective_sq_ft_weight,
        v_resolved_core_type,
        v_width_in,
        v_initial_feet,
        v_resolved_initial_weight,
        v_box_id,
        coalesce(v_film_data.notes, '')
      );
      v_warnings := app_api.push_warning(v_warnings, format('FILM DATA was created from the first received weight for %s.', v_film_key));
    end if;

    if v_resolved_last_roll_weight is null then
      v_resolved_last_roll_weight := coalesce(v_existing.last_roll_weight_lbs, v_resolved_initial_weight);
    end if;
    if v_resolved_last_weighed_date is null then
      v_resolved_last_weighed_date := coalesce(v_existing.last_weighed_date, v_received_date);
    end if;

    if v_film_data.id is not null and (coalesce(v_film_data.default_core_type, '') = '' or coalesce(v_film_data.default_core_type, '') <> v_resolved_core_type) then
      perform app_api.save_film_catalog(
        p_org_id,
        v_film_key,
        coalesce(v_film_data.manufacturer, v_manufacturer),
        coalesce(v_film_data.film_name, v_film_name),
        coalesce(v_film_data.sq_ft_weight_lbs_per_sq_ft, v_effective_sq_ft_weight),
        v_resolved_core_type,
        coalesce(v_film_data.source_width_in, v_width_in),
        coalesce(v_film_data.source_initial_feet, v_initial_feet),
        coalesce(v_film_data.source_initial_weight_lbs, v_resolved_initial_weight),
        coalesce(v_film_data.source_box_id, v_box_id),
        coalesce(v_film_data.notes, '')
      );
      v_warnings := app_api.push_warning(v_warnings, 'FILM DATA was updated with the selected core type.');
    end if;

    select coalesce(sum(a.allocated_feet), 0)::integer
    into v_active_allocated_feet
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_box_id
      and a.status = 'ACTIVE';

    v_is_first_receipt := v_existing.received_date is null;
    v_weight_changed := v_existing.last_roll_weight_lbs is distinct from v_resolved_last_roll_weight;

    if v_is_first_receipt then
      v_feet_available := greatest(v_initial_feet - v_active_allocated_feet, 0);
    elsif v_weight_changed then
      v_feet_available := greatest(
        app_api.derive_feet_available_from_roll_weight(
          v_resolved_last_roll_weight,
          v_resolved_core_weight,
          v_resolved_lf_weight,
          v_initial_feet
        ) - v_active_allocated_feet,
        0
      );
    else
      v_feet_available := least(greatest(coalesce(v_existing.feet_available, v_feet_available), 0), v_initial_feet);
    end if;
  else
    v_resolved_initial_weight := null;
    v_resolved_last_roll_weight := null;
    v_resolved_last_weighed_date := null;
    v_resolved_core_type := '';
    v_resolved_core_weight := null;
    v_resolved_lf_weight := null;
  end if;

  v_box.id := v_existing.id;
  v_box.org_id := p_org_id;
  v_box.box_id := v_box_id;
  v_box.warehouse := v_resolved_warehouse;
  v_box.manufacturer := v_manufacturer;
  v_box.film_name := v_film_name;
  v_box.width_in := v_width_in;
  v_box.initial_feet := v_initial_feet;
  v_box.feet_available := v_feet_available;
  v_box.lot_run := app_api.trim_text(p_payload->>'lotRun');
  v_box.status := case
    when v_existing.status in ('CHECKED_OUT', 'ZEROED', 'RETIRED') then v_existing.status
    else app_api.derive_lifecycle_status(v_received_date)
  end;
  v_box.order_date := v_order_date;
  v_box.received_date := v_received_date;
  v_box.initial_weight_lbs := v_resolved_initial_weight;
  v_box.last_roll_weight_lbs := v_resolved_last_roll_weight;
  v_box.last_weighed_date := v_resolved_last_weighed_date;
  v_box.film_key := v_film_key;
  v_box.core_type := v_resolved_core_type;
  v_box.core_weight_lbs := v_resolved_core_weight;
  v_box.lf_weight_lbs_per_ft := v_resolved_lf_weight;
  v_box.price_per_lf := nullif(app_api.trim_text(p_payload->>'pricePerLf'), '')::numeric;
  if v_box.price_per_lf is not null and v_box.price_per_lf < 0 then
    perform app_api.raise_http(400, 'PricePerLf must be zero or greater.');
  end if;
  v_box.purchase_cost := nullif(app_api.trim_text(p_payload->>'purchaseCost'), '')::numeric;
  v_box.notes := app_api.trim_text(p_payload->>'notes');
  v_box.has_ever_been_checked_out := coalesce(v_existing.has_ever_been_checked_out, false);
  v_box.last_checkout_job := coalesce(v_existing.last_checkout_job, '');
  v_box.last_checkout_date := v_existing.last_checkout_date;
  v_box.zeroed_date := null;
  v_box.zeroed_reason := '';
  v_box.zeroed_by := '';

  return jsonb_build_object(
    'box', to_jsonb(v_box),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function app_api.public_box_state_to_box_row(
  p_org_id uuid,
  p_state jsonb,
  p_existing_id uuid default null
)
returns app.boxes
language plpgsql
stable
security definer
set search_path = public, app, app_api
as $$
declare
  v_box app.boxes;
begin
  if p_state is null then
    return null;
  end if;

  v_box.id := p_existing_id;
  v_box.org_id := p_org_id;
  v_box.box_id := p_state->>'boxId';
  v_box.warehouse := app_api.require_org_warehouse(p_org_id, p_state->>'warehouse', 'Warehouse');
  v_box.manufacturer := coalesce(p_state->>'manufacturer', '');
  v_box.film_name := coalesce(p_state->>'filmName', '');
  v_box.width_in := nullif(app_api.trim_text(p_state->>'widthIn'), '')::numeric;
  v_box.initial_feet := coalesce((p_state->>'initialFeet')::integer, 0);
  v_box.feet_available := coalesce((p_state->>'feetAvailable')::integer, 0);
  v_box.lot_run := coalesce(p_state->>'lotRun', '');
  v_box.status := (p_state->>'status')::app.box_status;
  v_box.order_date := nullif(app_api.trim_text(p_state->>'orderDate'), '')::date;
  v_box.received_date := nullif(app_api.trim_text(p_state->>'receivedDate'), '')::date;
  v_box.initial_weight_lbs := nullif(app_api.trim_text(p_state->>'initialWeightLbs'), '')::numeric;
  v_box.last_roll_weight_lbs := nullif(app_api.trim_text(p_state->>'lastRollWeightLbs'), '')::numeric;
  v_box.last_weighed_date := nullif(app_api.trim_text(p_state->>'lastWeighedDate'), '')::date;
  v_box.film_key := coalesce(p_state->>'filmKey', '');
  v_box.core_type := coalesce(p_state->>'coreType', '');
  v_box.core_weight_lbs := nullif(app_api.trim_text(p_state->>'coreWeightLbs'), '')::numeric;
  v_box.lf_weight_lbs_per_ft := nullif(app_api.trim_text(p_state->>'lfWeightLbsPerFt'), '')::numeric;
  v_box.price_per_lf := nullif(app_api.trim_text(p_state->>'pricePerLf'), '')::numeric;
  v_box.purchase_cost := nullif(app_api.trim_text(p_state->>'purchaseCost'), '')::numeric;
  v_box.notes := coalesce(p_state->>'notes', '');
  v_box.has_ever_been_checked_out := coalesce((p_state->>'hasEverBeenCheckedOut')::boolean, false);
  v_box.last_checkout_job := coalesce(p_state->>'lastCheckoutJob', '');
  v_box.last_checkout_date := nullif(app_api.trim_text(p_state->>'lastCheckoutDate'), '')::date;
  v_box.zeroed_date := nullif(app_api.trim_text(p_state->>'zeroedDate'), '')::date;
  v_box.zeroed_reason := coalesce(p_state->>'zeroedReason', '');
  v_box.zeroed_by := coalesce(p_state->>'zeroedBy', '');

  return v_box;
end;
$$;

create or replace function import.merge_boxes_from_staging(
  target_org_id uuid,
  normalize_existing boolean default true,
  conflict_mode text default 'keep_existing'
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, import, app_api
as $$
declare
  v_mode text := lower(btrim(coalesce(conflict_mode, 'keep_existing')));
  v_prepared_count integer := 0;
  v_inserted_count integer := 0;
  v_updated_count integer := 0;
  v_skipped_count integer := 0;
  v_existing_conflicts integer := 0;
  v_stage_duplicates integer := 0;
  v_normalize_result jsonb := '{}'::jsonb;
  v_price_per_lf_backfilled_count integer := 0;
begin
  if target_org_id is null then
    raise exception 'target_org_id is required';
  end if;

  if not exists (
    select 1
    from app.organizations o
    where o.id = target_org_id
  ) then
    raise exception 'Organization % does not exist in app.organizations', target_org_id;
  end if;

  if v_mode not in ('keep_existing', 'overwrite_existing') then
    raise exception 'Invalid conflict_mode %. Allowed values: keep_existing, overwrite_existing', conflict_mode;
  end if;

  -- Make sure IL/MS warehouse defaults exist for older orgs.
  perform app_api.ensure_default_warehouses_for_org(target_org_id, 'import-merge');

  if normalize_existing then
    v_normalize_result := import.normalize_existing_box_ids(target_org_id);
  end if;

  create temporary table tmp_import_boxes_prepared on commit drop as
  with src as (
    select
      trim("BoxID") as raw_box_id,
      trim("Manufacturer") as manufacturer,
      trim("FilmName") as film_name,
      trim("WidthIn") as width_in_raw,
      trim("InitialFeet") as initial_feet_raw,
      trim("FeetAvailable") as feet_available_raw,
      trim("LotRun") as lot_run_raw,
      trim("Status") as status_raw,
      trim("OrderDate") as order_date_raw,
      trim("ReceivedDate") as received_date_raw,
      trim("InitialWeightLbs") as initial_weight_lbs_raw,
      trim("LastRollWeightLbs") as last_roll_weight_lbs_raw,
      trim("LastWeighedDate") as last_weighed_date_raw,
      trim("FilmKey") as film_key_raw,
      trim("CoreType") as core_type_raw,
      trim("CoreWeightLbs") as core_weight_lbs_raw,
      trim("LfWeightLbsPerFt") as lf_weight_lbs_per_ft_raw,
      trim("PricePerLf") as price_per_lf_raw,
      trim("PurchaseCost") as purchase_cost_raw,
      trim("Notes") as notes_raw,
      trim("HasEverBeenCheckedOut") as has_ever_raw,
      trim("LastCheckoutJob") as last_checkout_job_raw,
      trim("LastCheckoutDate") as last_checkout_date_raw,
      trim("ZeroedDate") as zeroed_date_raw,
      trim("ZeroedReason") as zeroed_reason_raw,
      trim("ZeroedBy") as zeroed_by_raw
    from import.boxes_raw
    where coalesce(trim("BoxID"), '') <> ''
  ),
  canon as (
    select
      import.canonical_box_id(
        target_org_id,
        case when upper(left(raw_box_id, 1)) = 'M' then 'MS' else 'IL' end,
        raw_box_id
      ) as box_id,
      manufacturer,
      film_name,
      width_in_raw,
      initial_feet_raw,
      feet_available_raw,
      lot_run_raw,
      status_raw,
      order_date_raw,
      received_date_raw,
      initial_weight_lbs_raw,
      last_roll_weight_lbs_raw,
      last_weighed_date_raw,
      film_key_raw,
      core_type_raw,
      core_weight_lbs_raw,
      lf_weight_lbs_per_ft_raw,
      price_per_lf_raw,
      purchase_cost_raw,
      notes_raw,
      has_ever_raw,
      last_checkout_job_raw,
      last_checkout_date_raw,
      zeroed_date_raw,
      zeroed_reason_raw,
      zeroed_by_raw
    from src
  )
  select
    c.box_id,
    app_api.resolve_warehouse_from_box_id(target_org_id, c.box_id) as warehouse,
    c.manufacturer,
    c.film_name,
    nullif(c.width_in_raw, '')::numeric(10, 4) as width_in,
    nullif(c.initial_feet_raw, '')::integer as initial_feet,
    coalesce(nullif(c.feet_available_raw, '')::integer, 0) as feet_available,
    coalesce(c.lot_run_raw, '') as lot_run,
    (
      case
        when upper(coalesce(c.status_raw, '')) in ('ORDERED', 'IN_STOCK', 'CHECKED_OUT', 'ZEROED', 'RETIRED')
          then upper(c.status_raw)
        when nullif(c.received_date_raw, '') is not null and nullif(c.received_date_raw, '')::date <= current_date
          then 'IN_STOCK'
        else 'ORDERED'
      end
    )::app.box_status as status,
    nullif(c.order_date_raw, '')::date as order_date,
    nullif(c.received_date_raw, '')::date as received_date,
    nullif(c.initial_weight_lbs_raw, '')::numeric(12, 2) as initial_weight_lbs,
    nullif(c.last_roll_weight_lbs_raw, '')::numeric(12, 2) as last_roll_weight_lbs,
    nullif(c.last_weighed_date_raw, '')::date as last_weighed_date,
    coalesce(nullif(c.film_key_raw, ''), upper(c.manufacturer) || '|' || upper(c.film_name)) as film_key,
    coalesce(nullif(c.core_type_raw, ''), '') as core_type,
    nullif(c.core_weight_lbs_raw, '')::numeric(12, 4) as core_weight_lbs,
    nullif(c.lf_weight_lbs_per_ft_raw, '')::numeric(12, 6) as lf_weight_lbs_per_ft,
    nullif(c.price_per_lf_raw, '')::numeric(12, 4) as price_per_lf,
    nullif(c.purchase_cost_raw, '')::numeric(12, 2) as purchase_cost,
    coalesce(c.notes_raw, '') as notes,
    import.to_bool(c.has_ever_raw) as has_ever_been_checked_out,
    coalesce(c.last_checkout_job_raw, '') as last_checkout_job,
    nullif(c.last_checkout_date_raw, '')::date as last_checkout_date,
    nullif(c.zeroed_date_raw, '')::date as zeroed_date,
    coalesce(c.zeroed_reason_raw, '') as zeroed_reason,
    coalesce(c.zeroed_by_raw, '') as zeroed_by
  from canon c
  where coalesce(c.box_id, '') <> '';

  select count(*)
  into v_stage_duplicates
  from (
    select t.box_id
    from tmp_import_boxes_prepared t
    group by t.box_id
    having count(*) > 1
  ) d;

  if v_stage_duplicates > 0 then
    raise exception
      'Staging contains % canonical BoxID duplicate(s) after prefix normalization. Resolve duplicates before merge.',
      v_stage_duplicates;
  end if;

  select count(*)
  into v_prepared_count
  from tmp_import_boxes_prepared;

  select count(*)
  into v_existing_conflicts
  from tmp_import_boxes_prepared t
  join app.boxes b
    on b.org_id = target_org_id
   and b.box_id = t.box_id;

  if v_mode = 'keep_existing' then
    insert into app.boxes (
      id,
      org_id,
      box_id,
      warehouse,
      manufacturer,
      film_name,
      width_in,
      initial_feet,
      feet_available,
      lot_run,
      status,
      order_date,
      received_date,
      initial_weight_lbs,
      last_roll_weight_lbs,
      last_weighed_date,
      film_key,
      core_type,
      core_weight_lbs,
      lf_weight_lbs_per_ft,
      price_per_lf,
      purchase_cost,
      notes,
      has_ever_been_checked_out,
      last_checkout_job,
      last_checkout_date,
      zeroed_date,
      zeroed_reason,
      zeroed_by
    )
    select
      gen_random_uuid(),
      target_org_id,
      t.box_id,
      t.warehouse,
      t.manufacturer,
      t.film_name,
      t.width_in,
      t.initial_feet,
      t.feet_available,
      t.lot_run,
      t.status,
      t.order_date,
      t.received_date,
      t.initial_weight_lbs,
      t.last_roll_weight_lbs,
      t.last_weighed_date,
      t.film_key,
      t.core_type,
      t.core_weight_lbs,
      t.lf_weight_lbs_per_ft,
      t.price_per_lf,
      t.purchase_cost,
      t.notes,
      t.has_ever_been_checked_out,
      t.last_checkout_job,
      t.last_checkout_date,
      t.zeroed_date,
      t.zeroed_reason,
      t.zeroed_by
    from tmp_import_boxes_prepared t
    on conflict (org_id, box_id) do nothing;

    get diagnostics v_inserted_count = row_count;
    v_updated_count := 0;
    v_skipped_count := v_prepared_count - v_inserted_count;

    update app.boxes b
    set
      price_per_lf = t.price_per_lf,
      updated_at = now()
    from tmp_import_boxes_prepared t
    where b.org_id = target_org_id
      and b.box_id = t.box_id
      and b.price_per_lf is null
      and t.price_per_lf is not null;
    get diagnostics v_price_per_lf_backfilled_count = row_count;
  else
    insert into app.boxes (
      id,
      org_id,
      box_id,
      warehouse,
      manufacturer,
      film_name,
      width_in,
      initial_feet,
      feet_available,
      lot_run,
      status,
      order_date,
      received_date,
      initial_weight_lbs,
      last_roll_weight_lbs,
      last_weighed_date,
      film_key,
      core_type,
      core_weight_lbs,
      lf_weight_lbs_per_ft,
      price_per_lf,
      purchase_cost,
      notes,
      has_ever_been_checked_out,
      last_checkout_job,
      last_checkout_date,
      zeroed_date,
      zeroed_reason,
      zeroed_by
    )
    select
      gen_random_uuid(),
      target_org_id,
      t.box_id,
      t.warehouse,
      t.manufacturer,
      t.film_name,
      t.width_in,
      t.initial_feet,
      t.feet_available,
      t.lot_run,
      t.status,
      t.order_date,
      t.received_date,
      t.initial_weight_lbs,
      t.last_roll_weight_lbs,
      t.last_weighed_date,
      t.film_key,
      t.core_type,
      t.core_weight_lbs,
      t.lf_weight_lbs_per_ft,
      t.price_per_lf,
      t.purchase_cost,
      t.notes,
      t.has_ever_been_checked_out,
      t.last_checkout_job,
      t.last_checkout_date,
      t.zeroed_date,
      t.zeroed_reason,
      t.zeroed_by
    from tmp_import_boxes_prepared t
    on conflict (org_id, box_id) do update set
      warehouse = excluded.warehouse,
      manufacturer = excluded.manufacturer,
      film_name = excluded.film_name,
      width_in = excluded.width_in,
      initial_feet = excluded.initial_feet,
      feet_available = excluded.feet_available,
      lot_run = excluded.lot_run,
      status = excluded.status,
      order_date = excluded.order_date,
      received_date = excluded.received_date,
      initial_weight_lbs = excluded.initial_weight_lbs,
      last_roll_weight_lbs = excluded.last_roll_weight_lbs,
      last_weighed_date = excluded.last_weighed_date,
      film_key = excluded.film_key,
      core_type = excluded.core_type,
      core_weight_lbs = excluded.core_weight_lbs,
      lf_weight_lbs_per_ft = excluded.lf_weight_lbs_per_ft,
      price_per_lf = coalesce(app.boxes.price_per_lf, excluded.price_per_lf),
      purchase_cost = excluded.purchase_cost,
      notes = excluded.notes,
      has_ever_been_checked_out = excluded.has_ever_been_checked_out,
      last_checkout_job = excluded.last_checkout_job,
      last_checkout_date = excluded.last_checkout_date,
      zeroed_date = excluded.zeroed_date,
      zeroed_reason = excluded.zeroed_reason,
      zeroed_by = excluded.zeroed_by,
      updated_at = now();

    -- On overwrite mode, all prepared rows are applied.
    v_inserted_count := v_prepared_count - v_existing_conflicts;
    v_updated_count := v_existing_conflicts;
    v_skipped_count := 0;
  end if;

  return jsonb_build_object(
    'mode', v_mode,
    'prepared_rows', v_prepared_count,
    'existing_conflicts', v_existing_conflicts,
    'inserted_rows', v_inserted_count,
    'updated_rows', v_updated_count,
    'skipped_rows', v_skipped_count,
    'price_per_lf_backfilled_rows', v_price_per_lf_backfilled_count,
    'normalize_existing_applied', normalize_existing,
    'normalize_existing_result', v_normalize_result
  );
end;
$$;

-- Derive price_per_lf from purchase_cost when purchase cost is provided on add/update.

create or replace function app_api.build_box_from_payload(
  p_org_id uuid,
  p_payload jsonb,
  p_existing_box_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_box app.boxes;
  v_film_data app.film_catalog;
  v_warnings text[] := array[]::text[];
  v_box_id text;
  v_manufacturer text;
  v_film_name text;
  v_width_in numeric;
  v_initial_feet integer;
  v_order_date date;
  v_received_date date;
  v_feet_available_input text;
  v_feet_available integer;
  v_film_key text;
  v_initial_weight_input numeric;
  v_last_roll_weight_input numeric;
  v_last_weighed_date_input date;
  v_core_type_input text;
  v_existing_core_type text;
  v_resolved_initial_weight numeric;
  v_resolved_last_roll_weight numeric;
  v_resolved_last_weighed_date date;
  v_resolved_core_type text;
  v_resolved_core_weight numeric;
  v_resolved_lf_weight numeric;
  v_effective_sq_ft_weight numeric;
  v_active_allocated_feet integer := 0;
  v_is_first_receipt boolean := false;
  v_weight_changed boolean := false;
  v_resolved_warehouse text;
  v_has_price_per_lf boolean := coalesce(p_payload, '{}'::jsonb) ? 'pricePerLf';
begin
  if p_existing_box_id is not null then
    select *
    into v_existing
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id = app_api.trim_text(p_existing_box_id)
    for update;

    if not found then
      perform app_api.raise_http(404, 'Box not found.');
    end if;
  end if;

  v_box_id := coalesce(v_existing.box_id, app_api.require_text(p_payload->>'boxId', 'BoxID'));
  v_manufacturer := app_api.require_text(p_payload->>'manufacturer', 'Manufacturer');
  v_film_name := app_api.require_text(p_payload->>'filmName', 'FilmName');
  v_width_in := nullif(app_api.trim_text(p_payload->>'widthIn'), '')::numeric;
  v_initial_feet := floor(nullif(app_api.trim_text(p_payload->>'initialFeet'), '')::numeric);
  v_order_date := nullif(app_api.trim_text(p_payload->>'orderDate'), '')::date;
  v_received_date := nullif(app_api.trim_text(p_payload->>'receivedDate'), '')::date;
  v_feet_available_input := app_api.trim_text(p_payload->>'feetAvailable');
  v_film_key := upper(coalesce(nullif(app_api.trim_text(p_payload->>'filmKey'), ''), upper(v_manufacturer) || '|' || upper(v_film_name)));
  v_initial_weight_input := nullif(app_api.trim_text(p_payload->>'initialWeightLbs'), '')::numeric;
  v_last_roll_weight_input := nullif(app_api.trim_text(p_payload->>'lastRollWeightLbs'), '')::numeric;
  v_last_weighed_date_input := nullif(app_api.trim_text(p_payload->>'lastWeighedDate'), '')::date;
  v_core_type_input := app_api.normalize_core_type(p_payload->>'coreType', true);
  v_existing_core_type := coalesce(app_api.normalize_core_type(v_existing.core_type, true), '');
  v_resolved_warehouse := app_api.resolve_warehouse_from_box_id(p_org_id, v_box_id);

  if v_width_in is null or v_width_in <= 0 then
    perform app_api.raise_http(400, 'WidthIn must be greater than zero.');
  end if;

  if v_initial_feet is null or v_initial_feet < 0 then
    perform app_api.raise_http(400, 'InitialFeet must be zero or greater.');
  end if;

  if v_order_date is null then
    perform app_api.raise_http(400, 'OrderDate is required.');
  end if;

  if v_existing.received_date is not null and v_received_date is null then
    perform app_api.raise_http(400, 'ReceivedDate cannot be cleared after a box has been received.');
  end if;

  if v_feet_available_input = '' then
    v_feet_available := coalesce(v_existing.feet_available, app_api.derive_add_feet_available(v_initial_feet, v_received_date));
  else
    v_feet_available := floor(v_feet_available_input::numeric);
    if v_feet_available < 0 then
      v_feet_available := 0;
      v_warnings := app_api.push_warning(v_warnings, 'FeetAvailable was clamped to 0.');
    end if;
  end if;

  v_resolved_initial_weight := v_initial_weight_input;
  v_resolved_last_roll_weight := v_last_roll_weight_input;
  v_resolved_last_weighed_date := v_last_weighed_date_input;
  v_resolved_core_type := coalesce(nullif(v_core_type_input, ''), v_existing_core_type, '');
  v_resolved_core_weight := v_existing.core_weight_lbs;
  v_resolved_lf_weight := v_existing.lf_weight_lbs_per_ft;

  if v_received_date is not null then
    if v_initial_feet <= 0 then
      perform app_api.raise_http(400, 'InitialFeet must be greater than zero for received boxes.');
    end if;

    select *
    into v_film_data
    from app.film_catalog f
    where f.org_id = p_org_id
      and f.film_key = v_film_key
    for update;

    if v_resolved_core_type = '' then
      v_resolved_core_type := app_api.normalize_core_type(v_film_data.default_core_type, true);
    end if;

    if v_film_data.sq_ft_weight_lbs_per_sq_ft is not null then
      if v_resolved_core_type = '' then
        perform app_api.raise_http(400, 'CoreType is required before this film can be received.');
      end if;

      v_effective_sq_ft_weight := v_film_data.sq_ft_weight_lbs_per_sq_ft;
      v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_width_in);

      if v_initial_weight_input is not null then
        v_effective_sq_ft_weight := app_api.derive_sqft_weight_lbs_per_sqft(
          v_initial_weight_input,
          v_resolved_core_weight,
          v_width_in,
          v_initial_feet
        );
        v_resolved_initial_weight := round(v_initial_weight_input, 2);
      else
        v_resolved_initial_weight := app_api.derive_initial_weight_lbs(
          app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in),
          v_initial_feet,
          v_resolved_core_weight
        );
        v_warnings := app_api.push_warning(v_warnings, 'Initial and last roll weights were auto-filled from FILM DATA.');
      end if;

      v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
    else
      if v_resolved_core_type = '' then
        perform app_api.raise_http(400, 'CoreType is required the first time a received film is saved.');
      end if;

      if v_initial_weight_input is null and v_existing.initial_weight_lbs is null then
        perform app_api.raise_http(400, 'InitialWeightLbs is required the first time a received film is saved.');
      end if;

      v_resolved_initial_weight := coalesce(v_initial_weight_input, v_existing.initial_weight_lbs);
      v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_width_in);
      v_effective_sq_ft_weight := app_api.derive_sqft_weight_lbs_per_sqft(
        v_resolved_initial_weight,
        v_resolved_core_weight,
        v_width_in,
        v_initial_feet
      );
      v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
      perform app_api.save_film_catalog(
        p_org_id,
        v_film_key,
        v_manufacturer,
        v_film_name,
        v_effective_sq_ft_weight,
        v_resolved_core_type,
        v_width_in,
        v_initial_feet,
        v_resolved_initial_weight,
        v_box_id,
        coalesce(v_film_data.notes, '')
      );
      v_warnings := app_api.push_warning(v_warnings, format('FILM DATA was created from the first received weight for %s.', v_film_key));
    end if;

    if v_resolved_last_roll_weight is null then
      v_resolved_last_roll_weight := coalesce(v_existing.last_roll_weight_lbs, v_resolved_initial_weight);
    end if;
    if v_resolved_last_weighed_date is null then
      v_resolved_last_weighed_date := coalesce(v_existing.last_weighed_date, v_received_date);
    end if;

    if v_film_data.id is not null and (coalesce(v_film_data.default_core_type, '') = '' or coalesce(v_film_data.default_core_type, '') <> v_resolved_core_type) then
      perform app_api.save_film_catalog(
        p_org_id,
        v_film_key,
        coalesce(v_film_data.manufacturer, v_manufacturer),
        coalesce(v_film_data.film_name, v_film_name),
        coalesce(v_film_data.sq_ft_weight_lbs_per_sq_ft, v_effective_sq_ft_weight),
        v_resolved_core_type,
        coalesce(v_film_data.source_width_in, v_width_in),
        coalesce(v_film_data.source_initial_feet, v_initial_feet),
        coalesce(v_film_data.source_initial_weight_lbs, v_resolved_initial_weight),
        coalesce(v_film_data.source_box_id, v_box_id),
        coalesce(v_film_data.notes, '')
      );
      v_warnings := app_api.push_warning(v_warnings, 'FILM DATA was updated with the selected core type.');
    end if;

    select coalesce(sum(a.allocated_feet), 0)::integer
    into v_active_allocated_feet
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_box_id
      and a.status = 'ACTIVE';

    v_is_first_receipt := v_existing.received_date is null;
    v_weight_changed := v_existing.last_roll_weight_lbs is distinct from v_resolved_last_roll_weight;

    if v_is_first_receipt then
      v_feet_available := greatest(v_initial_feet - v_active_allocated_feet, 0);
    elsif v_weight_changed then
      v_feet_available := greatest(
        app_api.derive_feet_available_from_roll_weight(
          v_resolved_last_roll_weight,
          v_resolved_core_weight,
          v_resolved_lf_weight,
          v_initial_feet
        ) - v_active_allocated_feet,
        0
      );
    else
      v_feet_available := least(greatest(coalesce(v_existing.feet_available, v_feet_available), 0), v_initial_feet);
    end if;
  else
    v_resolved_initial_weight := null;
    v_resolved_last_roll_weight := null;
    v_resolved_last_weighed_date := null;
    v_resolved_core_type := '';
    v_resolved_core_weight := null;
    v_resolved_lf_weight := null;
  end if;

  v_box.id := v_existing.id;
  v_box.org_id := p_org_id;
  v_box.box_id := v_box_id;
  v_box.warehouse := v_resolved_warehouse;
  v_box.manufacturer := v_manufacturer;
  v_box.film_name := v_film_name;
  v_box.width_in := v_width_in;
  v_box.initial_feet := v_initial_feet;
  v_box.feet_available := v_feet_available;
  v_box.lot_run := app_api.trim_text(p_payload->>'lotRun');
  v_box.status := case
    when v_existing.status in ('CHECKED_OUT', 'ZEROED', 'RETIRED') then v_existing.status
    else app_api.derive_lifecycle_status(v_received_date)
  end;
  v_box.order_date := v_order_date;
  v_box.received_date := v_received_date;
  v_box.initial_weight_lbs := v_resolved_initial_weight;
  v_box.last_roll_weight_lbs := v_resolved_last_roll_weight;
  v_box.last_weighed_date := v_resolved_last_weighed_date;
  v_box.film_key := v_film_key;
  v_box.core_type := v_resolved_core_type;
  v_box.core_weight_lbs := v_resolved_core_weight;
  v_box.lf_weight_lbs_per_ft := v_resolved_lf_weight;
  v_box.purchase_cost := nullif(app_api.trim_text(p_payload->>'purchaseCost'), '')::numeric;
  if v_box.purchase_cost is not null and v_box.purchase_cost < 0 then
    perform app_api.raise_http(400, 'PurchaseCost must be zero or greater.');
  end if;
  if v_box.purchase_cost is not null and v_initial_feet <= 0 then
    perform app_api.raise_http(400, 'PurchaseCost requires InitialFeet > 0 to derive PricePerLf.');
  end if;

  if v_box.purchase_cost is not null then
    v_box.price_per_lf := round(v_box.purchase_cost / v_initial_feet, 4);
  elsif v_has_price_per_lf then
    v_box.price_per_lf := nullif(app_api.trim_text(p_payload->>'pricePerLf'), '')::numeric;
    if v_box.price_per_lf is not null and v_box.price_per_lf < 0 then
      perform app_api.raise_http(400, 'PricePerLf must be zero or greater.');
    end if;
  else
    v_box.price_per_lf := v_existing.price_per_lf;
  end if;
  v_box.notes := app_api.trim_text(p_payload->>'notes');
  v_box.has_ever_been_checked_out := coalesce(v_existing.has_ever_been_checked_out, false);
  v_box.last_checkout_job := coalesce(v_existing.last_checkout_job, '');
  v_box.last_checkout_date := v_existing.last_checkout_date;
  v_box.zeroed_date := null;
  v_box.zeroed_reason := '';
  v_box.zeroed_by := '';

  return jsonb_build_object(
    'box', to_jsonb(v_box),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function public.api_acl_allocations_caulk_checkin(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_checkout app.caulk_job_checkouts;
  v_allocation app.caulk_job_allocations;
  v_actor text := app_api.trim_text(p_actor);
  v_caulk_checkout_id text := app_api.require_text(p_payload->>'caulkCheckoutId', 'CaulkCheckoutId');
  v_unused_loose_tubes integer := floor(nullif(app_api.trim_text(p_payload->>'unusedLooseTubes'), '')::numeric);
  v_unused_cases integer := floor(nullif(app_api.trim_text(p_payload->>'unusedCases'), '')::numeric);
  v_unused_tubes_legacy integer := floor(nullif(app_api.trim_text(p_payload->>'unusedTubes'), '')::numeric);
  v_tubes_per_case integer;
  v_total_returned_tubes integer;
  v_used_tubes integer;
  v_notes text := app_api.trim_text(p_payload->>'notes');
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  select *
  into v_checkout
  from app.caulk_job_checkouts c
  where c.org_id = p_org_id
    and c.caulk_checkout_id = v_caulk_checkout_id
  for update;

  if not found then
    perform app_api.raise_http(404, format('Caulk checkout %s was not found.', v_caulk_checkout_id));
  end if;

  if v_checkout.status <> 'OPEN' then
    perform app_api.raise_http(400, format('Caulk checkout %s is already closed.', v_caulk_checkout_id));
  end if;

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.id = v_checkout.caulk_allocation_id
  for update;

  if not found then
    perform app_api.raise_http(404, 'Parent caulk allocation was not found.');
  end if;

  if v_allocation.status <> 'ACTIVE' then
    perform app_api.raise_http(400, 'Parent caulk allocation is no longer active.');
  end if;

  select p.tubes_per_case
  into v_tubes_per_case
  from app.caulk_products p
  where p.org_id = p_org_id
    and p.id = v_allocation.product_id;

  if v_tubes_per_case is null or v_tubes_per_case <= 0 then
    perform app_api.raise_http(400, 'This caulk product is missing a valid tubesPerCase value.');
  end if;

  if v_unused_loose_tubes is null and v_unused_cases is null then
    if v_unused_tubes_legacy is null or v_unused_tubes_legacy < 0 then
      perform app_api.raise_http(400, 'unusedTubes must be zero or greater.');
    end if;

    v_total_returned_tubes := v_unused_tubes_legacy;
  else
    v_unused_loose_tubes := coalesce(v_unused_loose_tubes, 0);
    v_unused_cases := coalesce(v_unused_cases, 0);

    if v_unused_loose_tubes < 0 then
      perform app_api.raise_http(400, 'unusedLooseTubes must be zero or greater.');
    end if;

    if v_unused_cases < 0 then
      perform app_api.raise_http(400, 'unusedCases must be zero or greater.');
    end if;

    if v_unused_loose_tubes >= v_tubes_per_case then
      perform app_api.raise_http(
        400,
        format('unusedLooseTubes must be less than tubesPerCase (%s).', v_tubes_per_case)
      );
    end if;

    v_total_returned_tubes := v_unused_loose_tubes + (v_unused_cases * v_tubes_per_case);
  end if;

  if v_total_returned_tubes > v_checkout.checkout_tubes then
    perform app_api.raise_http(400, 'Returned caulk cannot exceed checked-out tubes.');
  end if;

  v_used_tubes := v_checkout.checkout_tubes - v_total_returned_tubes;

  if v_total_returned_tubes > 0 then
    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_allocation.product_id,
      v_allocation.warehouse,
      'JOB_CHECKIN_UNUSED',
      v_total_returned_tubes,
      format('Checked in unused caulk from allocation %s.', v_allocation.caulk_allocation_id),
      '',
      v_allocation.caulk_allocation_id,
      v_notes
    );
  end if;

  update app.caulk_job_checkouts
  set
    status = 'CLOSED',
    checked_in_at = now(),
    checked_in_by = v_actor,
    unused_tubes = v_total_returned_tubes,
    used_tubes = v_used_tubes,
    notes = v_notes
  where id = v_checkout.id
    and org_id = p_org_id;

  update app.caulk_job_allocations
  set
    returned_unused_tubes_total = v_allocation.returned_unused_tubes_total + v_total_returned_tubes,
    used_tubes_total = v_allocation.used_tubes_total + v_used_tubes,
    updated_at = now(),
    updated_by = v_actor
  where id = v_allocation.id
    and org_id = p_org_id;

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'caulkCheckoutId', v_checkout.caulk_checkout_id,
    'warnings', '[]'::jsonb
  );
end;
$$;

alter table app.jobs
  add column if not exists is_staged_for_pickup boolean not null default false;

create index if not exists idx_jobs_org_due_date_lifecycle
  on app.jobs (org_id, due_date desc, lifecycle_status, job_number);

create or replace function public.api_jobs_calendar(
  p_org_id uuid,
  p_month text,
  p_lifecycle_status text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_result jsonb;
  v_month text := app_api.trim_text(p_month);
  v_lifecycle text := upper(app_api.trim_text(p_lifecycle_status));
  v_start date;
  v_end date;
begin
  perform app_api.require_org_member(p_org_id);

  if v_month !~ '^\d{4}-\d{2}$' then
    perform app_api.raise_http(400, 'month must use yyyy-mm.');
  end if;

  if v_lifecycle = '' then
    v_lifecycle := 'ACTIVE';
  end if;

  if v_lifecycle not in ('ACTIVE', 'COMPLETED') then
    perform app_api.raise_http(400, 'lifecycleStatus must be ACTIVE or COMPLETED.');
  end if;

  v_start := (v_month || '-01')::date;
  v_end := (v_start + interval '1 month')::date;

  select coalesce(
    jsonb_agg(to_jsonb(j) order by j.due_date asc nulls last, j.job_number asc),
    '[]'::jsonb
  )
  into v_result
  from app.jobs j
  where j.org_id = p_org_id
    and j.due_date >= v_start
    and j.due_date < v_end
    and j.lifecycle_status::text = v_lifecycle;

  return v_result;
end;
$$;

create or replace function public.api_acl_list_jobs_calendar(
  p_org_id uuid,
  p_month text,
  p_lifecycle_status text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  perform app_api.require_effective_feature_access(p_org_id, 'jobs', 'read');
  return public.api_jobs_calendar(p_org_id, p_month, p_lifecycle_status);
end;
$$;

create or replace function public.api_jobs_set_staged_pickup(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_actor text := app_api.trim_text(p_actor);
  v_job_number text := app_api.require_job_number_digits(
    coalesce(p_payload->>'jobNumber', p_payload->>'job_number'),
    'JobNumber'
  );
  v_flag_text text := lower(app_api.trim_text(
    coalesce(
      p_payload->>'isStagedForPickup',
      p_payload->>'is_staged_for_pickup',
      p_payload->>'staged'
    )
  ));
  v_is_staged boolean;
  v_legacy_warehouse text := '';
  v_legacy_due_date date;
  v_legacy_crew_leader text := '';
  v_legacy_created_at timestamptz;
  v_legacy_updated_at timestamptz;
begin
  perform app_api.require_org_member(p_org_id);

  if v_flag_text in ('true', 't', '1', 'yes', 'on') then
    v_is_staged := true;
  elsif v_flag_text in ('false', 'f', '0', 'no', 'off') then
    v_is_staged := false;
  else
    perform app_api.raise_http(400, 'isStagedForPickup must be true or false.');
  end if;

  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and upper(trim(j.job_number)) = upper(trim(v_job_number))
  for update;

  if not found then
    select
      coalesce(min(src.warehouse), ''),
      min(src.job_date),
      coalesce(min(src.crew_leader), ''),
      min(src.created_at),
      max(src.updated_at)
    into
      v_legacy_warehouse,
      v_legacy_due_date,
      v_legacy_crew_leader,
      v_legacy_created_at,
      v_legacy_updated_at
    from (
      select
        a.warehouse,
        a.job_date,
        nullif(a.crew_leader, '') as crew_leader,
        a.created_at,
        coalesce(a.resolved_at, a.created_at) as updated_at
      from app.allocations a
      where a.org_id = p_org_id
        and upper(trim(a.job_number)) = upper(trim(v_job_number))

      union all

      select
        f.warehouse,
        f.job_date,
        nullif(f.crew_leader, '') as crew_leader,
        f.created_at,
        coalesce(f.resolved_at, f.created_at) as updated_at
      from app.film_orders f
      where f.org_id = p_org_id
        and upper(trim(f.job_number)) = upper(trim(v_job_number))
    ) src;

    if v_legacy_created_at is null then
      perform app_api.raise_http(404, format('Job %s was not found.', v_job_number));
    end if;

    v_job.id := gen_random_uuid();
    v_job.org_id := p_org_id;
    v_job.job_number := v_job_number;
    v_job.warehouse := v_legacy_warehouse;
    v_job.sections := null;
    v_job.due_date := v_legacy_due_date;
    v_job.crew_leader := v_legacy_crew_leader;
    v_job.lifecycle_status := 'ACTIVE';
    v_job.is_staged_for_pickup := false;
    v_job.notes := '';
    v_job.created_at := coalesce(v_legacy_created_at, now());
    v_job.created_by := v_actor;
    v_job.updated_at := coalesce(v_legacy_updated_at, now());
    v_job.updated_by := v_actor;
    v_job := app_api.save_job(v_job);
  end if;

  if v_job.lifecycle_status::text <> 'ACTIVE' then
    perform app_api.raise_http(
      400,
      format('Job %s is closed and staged pickup cannot be changed.', v_job_number)
    );
  end if;

  update app.jobs
  set
    is_staged_for_pickup = v_is_staged,
    updated_at = now(),
    updated_by = v_actor
  where id = v_job.id
    and org_id = p_org_id
  returning * into v_job;

  return jsonb_build_object(
    'jobNumber', v_job.job_number,
    'isStagedForPickup', v_job.is_staged_for_pickup,
    'updatedAt', to_char(v_job.updated_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_acl_jobs_set_staged_pickup(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  perform app_api.require_effective_feature_access(p_org_id, 'jobs', 'write');
  return public.api_jobs_set_staged_pickup(p_org_id, p_actor, p_payload);
end;
$$;

select app_api.revoke_execute_if_exists('public.api_jobs_calendar(uuid, text, text)', 'authenticated');
select app_api.revoke_execute_if_exists('public.api_jobs_set_staged_pickup(uuid, text, jsonb)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_list_jobs_calendar(uuid, text, text)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_jobs_set_staged_pickup(uuid, text, jsonb)', 'authenticated');

alter table app.jobs
  add column if not exists is_labor_only boolean not null default false;

create or replace function app_api.save_job(p_job app.jobs)
returns app.jobs
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_row app.jobs;
begin
  insert into app.jobs (
    id,
    org_id,
    job_number,
    warehouse,
    sections,
    due_date,
    crew_leader,
    lifecycle_status,
    is_staged_for_pickup,
    is_labor_only,
    notes,
    created_at,
    created_by,
    updated_at,
    updated_by
  )
  values (
    coalesce(p_job.id, gen_random_uuid()),
    p_job.org_id,
    p_job.job_number,
    p_job.warehouse,
    p_job.sections,
    p_job.due_date,
    coalesce(p_job.crew_leader, ''),
    p_job.lifecycle_status,
    coalesce(p_job.is_staged_for_pickup, false),
    coalesce(p_job.is_labor_only, false),
    coalesce(p_job.notes, ''),
    coalesce(p_job.created_at, now()),
    coalesce(p_job.created_by, ''),
    coalesce(p_job.updated_at, now()),
    coalesce(p_job.updated_by, '')
  )
  on conflict (org_id, job_number) do update set
    warehouse = excluded.warehouse,
    sections = excluded.sections,
    due_date = excluded.due_date,
    crew_leader = excluded.crew_leader,
    lifecycle_status = excluded.lifecycle_status,
    is_staged_for_pickup = excluded.is_staged_for_pickup,
    is_labor_only = excluded.is_labor_only,
    notes = excluded.notes,
    updated_at = excluded.updated_at,
    updated_by = excluded.updated_by
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function public.api_jobs_create(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_now timestamptz := now();
  v_has_film_requirements boolean := exists (
    select 1
    from app_api.requirement_rows_from_payload(p_payload->'requirements')
  );
  v_has_caulk_requirements boolean := exists (
    select 1
    from app_api.caulk_requirement_rows_from_payload(p_payload->'caulkRequirements')
  );
  v_has_labor_only_input boolean := coalesce(p_payload ? 'isLaborOnly', false) or coalesce(p_payload ? 'is_labor_only', false);
  v_labor_only_text text := lower(
    app_api.trim_text(coalesce(p_payload->>'isLaborOnly', p_payload->>'is_labor_only'))
  );
  v_is_labor_only boolean := false;
  v_had_labor_only boolean := false;
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and j.job_number = app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number')
  for update;

  if not found then
    v_job.id := gen_random_uuid();
    v_job.created_at := v_now;
    v_job.created_by := app_api.trim_text(p_actor);
    v_job.is_staged_for_pickup := false;
    v_job.is_labor_only := false;
  end if;

  v_had_labor_only := coalesce(v_job.is_labor_only, false);

  v_job.org_id := p_org_id;
  v_job.job_number := app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number');
  v_job.warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'warehouse', 'Warehouse');
  v_job.sections := app_api.normalize_job_sections(p_payload->>'sections');
  v_job.due_date := nullif(app_api.trim_text(p_payload->>'dueDate'), '')::date;
  v_job.crew_leader := app_api.trim_text(p_payload->>'crewLeader');
  v_job.lifecycle_status := app_api.normalize_job_lifecycle_status(p_payload->>'lifecycleStatus');
  v_job.notes := app_api.trim_text(p_payload->>'notes');

  if v_has_labor_only_input then
    if v_labor_only_text in ('true', 't', '1', 'yes', 'on') then
      v_is_labor_only := true;
    elsif v_labor_only_text in ('false', 'f', '0', 'no', 'off') then
      v_is_labor_only := false;
    else
      perform app_api.raise_http(400, 'isLaborOnly must be true or false.');
    end if;
  else
    v_is_labor_only := v_had_labor_only;
  end if;

  if v_has_film_requirements or v_has_caulk_requirements then
    v_is_labor_only := false;
    if v_had_labor_only then
      v_job.is_staged_for_pickup := false;
    end if;
  elsif v_is_labor_only then
    v_job.is_staged_for_pickup := true;
  elsif v_has_labor_only_input and not v_is_labor_only and v_had_labor_only then
    v_job.is_staged_for_pickup := false;
  end if;

  v_job.is_labor_only := v_is_labor_only;
  v_job.updated_at := v_now;
  v_job.updated_by := app_api.trim_text(p_actor);

  v_job := app_api.save_job(v_job);
  perform app_api.replace_job_requirements(p_org_id, v_job, p_payload->'requirements', p_actor, v_now);
  perform app_api.replace_job_caulk_requirements(p_org_id, v_job, p_payload->'caulkRequirements', p_actor, v_now);

  return jsonb_build_object(
    'jobNumber', v_job.job_number,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_jobs_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_now timestamptz := now();
  v_has_film_requirements boolean := exists (
    select 1
    from app_api.requirement_rows_from_payload(p_payload->'requirements')
  );
  v_has_caulk_requirements boolean := exists (
    select 1
    from app_api.caulk_requirement_rows_from_payload(p_payload->'caulkRequirements')
  );
  v_has_labor_only_input boolean := coalesce(p_payload ? 'isLaborOnly', false) or coalesce(p_payload ? 'is_labor_only', false);
  v_labor_only_text text := lower(
    app_api.trim_text(coalesce(p_payload->>'isLaborOnly', p_payload->>'is_labor_only'))
  );
  v_is_labor_only boolean := false;
  v_had_labor_only boolean := false;
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and j.job_number = app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number')
  for update;

  if not found then
    v_job.id := gen_random_uuid();
    v_job.org_id := p_org_id;
    v_job.job_number := app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number');
    v_job.warehouse := coalesce(
      case
        when app_api.trim_text(p_payload->>'warehouse') <> ''
          then app_api.require_org_warehouse(p_org_id, p_payload->>'warehouse', 'Warehouse')
        else null
      end,
      (
        select w.code
        from app.warehouses w
        where w.org_id = p_org_id
          and w.box_id_prefix = ''
        order by case when w.code = 'IL' then 0 else 1 end, w.code
        limit 1
      ),
      (
        select w.code
        from app.warehouses w
        where w.org_id = p_org_id
        order by w.code
        limit 1
      )
    );
    if v_job.warehouse is null then
      perform app_api.raise_http(400, 'No warehouse is configured for this organization.');
    end if;
    v_job.sections := null;
    v_job.due_date := null;
    v_job.crew_leader := '';
    v_job.lifecycle_status := 'ACTIVE';
    v_job.is_staged_for_pickup := false;
    v_job.is_labor_only := false;
    v_job.notes := '';
    v_job.created_at := v_now;
    v_job.created_by := app_api.trim_text(p_actor);
  end if;

  v_had_labor_only := coalesce(v_job.is_labor_only, false);

  if p_payload ? 'warehouse' then
    v_job.warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'warehouse', 'Warehouse');
  end if;
  if p_payload ? 'sections' then
    v_job.sections := app_api.normalize_job_sections(p_payload->>'sections');
  end if;
  if p_payload ? 'dueDate' then
    v_job.due_date := nullif(app_api.trim_text(p_payload->>'dueDate'), '')::date;
  end if;
  if p_payload ? 'crewLeader' then
    v_job.crew_leader := app_api.trim_text(p_payload->>'crewLeader');
  end if;
  if p_payload ? 'lifecycleStatus' then
    v_job.lifecycle_status := app_api.normalize_job_lifecycle_status(p_payload->>'lifecycleStatus');
  end if;
  if p_payload ? 'notes' then
    v_job.notes := app_api.trim_text(p_payload->>'notes');
  end if;

  if v_has_labor_only_input then
    if v_labor_only_text in ('true', 't', '1', 'yes', 'on') then
      v_is_labor_only := true;
    elsif v_labor_only_text in ('false', 'f', '0', 'no', 'off') then
      v_is_labor_only := false;
    else
      perform app_api.raise_http(400, 'isLaborOnly must be true or false.');
    end if;
  else
    v_is_labor_only := v_had_labor_only;
  end if;

  if v_has_film_requirements or v_has_caulk_requirements then
    v_is_labor_only := false;
    if v_had_labor_only then
      v_job.is_staged_for_pickup := false;
    end if;
  elsif v_is_labor_only then
    v_job.is_staged_for_pickup := true;
  elsif v_has_labor_only_input and not v_is_labor_only and v_had_labor_only then
    v_job.is_staged_for_pickup := false;
  end if;

  v_job.is_labor_only := v_is_labor_only;
  v_job.updated_at := v_now;
  v_job.updated_by := app_api.trim_text(p_actor);
  v_job := app_api.save_job(v_job);
  perform app_api.replace_job_requirements(p_org_id, v_job, p_payload->'requirements', p_actor, v_now);
  perform app_api.replace_job_caulk_requirements(p_org_id, v_job, p_payload->'caulkRequirements', p_actor, v_now);

  return jsonb_build_object(
    'jobNumber', v_job.job_number,
    'warnings', '[]'::jsonb
  );
end;
$$;

-- Honor explicitly confirmed zeroed-box edits that force Available Feet to 0.

create or replace function public.api_boxes_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_build jsonb;
  v_box app.boxes;
  v_public_before jsonb;
  v_public_after jsonb;
  v_receipt_result jsonb;
  v_log_id text;
  v_warnings text[] := array[]::text[];
  v_reached_zero boolean;
  v_move_to_zeroed boolean := coalesce((p_payload->>'moveToZeroed')::boolean, false);
  v_auto_zero boolean;
  v_requested_feet_available integer;
  v_confirmed_zero_feet_move boolean := false;
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_existing.status = 'ZEROED' then
    perform app_api.raise_http(400, 'Zeroed boxes cannot be edited directly. Use audit undo instead.');
  end if;

  v_build := app_api.build_box_from_payload(p_org_id, p_payload, v_existing.box_id);
  v_box := jsonb_populate_record(null::app.boxes, v_build->'box');
  v_warnings := coalesce(array(select jsonb_array_elements_text(v_build->'warnings')), array[]::text[]);
  v_requested_feet_available := case
    when app_api.trim_text(p_payload->>'feetAvailable') = '' then null
    else floor((app_api.trim_text(p_payload->>'feetAvailable'))::numeric)
  end;

  v_confirmed_zero_feet_move :=
    v_move_to_zeroed
    and v_existing.received_date is not null
    and app_api.has_positive_physical_feet(v_existing)
    and v_requested_feet_available is not null
    and v_requested_feet_available <= 0;

  if v_confirmed_zero_feet_move then
    v_box.feet_available := 0;
  end if;

  v_reached_zero := v_box.received_date is not null and (v_box.feet_available = 0 or coalesce(v_box.last_roll_weight_lbs, 0) = 0);
  v_auto_zero := v_existing.received_date is not null and app_api.has_positive_physical_feet(v_existing) and v_reached_zero;

  if v_move_to_zeroed and not (v_auto_zero or v_confirmed_zero_feet_move) then
    perform app_api.raise_http(
      400,
      'Received boxes move to zeroed out inventory only after they have had Available Feet above 0 and then reach 0 Available Feet or 0 Last Roll Weight.'
    );
  end if;

  if v_auto_zero or v_confirmed_zero_feet_move then
    v_box.status := 'ZEROED';
    v_box.feet_available := 0;
    v_box.zeroed_date := app_api.today_date();
    v_box.zeroed_reason := app_api.determine_zeroed_reason(v_box.feet_available, v_box.last_roll_weight_lbs);
    v_box.zeroed_by := app_api.trim_text(p_actor);
    if app_api.trim_text(p_payload->>'auditNote') <> '' then
      v_box.zeroed_reason := v_box.zeroed_reason || ' Additional note: ' || app_api.normalize_meaningful_zeroed_note(p_payload->>'auditNote');
    end if;
    perform app_api.cancel_active_allocations_for_box(
      p_org_id,
      v_box.box_id,
      p_actor,
      'Auto-cancelled because the box was moved to zeroed out inventory.'
    );
    if v_confirmed_zero_feet_move and not v_auto_zero then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was moved to zeroed out inventory after confirming an Available Feet value of 0 on a received box with recorded physical feet.'
      );
    end if;
  else
    v_receipt_result := app_api.process_linked_box_receipt(p_org_id, v_box, p_actor);
    v_box := jsonb_populate_record(null::app.boxes, v_receipt_result->'box');
    v_warnings := array_cat(
      v_warnings,
      coalesce(array(select jsonb_array_elements_text(v_receipt_result->'warnings')), array[]::text[])
    );
  end if;

  v_box := app_api.save_box(v_box);
  v_public_before := app_api.public_box_json(v_existing);
  v_public_after := app_api.public_box_json(v_box);
  v_log_id := app_api.append_audit_entry(
    p_org_id,
    case when v_box.status = 'ZEROED' then 'ZERO_OUT_BOX' else 'UPDATE_BOX' end,
    v_box.box_id,
    v_public_before,
    v_public_after,
    p_actor,
    app_api.trim_text(p_payload->>'auditNote')
  );

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

-- Allow confirmed zeroed-box edits to reactivate boxes back into active inventory.

create or replace function public.api_boxes_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_build jsonb;
  v_box app.boxes;
  v_public_before jsonb;
  v_public_after jsonb;
  v_receipt_result jsonb;
  v_log_id text;
  v_warnings text[] := array[]::text[];
  v_reached_zero boolean;
  v_move_to_zeroed boolean := coalesce((p_payload->>'moveToZeroed')::boolean, false);
  v_reactivate_from_zeroed boolean := coalesce((p_payload->>'reactivateFromZeroed')::boolean, false);
  v_auto_zero boolean;
  v_requested_feet_available integer;
  v_confirmed_zero_feet_move boolean := false;
  v_has_positive_reactivation_signal boolean := false;
  v_should_reactivate boolean := false;
  v_audit_action text := 'UPDATE_BOX';
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  v_build := app_api.build_box_from_payload(p_org_id, p_payload, v_existing.box_id);
  v_box := jsonb_populate_record(null::app.boxes, v_build->'box');
  v_warnings := coalesce(array(select jsonb_array_elements_text(v_build->'warnings')), array[]::text[]);
  v_requested_feet_available := case
    when app_api.trim_text(p_payload->>'feetAvailable') = '' then null
    else floor((app_api.trim_text(p_payload->>'feetAvailable'))::numeric)
  end;

  if v_existing.status = 'ZEROED' then
    v_has_positive_reactivation_signal :=
      coalesce(v_box.feet_available, 0) > 0
      or coalesce(v_box.last_roll_weight_lbs, 0) > 0;

    if v_has_positive_reactivation_signal and not v_reactivate_from_zeroed then
      perform app_api.raise_http(
        400,
        'Zeroed boxes with new active inventory values must be confirmed before moving back to IN_STOCK.'
      );
    end if;

    v_should_reactivate := v_has_positive_reactivation_signal and v_reactivate_from_zeroed;

    if v_should_reactivate then
      v_box.status := 'IN_STOCK';
      v_box.zeroed_date := null;
      v_box.zeroed_reason := '';
      v_box.zeroed_by := '';
      v_warnings := app_api.push_warning(
        v_warnings,
        format('Box %s was moved back to active IN_STOCK inventory.', v_box.box_id)
      );
      v_audit_action := 'SET_STATUS';
    else
      v_box.status := 'ZEROED';
      v_box.zeroed_date := v_existing.zeroed_date;
      v_box.zeroed_reason := coalesce(v_existing.zeroed_reason, '');
      v_box.zeroed_by := coalesce(v_existing.zeroed_by, '');
    end if;

    v_box := app_api.save_box(v_box);
    v_public_before := app_api.public_box_json(v_existing);
    v_public_after := app_api.public_box_json(v_box);
    v_log_id := app_api.append_audit_entry(
      p_org_id,
      v_audit_action,
      v_box.box_id,
      v_public_before,
      v_public_after,
      p_actor,
      app_api.trim_text(p_payload->>'auditNote')
    );

    return jsonb_build_object(
      'boxId', v_box.box_id,
      'logId', v_log_id,
      'warnings', to_jsonb(v_warnings)
    );
  end if;

  v_confirmed_zero_feet_move :=
    v_move_to_zeroed
    and v_existing.received_date is not null
    and app_api.has_positive_physical_feet(v_existing)
    and v_requested_feet_available is not null
    and v_requested_feet_available <= 0;

  if v_confirmed_zero_feet_move then
    v_box.feet_available := 0;
  end if;

  v_reached_zero := v_box.received_date is not null and (v_box.feet_available = 0 or coalesce(v_box.last_roll_weight_lbs, 0) = 0);
  v_auto_zero := v_existing.received_date is not null and app_api.has_positive_physical_feet(v_existing) and v_reached_zero;

  if v_move_to_zeroed and not (v_auto_zero or v_confirmed_zero_feet_move) then
    perform app_api.raise_http(
      400,
      'Received boxes move to zeroed out inventory only after they have had Available Feet above 0 and then reach 0 Available Feet or 0 Last Roll Weight.'
    );
  end if;

  if v_auto_zero or v_confirmed_zero_feet_move then
    v_box.status := 'ZEROED';
    v_box.feet_available := 0;
    v_box.zeroed_date := app_api.today_date();
    v_box.zeroed_reason := app_api.determine_zeroed_reason(v_box.feet_available, v_box.last_roll_weight_lbs);
    v_box.zeroed_by := app_api.trim_text(p_actor);
    if app_api.trim_text(p_payload->>'auditNote') <> '' then
      v_box.zeroed_reason := v_box.zeroed_reason || ' Additional note: ' || app_api.normalize_meaningful_zeroed_note(p_payload->>'auditNote');
    end if;
    perform app_api.cancel_active_allocations_for_box(
      p_org_id,
      v_box.box_id,
      p_actor,
      'Auto-cancelled because the box was moved to zeroed out inventory.'
    );
    if v_confirmed_zero_feet_move and not v_auto_zero then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was moved to zeroed out inventory after confirming an Available Feet value of 0 on a received box with recorded physical feet.'
      );
    end if;
    v_audit_action := 'ZERO_OUT_BOX';
  else
    v_receipt_result := app_api.process_linked_box_receipt(p_org_id, v_box, p_actor);
    v_box := jsonb_populate_record(null::app.boxes, v_receipt_result->'box');
    v_warnings := array_cat(
      v_warnings,
      coalesce(array(select jsonb_array_elements_text(v_receipt_result->'warnings')), array[]::text[])
    );
  end if;

  v_box := app_api.save_box(v_box);
  v_public_before := app_api.public_box_json(v_existing);
  v_public_after := app_api.public_box_json(v_box);
  v_log_id := app_api.append_audit_entry(
    p_org_id,
    v_audit_action,
    v_box.box_id,
    v_public_before,
    v_public_after,
    p_actor,
    app_api.trim_text(p_payload->>'auditNote')
  );

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

-- Recalculate received-box feet_available when effective roll-weight inputs change.

create or replace function app_api.should_recalculate_received_feet(
  p_existing app.boxes,
  p_initial_feet integer,
  p_resolved_last_roll_weight numeric,
  p_resolved_core_weight numeric,
  p_resolved_lf_weight numeric,
  p_reactivate_from_zeroed boolean
)
returns boolean
language sql
stable
security definer
set search_path = public, app, app_api
as $$
  select
    coalesce(p_reactivate_from_zeroed, false)
    or p_existing is null
    or p_existing.received_date is null
    or p_existing.initial_feet is distinct from p_initial_feet
    or p_existing.last_roll_weight_lbs is distinct from p_resolved_last_roll_weight
    or p_existing.core_weight_lbs is distinct from p_resolved_core_weight
    or p_existing.lf_weight_lbs_per_ft is distinct from p_resolved_lf_weight;
$$;

create or replace function app_api.build_box_from_payload(
  p_org_id uuid,
  p_payload jsonb,
  p_existing_box_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_box app.boxes;
  v_film_data app.film_catalog;
  v_warnings text[] := array[]::text[];
  v_box_id text;
  v_manufacturer text;
  v_film_name text;
  v_width_in numeric;
  v_initial_feet integer;
  v_order_date date;
  v_received_date date;
  v_feet_available_input text;
  v_feet_available integer;
  v_film_key text;
  v_initial_weight_input numeric;
  v_last_roll_weight_input numeric;
  v_last_weighed_date_input date;
  v_core_type_input text;
  v_existing_core_type text;
  v_resolved_initial_weight numeric;
  v_resolved_last_roll_weight numeric;
  v_resolved_last_weighed_date date;
  v_resolved_core_type text;
  v_resolved_core_weight numeric;
  v_resolved_lf_weight numeric;
  v_effective_sq_ft_weight numeric;
  v_active_allocated_feet integer := 0;
  v_is_first_receipt boolean := false;
  v_should_recalculate_received_feet boolean := false;
  v_resolved_warehouse text;
  v_has_price_per_lf boolean := coalesce(p_payload, '{}'::jsonb) ? 'pricePerLf';
  v_reactivate_from_zeroed boolean := coalesce((p_payload->>'reactivateFromZeroed')::boolean, false);
begin
  if p_existing_box_id is not null then
    select *
    into v_existing
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id = app_api.trim_text(p_existing_box_id)
    for update;

    if not found then
      perform app_api.raise_http(404, 'Box not found.');
    end if;
  end if;

  v_box_id := coalesce(v_existing.box_id, app_api.require_text(p_payload->>'boxId', 'BoxID'));
  v_manufacturer := app_api.require_text(p_payload->>'manufacturer', 'Manufacturer');
  v_film_name := app_api.require_text(p_payload->>'filmName', 'FilmName');
  v_width_in := nullif(app_api.trim_text(p_payload->>'widthIn'), '')::numeric;
  v_initial_feet := floor(nullif(app_api.trim_text(p_payload->>'initialFeet'), '')::numeric);
  v_order_date := nullif(app_api.trim_text(p_payload->>'orderDate'), '')::date;
  v_received_date := nullif(app_api.trim_text(p_payload->>'receivedDate'), '')::date;
  v_feet_available_input := app_api.trim_text(p_payload->>'feetAvailable');
  v_film_key := upper(coalesce(nullif(app_api.trim_text(p_payload->>'filmKey'), ''), upper(v_manufacturer) || '|' || upper(v_film_name)));
  v_initial_weight_input := nullif(app_api.trim_text(p_payload->>'initialWeightLbs'), '')::numeric;
  v_last_roll_weight_input := nullif(app_api.trim_text(p_payload->>'lastRollWeightLbs'), '')::numeric;
  v_last_weighed_date_input := nullif(app_api.trim_text(p_payload->>'lastWeighedDate'), '')::date;
  v_core_type_input := app_api.normalize_core_type(p_payload->>'coreType', true);
  v_existing_core_type := coalesce(app_api.normalize_core_type(v_existing.core_type, true), '');
  v_resolved_warehouse := app_api.resolve_warehouse_from_box_id(p_org_id, v_box_id);

  if v_width_in is null or v_width_in <= 0 then
    perform app_api.raise_http(400, 'WidthIn must be greater than zero.');
  end if;

  if v_initial_feet is null or v_initial_feet < 0 then
    perform app_api.raise_http(400, 'InitialFeet must be zero or greater.');
  end if;

  if v_order_date is null then
    perform app_api.raise_http(400, 'OrderDate is required.');
  end if;

  if v_existing.received_date is not null and v_received_date is null then
    perform app_api.raise_http(400, 'ReceivedDate cannot be cleared after a box has been received.');
  end if;

  if v_feet_available_input = '' then
    v_feet_available := coalesce(v_existing.feet_available, app_api.derive_add_feet_available(v_initial_feet, v_received_date));
  else
    v_feet_available := floor(v_feet_available_input::numeric);
    if v_feet_available < 0 then
      v_feet_available := 0;
      v_warnings := app_api.push_warning(v_warnings, 'FeetAvailable was clamped to 0.');
    end if;
  end if;

  v_resolved_initial_weight := v_initial_weight_input;
  v_resolved_last_roll_weight := v_last_roll_weight_input;
  v_resolved_last_weighed_date := v_last_weighed_date_input;
  v_resolved_core_type := coalesce(nullif(v_core_type_input, ''), v_existing_core_type, '');
  v_resolved_core_weight := v_existing.core_weight_lbs;
  v_resolved_lf_weight := v_existing.lf_weight_lbs_per_ft;

  if v_received_date is not null then
    if v_initial_feet <= 0 then
      perform app_api.raise_http(400, 'InitialFeet must be greater than zero for received boxes.');
    end if;

    select *
    into v_film_data
    from app.film_catalog f
    where f.org_id = p_org_id
      and f.film_key = v_film_key
    for update;

    if v_resolved_core_type = '' then
      v_resolved_core_type := app_api.normalize_core_type(v_film_data.default_core_type, true);
    end if;

    if v_film_data.sq_ft_weight_lbs_per_sq_ft is not null then
      if v_resolved_core_type = '' then
        perform app_api.raise_http(400, 'CoreType is required before this film can be received.');
      end if;

      v_effective_sq_ft_weight := v_film_data.sq_ft_weight_lbs_per_sq_ft;
      v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_width_in);

      if v_initial_weight_input is not null then
        v_effective_sq_ft_weight := app_api.derive_sqft_weight_lbs_per_sqft(
          v_initial_weight_input,
          v_resolved_core_weight,
          v_width_in,
          v_initial_feet
        );
        v_resolved_initial_weight := round(v_initial_weight_input, 2);
      else
        v_resolved_initial_weight := app_api.derive_initial_weight_lbs(
          app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in),
          v_initial_feet,
          v_resolved_core_weight
        );
        v_warnings := app_api.push_warning(v_warnings, 'Initial and last roll weights were auto-filled from FILM DATA.');
      end if;

      v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
    else
      if v_resolved_core_type = '' then
        perform app_api.raise_http(400, 'CoreType is required the first time a received film is saved.');
      end if;

      if v_initial_weight_input is null and v_existing.initial_weight_lbs is null then
        perform app_api.raise_http(400, 'InitialWeightLbs is required the first time a received film is saved.');
      end if;

      v_resolved_initial_weight := coalesce(v_initial_weight_input, v_existing.initial_weight_lbs);
      v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_width_in);
      v_effective_sq_ft_weight := app_api.derive_sqft_weight_lbs_per_sqft(
        v_resolved_initial_weight,
        v_resolved_core_weight,
        v_width_in,
        v_initial_feet
      );
      v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
      perform app_api.save_film_catalog(
        p_org_id,
        v_film_key,
        v_manufacturer,
        v_film_name,
        v_effective_sq_ft_weight,
        v_resolved_core_type,
        v_width_in,
        v_initial_feet,
        v_resolved_initial_weight,
        v_box_id,
        coalesce(v_film_data.notes, '')
      );
      v_warnings := app_api.push_warning(v_warnings, format('FILM DATA was created from the first received weight for %s.', v_film_key));
    end if;

    if v_resolved_last_roll_weight is null then
      v_resolved_last_roll_weight := coalesce(v_existing.last_roll_weight_lbs, v_resolved_initial_weight);
    end if;
    if v_resolved_last_weighed_date is null then
      v_resolved_last_weighed_date := coalesce(v_existing.last_weighed_date, v_received_date);
    end if;

    if v_film_data.id is not null and (coalesce(v_film_data.default_core_type, '') = '' or coalesce(v_film_data.default_core_type, '') <> v_resolved_core_type) then
      perform app_api.save_film_catalog(
        p_org_id,
        v_film_key,
        coalesce(v_film_data.manufacturer, v_manufacturer),
        coalesce(v_film_data.film_name, v_film_name),
        coalesce(v_film_data.sq_ft_weight_lbs_per_sq_ft, v_effective_sq_ft_weight),
        v_resolved_core_type,
        coalesce(v_film_data.source_width_in, v_width_in),
        coalesce(v_film_data.source_initial_feet, v_initial_feet),
        coalesce(v_film_data.source_initial_weight_lbs, v_resolved_initial_weight),
        coalesce(v_film_data.source_box_id, v_box_id),
        coalesce(v_film_data.notes, '')
      );
      v_warnings := app_api.push_warning(v_warnings, 'FILM DATA was updated with the selected core type.');
    end if;

    select coalesce(sum(a.allocated_feet), 0)::integer
    into v_active_allocated_feet
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_box_id
      and a.status = 'ACTIVE';

    v_is_first_receipt := v_existing.received_date is null;
    v_should_recalculate_received_feet := app_api.should_recalculate_received_feet(
      v_existing,
      v_initial_feet,
      v_resolved_last_roll_weight,
      v_resolved_core_weight,
      v_resolved_lf_weight,
      v_reactivate_from_zeroed
    ) or (
      v_existing.received_date is not null
      and coalesce(v_existing.feet_available, 0) <= 0
      and app_api.derive_feet_available_from_roll_weight(
        v_resolved_last_roll_weight,
        v_resolved_core_weight,
        v_resolved_lf_weight,
        v_initial_feet
      ) > 0
    );

    if v_is_first_receipt then
      v_feet_available := greatest(v_initial_feet - v_active_allocated_feet, 0);
    elsif v_should_recalculate_received_feet then
      v_feet_available := greatest(
        app_api.derive_feet_available_from_roll_weight(
          v_resolved_last_roll_weight,
          v_resolved_core_weight,
          v_resolved_lf_weight,
          v_initial_feet
        ) - v_active_allocated_feet,
        0
      );
    else
      v_feet_available := least(greatest(coalesce(v_existing.feet_available, v_feet_available), 0), v_initial_feet);
    end if;
  else
    v_resolved_initial_weight := null;
    v_resolved_last_roll_weight := null;
    v_resolved_last_weighed_date := null;
    v_resolved_core_type := '';
    v_resolved_core_weight := null;
    v_resolved_lf_weight := null;
  end if;

  v_box.id := v_existing.id;
  v_box.org_id := p_org_id;
  v_box.box_id := v_box_id;
  v_box.warehouse := v_resolved_warehouse;
  v_box.manufacturer := v_manufacturer;
  v_box.film_name := v_film_name;
  v_box.width_in := v_width_in;
  v_box.initial_feet := v_initial_feet;
  v_box.feet_available := v_feet_available;
  v_box.lot_run := app_api.trim_text(p_payload->>'lotRun');
  v_box.status := case
    when v_existing.status in ('CHECKED_OUT', 'ZEROED', 'RETIRED') then v_existing.status
    else app_api.derive_lifecycle_status(v_received_date)
  end;
  v_box.order_date := v_order_date;
  v_box.received_date := v_received_date;
  v_box.initial_weight_lbs := v_resolved_initial_weight;
  v_box.last_roll_weight_lbs := v_resolved_last_roll_weight;
  v_box.last_weighed_date := v_resolved_last_weighed_date;
  v_box.film_key := v_film_key;
  v_box.core_type := v_resolved_core_type;
  v_box.core_weight_lbs := v_resolved_core_weight;
  v_box.lf_weight_lbs_per_ft := v_resolved_lf_weight;
  v_box.purchase_cost := nullif(app_api.trim_text(p_payload->>'purchaseCost'), '')::numeric;
  if v_box.purchase_cost is not null and v_box.purchase_cost < 0 then
    perform app_api.raise_http(400, 'PurchaseCost must be zero or greater.');
  end if;
  if v_box.purchase_cost is not null and v_initial_feet <= 0 then
    perform app_api.raise_http(400, 'PurchaseCost requires InitialFeet > 0 to derive PricePerLf.');
  end if;

  if v_box.purchase_cost is not null then
    v_box.price_per_lf := round(v_box.purchase_cost / v_initial_feet, 4);
  elsif v_has_price_per_lf then
    v_box.price_per_lf := nullif(app_api.trim_text(p_payload->>'pricePerLf'), '')::numeric;
    if v_box.price_per_lf is not null and v_box.price_per_lf < 0 then
      perform app_api.raise_http(400, 'PricePerLf must be zero or greater.');
    end if;
  else
    v_box.price_per_lf := v_existing.price_per_lf;
  end if;
  v_box.notes := app_api.trim_text(p_payload->>'notes');
  v_box.has_ever_been_checked_out := coalesce(v_existing.has_ever_been_checked_out, false);
  v_box.last_checkout_job := coalesce(v_existing.last_checkout_job, '');
  v_box.last_checkout_date := v_existing.last_checkout_date;
  v_box.zeroed_date := null;
  v_box.zeroed_reason := '';
  v_box.zeroed_by := '';

  return jsonb_build_object(
    'box', to_jsonb(v_box),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

alter table app.allocations
  add column if not exists requirement_id uuid references app.job_requirements(id) on delete set null;

create index if not exists idx_allocations_org_upper_job_requirement_id
  on app.allocations (org_id, upper(trim(job_number)), requirement_id);

create or replace function app_api.normalize_requirement_film_key(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns text
language sql
stable
as $$
  select app_api.normalize_catalog_manufacturer_lookup_key(p_manufacturer)
    || '|' || app_api.normalize_catalog_lookup_key(
      app_api.resolve_canonical_film_name(p_org_id, p_manufacturer, p_film_name)
    );
$$;

create or replace function app_api.save_allocation(p_allocation app.allocations)
returns app.allocations
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_row app.allocations;
begin
  insert into app.allocations (
    id,
    org_id,
    allocation_id,
    box_id,
    job_id,
    job_number,
    warehouse,
    job_date,
    allocated_feet,
    requirement_id,
    status,
    created_at,
    created_by,
    resolved_at,
    resolved_by,
    notes,
    crew_leader,
    film_order_id,
    allocation_kind
  )
  values (
    coalesce(p_allocation.id, gen_random_uuid()),
    p_allocation.org_id,
    p_allocation.allocation_id,
    p_allocation.box_id,
    p_allocation.job_id,
    p_allocation.job_number,
    p_allocation.warehouse,
    p_allocation.job_date,
    p_allocation.allocated_feet,
    p_allocation.requirement_id,
    p_allocation.status,
    coalesce(p_allocation.created_at, now()),
    coalesce(p_allocation.created_by, ''),
    p_allocation.resolved_at,
    coalesce(p_allocation.resolved_by, ''),
    coalesce(p_allocation.notes, ''),
    coalesce(p_allocation.crew_leader, ''),
    coalesce(p_allocation.film_order_id, ''),
    coalesce(p_allocation.allocation_kind, 'REQUIREMENT'::app.allocation_kind)
  )
  on conflict (org_id, allocation_id) do update set
    box_id = excluded.box_id,
    job_id = excluded.job_id,
    job_number = excluded.job_number,
    warehouse = excluded.warehouse,
    job_date = excluded.job_date,
    allocated_feet = excluded.allocated_feet,
    requirement_id = excluded.requirement_id,
    status = excluded.status,
    created_at = excluded.created_at,
    created_by = excluded.created_by,
    resolved_at = excluded.resolved_at,
    resolved_by = excluded.resolved_by,
    notes = excluded.notes,
    crew_leader = excluded.crew_leader,
    film_order_id = excluded.film_order_id,
    allocation_kind = excluded.allocation_kind
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function app_api.create_allocation(
  p_org_id uuid,
  p_box app.boxes,
  p_job_context jsonb,
  p_allocated_feet integer,
  p_actor text,
  p_film_order_id text default '',
  p_allocation_kind text default 'REQUIREMENT',
  p_requirement_id uuid default null
)
returns app.allocations
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_allocation app.allocations;
  v_kind text := upper(app_api.trim_text(p_allocation_kind));
begin
  if v_kind = '' then
    v_kind := 'REQUIREMENT';
  end if;

  if v_kind not in ('REQUIREMENT', 'EXTRA') then
    perform app_api.raise_http(400, 'Allocation kind must be REQUIREMENT or EXTRA.');
  end if;

  v_allocation.id := gen_random_uuid();
  v_allocation.org_id := p_org_id;
  v_allocation.allocation_id := app_api.create_log_id();
  v_allocation.box_id := p_box.box_id;
  v_allocation.job_id := app_api.get_or_resolve_job_id(p_org_id, p_job_context->>'jobNumber');
  v_allocation.job_number := p_job_context->>'jobNumber';
  v_allocation.warehouse := p_box.warehouse;
  v_allocation.job_date := nullif(app_api.trim_text(p_job_context->>'jobDate'), '')::date;
  v_allocation.allocated_feet := p_allocated_feet;
  v_allocation.requirement_id := p_requirement_id;
  v_allocation.status := 'ACTIVE';
  v_allocation.created_at := now();
  v_allocation.created_by := app_api.trim_text(p_actor);
  v_allocation.resolved_at := null;
  v_allocation.resolved_by := '';
  v_allocation.notes := '';
  v_allocation.crew_leader := coalesce(p_job_context->>'crewLeader', '');
  v_allocation.film_order_id := app_api.trim_text(p_film_order_id);
  v_allocation.allocation_kind := v_kind::app.allocation_kind;

  return app_api.save_allocation(v_allocation);
end;
$$;

create or replace function public.api_allocations_apply(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_source app.boxes;
  v_candidate app.boxes;
  v_job_context jsonb;
  v_requested_feet integer := coalesce(floor(nullif(app_api.trim_text(p_payload->>'requestedFeet'), '')::numeric), 0);
  v_requested_width_in numeric := nullif(app_api.trim_text(p_payload->>'requestedWidthIn'), '')::numeric;
  v_requirement_id_text text := app_api.trim_text(p_payload->>'requirementId');
  v_requirement_id uuid;
  v_requirement app.job_requirements;
  v_source_film_key text;
  v_requirement_film_key text;
  v_remaining integer;
  v_source_suggested integer := 0;
  v_cross_warehouse boolean := coalesce((p_payload->>'crossWarehouse')::boolean, false);
  v_selected_box_ids text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'selectedSuggestionBoxIds', '[]'::jsonb))),
    array[]::text[]
  );
  v_extra_allocations jsonb := coalesce(p_payload->'extraAllocations', '[]'::jsonb);
  v_extra_entry jsonb;
  v_extra_box_id text;
  v_extra_feet integer;
  v_extra_processed_box_ids text[] := array[]::text[];
  v_allocation app.allocations;
  v_allocation_ids text[] := array[]::text[];
  v_film_order app.film_orders;
  v_conflict_count integer;
  v_job_warehouse text;
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_org_member(p_org_id);

  if v_requested_feet < 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be zero or greater.');
  end if;

  if coalesce(jsonb_typeof(v_extra_allocations), '') not in ('', 'array') then
    perform app_api.raise_http(400, 'extraAllocations must be an array.');
  end if;

  select *
  into v_source
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_source.status <> 'IN_STOCK' then
    perform app_api.raise_http(400, 'Only in-stock boxes can be allocated.');
  end if;

  v_job_context := app_api.resolve_job_context(
    p_org_id,
    p_payload->>'jobNumber',
    p_payload->>'jobDate',
    p_payload->>'crewLeader'
  );

  v_source_film_key := app_api.normalize_requirement_film_key(
    p_org_id,
    v_source.manufacturer,
    v_source.film_name
  );

  if v_requested_feet > 0 then
    if v_requirement_id_text = '' then
      perform app_api.raise_http(400, 'RequirementId is required for film allocations.');
    end if;

    begin
      v_requirement_id := v_requirement_id_text::uuid;
    exception
      when others then
        perform app_api.raise_http(400, 'RequirementId must be a valid UUID.');
    end;

    select r.*
    into v_requirement
    from app.job_requirements r
    where r.org_id = p_org_id
      and r.job_id = app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber')
      and r.id = v_requirement_id;

    if not found then
      perform app_api.raise_http(
        400,
        format('Requirement %s does not belong to job %s.', v_requirement_id, v_job_context->>'jobNumber')
      );
    end if;

    v_requirement_film_key := app_api.normalize_requirement_film_key(
      p_org_id,
      v_requirement.manufacturer,
      v_requirement.film_name
    );

    if v_requirement_film_key <> v_source_film_key then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    if v_source.width_in < v_requirement.width_in then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    v_requested_width_in := v_requirement.width_in;
  elsif v_requested_width_in is null or v_requested_width_in <= 0 then
    v_requested_width_in := v_source.width_in;
  end if;

  if v_source.width_in < v_requested_width_in then
    perform app_api.raise_http(400, 'Source box width must meet or exceed the requested width.');
  end if;

  if v_requested_feet > 0 then
    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_source.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count = 0 then
      v_source_suggested := least(v_source.feet_available, v_requested_feet);
    end if;
  end if;

  v_remaining := greatest(v_requested_feet - v_source_suggested, 0);

  if v_source_suggested > 0 then
    v_allocation := app_api.create_allocation(
      p_org_id,
      v_source,
      v_job_context,
      v_source_suggested,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    v_source.feet_available := greatest(v_source.feet_available - v_source_suggested, 0);
    v_source := app_api.save_box(v_source);
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end if;

  for v_candidate in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id <> v_source.box_id
      and b.status = 'IN_STOCK'
      and b.feet_available > 0
      and app_api.normalize_requirement_film_key(p_org_id, b.manufacturer, b.film_name) = v_source_film_key
      and b.width_in >= v_requested_width_in
      and (v_cross_warehouse or b.warehouse = v_source.warehouse)
    order by (b.width_in - v_requested_width_in), coalesce(b.received_date, b.order_date, '9999-12-31'::date), b.box_id
    for update
  loop
    exit when v_remaining <= 0;

    if coalesce(array_length(v_selected_box_ids, 1), 0) > 0 and array_position(v_selected_box_ids, v_candidate.box_id) is null then
      continue;
    end if;

    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_candidate.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count > 0 then
      continue;
    end if;

    v_allocation := app_api.create_allocation(
      p_org_id,
      v_candidate,
      v_job_context,
      least(v_candidate.feet_available, v_remaining),
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    v_candidate.feet_available := greatest(v_candidate.feet_available - v_allocation.allocated_feet, 0);
    perform app_api.save_box(v_candidate);
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
    v_remaining := v_remaining - v_allocation.allocated_feet;
  end loop;

  if coalesce(jsonb_typeof(v_extra_allocations), '') = 'array' then
    for v_extra_entry in
      select value
      from jsonb_array_elements(v_extra_allocations)
    loop
      if coalesce(jsonb_typeof(v_extra_entry), '') <> 'object' then
        perform app_api.raise_http(400, 'Each extra allocation entry must be an object.');
      end if;

      v_extra_box_id := app_api.require_text(v_extra_entry->>'boxId', 'extraAllocations[].boxId');
      v_extra_feet := floor(nullif(app_api.trim_text(v_extra_entry->>'allocatedFeet'), '')::numeric);

      if v_extra_feet is null or v_extra_feet <= 0 then
        perform app_api.raise_http(400, format('Extra allocation for box %s must be greater than zero.', v_extra_box_id));
      end if;

      if array_position(v_extra_processed_box_ids, v_extra_box_id) is not null then
        perform app_api.raise_http(400, format('Duplicate extra allocation entry for box %s.', v_extra_box_id));
      end if;

      select *
      into v_candidate
      from app.boxes b
      where b.org_id = p_org_id
        and b.box_id = v_extra_box_id
      for update;

      if not found then
        perform app_api.raise_http(404, format('Box not found: %s', v_extra_box_id));
      end if;

      if v_candidate.status <> 'IN_STOCK' then
        perform app_api.raise_http(400, format('Box %s is no longer allocatable.', v_candidate.box_id));
      end if;

      if app_api.normalize_requirement_film_key(p_org_id, v_candidate.manufacturer, v_candidate.film_name) <> v_source_film_key
        or v_candidate.width_in < v_requested_width_in then
        perform app_api.raise_http(
          400,
          format(
            'Extra box %s must match film and meet the requested width for this allocation.',
            v_candidate.box_id
          )
        );
      end if;

      if v_candidate.feet_available < v_extra_feet then
        perform app_api.raise_http(400, format('Box %s no longer has enough available LF.', v_candidate.box_id));
      end if;

      v_allocation := app_api.create_allocation(
        p_org_id,
        v_candidate,
        v_job_context,
        v_extra_feet,
        p_actor,
        '',
        'EXTRA',
        null
      );
      v_candidate.feet_available := greatest(v_candidate.feet_available - v_extra_feet, 0);
      perform app_api.save_box(v_candidate);
      v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
      v_extra_processed_box_ids := array_append(v_extra_processed_box_ids, v_extra_box_id);
    end loop;
  end if;

  if v_requested_feet = 0 and coalesce(array_length(v_extra_processed_box_ids, 1), 0) = 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be greater than zero unless extraAllocations are provided.');
  end if;

  if v_remaining > 0 then
    if app_api.trim_text(p_payload->>'jobWarehouse') <> '' then
      v_job_warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'jobWarehouse', 'Job warehouse');
    else
      v_job_warehouse := v_source.warehouse;
    end if;

    v_film_order.id := gen_random_uuid();
    v_film_order.org_id := p_org_id;
    v_film_order.film_order_id := app_api.create_log_id();
    v_film_order.job_id := app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber');
    v_film_order.job_number := v_job_context->>'jobNumber';
    v_film_order.warehouse := v_job_warehouse;
    v_film_order.manufacturer := v_source.manufacturer;
    v_film_order.film_name := v_source.film_name;
    v_film_order.width_in := v_source.width_in;
    v_film_order.requested_feet := v_remaining;
    v_film_order.covered_feet := 0;
    v_film_order.ordered_feet := 0;
    v_film_order.remaining_to_order_feet := v_remaining;
    v_film_order.job_date := nullif(v_job_context->>'jobDate', '')::date;
    v_film_order.crew_leader := coalesce(v_job_context->>'crewLeader', '');
    v_film_order.status := 'FILM_ORDER';
    v_film_order.source_box_id := v_source.box_id;
    v_film_order.resolved_at := null;
    v_film_order.resolved_by := '';
    v_film_order.notes := format('Created from a shortage while trying to allocate %s LF.', v_requested_feet);
    v_film_order.created_at := now();
    v_film_order.created_by := app_api.trim_text(p_actor);
    v_film_order := app_api.save_film_order(v_film_order);
    v_warnings := app_api.push_warning(
      v_warnings,
      format('Film Order %s was created for the remaining %s LF.', v_film_order.film_order_id, v_remaining)
    );
  end if;

  return jsonb_build_object(
    'allocationIds', to_jsonb(v_allocation_ids),
    'filmOrderId', coalesce(v_film_order.film_order_id, ''),
    'remainingUncoveredFeet', greatest(v_remaining, 0),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function app_api.public_allocation_json(p_entry app.allocations)
returns jsonb
language sql
stable
as $$
  select jsonb_build_object(
    'allocationId', coalesce(p_entry.allocation_id, ''),
    'boxId', coalesce(p_entry.box_id, ''),
    'warehouse', coalesce(p_entry.warehouse::text, ''),
    'jobNumber', coalesce(p_entry.job_number, ''),
    'jobDate', coalesce(to_char(p_entry.job_date, 'YYYY-MM-DD'), ''),
    'crewLeader', coalesce(p_entry.crew_leader, ''),
    'allocatedFeet', p_entry.allocated_feet,
    'requirementId', coalesce(p_entry.requirement_id::text, ''),
    'allocationKind', coalesce(p_entry.allocation_kind::text, 'REQUIREMENT'),
    'status', coalesce(p_entry.status::text, 'ACTIVE'),
    'createdAt', coalesce(to_char(p_entry.created_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), ''),
    'createdBy', coalesce(p_entry.created_by, ''),
    'resolvedAt', coalesce(to_char(p_entry.resolved_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), ''),
    'resolvedBy', coalesce(p_entry.resolved_by, ''),
    'filmOrderId', coalesce(p_entry.film_order_id, ''),
    'notes', coalesce(p_entry.notes, '')
  );
$$;

do $$
declare
  v_allocation record;
  v_requirement_id uuid;
begin
  create temporary table if not exists tmp_requirement_remaining (
    org_id uuid not null,
    job_number text not null,
    requirement_id uuid not null,
    film_key text not null,
    width_in numeric not null,
    remaining_feet integer not null,
    manufacturer_sort text not null,
    film_sort text not null
  ) on commit drop;

  truncate table tmp_requirement_remaining;

  insert into tmp_requirement_remaining (
    org_id,
    job_number,
    requirement_id,
    film_key,
    width_in,
    remaining_feet,
    manufacturer_sort,
    film_sort
  )
  select
    r.org_id,
    j.job_number,
    r.id,
    app_api.normalize_requirement_film_key(r.org_id, r.manufacturer, r.film_name),
    r.width_in,
    r.required_feet,
    app_api.normalize_catalog_manufacturer_lookup_key(r.manufacturer),
    app_api.normalize_catalog_lookup_key(app_api.resolve_canonical_film_name(r.org_id, r.manufacturer, r.film_name))
  from app.job_requirements r
  join app.jobs j
    on j.org_id = r.org_id
   and j.id = r.job_id;

  update tmp_requirement_remaining t
  set remaining_feet = greatest(t.remaining_feet - coverage.covered_feet, 0)
  from (
    select
      a.org_id,
      a.requirement_id,
      sum(a.allocated_feet)::integer as covered_feet
    from app.allocations a
    join app.boxes b
      on b.org_id = a.org_id
     and upper(b.box_id) = upper(a.box_id)
    join tmp_requirement_remaining t
      on t.org_id = a.org_id
     and t.requirement_id = a.requirement_id
    where a.requirement_id is not null
      and a.status = 'ACTIVE'
      and coalesce(a.allocation_kind::text, 'REQUIREMENT') <> 'EXTRA'
      and coalesce(b.status::text, '') not in ('ZEROED', 'RETIRED')
      and t.film_key = app_api.normalize_requirement_film_key(
        a.org_id,
        b.manufacturer,
        b.film_name
      )
      and coalesce(b.width_in, 0) >= coalesce(t.width_in, 0)
    group by a.org_id, a.requirement_id
  ) coverage
  where t.org_id = coverage.org_id
    and t.requirement_id = coverage.requirement_id;

  for v_allocation in
    select
      a.id,
      a.org_id,
      a.job_number,
      a.allocated_feet,
      b.manufacturer,
      b.film_name,
      b.width_in
    from app.allocations a
    join app.boxes b
      on b.org_id = a.org_id
     and upper(b.box_id) = upper(a.box_id)
    where a.requirement_id is null
      and a.status = 'ACTIVE'
      and coalesce(a.allocation_kind::text, 'REQUIREMENT') <> 'EXTRA'
      and a.allocated_feet > 0
      and coalesce(b.status::text, '') not in ('ZEROED', 'RETIRED')
    order by a.created_at, a.allocation_id
  loop
    v_requirement_id := null;

    select t.requirement_id
    into v_requirement_id
    from tmp_requirement_remaining t
    where t.org_id = v_allocation.org_id
      and upper(trim(t.job_number)) = upper(trim(v_allocation.job_number))
      and t.remaining_feet > 0
      and t.film_key = app_api.normalize_requirement_film_key(
        v_allocation.org_id,
        v_allocation.manufacturer,
        v_allocation.film_name
      )
      and coalesce(v_allocation.width_in, 0) >= coalesce(t.width_in, 0)
    order by t.manufacturer_sort, t.film_sort, t.width_in, t.requirement_id
    limit 1;

    if v_requirement_id is null then
      continue;
    end if;

    update app.allocations
    set requirement_id = v_requirement_id
    where id = v_allocation.id;

    update tmp_requirement_remaining
    set remaining_feet = greatest(remaining_feet - v_allocation.allocated_feet, 0)
    where org_id = v_allocation.org_id
      and requirement_id = v_requirement_id;
  end loop;
end;
$$;

alter table app.allocations
  add column if not exists covered_feet integer;

update app.allocations
set covered_feet = allocated_feet
where covered_feet is null;

alter table app.allocations
  alter column covered_feet set default 0;

alter table app.allocations
  alter column covered_feet set not null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conrelid = 'app.allocations'::regclass
      and conname = 'allocations_covered_feet_check'
  ) then
    alter table app.allocations
      add constraint allocations_covered_feet_check check (covered_feet >= 0);
  end if;
end;
$$;

create or replace function app_api.allocation_coverage_multiplier(
  p_source_width_in numeric,
  p_requirement_width_in numeric
)
returns integer
language sql
immutable
as $$
  select case
    when coalesce(p_source_width_in, 0) = 72
      and coalesce(p_requirement_width_in, 0) = 36
      then 2
    else 1
  end;
$$;

create or replace function app_api.compute_physical_feet_for_coverage(
  p_requested_covered_feet integer,
  p_source_width_in numeric,
  p_requirement_width_in numeric
)
returns integer
language sql
immutable
as $$
  select case
    when greatest(coalesce(p_requested_covered_feet, 0), 0) <= 0 then 0
    when app_api.allocation_coverage_multiplier(p_source_width_in, p_requirement_width_in) > 1
      then ceil(
        greatest(coalesce(p_requested_covered_feet, 0), 0)::numeric
        / app_api.allocation_coverage_multiplier(p_source_width_in, p_requirement_width_in)::numeric
      )::integer
    else greatest(coalesce(p_requested_covered_feet, 0), 0)
  end;
$$;

create or replace function app_api.compute_covered_feet_from_allocation(
  p_allocated_feet integer,
  p_source_width_in numeric,
  p_requirement_width_in numeric,
  p_requested_covered_feet integer default null
)
returns integer
language sql
immutable
as $$
  select case
    when greatest(coalesce(p_allocated_feet, 0), 0) <= 0 then 0
    when p_requested_covered_feet is null then
      greatest(coalesce(p_allocated_feet, 0), 0)
      * app_api.allocation_coverage_multiplier(p_source_width_in, p_requirement_width_in)
    else least(
      greatest(coalesce(p_requested_covered_feet, 0), 0),
      greatest(coalesce(p_allocated_feet, 0), 0)
      * app_api.allocation_coverage_multiplier(p_source_width_in, p_requirement_width_in)
    )
  end;
$$;

create or replace function app_api.plan_allocation_coverage(
  p_requested_covered_feet integer,
  p_available_feet integer,
  p_source_width_in numeric,
  p_requirement_width_in numeric
)
returns table (
  allocated_feet integer,
  covered_feet integer,
  remaining_covered_feet integer
)
language sql
immutable
as $$
  with normalized as (
    select
      greatest(coalesce(p_requested_covered_feet, 0), 0) as requested_covered_feet,
      greatest(coalesce(p_available_feet, 0), 0) as available_feet
  ),
  planned as (
    select
      least(
        normalized.available_feet,
        app_api.compute_physical_feet_for_coverage(
          normalized.requested_covered_feet,
          p_source_width_in,
          p_requirement_width_in
        )
      ) as allocated_feet,
      normalized.requested_covered_feet
    from normalized
  )
  select
    planned.allocated_feet,
    app_api.compute_covered_feet_from_allocation(
      planned.allocated_feet,
      p_source_width_in,
      p_requirement_width_in,
      planned.requested_covered_feet
    ) as covered_feet,
    greatest(
      planned.requested_covered_feet
      - app_api.compute_covered_feet_from_allocation(
        planned.allocated_feet,
        p_source_width_in,
        p_requirement_width_in,
        planned.requested_covered_feet
      ),
      0
    ) as remaining_covered_feet
  from planned;
$$;

create or replace function app_api.save_allocation(p_allocation app.allocations)
returns app.allocations
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_row app.allocations;
begin
  insert into app.allocations (
    id,
    org_id,
    allocation_id,
    box_id,
    job_id,
    job_number,
    warehouse,
    job_date,
    allocated_feet,
    covered_feet,
    requirement_id,
    status,
    created_at,
    created_by,
    resolved_at,
    resolved_by,
    notes,
    crew_leader,
    film_order_id,
    allocation_kind
  )
  values (
    coalesce(p_allocation.id, gen_random_uuid()),
    p_allocation.org_id,
    p_allocation.allocation_id,
    p_allocation.box_id,
    p_allocation.job_id,
    p_allocation.job_number,
    p_allocation.warehouse,
    p_allocation.job_date,
    p_allocation.allocated_feet,
    coalesce(p_allocation.covered_feet, p_allocation.allocated_feet),
    p_allocation.requirement_id,
    p_allocation.status,
    coalesce(p_allocation.created_at, now()),
    coalesce(p_allocation.created_by, ''),
    p_allocation.resolved_at,
    coalesce(p_allocation.resolved_by, ''),
    coalesce(p_allocation.notes, ''),
    coalesce(p_allocation.crew_leader, ''),
    coalesce(p_allocation.film_order_id, ''),
    coalesce(p_allocation.allocation_kind, 'REQUIREMENT'::app.allocation_kind)
  )
  on conflict (org_id, allocation_id) do update set
    box_id = excluded.box_id,
    job_id = excluded.job_id,
    job_number = excluded.job_number,
    warehouse = excluded.warehouse,
    job_date = excluded.job_date,
    allocated_feet = excluded.allocated_feet,
    covered_feet = excluded.covered_feet,
    requirement_id = excluded.requirement_id,
    status = excluded.status,
    created_at = excluded.created_at,
    created_by = excluded.created_by,
    resolved_at = excluded.resolved_at,
    resolved_by = excluded.resolved_by,
    notes = excluded.notes,
    crew_leader = excluded.crew_leader,
    film_order_id = excluded.film_order_id,
    allocation_kind = excluded.allocation_kind
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function app_api.create_allocation(
  p_org_id uuid,
  p_box app.boxes,
  p_job_context jsonb,
  p_allocated_feet integer,
  p_actor text,
  p_film_order_id text default '',
  p_allocation_kind text default 'REQUIREMENT',
  p_requirement_id uuid default null
)
returns app.allocations
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_allocation app.allocations;
  v_kind text := upper(app_api.trim_text(p_allocation_kind));
begin
  if v_kind = '' then
    v_kind := 'REQUIREMENT';
  end if;

  if v_kind not in ('REQUIREMENT', 'EXTRA') then
    perform app_api.raise_http(400, 'Allocation kind must be REQUIREMENT or EXTRA.');
  end if;

  v_allocation.id := gen_random_uuid();
  v_allocation.org_id := p_org_id;
  v_allocation.allocation_id := app_api.create_log_id();
  v_allocation.box_id := p_box.box_id;
  v_allocation.job_id := app_api.get_or_resolve_job_id(p_org_id, p_job_context->>'jobNumber');
  v_allocation.job_number := p_job_context->>'jobNumber';
  v_allocation.warehouse := p_box.warehouse;
  v_allocation.job_date := nullif(app_api.trim_text(p_job_context->>'jobDate'), '')::date;
  v_allocation.allocated_feet := p_allocated_feet;
  v_allocation.covered_feet := p_allocated_feet;
  v_allocation.requirement_id := p_requirement_id;
  v_allocation.status := 'ACTIVE';
  v_allocation.created_at := now();
  v_allocation.created_by := app_api.trim_text(p_actor);
  v_allocation.resolved_at := null;
  v_allocation.resolved_by := '';
  v_allocation.notes := '';
  v_allocation.crew_leader := coalesce(p_job_context->>'crewLeader', '');
  v_allocation.film_order_id := app_api.trim_text(p_film_order_id);
  v_allocation.allocation_kind := v_kind::app.allocation_kind;

  return app_api.save_allocation(v_allocation);
end;
$$;

create or replace function app_api.create_allocation_with_coverage(
  p_org_id uuid,
  p_box app.boxes,
  p_job_context jsonb,
  p_allocated_feet integer,
  p_covered_feet integer,
  p_actor text,
  p_film_order_id text default '',
  p_allocation_kind text default 'REQUIREMENT',
  p_requirement_id uuid default null
)
returns app.allocations
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_allocation app.allocations;
  v_kind text := upper(app_api.trim_text(p_allocation_kind));
begin
  if v_kind = '' then
    v_kind := 'REQUIREMENT';
  end if;

  if v_kind not in ('REQUIREMENT', 'EXTRA') then
    perform app_api.raise_http(400, 'Allocation kind must be REQUIREMENT or EXTRA.');
  end if;

  v_allocation.id := gen_random_uuid();
  v_allocation.org_id := p_org_id;
  v_allocation.allocation_id := app_api.create_log_id();
  v_allocation.box_id := p_box.box_id;
  v_allocation.job_id := app_api.get_or_resolve_job_id(p_org_id, p_job_context->>'jobNumber');
  v_allocation.job_number := p_job_context->>'jobNumber';
  v_allocation.warehouse := p_box.warehouse;
  v_allocation.job_date := nullif(app_api.trim_text(p_job_context->>'jobDate'), '')::date;
  v_allocation.allocated_feet := p_allocated_feet;
  v_allocation.covered_feet := greatest(coalesce(p_covered_feet, p_allocated_feet), 0);
  v_allocation.requirement_id := p_requirement_id;
  v_allocation.status := 'ACTIVE';
  v_allocation.created_at := now();
  v_allocation.created_by := app_api.trim_text(p_actor);
  v_allocation.resolved_at := null;
  v_allocation.resolved_by := '';
  v_allocation.notes := '';
  v_allocation.crew_leader := coalesce(p_job_context->>'crewLeader', '');
  v_allocation.film_order_id := app_api.trim_text(p_film_order_id);
  v_allocation.allocation_kind := v_kind::app.allocation_kind;

  return app_api.save_allocation(v_allocation);
end;
$$;

create or replace function public.api_allocations_apply(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_source app.boxes;
  v_candidate app.boxes;
  v_job_context jsonb;
  v_requested_feet integer := coalesce(floor(nullif(app_api.trim_text(p_payload->>'requestedFeet'), '')::numeric), 0);
  v_requested_width_in numeric := nullif(app_api.trim_text(p_payload->>'requestedWidthIn'), '')::numeric;
  v_requirement_id_text text := app_api.trim_text(p_payload->>'requirementId');
  v_requirement_id uuid;
  v_requirement app.job_requirements;
  v_source_film_key text;
  v_requirement_film_key text;
  v_remaining integer := 0;
  v_source_suggested integer := 0;
  v_source_suggested_covered integer := 0;
  v_candidate_suggested integer := 0;
  v_candidate_suggested_covered integer := 0;
  v_cross_warehouse boolean := coalesce((p_payload->>'crossWarehouse')::boolean, false);
  v_selected_box_ids text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'selectedSuggestionBoxIds', '[]'::jsonb))),
    array[]::text[]
  );
  v_extra_allocations jsonb := coalesce(p_payload->'extraAllocations', '[]'::jsonb);
  v_extra_entry jsonb;
  v_extra_box_id text;
  v_extra_feet integer;
  v_extra_processed_box_ids text[] := array[]::text[];
  v_allocation app.allocations;
  v_allocation_ids text[] := array[]::text[];
  v_film_order app.film_orders;
  v_conflict_count integer;
  v_job_warehouse text;
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_org_member(p_org_id);

  if v_requested_feet < 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be zero or greater.');
  end if;

  if coalesce(jsonb_typeof(v_extra_allocations), '') not in ('', 'array') then
    perform app_api.raise_http(400, 'extraAllocations must be an array.');
  end if;

  select *
  into v_source
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_source.status <> 'IN_STOCK' then
    perform app_api.raise_http(400, 'Only in-stock boxes can be allocated.');
  end if;

  v_job_context := app_api.resolve_job_context(
    p_org_id,
    p_payload->>'jobNumber',
    p_payload->>'jobDate',
    p_payload->>'crewLeader'
  );

  v_source_film_key := app_api.normalize_requirement_film_key(
    p_org_id,
    v_source.manufacturer,
    v_source.film_name
  );

  if v_requested_feet > 0 then
    if v_requirement_id_text = '' then
      perform app_api.raise_http(400, 'RequirementId is required for film allocations.');
    end if;

    begin
      v_requirement_id := v_requirement_id_text::uuid;
    exception
      when others then
        perform app_api.raise_http(400, 'RequirementId must be a valid UUID.');
    end;

    select r.*
    into v_requirement
    from app.job_requirements r
    where r.org_id = p_org_id
      and r.job_id = app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber')
      and r.id = v_requirement_id;

    if not found then
      perform app_api.raise_http(
        400,
        format('Requirement %s does not belong to job %s.', v_requirement_id, v_job_context->>'jobNumber')
      );
    end if;

    v_requirement_film_key := app_api.normalize_requirement_film_key(
      p_org_id,
      v_requirement.manufacturer,
      v_requirement.film_name
    );

    if v_requirement_film_key <> v_source_film_key then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    if v_source.width_in < v_requirement.width_in then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    v_requested_width_in := v_requirement.width_in;
  elsif v_requested_width_in is null or v_requested_width_in <= 0 then
    v_requested_width_in := v_source.width_in;
  end if;

  if v_source.width_in < v_requested_width_in then
    perform app_api.raise_http(400, 'Source box width must meet or exceed the requested width.');
  end if;

  v_remaining := greatest(v_requested_feet, 0);

  if v_requested_feet > 0 then
    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_source.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count = 0 then
      select
        p.allocated_feet,
        p.covered_feet,
        p.remaining_covered_feet
      into
        v_source_suggested,
        v_source_suggested_covered,
        v_remaining
      from app_api.plan_allocation_coverage(
        v_remaining,
        v_source.feet_available,
        v_source.width_in,
        v_requested_width_in
      ) p;
    end if;
  end if;

  if v_source_suggested > 0 then
    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_source,
      v_job_context,
      v_source_suggested,
      v_source_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    v_source.feet_available := greatest(v_source.feet_available - v_source_suggested, 0);
    v_source := app_api.save_box(v_source);
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end if;

  for v_candidate in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id <> v_source.box_id
      and b.status = 'IN_STOCK'
      and b.feet_available > 0
      and app_api.normalize_requirement_film_key(p_org_id, b.manufacturer, b.film_name) = v_source_film_key
      and b.width_in >= v_requested_width_in
      and (v_cross_warehouse or b.warehouse = v_source.warehouse)
    order by
      case
        when b.width_in = v_requested_width_in then 0
        when app_api.allocation_coverage_multiplier(b.width_in, v_requested_width_in) > 1 then 1
        else 2
      end,
      (b.width_in - v_requested_width_in),
      coalesce(b.received_date, b.order_date, '9999-12-31'::date),
      b.box_id
    for update
  loop
    exit when v_remaining <= 0;

    if coalesce(array_length(v_selected_box_ids, 1), 0) > 0 and array_position(v_selected_box_ids, v_candidate.box_id) is null then
      continue;
    end if;

    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_candidate.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count > 0 then
      continue;
    end if;

    select
      p.allocated_feet,
      p.covered_feet,
      p.remaining_covered_feet
    into
      v_candidate_suggested,
      v_candidate_suggested_covered,
      v_remaining
    from app_api.plan_allocation_coverage(
      v_remaining,
      v_candidate.feet_available,
      v_candidate.width_in,
      v_requested_width_in
    ) p;

    if v_candidate_suggested <= 0 or v_candidate_suggested_covered <= 0 then
      continue;
    end if;

    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_candidate,
      v_job_context,
      v_candidate_suggested,
      v_candidate_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    v_candidate.feet_available := greatest(v_candidate.feet_available - v_allocation.allocated_feet, 0);
    perform app_api.save_box(v_candidate);
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end loop;

  if coalesce(jsonb_typeof(v_extra_allocations), '') = 'array' then
    for v_extra_entry in
      select value
      from jsonb_array_elements(v_extra_allocations)
    loop
      if coalesce(jsonb_typeof(v_extra_entry), '') <> 'object' then
        perform app_api.raise_http(400, 'Each extra allocation entry must be an object.');
      end if;

      v_extra_box_id := app_api.require_text(v_extra_entry->>'boxId', 'extraAllocations[].boxId');
      v_extra_feet := floor(nullif(app_api.trim_text(v_extra_entry->>'allocatedFeet'), '')::numeric);

      if v_extra_feet is null or v_extra_feet <= 0 then
        perform app_api.raise_http(400, format('Extra allocation for box %s must be greater than zero.', v_extra_box_id));
      end if;

      if array_position(v_extra_processed_box_ids, v_extra_box_id) is not null then
        perform app_api.raise_http(400, format('Duplicate extra allocation entry for box %s.', v_extra_box_id));
      end if;

      select *
      into v_candidate
      from app.boxes b
      where b.org_id = p_org_id
        and b.box_id = v_extra_box_id
      for update;

      if not found then
        perform app_api.raise_http(404, format('Box not found: %s', v_extra_box_id));
      end if;

      if v_candidate.status <> 'IN_STOCK' then
        perform app_api.raise_http(400, format('Box %s is no longer allocatable.', v_candidate.box_id));
      end if;

      if app_api.normalize_requirement_film_key(p_org_id, v_candidate.manufacturer, v_candidate.film_name) <> v_source_film_key
        or v_candidate.width_in < v_requested_width_in then
        perform app_api.raise_http(
          400,
          format(
            'Extra box %s must match film and meet the requested width for this allocation.',
            v_candidate.box_id
          )
        );
      end if;

      if v_candidate.feet_available < v_extra_feet then
        perform app_api.raise_http(400, format('Box %s no longer has enough available LF.', v_candidate.box_id));
      end if;

      v_allocation := app_api.create_allocation(
        p_org_id,
        v_candidate,
        v_job_context,
        v_extra_feet,
        p_actor,
        '',
        'EXTRA',
        null
      );
      v_candidate.feet_available := greatest(v_candidate.feet_available - v_extra_feet, 0);
      perform app_api.save_box(v_candidate);
      v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
      v_extra_processed_box_ids := array_append(v_extra_processed_box_ids, v_extra_box_id);
    end loop;
  end if;

  if v_requested_feet = 0 and coalesce(array_length(v_extra_processed_box_ids, 1), 0) = 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be greater than zero unless extraAllocations are provided.');
  end if;

  if v_remaining > 0 then
    if app_api.trim_text(p_payload->>'jobWarehouse') <> '' then
      v_job_warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'jobWarehouse', 'Job warehouse');
    else
      v_job_warehouse := v_source.warehouse;
    end if;

    v_film_order.id := gen_random_uuid();
    v_film_order.org_id := p_org_id;
    v_film_order.film_order_id := app_api.create_log_id();
    v_film_order.job_id := app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber');
    v_film_order.job_number := v_job_context->>'jobNumber';
    v_film_order.warehouse := v_job_warehouse;
    v_film_order.manufacturer := v_source.manufacturer;
    v_film_order.film_name := v_source.film_name;
    v_film_order.width_in := v_requested_width_in;
    v_film_order.requested_feet := v_remaining;
    v_film_order.covered_feet := 0;
    v_film_order.ordered_feet := 0;
    v_film_order.remaining_to_order_feet := v_remaining;
    v_film_order.job_date := nullif(v_job_context->>'jobDate', '')::date;
    v_film_order.crew_leader := coalesce(v_job_context->>'crewLeader', '');
    v_film_order.status := 'FILM_ORDER';
    v_film_order.source_box_id := v_source.box_id;
    v_film_order.resolved_at := null;
    v_film_order.resolved_by := '';
    v_film_order.notes := format('Created from a shortage while trying to allocate %s LF.', v_requested_feet);
    v_film_order.created_at := now();
    v_film_order.created_by := app_api.trim_text(p_actor);
    v_film_order := app_api.save_film_order(v_film_order);
    v_warnings := app_api.push_warning(
      v_warnings,
      format('Film Order %s was created for the remaining %s LF.', v_film_order.film_order_id, v_remaining)
    );
  end if;

  return jsonb_build_object(
    'allocationIds', to_jsonb(v_allocation_ids),
    'filmOrderId', coalesce(v_film_order.film_order_id, ''),
    'remainingUncoveredFeet', greatest(v_remaining, 0),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function app_api.public_allocation_json(p_entry app.allocations)
returns jsonb
language sql
stable
as $$
  select jsonb_build_object(
    'allocationId', coalesce(p_entry.allocation_id, ''),
    'boxId', coalesce(p_entry.box_id, ''),
    'warehouse', coalesce(p_entry.warehouse::text, ''),
    'jobNumber', coalesce(p_entry.job_number, ''),
    'jobDate', coalesce(to_char(p_entry.job_date, 'YYYY-MM-DD'), ''),
    'crewLeader', coalesce(p_entry.crew_leader, ''),
    'allocatedFeet', p_entry.allocated_feet,
    'coveredFeet', coalesce(p_entry.covered_feet, p_entry.allocated_feet),
    'requirementId', coalesce(p_entry.requirement_id::text, ''),
    'allocationKind', coalesce(p_entry.allocation_kind::text, 'REQUIREMENT'),
    'status', coalesce(p_entry.status::text, 'ACTIVE'),
    'createdAt', coalesce(to_char(p_entry.created_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), ''),
    'createdBy', coalesce(p_entry.created_by, ''),
    'resolvedAt', coalesce(to_char(p_entry.resolved_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), ''),
    'resolvedBy', coalesce(p_entry.resolved_by, ''),
    'filmOrderId', coalesce(p_entry.film_order_id, ''),
    'notes', coalesce(p_entry.notes, '')
  );
$$;

create or replace function app_api.sum_film_order_covered_feet(p_org_id uuid, p_film_order_id text)
returns integer
language sql
stable
as $$
  select coalesce(sum(coalesce(a.covered_feet, a.allocated_feet)), 0)::integer
  from app.allocations a
  where a.org_id = p_org_id
    and upper(a.film_order_id) = upper(p_film_order_id)
    and a.status <> 'CANCELLED';
$$;

create or replace function app_api.normalize_core_type(p_value text, p_allow_blank boolean default false)
returns text
language plpgsql
immutable
as $$
declare
  v_trimmed text := app_api.trim_text(p_value);
  v_normalized text := lower(v_trimmed);
begin
  if v_trimmed = '' then
    if p_allow_blank then
      return '';
    end if;

    perform app_api.raise_http(400, 'CoreType is required.');
  end if;

  if v_normalized in ('white', 'white plastic', 'whiteplastic') then
    return 'White plastic';
  end if;

  if v_normalized in ('red', 'red plastic', 'redplastic') then
    return 'Red plastic';
  end if;

  if v_normalized in ('cardboard', 'cardboard 1/8"', 'cardboard 1/8', 'cardboard 1-8"', 'cardboard 1-8') then
    return 'Cardboard 1/8"';
  end if;

  if v_normalized in (
    'thick cardboard',
    'thick-cardboard',
    'thick_cardboard',
    'thickcardboard',
    'cardboard 3/4"',
    'cardboard 3/4',
    'cardboard 3-4"',
    'cardboard 3-4',
    'cardboard 3/8"',
    'cardboard 3/8',
    'cardboard 3-8"',
    'cardboard 3-8'
  ) then
    return 'Cardboard 3/8"';
  end if;

  if v_normalized in (
    'security 1/4" cardboard',
    'security 1/4 cardboard',
    'security 1-4" cardboard',
    'security 1-4 cardboard'
  ) then
    return 'SECURITY 1/4" Cardboard';
  end if;

  if v_normalized in (
    'security white plastic 3/8"',
    'security white plastic 3/8',
    'security white plastic 3-8"',
    'security white plastic 3-8',
    'security whiteplastic 3/8"',
    'security whiteplastic 3/8',
    'security whiteplastic 3-8"',
    'security whiteplastic 3-8',
    'security white 3/8"',
    'security white 3/8',
    'security white 3-8"',
    'security white 3-8'
  ) then
    return 'SECURITY White plastic 3/8"';
  end if;

  perform app_api.raise_http(
    400,
    'CoreType must be White plastic, Red plastic, Cardboard 1/8", Cardboard 3/8", SECURITY 1/4" Cardboard, or SECURITY White plastic 3/8".'
  );
  return '';
end;
$$;

create or replace function app_api.derive_core_weight_lbs(p_core_type text, p_width_in numeric)
returns numeric
language sql
immutable
as $$
  select round(
    (
      case app_api.normalize_core_type(p_core_type, false)
        when 'White plastic' then 2::numeric
        when 'Red plastic' then 1.85::numeric
        when 'Cardboard 1/8"' then 2.05::numeric
        when 'Cardboard 3/8"' then 6.15::numeric
        when 'SECURITY 1/4" Cardboard' then 11.6::numeric
        when 'SECURITY White plastic 3/8"' then 14.4::numeric
      end / 72::numeric
    ) * p_width_in,
    4
  );
$$;

