create or replace function public.api_acl_audit_undo(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_log_id text := app_api.require_text(v_payload->>'logId', 'LogID');
  v_action text := '';
begin
  perform app_api.require_effective_feature_access(p_org_id, 'activity_history', 'write');

  select upper(btrim(a.action))
  into v_action
  from app.audit_log a
  where a.org_id = p_org_id
    and a.log_id = v_log_id;

  if v_action in ('START_TRANSFER', 'RECEIVE_TRANSFER', 'CANCEL_TRANSFER') then
    perform app_api.raise_http(
      400,
      'Transfer history cannot be undone from audit undo. Use the transfer receive or cancel actions instead.'
    );
  end if;

  return public.api_audit_undo(p_org_id, p_actor, v_payload);
end;
$$;

create or replace function app_api.extract_requirement_compact_base_code(
  p_compact_family text
)
returns text
language sql
immutable
as $$
  select coalesce(
    (regexp_match(coalesce(p_compact_family, ''), '^([a-z]{1,4}[0-9]{1,4})'))[1],
    ''
  );
$$;

create or replace function app_api.requirement_film_is_compatible(
  p_org_id uuid,
  p_candidate_manufacturer text,
  p_candidate_film_name text,
  p_requirement_manufacturer text,
  p_requirement_film_name text
)
returns boolean
language sql
stable
as $$
  with candidate as (
    select
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_candidate_manufacturer,
          p_candidate_film_name
        ),
        '|',
        1
      ) as manufacturer_key,
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_candidate_manufacturer,
          p_candidate_film_name
        ),
        '|',
        2
      ) as compact_family,
      app_api.extract_requirement_compact_base_code(
        split_part(
          app_api.normalize_requirement_film_family_key(
            p_org_id,
            p_candidate_manufacturer,
            p_candidate_film_name
          ),
          '|',
          2
        )
      ) as compact_base_code,
      app_api.requirement_film_is_exterior(
        p_org_id,
        p_candidate_manufacturer,
        p_candidate_film_name
      ) as is_exterior
  ),
  requirement as (
    select
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_requirement_manufacturer,
          p_requirement_film_name
        ),
        '|',
        1
      ) as manufacturer_key,
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_requirement_manufacturer,
          p_requirement_film_name
        ),
        '|',
        2
      ) as compact_family,
      app_api.extract_requirement_compact_base_code(
        split_part(
          app_api.normalize_requirement_film_family_key(
            p_org_id,
            p_requirement_manufacturer,
            p_requirement_film_name
          ),
          '|',
          2
        )
      ) as compact_base_code,
      app_api.requirement_film_is_exterior(
        p_org_id,
        p_requirement_manufacturer,
        p_requirement_film_name
      ) as is_exterior
  )
  select
    candidate.manufacturer_key = requirement.manufacturer_key
    and (
      candidate.compact_family = requirement.compact_family
      or (
        requirement.compact_base_code <> ''
        and requirement.compact_family = requirement.compact_base_code
        and candidate.compact_base_code = requirement.compact_base_code
        and candidate.compact_family like requirement.compact_family || '%'
        and length(candidate.compact_family) > length(requirement.compact_family)
      )
    )
    and (
      not requirement.is_exterior
      or candidate.is_exterior
    )
  from candidate, requirement;
$$;

alter table app.boxes
  add column if not exists updated_by text not null default '';

create or replace function app_api.extract_requirement_compact_base_code(
  p_compact_family text
)
returns text
language sql
immutable
as $$
  select coalesce(
    (regexp_match(coalesce(p_compact_family, ''), '^([a-z]{1,4}[0-9]{1,4})'))[1],
    ''
  );
$$;

create or replace function app_api.requirement_film_is_compatible(
  p_org_id uuid,
  p_candidate_manufacturer text,
  p_candidate_film_name text,
  p_requirement_manufacturer text,
  p_requirement_film_name text
)
returns boolean
language sql
stable
as $$
  with candidate as (
    select
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_candidate_manufacturer,
          p_candidate_film_name
        ),
        '|',
        1
      ) as manufacturer_key,
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_candidate_manufacturer,
          p_candidate_film_name
        ),
        '|',
        2
      ) as compact_family,
      app_api.extract_requirement_compact_base_code(
        split_part(
          app_api.normalize_requirement_film_family_key(
            p_org_id,
            p_candidate_manufacturer,
            p_candidate_film_name
          ),
          '|',
          2
        )
      ) as compact_base_code,
      app_api.requirement_film_is_exterior(
        p_org_id,
        p_candidate_manufacturer,
        p_candidate_film_name
      ) as is_exterior
  ),
  requirement as (
    select
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_requirement_manufacturer,
          p_requirement_film_name
        ),
        '|',
        1
      ) as manufacturer_key,
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_requirement_manufacturer,
          p_requirement_film_name
        ),
        '|',
        2
      ) as compact_family,
      app_api.extract_requirement_compact_base_code(
        split_part(
          app_api.normalize_requirement_film_family_key(
            p_org_id,
            p_requirement_manufacturer,
            p_requirement_film_name
          ),
          '|',
          2
        )
      ) as compact_base_code,
      app_api.requirement_film_is_exterior(
        p_org_id,
        p_requirement_manufacturer,
        p_requirement_film_name
      ) as is_exterior
  )
  select
    candidate.manufacturer_key = requirement.manufacturer_key
    and (
      candidate.compact_family = requirement.compact_family
      or (
        requirement.compact_base_code <> ''
        and requirement.compact_family = requirement.compact_base_code
        and candidate.compact_base_code = requirement.compact_base_code
        and candidate.compact_family like requirement.compact_family || '%'
        and length(candidate.compact_family) > length(requirement.compact_family)
      )
    )
    and (
      not requirement.is_exterior
      or candidate.is_exterior
    )
  from candidate, requirement;
$$;

create or replace function public.api_allocations_apply(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_source app.boxes;
  v_candidate app.boxes;
  v_job_context jsonb;
  v_requested_feet integer := coalesce(floor(nullif(app_api.trim_text(p_payload->>'requestedFeet'), '')::numeric), 0);
  v_requested_width_in numeric := nullif(app_api.trim_text(p_payload->>'requestedWidthIn'), '')::numeric;
  v_requirement_id_text text := app_api.trim_text(p_payload->>'requirementId');
  v_requirement_id uuid;
  v_requirement app.job_requirements;
  v_source_film_key text;
  v_requirement_is_exterior boolean := false;
  v_remaining integer := 0;
  v_source_suggested integer := 0;
  v_source_suggested_covered integer := 0;
  v_candidate_suggested integer := 0;
  v_candidate_suggested_covered integer := 0;
  v_cross_warehouse boolean := coalesce((p_payload->>'crossWarehouse')::boolean, false);
  v_selected_box_ids text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'selectedSuggestionBoxIds', '[]'::jsonb))),
    array[]::text[]
  );
  v_extra_allocations jsonb := coalesce(p_payload->'extraAllocations', '[]'::jsonb);
  v_extra_entry jsonb;
  v_extra_box_id text;
  v_extra_feet integer;
  v_extra_processed_box_ids text[] := array[]::text[];
  v_allocation app.allocations;
  v_allocation_ids text[] := array[]::text[];
  v_film_order app.film_orders;
  v_conflict_count integer;
  v_job_warehouse text;
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_org_member(p_org_id);

  if v_requested_feet < 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be zero or greater.');
  end if;

  if coalesce(jsonb_typeof(v_extra_allocations), '') not in ('', 'array') then
    perform app_api.raise_http(400, 'extraAllocations must be an array.');
  end if;

  select *
  into v_source
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_source.status <> 'IN_STOCK' then
    perform app_api.raise_http(400, 'Only in-stock boxes can be allocated.');
  end if;

  v_job_context := app_api.resolve_job_context(
    p_org_id,
    p_payload->>'jobNumber',
    p_payload->>'jobDate',
    p_payload->>'crewLeader'
  );

  v_source_film_key := app_api.normalize_requirement_film_key(
    p_org_id,
    v_source.manufacturer,
    v_source.film_name
  );

  if v_requested_feet > 0 then
    if v_requirement_id_text = '' then
      perform app_api.raise_http(400, 'RequirementId is required for film allocations.');
    end if;

    begin
      v_requirement_id := v_requirement_id_text::uuid;
    exception
      when others then
        perform app_api.raise_http(400, 'RequirementId must be a valid UUID.');
    end;

    select r.*
    into v_requirement
    from app.job_requirements r
    where r.org_id = p_org_id
      and r.job_id = app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber')
      and r.id = v_requirement_id;

    if not found then
      perform app_api.raise_http(
        400,
        format('Requirement %s does not belong to job %s.', v_requirement_id, v_job_context->>'jobNumber')
      );
    end if;

    v_requirement_is_exterior := app_api.requirement_film_is_exterior(
      p_org_id,
      v_requirement.manufacturer,
      v_requirement.film_name
    );

    if not app_api.requirement_film_is_compatible(
      p_org_id,
      v_source.manufacturer,
      v_source.film_name,
      v_requirement.manufacturer,
      v_requirement.film_name
    ) then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    if v_source.width_in < v_requirement.width_in then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    v_requested_width_in := v_requirement.width_in;
  elsif v_requested_width_in is null or v_requested_width_in <= 0 then
    v_requested_width_in := v_source.width_in;
  end if;

  if v_source.width_in < v_requested_width_in then
    perform app_api.raise_http(400, 'Source box width must meet or exceed the requested width.');
  end if;

  v_remaining := greatest(v_requested_feet, 0);

  if v_requested_feet > 0 then
    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_source.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count = 0 then
      select
        p.allocated_feet,
        p.covered_feet,
        p.remaining_covered_feet
      into
        v_source_suggested,
        v_source_suggested_covered,
        v_remaining
      from app_api.plan_allocation_coverage(
        v_remaining,
        v_source.feet_available,
        v_source.width_in,
        v_requested_width_in
      ) p;
    end if;
  end if;

  if v_source_suggested > 0 then
    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_source,
      v_job_context,
      v_source_suggested,
      v_source_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    v_source.feet_available := greatest(v_source.feet_available - v_source_suggested, 0);
    v_source := app_api.save_box(v_source);
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end if;

  for v_candidate in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id <> v_source.box_id
      and b.status = 'IN_STOCK'
      and b.feet_available > 0
      and case
        when v_requirement_id is not null then app_api.requirement_film_is_compatible(
          p_org_id,
          b.manufacturer,
          b.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        )
        else app_api.normalize_requirement_film_key(p_org_id, b.manufacturer, b.film_name) = v_source_film_key
      end
      and b.width_in >= v_requested_width_in
      and (v_cross_warehouse or b.warehouse = v_source.warehouse)
    order by
      case
        when b.width_in = v_requested_width_in then 0
        when app_api.allocation_coverage_multiplier(b.width_in, v_requested_width_in) > 1 then 1
        else 2
      end,
      (b.width_in - v_requested_width_in),
      case
        when v_requirement_id is not null
          and not v_requirement_is_exterior
          and app_api.requirement_film_is_exterior(p_org_id, b.manufacturer, b.film_name)
        then 1
        else 0
      end,
      coalesce(b.received_date, b.order_date, '9999-12-31'::date),
      b.box_id
    for update
  loop
    exit when v_remaining <= 0;

    if coalesce(array_length(v_selected_box_ids, 1), 0) > 0 and array_position(v_selected_box_ids, v_candidate.box_id) is null then
      continue;
    end if;

    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_candidate.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count > 0 then
      continue;
    end if;

    select
      p.allocated_feet,
      p.covered_feet,
      p.remaining_covered_feet
    into
      v_candidate_suggested,
      v_candidate_suggested_covered,
      v_remaining
    from app_api.plan_allocation_coverage(
      v_remaining,
      v_candidate.feet_available,
      v_candidate.width_in,
      v_requested_width_in
    ) p;

    if v_candidate_suggested <= 0 or v_candidate_suggested_covered <= 0 then
      continue;
    end if;

    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_candidate,
      v_job_context,
      v_candidate_suggested,
      v_candidate_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    v_candidate.feet_available := greatest(v_candidate.feet_available - v_allocation.allocated_feet, 0);
    perform app_api.save_box(v_candidate);
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end loop;

  if coalesce(jsonb_typeof(v_extra_allocations), '') = 'array' then
    for v_extra_entry in
      select value
      from jsonb_array_elements(v_extra_allocations)
    loop
      if coalesce(jsonb_typeof(v_extra_entry), '') <> 'object' then
        perform app_api.raise_http(400, 'Each extra allocation entry must be an object.');
      end if;

      v_extra_box_id := app_api.require_text(v_extra_entry->>'boxId', 'extraAllocations[].boxId');
      v_extra_feet := floor(nullif(app_api.trim_text(v_extra_entry->>'allocatedFeet'), '')::numeric);

      if v_extra_feet is null or v_extra_feet <= 0 then
        perform app_api.raise_http(400, format('Extra allocation for box %s must be greater than zero.', v_extra_box_id));
      end if;

      if array_position(v_extra_processed_box_ids, v_extra_box_id) is not null then
        perform app_api.raise_http(400, format('Duplicate extra allocation entry for box %s.', v_extra_box_id));
      end if;

      select *
      into v_candidate
      from app.boxes b
      where b.org_id = p_org_id
        and b.box_id = v_extra_box_id
      for update;

      if not found then
        perform app_api.raise_http(404, format('Box not found: %s', v_extra_box_id));
      end if;

      if v_candidate.status <> 'IN_STOCK' then
        perform app_api.raise_http(400, format('Box %s is no longer allocatable.', v_candidate.box_id));
      end if;

      if v_requirement_id is not null then
        if not app_api.requirement_film_is_compatible(
          p_org_id,
          v_candidate.manufacturer,
          v_candidate.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        ) or v_candidate.width_in < v_requested_width_in then
          perform app_api.raise_http(
            400,
            format(
              'Extra box %s must use a compatible film and meet the requested width for this allocation.',
              v_candidate.box_id
            )
          );
        end if;
      elsif app_api.normalize_requirement_film_key(p_org_id, v_candidate.manufacturer, v_candidate.film_name) <> v_source_film_key
        or v_candidate.width_in < v_requested_width_in then
        perform app_api.raise_http(
          400,
          format(
            'Extra box %s must match film and meet the requested width for this allocation.',
            v_candidate.box_id
          )
        );
      end if;

      if v_candidate.feet_available < v_extra_feet then
        perform app_api.raise_http(400, format('Box %s no longer has enough available LF.', v_candidate.box_id));
      end if;

      v_allocation := app_api.create_allocation(
        p_org_id,
        v_candidate,
        v_job_context,
        v_extra_feet,
        p_actor,
        '',
        'EXTRA',
        null
      );
      v_candidate.feet_available := greatest(v_candidate.feet_available - v_extra_feet, 0);
      perform app_api.save_box(v_candidate);
      v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
      v_extra_processed_box_ids := array_append(v_extra_processed_box_ids, v_extra_box_id);
    end loop;
  end if;

  if v_requested_feet = 0 and coalesce(array_length(v_extra_processed_box_ids, 1), 0) = 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be greater than zero unless extraAllocations are provided.');
  end if;

  if v_remaining > 0 then
    if app_api.trim_text(p_payload->>'jobWarehouse') <> '' then
      v_job_warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'jobWarehouse', 'Job warehouse');
    else
      v_job_warehouse := v_source.warehouse;
    end if;

    v_film_order.id := gen_random_uuid();
    v_film_order.org_id := p_org_id;
    v_film_order.film_order_id := app_api.create_log_id();
    v_film_order.job_id := app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber');
    v_film_order.job_number := v_job_context->>'jobNumber';
    v_film_order.warehouse := v_job_warehouse;
    v_film_order.manufacturer := coalesce(v_requirement.manufacturer, v_source.manufacturer);
    v_film_order.film_name := coalesce(v_requirement.film_name, v_source.film_name);
    v_film_order.width_in := v_requested_width_in;
    v_film_order.requested_feet := v_remaining;
    v_film_order.covered_feet := 0;
    v_film_order.ordered_feet := 0;
    v_film_order.remaining_to_order_feet := v_remaining;
    v_film_order.job_date := nullif(v_job_context->>'jobDate', '')::date;
    v_film_order.crew_leader := coalesce(v_job_context->>'crewLeader', '');
    v_film_order.status := 'FILM_ORDER';
    v_film_order.source_box_id := v_source.box_id;
    v_film_order.resolved_at := null;
    v_film_order.resolved_by := '';
    v_film_order.notes := format('Created from a shortage while trying to allocate %s LF.', v_requested_feet);
    v_film_order.created_at := now();
    v_film_order.created_by := app_api.trim_text(p_actor);
    v_film_order := app_api.save_film_order(v_film_order);
    v_warnings := app_api.push_warning(
      v_warnings,
      format('Film Order %s was created for the remaining %s LF.', v_film_order.film_order_id, v_remaining)
    );
  end if;

  return jsonb_build_object(
    'allocationIds', to_jsonb(v_allocation_ids),
    'filmOrderId', coalesce(v_film_order.film_order_id, ''),
    'remainingUncoveredFeet', greatest(v_remaining, 0),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

alter table app.box_id_aliases
  drop constraint if exists box_id_aliases_org_id_canonical_box_id_fkey;

alter table app.box_id_aliases
  add constraint box_id_aliases_org_id_canonical_box_id_fkey
  foreign key (org_id, canonical_box_id)
  references app.boxes(org_id, box_id)
  on update cascade
  on delete cascade;

create or replace function app_api.normalize_requirement_match_manufacturer_label(p_value text)
returns text
language sql
immutable
as $$
  select
    case lower(app_api.normalize_collapsed_catalog_label(p_value))
      when '3m' then '3M Solar'
      when '3m solar' then '3M Solar'
      when 'fasara' then '3M Fasara'
      when '3m fasara' then '3M Fasara'
      when 'avery' then 'Avery Dennison'
      when 'avery dennison' then 'Avery Dennison'
      when 'llumar vista' then 'Llumar'
      when 'llumarvista' then 'Llumar'
      when 'llumar' then 'Llumar'
      when 'solar guard' then 'Solar Gard'
      when 'solar gard' then 'Solar Gard'
      when 'solarguard' then 'Solar Gard'
      when 'solargard' then 'Solar Gard'
      when 'sg' then 'Solar Gard'
      when 'solyx' then 'SOLYX'
      when 'sol' then 'SOLYX'
      when 'madico' then 'Madico'
      when 'v-kool' then 'ASWFVKOOL'
      when 'vkool' then 'ASWFVKOOL'
      when 'aswfvkool' then 'ASWFVKOOL'
      when 'di-noc' then 'Di-Noc'
      when 'dinoc' then 'Di-Noc'
      when 'vinyl' then 'Vinyl'
      else app_api.normalize_collapsed_catalog_label(p_value)
    end;
$$;

create or replace function app_api.normalize_requirement_match_manufacturer_lookup_key(p_value text)
returns text
language sql
immutable
as $$
  select lower(app_api.normalize_requirement_match_manufacturer_label(p_value));
$$;

create or replace function app_api.normalize_requirement_match_compact_lookup_key(p_value text)
returns text
language sql
immutable
as $$
  select regexp_replace(
    lower(app_api.normalize_collapsed_catalog_label(p_value)),
    '[^a-z0-9]+',
    '',
    'g'
  );
$$;

create or replace function app_api.normalize_requirement_match_descriptor_tokens(p_value text)
returns text
language sql
immutable
as $$
  select app_api.normalize_collapsed_catalog_label(
    regexp_replace(
      regexp_replace(
        app_api.normalize_collapsed_catalog_label(p_value),
        '(^|[^a-z0-9])refl(?:ective)?\.?([^a-z0-9]|$)',
        '\1Reflective\2',
        'gi'
      ),
      'one[-[:space:]]*way',
      'One Way',
      'gi'
    )
  );
$$;

create or replace function app_api.strip_requirement_match_manufacturer_prefixes(
  p_manufacturer text,
  p_film_name text
)
returns text
language plpgsql
immutable
as $$
declare
  v_manufacturer text := app_api.normalize_requirement_match_manufacturer_label(p_manufacturer);
  v_value text := app_api.normalize_collapsed_catalog_label(p_film_name);
  v_patterns text[] := array[]::text[];
  v_next text;
  v_changed boolean := true;
  v_index integer;
begin
  if v_value = '' then
    return '';
  end if;

  case v_manufacturer
    when '3M Solar' then
      v_patterns := array['^3m(?:\s+solar)?\s+'];
    when '3M Fasara' then
      v_patterns := array['^3m\s+fasara\s+', '^fasara\s+', '^3m\s+'];
    when 'Solar Gard' then
      v_patterns := array['^sg\s+', '^solar\s*guard\s+', '^solar\s+gard\s+', '^solarguard\s+', '^solargard\s+'];
    when 'Llumar' then
      v_patterns := array['^llumar(?:\s+vista)?\s+', '^llumarvista\s+'];
    when 'Avery Dennison' then
      v_patterns := array['^avery\s+dennison\s+', '^avery\s+', '^ad\s+'];
    when 'SOLYX' then
      v_patterns := array['^solyx\s+', '^sol\s+'];
    when 'Madico' then
      v_patterns := array['^madico\s+'];
    else
      return v_value;
  end case;

  while v_changed loop
    v_changed := false;
    for v_index in 1..coalesce(array_length(v_patterns, 1), 0) loop
      v_next := app_api.normalize_collapsed_catalog_label(
        regexp_replace(v_value, v_patterns[v_index], '', 'i')
      );
      if v_next <> '' and v_next <> v_value then
        v_value := v_next;
        v_changed := true;
      end if;
    end loop;
  end loop;

  return v_value;
end;
$$;

create or replace function app_api.normalize_requirement_avery_natura_shade_film_name(
  p_manufacturer text,
  p_film_name text
)
returns text
language plpgsql
immutable
as $$
declare
  v_manufacturer_key text := app_api.normalize_requirement_match_manufacturer_lookup_key(p_manufacturer);
  v_value text := app_api.normalize_collapsed_catalog_label(p_film_name);
  v_match text[];
  v_digits text;
  v_suffix text;
begin
  if v_value = '' then
    return '';
  end if;

  if v_manufacturer_key <> app_api.normalize_requirement_match_manufacturer_lookup_key('Avery Dennison') then
    return v_value;
  end if;

  v_match := regexp_match(v_value, '^natura\s*0*([0-9]{1,3})(.*)$', 'i');
  if v_match is null then
    return v_value;
  end if;

  v_digits := regexp_replace(coalesce(v_match[1], ''), '^0+', '');
  if v_digits = '' then
    v_digits := '0';
  end if;

  v_suffix := app_api.normalize_collapsed_catalog_label(coalesce(v_match[2], ''));
  if v_suffix = '' then
    return format('Natura %s', v_digits);
  end if;

  return format(
    'Natura %s%s%s',
    v_digits,
    case when left(v_suffix, 1) = '-' then '' else ' ' end,
    v_suffix
  );
end;
$$;

create or replace function app_api.infer_requirement_night_vision_code(p_value text)
returns text
language plpgsql
immutable
as $$
declare
  v_normalized text := lower(app_api.normalize_collapsed_catalog_label(p_value));
  v_match text[];
  v_digits text := '';
begin
  if v_normalized = '' then
    return '';
  end if;

  v_match := regexp_match(
    v_normalized,
    '(^|[^a-z0-9])night\s*vision\s*(\d{1,3})([^a-z0-9]|$)',
    'i'
  );

  if v_match is null then
    v_match := regexp_match(
      v_normalized,
      '(^|[^a-z0-9])s?nv\s*-?\s*(\d{1,3})([^a-z0-9]|$)',
      'i'
    );
  end if;

  if v_match is null then
    v_match := regexp_match(
      v_normalized,
      '(^|[^a-z0-9])s\s*(\d{1,3})\s*nv([^a-z0-9]|$)',
      'i'
    );
  end if;

  if v_match is null then
    return '';
  end if;

  v_digits := regexp_replace(coalesce(v_match[2], ''), '^0+', '');
  if v_digits = '' then
    v_digits := '0';
  end if;

  return v_digits;
end;
$$;

create or replace function app_api.normalize_requirement_film_family_name(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns text
language plpgsql
stable
as $$
declare
  v_manufacturer text := app_api.normalize_requirement_match_manufacturer_label(p_manufacturer);
  v_manufacturer_key text := app_api.normalize_requirement_match_manufacturer_lookup_key(p_manufacturer);
  v_film_name text;
  v_night_vision_code text := '';
begin
  v_film_name := app_api.normalize_collapsed_catalog_label(
    app_api.resolve_canonical_film_name(p_org_id, v_manufacturer, p_film_name)
  );

  if v_film_name = '' then
    return '';
  end if;

  v_film_name := app_api.normalize_requirement_match_descriptor_tokens(
    app_api.strip_requirement_match_manufacturer_prefixes(v_manufacturer, v_film_name)
  );

  v_film_name := app_api.normalize_requirement_avery_natura_shade_film_name(
    v_manufacturer,
    v_film_name
  );

  if v_manufacturer_key = app_api.normalize_requirement_match_manufacturer_lookup_key('3M Solar') then
    v_night_vision_code := app_api.infer_requirement_night_vision_code(v_film_name);
    if v_night_vision_code <> '' then
      v_film_name := format('Night Vision %s', v_night_vision_code);
    end if;
  end if;

  if v_film_name ~* '(^|[[:space:]])Exterior[[:space:]]*$' then
    v_film_name := coalesce(
      nullif(
        app_api.normalize_collapsed_catalog_label(
          regexp_replace(v_film_name, '[[:space:]]+Exterior[[:space:]]*$', '', 'i')
        ),
        ''
      ),
      v_film_name
    );
  end if;

  return v_film_name;
end;
$$;

create or replace function app_api.normalize_requirement_film_family_key(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns text
language plpgsql
stable
as $$
declare
  v_manufacturer_key text := app_api.normalize_requirement_match_manufacturer_lookup_key(p_manufacturer);
  v_family_film_name text := app_api.normalize_requirement_film_family_name(
    p_org_id,
    p_manufacturer,
    p_film_name
  );
begin
  return v_manufacturer_key || '|' || app_api.normalize_requirement_match_compact_lookup_key(v_family_film_name);
end;
$$;

create or replace function app_api.requirement_film_is_exterior(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns boolean
language sql
stable
as $$
  select app_api.trim_text(
      app_api.resolve_canonical_film_name(
        p_org_id,
        app_api.normalize_requirement_match_manufacturer_label(p_manufacturer),
        p_film_name
      )
    ) ~* '(^|[[:space:]])Exterior[[:space:]]*$';
$$;

create or replace function app_api.extract_requirement_compact_base_code(
  p_compact_family text
)
returns text
language sql
immutable
as $$
  select coalesce(
    (regexp_match(coalesce(p_compact_family, ''), '^([a-z]{1,4}[0-9]{1,4})'))[1],
    ''
  );
$$;

create or replace function app_api.requirement_film_is_compatible(
  p_org_id uuid,
  p_candidate_manufacturer text,
  p_candidate_film_name text,
  p_requirement_manufacturer text,
  p_requirement_film_name text
)
returns boolean
language sql
stable
as $$
  with candidate as (
    select
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_candidate_manufacturer,
          p_candidate_film_name
        ),
        '|',
        1
      ) as manufacturer_key,
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_candidate_manufacturer,
          p_candidate_film_name
        ),
        '|',
        2
      ) as compact_family,
      app_api.extract_requirement_compact_base_code(
        split_part(
          app_api.normalize_requirement_film_family_key(
            p_org_id,
            p_candidate_manufacturer,
            p_candidate_film_name
          ),
          '|',
          2
        )
      ) as compact_base_code,
      app_api.requirement_film_is_exterior(
        p_org_id,
        p_candidate_manufacturer,
        p_candidate_film_name
      ) as is_exterior
  ),
  requirement as (
    select
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_requirement_manufacturer,
          p_requirement_film_name
        ),
        '|',
        1
      ) as manufacturer_key,
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_requirement_manufacturer,
          p_requirement_film_name
        ),
        '|',
        2
      ) as compact_family,
      app_api.extract_requirement_compact_base_code(
        split_part(
          app_api.normalize_requirement_film_family_key(
            p_org_id,
            p_requirement_manufacturer,
            p_requirement_film_name
          ),
          '|',
          2
        )
      ) as compact_base_code,
      app_api.requirement_film_is_exterior(
        p_org_id,
        p_requirement_manufacturer,
        p_requirement_film_name
      ) as is_exterior
  )
  select
    candidate.manufacturer_key = requirement.manufacturer_key
    and (
      candidate.compact_family = requirement.compact_family
      or (
        requirement.compact_base_code <> ''
        and requirement.compact_family = requirement.compact_base_code
        and candidate.compact_base_code = requirement.compact_base_code
        and candidate.compact_family like requirement.compact_family || '%'
        and length(candidate.compact_family) > length(requirement.compact_family)
      )
    )
    and (
      not requirement.is_exterior
      or candidate.is_exterior
    )
  from candidate, requirement;
$$;

create or replace function public.api_allocations_apply(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_source app.boxes;
  v_candidate app.boxes;
  v_job_context jsonb;
  v_requested_feet integer := coalesce(floor(nullif(app_api.trim_text(p_payload->>'requestedFeet'), '')::numeric), 0);
  v_requested_width_in numeric := nullif(app_api.trim_text(p_payload->>'requestedWidthIn'), '')::numeric;
  v_requirement_id_text text := app_api.trim_text(p_payload->>'requirementId');
  v_requirement_id uuid;
  v_requirement app.job_requirements;
  v_source_film_key text;
  v_requirement_is_exterior boolean := false;
  v_remaining integer := 0;
  v_source_suggested integer := 0;
  v_source_suggested_covered integer := 0;
  v_candidate_suggested integer := 0;
  v_candidate_suggested_covered integer := 0;
  v_cross_warehouse boolean := coalesce((p_payload->>'crossWarehouse')::boolean, false);
  v_selected_box_ids text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'selectedSuggestionBoxIds', '[]'::jsonb))),
    array[]::text[]
  );
  v_extra_allocations jsonb := coalesce(p_payload->'extraAllocations', '[]'::jsonb);
  v_extra_entry jsonb;
  v_extra_box_id text;
  v_extra_feet integer;
  v_extra_processed_box_ids text[] := array[]::text[];
  v_allocation app.allocations;
  v_allocation_ids text[] := array[]::text[];
  v_film_order app.film_orders;
  v_conflict_count integer;
  v_job_warehouse text;
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_org_member(p_org_id);

  if v_requested_feet < 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be zero or greater.');
  end if;

  if coalesce(jsonb_typeof(v_extra_allocations), '') not in ('', 'array') then
    perform app_api.raise_http(400, 'extraAllocations must be an array.');
  end if;

  select *
  into v_source
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_source.status <> 'IN_STOCK' then
    perform app_api.raise_http(400, 'Only in-stock boxes can be allocated.');
  end if;

  v_job_context := app_api.resolve_job_context(
    p_org_id,
    p_payload->>'jobNumber',
    p_payload->>'jobDate',
    p_payload->>'crewLeader'
  );

  v_source_film_key := app_api.normalize_requirement_film_key(
    p_org_id,
    v_source.manufacturer,
    v_source.film_name
  );

  if v_requested_feet > 0 then
    if v_requirement_id_text = '' then
      perform app_api.raise_http(400, 'RequirementId is required for film allocations.');
    end if;

    begin
      v_requirement_id := v_requirement_id_text::uuid;
    exception
      when others then
        perform app_api.raise_http(400, 'RequirementId must be a valid UUID.');
    end;

    select r.*
    into v_requirement
    from app.job_requirements r
    where r.org_id = p_org_id
      and r.job_id = app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber')
      and r.id = v_requirement_id;

    if not found then
      perform app_api.raise_http(
        400,
        format('Requirement %s does not belong to job %s.', v_requirement_id, v_job_context->>'jobNumber')
      );
    end if;

    v_requirement_is_exterior := app_api.requirement_film_is_exterior(
      p_org_id,
      v_requirement.manufacturer,
      v_requirement.film_name
    );

    if not app_api.requirement_film_is_compatible(
      p_org_id,
      v_source.manufacturer,
      v_source.film_name,
      v_requirement.manufacturer,
      v_requirement.film_name
    ) then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    if v_source.width_in < v_requirement.width_in then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    v_requested_width_in := v_requirement.width_in;
  elsif v_requested_width_in is null or v_requested_width_in <= 0 then
    v_requested_width_in := v_source.width_in;
  end if;

  if v_source.width_in < v_requested_width_in then
    perform app_api.raise_http(400, 'Source box width must meet or exceed the requested width.');
  end if;

  v_remaining := greatest(v_requested_feet, 0);

  if v_requested_feet > 0 then
    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_source.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count = 0 then
      select
        p.allocated_feet,
        p.covered_feet,
        p.remaining_covered_feet
      into
        v_source_suggested,
        v_source_suggested_covered,
        v_remaining
      from app_api.plan_allocation_coverage(
        v_remaining,
        v_source.feet_available,
        v_source.width_in,
        v_requested_width_in
      ) p;
    end if;
  end if;

  if v_source_suggested > 0 then
    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_source,
      v_job_context,
      v_source_suggested,
      v_source_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    v_source.feet_available := greatest(v_source.feet_available - v_source_suggested, 0);
    v_source := app_api.save_box(v_source);
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end if;

  for v_candidate in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id <> v_source.box_id
      and b.status = 'IN_STOCK'
      and b.feet_available > 0
      and case
        when v_requirement_id is not null then app_api.requirement_film_is_compatible(
          p_org_id,
          b.manufacturer,
          b.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        )
        else app_api.normalize_requirement_film_key(p_org_id, b.manufacturer, b.film_name) = v_source_film_key
      end
      and b.width_in >= v_requested_width_in
      and (v_cross_warehouse or b.warehouse = v_source.warehouse)
    order by
      case
        when b.width_in = v_requested_width_in then 0
        when app_api.allocation_coverage_multiplier(b.width_in, v_requested_width_in) > 1 then 1
        else 2
      end,
      (b.width_in - v_requested_width_in),
      case
        when v_requirement_id is not null
          and not v_requirement_is_exterior
          and app_api.requirement_film_is_exterior(p_org_id, b.manufacturer, b.film_name)
        then 1
        else 0
      end,
      coalesce(b.received_date, b.order_date, '9999-12-31'::date),
      b.box_id
    for update
  loop
    exit when v_remaining <= 0;

    if coalesce(array_length(v_selected_box_ids, 1), 0) > 0 and array_position(v_selected_box_ids, v_candidate.box_id) is null then
      continue;
    end if;

    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_candidate.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count > 0 then
      continue;
    end if;

    select
      p.allocated_feet,
      p.covered_feet,
      p.remaining_covered_feet
    into
      v_candidate_suggested,
      v_candidate_suggested_covered,
      v_remaining
    from app_api.plan_allocation_coverage(
      v_remaining,
      v_candidate.feet_available,
      v_candidate.width_in,
      v_requested_width_in
    ) p;

    if v_candidate_suggested <= 0 or v_candidate_suggested_covered <= 0 then
      continue;
    end if;

    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_candidate,
      v_job_context,
      v_candidate_suggested,
      v_candidate_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    v_candidate.feet_available := greatest(v_candidate.feet_available - v_allocation.allocated_feet, 0);
    perform app_api.save_box(v_candidate);
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end loop;

  if coalesce(jsonb_typeof(v_extra_allocations), '') = 'array' then
    for v_extra_entry in
      select value
      from jsonb_array_elements(v_extra_allocations)
    loop
      if coalesce(jsonb_typeof(v_extra_entry), '') <> 'object' then
        perform app_api.raise_http(400, 'Each extra allocation entry must be an object.');
      end if;

      v_extra_box_id := app_api.require_text(v_extra_entry->>'boxId', 'extraAllocations[].boxId');
      v_extra_feet := floor(nullif(app_api.trim_text(v_extra_entry->>'allocatedFeet'), '')::numeric);

      if v_extra_feet is null or v_extra_feet <= 0 then
        perform app_api.raise_http(400, format('Extra allocation for box %s must be greater than zero.', v_extra_box_id));
      end if;

      if array_position(v_extra_processed_box_ids, v_extra_box_id) is not null then
        perform app_api.raise_http(400, format('Duplicate extra allocation entry for box %s.', v_extra_box_id));
      end if;

      select *
      into v_candidate
      from app.boxes b
      where b.org_id = p_org_id
        and b.box_id = v_extra_box_id
      for update;

      if not found then
        perform app_api.raise_http(404, format('Box not found: %s', v_extra_box_id));
      end if;

      if v_candidate.status <> 'IN_STOCK' then
        perform app_api.raise_http(400, format('Box %s is no longer allocatable.', v_candidate.box_id));
      end if;

      if v_requirement_id is not null then
        if not app_api.requirement_film_is_compatible(
          p_org_id,
          v_candidate.manufacturer,
          v_candidate.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        ) or v_candidate.width_in < v_requested_width_in then
          perform app_api.raise_http(
            400,
            format(
              'Extra box %s must use a compatible film and meet the requested width for this allocation.',
              v_candidate.box_id
            )
          );
        end if;
      elsif app_api.normalize_requirement_film_key(p_org_id, v_candidate.manufacturer, v_candidate.film_name) <> v_source_film_key
        or v_candidate.width_in < v_requested_width_in then
        perform app_api.raise_http(
          400,
          format(
            'Extra box %s must match film and meet the requested width for this allocation.',
            v_candidate.box_id
          )
        );
      end if;

      if v_candidate.feet_available < v_extra_feet then
        perform app_api.raise_http(400, format('Box %s no longer has enough available LF.', v_candidate.box_id));
      end if;

      v_allocation := app_api.create_allocation(
        p_org_id,
        v_candidate,
        v_job_context,
        v_extra_feet,
        p_actor,
        '',
        'EXTRA',
        null
      );
      v_candidate.feet_available := greatest(v_candidate.feet_available - v_extra_feet, 0);
      perform app_api.save_box(v_candidate);
      v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
      v_extra_processed_box_ids := array_append(v_extra_processed_box_ids, v_extra_box_id);
    end loop;
  end if;

  if v_requested_feet = 0 and coalesce(array_length(v_extra_processed_box_ids, 1), 0) = 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be greater than zero unless extraAllocations are provided.');
  end if;

  if v_remaining > 0 then
    if app_api.trim_text(p_payload->>'jobWarehouse') <> '' then
      v_job_warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'jobWarehouse', 'Job warehouse');
    else
      v_job_warehouse := v_source.warehouse;
    end if;

    v_film_order.id := gen_random_uuid();
    v_film_order.org_id := p_org_id;
    v_film_order.film_order_id := app_api.create_log_id();
    v_film_order.job_id := app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber');
    v_film_order.job_number := v_job_context->>'jobNumber';
    v_film_order.warehouse := v_job_warehouse;
    v_film_order.manufacturer := coalesce(v_requirement.manufacturer, v_source.manufacturer);
    v_film_order.film_name := coalesce(v_requirement.film_name, v_source.film_name);
    v_film_order.width_in := v_requested_width_in;
    v_film_order.requested_feet := v_remaining;
    v_film_order.covered_feet := 0;
    v_film_order.ordered_feet := 0;
    v_film_order.remaining_to_order_feet := v_remaining;
    v_film_order.job_date := nullif(v_job_context->>'jobDate', '')::date;
    v_film_order.crew_leader := coalesce(v_job_context->>'crewLeader', '');
    v_film_order.status := 'FILM_ORDER';
    v_film_order.source_box_id := v_source.box_id;
    v_film_order.resolved_at := null;
    v_film_order.resolved_by := '';
    v_film_order.notes := format('Created from a shortage while trying to allocate %s LF.', v_requested_feet);
    v_film_order.created_at := now();
    v_film_order.created_by := app_api.trim_text(p_actor);
    v_film_order := app_api.save_film_order(v_film_order);
    v_warnings := app_api.push_warning(
      v_warnings,
      format('Film Order %s was created for the remaining %s LF.', v_film_order.film_order_id, v_remaining)
    );
  end if;

  return jsonb_build_object(
    'allocationIds', to_jsonb(v_allocation_ids),
    'filmOrderId', coalesce(v_film_order.film_order_id, ''),
    'remainingUncoveredFeet', greatest(v_remaining, 0),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

-- Preserve the descriptive Security/Madico Safetyshield Silver 20 label as its
-- own catalog entry and stop collapsing it through a legacy alias.

delete from app.film_name_aliases
where manufacturer_lookup_key = app_api.normalize_catalog_lookup_key('Security')
  and old_film_name_lookup_key = app_api.normalize_catalog_lookup_key('Madico Safetyshield 800 Silver 20')
  and app_api.normalize_catalog_lookup_key(canonical_film_name)
    = app_api.normalize_catalog_lookup_key('Madico Safetyshield 800');

with target_orgs as (
  select distinct b.org_id
  from app.boxes b
  where app_api.normalize_catalog_lookup_key(b.manufacturer) = app_api.normalize_catalog_lookup_key('Security')
    and (
      coalesce(b.notes, '') ilike '%Madico Safetyshield 800 Silver 20%'
      or app_api.normalize_catalog_lookup_key(b.film_name)
        = app_api.normalize_catalog_lookup_key('Madico Safetyshield 800')
    )

  union

  select distinct c.org_id
  from app.film_catalog c
  where app_api.normalize_catalog_lookup_key(c.manufacturer) = app_api.normalize_catalog_lookup_key('Security')
    and app_api.normalize_catalog_lookup_key(c.film_name)
      = app_api.normalize_catalog_lookup_key('Madico Safetyshield 800')

  union

  select distinct a.org_id
  from app.film_name_aliases a
  where a.manufacturer_lookup_key = app_api.normalize_catalog_lookup_key('Security')
    and a.old_film_name_lookup_key = app_api.normalize_catalog_lookup_key('Madico Safetyshield 800 Silver 20')
)
insert into app.film_catalog (
  org_id,
  film_key,
  manufacturer,
  film_name,
  source_width_in,
  source_initial_feet,
  source_initial_weight_lbs,
  source_box_id,
  notes,
  updated_at
)
select
  target_orgs.org_id,
  upper('Security') || '|' || upper('Madico Safetyshield 800 Silver 20'),
  'Security',
  'Madico Safetyshield 800 Silver 20',
  null,
  null,
  null,
  null,
  'Added by migration to preserve the descriptive Security/Madico Safetyshield 800 Silver 20 label as a distinct suggestion.',
  now()
from target_orgs
on conflict (org_id, film_key) do update
set
  manufacturer = excluded.manufacturer,
  film_name = excluded.film_name,
  updated_at = now();

create or replace function public.api_acl_boxes_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_lookup_box_id text;
  v_existing_status text := '';
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'write');
  v_lookup_box_id := app_api.resolve_box_id_alias(
    p_org_id,
    app_api.require_text(v_payload->>'boxId', 'BoxID')
  );

  select upper(btrim(b.status::text))
  into v_existing_status
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = v_lookup_box_id;

  if v_existing_status = 'TRANSFER' then
    perform app_api.raise_http(
      400,
      format(
        'Box %s has a pending transfer and can only be received or have the transfer cancelled.',
        v_lookup_box_id
      )
    );
  end if;

  v_payload := jsonb_set(v_payload, '{boxId}', to_jsonb(v_lookup_box_id), true);
  return public.api_boxes_update(p_org_id, p_actor, v_payload);
end;
$$;

