-- Reassert checkout and zeroed-edit guardrails after wrapper drift.

create or replace function app_api.resolve_allocations_for_checkout(
  p_org_id uuid,
  p_box_id text,
  p_job_number text,
  p_actor text
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_entry app.allocations;
  v_fulfilled_count integer := 0;
  v_fulfilled_feet integer := 0;
  v_other_jobs text[] := array[]::text[];
  v_checkout_note text := format('Checked out for job %s.', app_api.trim_text(p_job_number));
begin
  for v_entry in
    select *
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = app_api.trim_text(p_box_id)
      and a.status = 'ACTIVE'
    for update
  loop
    if upper(v_entry.job_number) = upper(app_api.trim_text(p_job_number)) then
      if v_entry.resolved_at is null then
        v_entry.resolved_at := now();
      end if;

      if coalesce(v_entry.resolved_by, '') = '' then
        v_entry.resolved_by := app_api.trim_text(p_actor);
      end if;

      if coalesce(v_entry.notes, '') <> v_checkout_note then
        v_entry.notes := v_checkout_note;
      end if;

      perform app_api.save_allocation(v_entry);
      v_fulfilled_count := v_fulfilled_count + 1;
      v_fulfilled_feet := v_fulfilled_feet + v_entry.allocated_feet;
    elsif array_position(v_other_jobs, v_entry.job_number) is null then
      v_other_jobs := array_append(v_other_jobs, v_entry.job_number);
    end if;
  end loop;

  return jsonb_build_object(
    'fulfilledCount', v_fulfilled_count,
    'fulfilledFeet', v_fulfilled_feet,
    'otherJobs', to_jsonb(v_other_jobs)
  );
end;
$$;

create or replace function app_api.reactivate_fulfilled_allocations_for_undo(
  p_org_id uuid,
  p_box_id text,
  p_job_number text
)
returns integer
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_entry app.allocations;
  v_count integer := 0;
  v_checkout_note text := format('Checked out for job %s.', app_api.trim_text(p_job_number));
  v_legacy_checkout_note text := format('Fulfilled by checkout for job %s.', app_api.trim_text(p_job_number));
begin
  for v_entry in
    select *
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = app_api.trim_text(p_box_id)
      and a.status in ('ACTIVE', 'FULFILLED')
      and upper(a.job_number) = upper(app_api.trim_text(p_job_number))
      and a.notes in (v_checkout_note, v_legacy_checkout_note)
    for update
  loop
    v_entry.status := 'ACTIVE';
    v_entry.resolved_at := null;
    v_entry.resolved_by := '';
    v_entry.notes := '';
    perform app_api.save_allocation(v_entry);
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;

create or replace function public.api_boxes_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_build jsonb;
  v_box app.boxes;
  v_public_before jsonb;
  v_public_after jsonb;
  v_receipt_result jsonb;
  v_log_id text;
  v_warnings text[] := array[]::text[];
  v_move_to_zeroed boolean := coalesce((p_payload->>'moveToZeroed')::boolean, false);
  v_reactivate_from_zeroed boolean := coalesce((p_payload->>'reactivateFromZeroed')::boolean, false);
  v_has_submitted_current_feet_on_roll boolean := coalesce(p_payload, '{}'::jsonb) ? 'currentFeetOnRoll';
  v_current_feet_on_roll_input integer;
  v_requested_feet_available integer;
  v_confirmed_zero_feet_move boolean := false;
  v_confirmed_zero_weight_move boolean := false;
  v_confirmed_incomplete_history_move boolean := false;
  v_has_positive_reactivation_signal boolean := false;
  v_should_reactivate boolean := false;
  v_audit_action text := 'UPDATE_BOX';
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  v_build := app_api.build_box_from_payload(p_org_id, p_payload, v_existing.box_id);
  v_box := jsonb_populate_record(null::app.boxes, v_build->'box');
  v_warnings := coalesce(array(select jsonb_array_elements_text(v_build->'warnings')), array[]::text[]);

  if v_has_submitted_current_feet_on_roll and app_api.trim_text(p_payload->>'currentFeetOnRoll') <> '' then
    v_current_feet_on_roll_input := floor((app_api.trim_text(p_payload->>'currentFeetOnRoll'))::numeric);
  else
    v_current_feet_on_roll_input := null;
  end if;

  v_requested_feet_available := case
    when app_api.trim_text(p_payload->>'feetAvailable') = '' then null
    else floor((app_api.trim_text(p_payload->>'feetAvailable'))::numeric)
  end;

  if v_existing.status = 'ZEROED' then
    v_has_positive_reactivation_signal :=
      coalesce(v_box.feet_available, 0) > 0
      or coalesce(v_box.last_roll_weight_lbs, 0) > 0;

    if v_has_positive_reactivation_signal and not v_reactivate_from_zeroed then
      perform app_api.raise_http(
        400,
        'Zeroed boxes with new active inventory values must be confirmed before moving back to IN_STOCK.'
      );
    end if;

    v_should_reactivate := v_has_positive_reactivation_signal and v_reactivate_from_zeroed;

    if v_should_reactivate then
      v_box.status := 'IN_STOCK';
      v_box.zeroed_date := null;
      v_box.zeroed_reason := '';
      v_box.zeroed_by := '';
      v_warnings := app_api.push_warning(
        v_warnings,
        format('Box %s was moved back to active IN_STOCK inventory.', v_box.box_id)
      );
      v_audit_action := 'SET_STATUS';
    else
      v_box.status := 'ZEROED';
      v_box.zeroed_date := v_existing.zeroed_date;
      v_box.zeroed_reason := coalesce(v_existing.zeroed_reason, '');
      v_box.zeroed_by := coalesce(v_existing.zeroed_by, '');
    end if;

    v_box := app_api.save_box(v_box);
    v_public_before := app_api.public_box_json(v_existing);
    v_public_after := app_api.public_box_json(v_box);
    v_log_id := app_api.append_audit_entry(
      p_org_id,
      v_audit_action,
      v_box.box_id,
      v_public_before,
      v_public_after,
      p_actor,
      app_api.trim_text(p_payload->>'auditNote')
    );

    return jsonb_build_object(
      'boxId', v_box.box_id,
      'logId', v_log_id,
      'warnings', to_jsonb(v_warnings)
    );
  end if;

  v_confirmed_zero_feet_move :=
    v_move_to_zeroed
    and v_existing.received_date is not null
    and app_api.has_positive_physical_feet(v_existing)
    and (
      (
        v_has_submitted_current_feet_on_roll
        and v_current_feet_on_roll_input is not null
        and v_current_feet_on_roll_input <= 0
      )
      or (
        not v_has_submitted_current_feet_on_roll
        and v_requested_feet_available is not null
        and v_requested_feet_available <= 0
      )
    );

  if v_confirmed_zero_feet_move then
    v_box.feet_available := 0;
  end if;

  v_confirmed_zero_weight_move :=
    v_move_to_zeroed
    and v_existing.received_date is not null
    and app_api.has_positive_physical_feet(v_existing)
    and coalesce(v_box.last_roll_weight_lbs, 0) = 0;

  v_confirmed_incomplete_history_move :=
    v_move_to_zeroed
    and coalesce(v_box.last_roll_weight_lbs, 0) = 0
    and (
      v_existing.received_date is null
      or v_existing.initial_weight_lbs is null
      or v_existing.core_weight_lbs is null
      or v_existing.last_weighed_date is null
      or v_box.received_date is null
      or v_box.initial_weight_lbs is null
      or v_box.core_weight_lbs is null
      or v_box.last_weighed_date is null
    );

  if v_move_to_zeroed and not (
    v_confirmed_incomplete_history_move
    or v_confirmed_zero_feet_move
    or v_confirmed_zero_weight_move
  ) then
    perform app_api.raise_http(
      400,
      'Received boxes move to zeroed out inventory only after they have had Available Feet above 0 and then reach 0 Available Feet or 0 Last Roll Weight.'
    );
  end if;

  if v_confirmed_incomplete_history_move or v_confirmed_zero_feet_move or v_confirmed_zero_weight_move then
    v_box.status := 'ZEROED';
    v_box.feet_available := 0;
    v_box.zeroed_date := app_api.today_date();
    v_box.zeroed_reason := app_api.determine_zeroed_reason(v_box.feet_available, v_box.last_roll_weight_lbs);
    v_box.zeroed_by := app_api.trim_text(p_actor);
    if app_api.trim_text(p_payload->>'auditNote') <> '' then
      v_box.zeroed_reason := v_box.zeroed_reason || ' Additional note: ' || app_api.normalize_meaningful_zeroed_note(p_payload->>'auditNote');
    end if;
    perform app_api.cancel_active_allocations_for_box(
      p_org_id,
      v_box.box_id,
      p_actor,
      'Auto-cancelled because the box was moved to zeroed out inventory.'
    );
    if v_confirmed_incomplete_history_move then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was moved to zeroed out inventory after confirming a 0 Last Roll Weight save on a box with incomplete history.'
      );
    elsif v_confirmed_zero_feet_move then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was moved to zeroed out inventory after confirming a Current Linear Feet value of 0 on a received box with recorded physical feet.'
      );
    elsif v_confirmed_zero_weight_move then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was moved to zeroed out inventory after confirming a Last Roll Weight value of 0 on a received box with recorded physical feet.'
      );
    end if;
    v_audit_action := 'ZERO_OUT_BOX';
  else
    v_receipt_result := app_api.process_linked_box_receipt(p_org_id, v_box, p_actor);
    v_box := jsonb_populate_record(null::app.boxes, v_receipt_result->'box');
    v_warnings := array_cat(
      v_warnings,
      coalesce(array(select jsonb_array_elements_text(v_receipt_result->'warnings')), array[]::text[])
    );
  end if;

  v_box := app_api.save_box(v_box);
  v_public_before := app_api.public_box_json(v_existing);
  v_public_after := app_api.public_box_json(v_box);
  v_log_id := app_api.append_audit_entry(
    p_org_id,
    v_audit_action,
    v_box.box_id,
    v_public_before,
    v_public_after,
    p_actor,
    app_api.trim_text(p_payload->>'auditNote')
  );

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function public.api_boxes_set_status(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_box app.boxes;
  v_status text := upper(app_api.require_text(p_payload->>'status', 'Status'));
  v_log_id text;
  v_public_before jsonb;
  v_public_after jsonb;
  v_warnings text[] := array[]::text[];
  v_checkout_job text;
  v_resolution jsonb;
  v_physical_feet integer;
  v_active_allocated_feet integer := 0;
  v_checkout_audit app.audit_log;
  v_checkout_user text := '';
  v_checkout_date text := '';
  v_weight_delta numeric;
begin
  perform app_api.require_org_member(p_org_id);

  if v_status not in ('IN_STOCK', 'CHECKED_OUT') then
    perform app_api.raise_http(400, 'Status must be IN_STOCK or CHECKED_OUT.');
  end if;

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_existing.received_date is null then
    perform app_api.raise_http(400, 'Add a ReceivedDate on or before today before changing status.');
  end if;

  if v_existing.status in ('ZEROED', 'RETIRED') then
    perform app_api.raise_http(400, 'This box cannot change status directly. Use audit undo instead.');
  end if;

  v_box := v_existing;
  v_public_before := app_api.public_box_json(v_existing);

  if v_status = 'CHECKED_OUT' then
    v_checkout_job := app_api.parse_checkout_job_from_note(p_payload->>'auditNote');
    if v_checkout_job = '' then
      perform app_api.raise_http(400, 'A checkout job number is required.');
    end if;

    v_box.status := 'CHECKED_OUT';
    v_box.has_ever_been_checked_out := true;
    v_box.last_checkout_job := v_checkout_job;
    v_box.last_checkout_date := app_api.today_date();
    v_box.zeroed_date := null;
    v_box.zeroed_reason := '';
    v_box.zeroed_by := '';

    v_resolution := app_api.resolve_allocations_for_checkout(p_org_id, v_box.box_id, v_checkout_job, p_actor);
    if coalesce((v_resolution->>'fulfilledCount')::integer, 0) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Kept %s allocation%s totaling %s LF linked to job %s after checkout.',
          (v_resolution->>'fulfilledCount')::integer,
          case when (v_resolution->>'fulfilledCount')::integer = 1 then '' else 's' end,
          (v_resolution->>'fulfilledFeet')::integer,
          v_checkout_job
        )
      );
    end if;

    if jsonb_array_length(coalesce(v_resolution->'otherJobs', '[]'::jsonb)) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'This box still has active allocations for ' ||
          array_to_string(array(select jsonb_array_elements_text(v_resolution->'otherJobs')), ', ') || '.'
      );
    end if;
  else
    v_box.status := 'IN_STOCK';
    v_box.last_roll_weight_lbs := nullif(app_api.trim_text(p_payload->>'lastRollWeightLbs'), '')::numeric;
    if v_box.last_roll_weight_lbs is null then
      perform app_api.raise_http(400, 'LastRollWeightLbs is required.');
    end if;

    v_box.last_weighed_date := app_api.today_date();

    if v_box.core_weight_lbs is not null and v_box.lf_weight_lbs_per_ft is not null and v_box.lf_weight_lbs_per_ft > 0 then
      v_physical_feet := app_api.derive_feet_available_from_roll_weight(
        v_box.last_roll_weight_lbs,
        v_box.core_weight_lbs,
        v_box.lf_weight_lbs_per_ft,
        v_box.initial_feet
      );
    else
      v_physical_feet := v_box.feet_available;
      v_warnings := app_api.push_warning(
        v_warnings,
        'Available Feet could not be recalculated because this box is missing core or LF weight metadata.'
      );
    end if;

    select coalesce(sum(a.allocated_feet), 0)::integer
    into v_active_allocated_feet
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_box.box_id
      and a.status = 'ACTIVE';

    v_box.feet_available := greatest(v_physical_feet - v_active_allocated_feet, 0);

    select *
    into v_checkout_audit
    from app.audit_log a
    where a.org_id = p_org_id
      and a.box_id = v_box.box_id
      and a.action = 'SET_STATUS'
      and coalesce(a.after_state->>'status', '') = 'CHECKED_OUT'
    order by a.created_at desc, a.log_id desc
    limit 1;

    v_checkout_user := coalesce(v_checkout_audit.actor, '');
    v_checkout_date := coalesce(substr(v_checkout_audit.created_at::text, 1, 10), '');
    v_checkout_job := coalesce(nullif(v_box.last_checkout_job, ''), app_api.parse_checkout_job_from_note(v_checkout_audit.notes));

    if v_checkout_job = '' then
      v_checkout_job := 'UNKNOWN';
      v_warnings := app_api.push_warning(
        v_warnings,
        'Roll history was logged with UNKNOWN job number because no checkout job was saved.'
      );
    end if;

    v_weight_delta := case
      when v_existing.last_roll_weight_lbs is null then null
      else round(v_existing.last_roll_weight_lbs - v_box.last_roll_weight_lbs, 2)
    end;

    perform app_api.append_roll_history_entry(
      p_org_id,
      row(
        gen_random_uuid(),
        p_org_id,
        app_api.create_log_id(),
        v_box.box_id,
        v_box.warehouse,
        v_box.manufacturer,
        v_box.film_name,
        v_box.width_in,
        v_checkout_job,
        coalesce(nullif(v_checkout_date, '')::timestamptz, now()),
        v_checkout_user,
        v_existing.last_roll_weight_lbs,
        now(),
        app_api.trim_text(p_actor),
        v_box.last_roll_weight_lbs,
        v_weight_delta,
        v_existing.feet_available,
        v_box.feet_available,
        app_api.trim_text(p_payload->>'auditNote')
      )::app.roll_weight_log
    );

    v_box.last_checkout_job := '';
    v_box.last_checkout_date := null;

    if app_api.has_positive_physical_feet(v_existing)
      and (v_box.feet_available = 0 or coalesce(v_box.last_roll_weight_lbs, 0) = 0) then
      v_box.status := 'ZEROED';
      v_box.feet_available := 0;
      v_box.zeroed_date := app_api.today_date();
      v_box.zeroed_reason := app_api.determine_zeroed_reason(v_box.feet_available, v_box.last_roll_weight_lbs);
      v_box.zeroed_by := app_api.trim_text(p_actor);
      perform app_api.cancel_active_allocations_for_box(
        p_org_id,
        v_box.box_id,
        p_actor,
        'Auto-cancelled because the box was moved to zeroed out inventory.'
      );
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was automatically moved to zeroed out inventory because Available Feet or Last Roll Weight reached 0.'
      );
    end if;
  end if;

  v_box := app_api.save_box(v_box);
  v_public_after := app_api.public_box_json(v_box);
  v_log_id := app_api.append_audit_entry(
    p_org_id,
    case when v_box.status = 'ZEROED' then 'ZERO_OUT_BOX' else 'SET_STATUS' end,
    v_box.box_id,
    v_public_before,
    v_public_after,
    p_actor,
    app_api.trim_text(p_payload->>'auditNote')
  );

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function public.api_acl_boxes_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_lookup_box_id text;
  v_existing_status text := '';
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'write');
  v_lookup_box_id := app_api.resolve_box_id_alias(
    p_org_id,
    app_api.require_text(v_payload->>'boxId', 'BoxID')
  );

  select upper(btrim(b.status::text))
  into v_existing_status
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = v_lookup_box_id;

  if v_existing_status = 'TRANSFER' then
    perform app_api.raise_http(
      400,
      format(
        'Box %s has a pending transfer and can only be received or have the transfer cancelled.',
        v_lookup_box_id
      )
    );
  end if;

  v_payload := jsonb_set(v_payload, '{boxId}', to_jsonb(v_lookup_box_id), true);
  return public.api_boxes_update(p_org_id, p_actor, v_payload);
end;
$$;

create or replace function public.api_acl_boxes_set_status(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_lookup_box_id text;
  v_existing_status text := '';
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'write');
  v_lookup_box_id := app_api.resolve_box_id_alias(
    p_org_id,
    app_api.require_text(v_payload->>'boxId', 'BoxID')
  );

  select upper(btrim(b.status::text))
  into v_existing_status
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = v_lookup_box_id;

  if v_existing_status = 'TRANSFER' then
    perform app_api.raise_http(
      400,
      format(
        'Box %s has a pending transfer and can only be received or have the transfer cancelled.',
        v_lookup_box_id
      )
    );
  end if;

  v_payload := jsonb_set(v_payload, '{boxId}', to_jsonb(v_lookup_box_id), true);
  return public.api_boxes_set_status(p_org_id, p_actor, v_payload);
end;
$$;

-- Reassert covered-feet persistence helpers after live function drift and
-- repair persisted allocation rows that were saved with covered_feet = 0.

create or replace function app_api.save_allocation(p_allocation app.allocations)
returns app.allocations
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_row app.allocations;
begin
  insert into app.allocations (
    id,
    org_id,
    allocation_id,
    box_id,
    job_id,
    job_number,
    warehouse,
    job_date,
    allocated_feet,
    covered_feet,
    requirement_id,
    status,
    created_at,
    created_by,
    resolved_at,
    resolved_by,
    notes,
    crew_leader,
    film_order_id,
    allocation_kind
  )
  values (
    coalesce(p_allocation.id, gen_random_uuid()),
    p_allocation.org_id,
    p_allocation.allocation_id,
    p_allocation.box_id,
    p_allocation.job_id,
    p_allocation.job_number,
    p_allocation.warehouse,
    p_allocation.job_date,
    p_allocation.allocated_feet,
    coalesce(p_allocation.covered_feet, p_allocation.allocated_feet),
    p_allocation.requirement_id,
    p_allocation.status,
    coalesce(p_allocation.created_at, now()),
    coalesce(p_allocation.created_by, ''),
    p_allocation.resolved_at,
    coalesce(p_allocation.resolved_by, ''),
    coalesce(p_allocation.notes, ''),
    coalesce(p_allocation.crew_leader, ''),
    coalesce(p_allocation.film_order_id, ''),
    coalesce(p_allocation.allocation_kind, 'REQUIREMENT'::app.allocation_kind)
  )
  on conflict (org_id, allocation_id) do update set
    box_id = excluded.box_id,
    job_id = excluded.job_id,
    job_number = excluded.job_number,
    warehouse = excluded.warehouse,
    job_date = excluded.job_date,
    allocated_feet = excluded.allocated_feet,
    covered_feet = excluded.covered_feet,
    requirement_id = excluded.requirement_id,
    status = excluded.status,
    created_at = excluded.created_at,
    created_by = excluded.created_by,
    resolved_at = excluded.resolved_at,
    resolved_by = excluded.resolved_by,
    notes = excluded.notes,
    crew_leader = excluded.crew_leader,
    film_order_id = excluded.film_order_id,
    allocation_kind = excluded.allocation_kind
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function app_api.public_allocation_json(p_entry app.allocations)
returns jsonb
language sql
stable
as $$
  select jsonb_build_object(
    'allocationId', coalesce(p_entry.allocation_id, ''),
    'boxId', coalesce(p_entry.box_id, ''),
    'warehouse', coalesce(p_entry.warehouse::text, ''),
    'jobNumber', coalesce(p_entry.job_number, ''),
    'jobDate', coalesce(to_char(p_entry.job_date, 'YYYY-MM-DD'), ''),
    'crewLeader', coalesce(p_entry.crew_leader, ''),
    'allocatedFeet', p_entry.allocated_feet,
    'coveredFeet', coalesce(p_entry.covered_feet, p_entry.allocated_feet),
    'requirementId', coalesce(p_entry.requirement_id::text, ''),
    'allocationKind', coalesce(p_entry.allocation_kind::text, 'REQUIREMENT'),
    'status', coalesce(p_entry.status::text, 'ACTIVE'),
    'createdAt', coalesce(to_char(p_entry.created_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), ''),
    'createdBy', coalesce(p_entry.created_by, ''),
    'resolvedAt', coalesce(to_char(p_entry.resolved_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), ''),
    'resolvedBy', coalesce(p_entry.resolved_by, ''),
    'filmOrderId', coalesce(p_entry.film_order_id, ''),
    'notes', coalesce(p_entry.notes, '')
  );
$$;

with covered_feet_backfill as (
  select
    a.id,
    case
      when a.requirement_id is not null
        and jr.id is not null
        and b.box_id is not null
        and b.width_in is not null
        and jr.width_in is not null
        and jr.required_feet is not null then
          greatest(
            app_api.compute_covered_feet_from_allocation(
              a.allocated_feet,
              b.width_in,
              jr.width_in,
              jr.required_feet
            ),
            0
          )
      else greatest(a.allocated_feet, 0)
    end as next_covered_feet
  from app.allocations a
  left join app.boxes b
    on b.org_id = a.org_id
   and b.box_id = a.box_id
  left join app.job_requirements jr
    on jr.org_id = a.org_id
   and jr.id = a.requirement_id
  where a.allocated_feet > 0
    and coalesce(a.covered_feet, 0) = 0
)
update app.allocations a
set covered_feet = covered_feet_backfill.next_covered_feet
from covered_feet_backfill
where a.id = covered_feet_backfill.id
  and a.allocated_feet > 0
  and coalesce(a.covered_feet, 0) = 0;

-- Ordered box allocation planning:
-- - expose derived planning capacity on box reads
-- - allow ORDERED boxes to participate in allocation planning without mutating on-hand feet
-- - block receipt/check-in saves when physical feet would drop below active allocations
-- - keep ordered boxes from regaining fake on-hand feet when job cancellations release allocations

create or replace function app_api.active_allocated_feet_for_box(
  p_org_id uuid,
  p_box_id text
)
returns integer
language sql
stable
security definer
set search_path = public, app, app_api
as $$
  select coalesce(sum(a.allocated_feet), 0)::integer
  from app.allocations a
  where a.org_id = p_org_id
    and a.box_id = app_api.trim_text(p_box_id)
    and a.status = 'ACTIVE';
$$;

create or replace function app_api.compute_allocation_planning_feet(
  p_status text,
  p_initial_feet integer,
  p_feet_available integer,
  p_active_allocated_feet integer
)
returns integer
language sql
immutable
as $$
  select
    case upper(coalesce(app_api.trim_text(p_status), ''))
      when 'IN_STOCK' then greatest(coalesce(p_feet_available, 0), 0)
      when 'ORDERED' then greatest(coalesce(p_initial_feet, 0) - coalesce(p_active_allocated_feet, 0), 0)
      else 0
    end;
$$;

create or replace function app_api.allocation_planning_feet_for_box(p_box app.boxes)
returns integer
language sql
stable
security definer
set search_path = public, app, app_api
as $$
  select app_api.compute_allocation_planning_feet(
    coalesce(p_box.status::text, ''),
    p_box.initial_feet,
    p_box.feet_available,
    app_api.active_allocated_feet_for_box(p_box.org_id, p_box.box_id)
  );
$$;

create or replace function app_api.next_feet_available_after_allocation_release(
  p_status text,
  p_feet_available integer,
  p_released_feet integer,
  p_initial_feet integer default null
)
returns integer
language sql
immutable
as $$
  select
    case upper(coalesce(app_api.trim_text(p_status), ''))
      when 'ZEROED' then greatest(coalesce(p_feet_available, 0), 0)
      when 'RETIRED' then greatest(coalesce(p_feet_available, 0), 0)
      when 'ORDERED' then greatest(coalesce(p_feet_available, 0), 0)
      else least(
        coalesce(p_initial_feet, greatest(coalesce(p_feet_available, 0) + coalesce(p_released_feet, 0), 0)),
        greatest(coalesce(p_feet_available, 0) + coalesce(p_released_feet, 0), 0)
      )
    end;
$$;

create or replace function app_api.public_box_json(p_box app.boxes)
returns jsonb
language sql
stable
as $$
  select jsonb_build_object(
    'boxId', coalesce(p_box.box_id, ''),
    'warehouse', coalesce(p_box.warehouse::text, ''),
    'manufacturer', coalesce(p_box.manufacturer, ''),
    'filmName', coalesce(p_box.film_name, ''),
    'widthIn', p_box.width_in,
    'initialFeet', p_box.initial_feet,
    'feetAvailable', p_box.feet_available,
    'allocationPlanningFeet', app_api.allocation_planning_feet_for_box(p_box),
    'lotRun', coalesce(p_box.lot_run, ''),
    'status', coalesce(p_box.status::text, 'ORDERED'),
    'orderDate', coalesce(to_char(p_box.order_date, 'YYYY-MM-DD'), ''),
    'receivedDate', coalesce(to_char(p_box.received_date, 'YYYY-MM-DD'), ''),
    'initialWeightLbs', p_box.initial_weight_lbs,
    'lastRollWeightLbs', p_box.last_roll_weight_lbs,
    'lastWeighedDate', coalesce(to_char(p_box.last_weighed_date, 'YYYY-MM-DD'), ''),
    'filmKey', upper(coalesce(p_box.film_key, '')),
    'coreType', coalesce(p_box.core_type, ''),
    'coreWeightLbs', p_box.core_weight_lbs,
    'lfWeightLbsPerFt', p_box.lf_weight_lbs_per_ft,
    'purchaseCost', p_box.purchase_cost,
    'pricePerLf', p_box.price_per_lf,
    'notes', coalesce(p_box.notes, ''),
    'hasEverBeenCheckedOut', p_box.has_ever_been_checked_out,
    'lastCheckoutJob', coalesce(p_box.last_checkout_job, ''),
    'lastCheckoutDate', coalesce(to_char(p_box.last_checkout_date, 'YYYY-MM-DD'), ''),
    'zeroedDate', coalesce(to_char(p_box.zeroed_date, 'YYYY-MM-DD'), ''),
    'zeroedReason', coalesce(p_box.zeroed_reason, ''),
    'zeroedBy', coalesce(p_box.zeroed_by, '')
  );
$$;

create or replace function app_api.public_box_read_json(p_box app.boxes)
returns jsonb
language sql
stable
security definer
set search_path = public, app, app_api
as $$
  select
    app_api.public_box_json(p_box)
    || jsonb_build_object(
      'activeAllocatedFeet',
      app_api.active_allocated_feet_for_box(p_box.org_id, p_box.box_id)
    );
$$;

create or replace function public.api_list_boxes(p_org_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_result jsonb;
begin
  perform app_api.require_org_member(p_org_id);

  select coalesce(
    jsonb_agg(app_api.public_box_read_json(b) order by b.box_id asc),
    '[]'::jsonb
  )
  into v_result
  from app.boxes b
  where b.org_id = p_org_id;

  return v_result;
end;
$$;

create or replace function public.api_find_box_by_id(p_org_id uuid, p_box_id text)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_result jsonb;
begin
  perform app_api.require_org_member(p_org_id);

  select app_api.public_box_read_json(b)
  into v_result
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.trim_text(p_box_id);

  return v_result;
end;
$$;

create or replace function app_api.build_box_from_payload(
  p_org_id uuid,
  p_payload jsonb,
  p_existing_box_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_box app.boxes;
  v_film_data app.film_catalog;
  v_warnings text[] := array[]::text[];
  v_box_id text;
  v_manufacturer text;
  v_film_name text;
  v_width_in numeric;
  v_initial_feet integer;
  v_order_date date;
  v_received_date date;
  v_feet_available_input text;
  v_feet_available integer;
  v_film_key text;
  v_initial_weight_input numeric;
  v_last_roll_weight_input numeric;
  v_last_weighed_date_input date;
  v_core_type_input text;
  v_current_feet_on_roll_input integer;
  v_existing_core_type text;
  v_resolved_initial_weight numeric;
  v_resolved_last_roll_weight numeric;
  v_resolved_last_weighed_date date;
  v_resolved_core_type text;
  v_resolved_core_weight numeric;
  v_resolved_lf_weight numeric;
  v_effective_sq_ft_weight numeric;
  v_effective_core_type text := '';
  v_seed_initial_weight numeric;
  v_active_allocated_feet integer := 0;
  v_is_first_receipt boolean := false;
  v_should_recalculate_received_feet boolean := false;
  v_should_repair_stale_feet boolean := false;
  v_resolved_warehouse text;
  v_physical_feet_available integer := 0;
  v_has_full_receiving_metrics boolean := false;
  v_use_partial_receiving_metrics boolean := false;
  v_has_price_per_lf boolean := coalesce(p_payload, '{}'::jsonb) ? 'pricePerLf';
  v_has_submitted_initial_weight boolean := coalesce(p_payload, '{}'::jsonb) ? 'initialWeightLbs';
  v_has_submitted_last_roll_weight boolean := coalesce(p_payload, '{}'::jsonb) ? 'lastRollWeightLbs';
  v_has_submitted_last_weighed_date boolean := coalesce(p_payload, '{}'::jsonb) ? 'lastWeighedDate';
  v_has_submitted_core_type boolean := coalesce(p_payload, '{}'::jsonb) ? 'coreType';
  v_has_submitted_current_feet_on_roll boolean := coalesce(p_payload, '{}'::jsonb) ? 'currentFeetOnRoll';
  v_reactivate_from_zeroed boolean := coalesce((p_payload->>'reactivateFromZeroed')::boolean, false);
begin
  if p_existing_box_id is not null then
    select *
    into v_existing
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id = app_api.trim_text(p_existing_box_id)
    for update;

    if not found then
      perform app_api.raise_http(404, 'Box not found.');
    end if;
  end if;

  v_box_id := coalesce(v_existing.box_id, app_api.require_text(p_payload->>'boxId', 'BoxID'));
  v_manufacturer := app_api.require_text(p_payload->>'manufacturer', 'Manufacturer');
  v_film_name := app_api.require_text(p_payload->>'filmName', 'FilmName');
  v_width_in := nullif(app_api.trim_text(p_payload->>'widthIn'), '')::numeric;
  v_initial_feet := floor(nullif(app_api.trim_text(p_payload->>'initialFeet'), '')::numeric);
  v_order_date := nullif(app_api.trim_text(p_payload->>'orderDate'), '')::date;
  v_received_date := nullif(app_api.trim_text(p_payload->>'receivedDate'), '')::date;
  v_feet_available_input := app_api.trim_text(p_payload->>'feetAvailable');
  v_film_key := upper(
    coalesce(
      nullif(app_api.trim_text(p_payload->>'filmKey'), ''),
      upper(v_manufacturer) || '|' || upper(v_film_name)
    )
  );
  v_initial_weight_input := nullif(app_api.trim_text(p_payload->>'initialWeightLbs'), '')::numeric;
  v_last_roll_weight_input := nullif(app_api.trim_text(p_payload->>'lastRollWeightLbs'), '')::numeric;
  v_last_weighed_date_input := nullif(app_api.trim_text(p_payload->>'lastWeighedDate'), '')::date;
  v_core_type_input := app_api.normalize_core_type(p_payload->>'coreType', true);
  v_existing_core_type := coalesce(app_api.normalize_core_type(v_existing.core_type, true), '');
  v_resolved_warehouse := app_api.resolve_warehouse_from_box_id(p_org_id, v_box_id);

  if v_has_submitted_current_feet_on_roll and app_api.trim_text(p_payload->>'currentFeetOnRoll') <> '' then
    v_current_feet_on_roll_input := floor((app_api.trim_text(p_payload->>'currentFeetOnRoll'))::numeric);
    if v_current_feet_on_roll_input < 0 then
      v_current_feet_on_roll_input := 0;
      v_warnings := app_api.push_warning(v_warnings, 'CurrentFeetOnRoll was clamped to 0.');
    end if;
  else
    v_current_feet_on_roll_input := null;
  end if;

  if v_width_in is null or v_width_in <= 0 then
    perform app_api.raise_http(400, 'WidthIn must be greater than zero.');
  end if;

  if v_initial_feet is null or v_initial_feet < 0 then
    perform app_api.raise_http(400, 'InitialFeet must be zero or greater.');
  end if;

  if v_order_date is null then
    perform app_api.raise_http(400, 'OrderDate is required.');
  end if;

  if v_existing.received_date is not null and v_received_date is null then
    perform app_api.raise_http(400, 'ReceivedDate cannot be cleared after a box has been received.');
  end if;

  if v_feet_available_input = '' then
    v_feet_available := coalesce(v_existing.feet_available, app_api.derive_add_feet_available(v_initial_feet, v_received_date));
  else
    v_feet_available := floor(v_feet_available_input::numeric);
    if v_feet_available < 0 then
      v_feet_available := 0;
      v_warnings := app_api.push_warning(v_warnings, 'FeetAvailable was clamped to 0.');
    end if;
  end if;

  v_resolved_initial_weight := v_initial_weight_input;
  v_resolved_last_roll_weight := v_last_roll_weight_input;
  v_resolved_last_weighed_date := v_last_weighed_date_input;
  v_resolved_core_type := coalesce(nullif(v_core_type_input, ''), v_existing_core_type, '');
  v_resolved_core_weight := v_existing.core_weight_lbs;
  v_resolved_lf_weight := v_existing.lf_weight_lbs_per_ft;

  if v_received_date is not null then
    if v_initial_feet <= 0 then
      perform app_api.raise_http(400, 'InitialFeet must be greater than zero for received boxes.');
    end if;

    select coalesce(sum(a.allocated_feet), 0)::integer
    into v_active_allocated_feet
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_box_id
      and a.status = 'ACTIVE';

    v_should_recalculate_received_feet :=
      p_existing_box_id is null
      or v_existing.received_date is null
      or v_existing.film_key is distinct from v_film_key
      or v_existing.width_in is distinct from v_width_in
      or v_existing.initial_feet is distinct from v_initial_feet
      or v_core_type_input is distinct from v_existing_core_type
      or v_initial_weight_input is distinct from v_existing.initial_weight_lbs;

    if v_should_recalculate_received_feet then
      select *
      into v_film_data
      from app.film_catalog f
      where f.org_id = p_org_id
        and f.film_key = v_film_key
      for update;

      if p_existing_box_id is not null and v_has_submitted_core_type and v_core_type_input = '' then
        v_effective_core_type := '';
      else
        v_effective_core_type := coalesce(
          nullif(v_core_type_input, ''),
          app_api.normalize_core_type(v_film_data.default_core_type, true),
          v_existing_core_type,
          ''
        );
      end if;

      if v_film_data.sq_ft_weight_lbs_per_sq_ft is not null then
        if v_effective_core_type = '' then
          if p_existing_box_id is null then
            perform app_api.raise_http(400, 'CoreType is required before this film can be received.');
          end if;
        else
          v_effective_sq_ft_weight := v_film_data.sq_ft_weight_lbs_per_sq_ft;
          v_resolved_core_type := v_effective_core_type;
          v_resolved_core_weight := app_api.derive_core_weight_lbs(v_effective_core_type, v_width_in);

          if v_initial_weight_input is not null then
            v_effective_sq_ft_weight := app_api.derive_sqft_weight_lbs_per_sqft(
              v_initial_weight_input,
              v_resolved_core_weight,
              v_width_in,
              v_initial_feet
            );
            v_resolved_initial_weight := round(v_initial_weight_input, 2);
            v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
          elsif p_existing_box_id is null or not v_has_submitted_initial_weight then
            v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
            v_resolved_initial_weight := app_api.derive_initial_weight_lbs(
              v_resolved_lf_weight,
              v_initial_feet,
              v_resolved_core_weight
            );
            if p_existing_box_id is null then
              v_warnings := app_api.push_warning(v_warnings, 'Initial and last roll weights were auto-filled from FILM DATA.');
            end if;
          end if;

          if v_resolved_last_roll_weight is null then
            if p_existing_box_id is not null and not v_has_submitted_last_roll_weight and v_existing.last_roll_weight_lbs is not null then
              v_resolved_last_roll_weight := v_existing.last_roll_weight_lbs;
            elsif p_existing_box_id is null and v_resolved_initial_weight is not null then
              v_resolved_last_roll_weight := v_resolved_initial_weight;
            end if;
          end if;

          if v_resolved_last_weighed_date is null then
            if p_existing_box_id is not null and not v_has_submitted_last_weighed_date and v_existing.last_weighed_date is not null then
              v_resolved_last_weighed_date := v_existing.last_weighed_date;
            elsif p_existing_box_id is null and v_resolved_last_roll_weight is not null then
              v_resolved_last_weighed_date := v_received_date;
            end if;
          end if;

          v_has_full_receiving_metrics :=
            v_resolved_initial_weight is not null
            and v_resolved_last_roll_weight is not null
            and v_resolved_core_weight is not null
            and v_resolved_lf_weight is not null
            and v_resolved_lf_weight > 0;

          if v_has_full_receiving_metrics and (coalesce(v_film_data.default_core_type, '') = '' or coalesce(v_film_data.default_core_type, '') <> v_effective_core_type) then
            perform app_api.save_film_catalog(
              p_org_id,
              v_film_key,
              coalesce(v_film_data.manufacturer, v_manufacturer),
              coalesce(v_film_data.film_name, v_film_name),
              v_effective_sq_ft_weight,
              v_effective_core_type,
              coalesce(v_film_data.source_width_in, v_width_in),
              coalesce(v_film_data.source_initial_feet, v_initial_feet),
              coalesce(v_film_data.source_initial_weight_lbs, v_resolved_initial_weight),
              coalesce(v_film_data.source_box_id, v_box_id),
              coalesce(v_film_data.notes, '')
            );
            v_warnings := app_api.push_warning(v_warnings, 'FILM DATA was updated with the selected core type.');
          end if;
        end if;
      else
        if p_existing_box_id is not null and v_has_submitted_initial_weight and v_initial_weight_input is null then
          v_seed_initial_weight := null;
        else
          v_seed_initial_weight := coalesce(v_initial_weight_input, v_existing.initial_weight_lbs);
        end if;

        if v_effective_core_type = '' then
          if p_existing_box_id is null then
            perform app_api.raise_http(400, 'CoreType is required the first time a received film is saved.');
          end if;
        elsif v_seed_initial_weight is null then
          if p_existing_box_id is null then
            perform app_api.raise_http(400, 'InitialWeightLbs is required the first time a received film is saved.');
          end if;
        else
          v_resolved_core_type := v_effective_core_type;
          v_resolved_core_weight := app_api.derive_core_weight_lbs(v_effective_core_type, v_width_in);
          v_effective_sq_ft_weight := app_api.derive_sqft_weight_lbs_per_sqft(
            v_seed_initial_weight,
            v_resolved_core_weight,
            v_width_in,
            v_initial_feet
          );
          v_resolved_lf_weight := app_api.derive_lf_weight_lbs_per_ft(v_effective_sq_ft_weight, v_width_in);
          v_resolved_initial_weight := round(v_seed_initial_weight, 2);

          if v_resolved_last_roll_weight is null then
            if p_existing_box_id is not null and not v_has_submitted_last_roll_weight and v_existing.last_roll_weight_lbs is not null then
              v_resolved_last_roll_weight := v_existing.last_roll_weight_lbs;
            elsif p_existing_box_id is null then
              v_resolved_last_roll_weight := v_resolved_initial_weight;
            end if;
          end if;

          if v_resolved_last_weighed_date is null then
            if p_existing_box_id is not null and not v_has_submitted_last_weighed_date and v_existing.last_weighed_date is not null then
              v_resolved_last_weighed_date := v_existing.last_weighed_date;
            elsif p_existing_box_id is null and v_resolved_last_roll_weight is not null then
              v_resolved_last_weighed_date := v_received_date;
            end if;
          end if;

          v_has_full_receiving_metrics :=
            v_resolved_initial_weight is not null
            and v_resolved_last_roll_weight is not null
            and v_resolved_core_weight is not null
            and v_resolved_lf_weight is not null
            and v_resolved_lf_weight > 0;

          if v_has_full_receiving_metrics then
            perform app_api.save_film_catalog(
              p_org_id,
              v_film_key,
              v_manufacturer,
              v_film_name,
              v_effective_sq_ft_weight,
              v_effective_core_type,
              v_width_in,
              v_initial_feet,
              v_resolved_initial_weight,
              v_box_id,
              coalesce(v_film_data.notes, '')
            );
            v_warnings := app_api.push_warning(v_warnings, format('FILM DATA was created from the first received weight for %s.', v_film_key));
          end if;
        end if;
      end if;
    else
      v_resolved_initial_weight := case
        when v_initial_weight_input is not null then v_initial_weight_input
        when p_existing_box_id is not null and not v_has_submitted_initial_weight then v_existing.initial_weight_lbs
        else null
      end;
      v_resolved_core_type := case
        when v_has_submitted_core_type then v_core_type_input
        else coalesce(nullif(v_core_type_input, ''), v_existing_core_type, '')
      end;
      v_resolved_core_weight := v_existing.core_weight_lbs;
      v_resolved_lf_weight := v_existing.lf_weight_lbs_per_ft;
      v_resolved_last_roll_weight := case
        when v_resolved_last_roll_weight is not null then v_resolved_last_roll_weight
        when p_existing_box_id is not null and not v_has_submitted_last_roll_weight then v_existing.last_roll_weight_lbs
        else null
      end;
      v_resolved_last_weighed_date := case
        when v_resolved_last_weighed_date is not null then v_resolved_last_weighed_date
        when p_existing_box_id is not null and not v_has_submitted_last_weighed_date then v_existing.last_weighed_date
        else null
      end;
    end if;

    if v_resolved_core_type <> '' and v_resolved_core_weight is null then
      v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_width_in);
    end if;

    if v_resolved_lf_weight is null then
      v_resolved_lf_weight := app_api.try_derive_lf_weight_lbs_per_ft(
        v_resolved_initial_weight,
        v_resolved_core_weight,
        v_width_in,
        v_initial_feet
      );
    end if;

    v_has_full_receiving_metrics :=
      v_resolved_initial_weight is not null
      and v_resolved_last_roll_weight is not null
      and v_resolved_core_weight is not null
      and v_resolved_lf_weight is not null
      and v_resolved_lf_weight > 0;

    if not v_has_full_receiving_metrics and p_existing_box_id is not null then
      v_use_partial_receiving_metrics := true;
      v_resolved_initial_weight := case
        when v_initial_weight_input is not null then v_initial_weight_input
        when not v_has_submitted_initial_weight then v_existing.initial_weight_lbs
        else null
      end;
      v_resolved_last_roll_weight := case
        when v_last_roll_weight_input is not null then v_last_roll_weight_input
        when not v_has_submitted_last_roll_weight then v_existing.last_roll_weight_lbs
        else null
      end;
      v_resolved_last_weighed_date := case
        when v_last_weighed_date_input is not null then v_last_weighed_date_input
        when not v_has_submitted_last_weighed_date then v_existing.last_weighed_date
        else null
      end;
      v_resolved_core_type := case
        when v_has_submitted_core_type then v_core_type_input
        else v_existing_core_type
      end;
      if v_resolved_core_type <> '' then
        v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_width_in);
      else
        v_resolved_core_weight := null;
      end if;
      v_resolved_lf_weight := app_api.try_derive_lf_weight_lbs_per_ft(
        v_resolved_initial_weight,
        v_resolved_core_weight,
        v_width_in,
        v_initial_feet
      );
    end if;

    if v_use_partial_receiving_metrics then
      if v_current_feet_on_roll_input is not null then
        if v_current_feet_on_roll_input < v_active_allocated_feet then
          perform app_api.raise_http(
            400,
            format(
              'CurrentFeetOnRoll cannot be lower than the box''s active allocated feet (%s).',
              v_active_allocated_feet
            )
          );
        end if;
        v_feet_available := app_api.clamp_feet_to_initial_range(
          v_current_feet_on_roll_input - v_active_allocated_feet,
          v_initial_feet
        );
      else
        v_feet_available := app_api.clamp_feet_to_initial_range(v_feet_available, v_initial_feet);
      end if;
    else
      if v_resolved_last_roll_weight is null then
        perform app_api.raise_http(
          400,
          'LastRollWeightLbs is required for received boxes because FeetAvailable is derived from roll weight.'
        );
      end if;

      if v_resolved_core_weight is null or v_resolved_lf_weight is null or v_resolved_lf_weight <= 0 then
        perform app_api.raise_http(
          400,
          'CoreWeightLbs and LfWeightLbsPerFt must be set for received boxes because FeetAvailable is derived from roll weight.'
        );
      end if;

      v_is_first_receipt := v_existing.received_date is null;
      v_should_recalculate_received_feet := app_api.should_recalculate_received_feet(
        v_existing,
        v_initial_feet,
        v_resolved_last_roll_weight,
        v_resolved_core_weight,
        v_resolved_lf_weight,
        v_reactivate_from_zeroed
      );
      v_physical_feet_available := app_api.derive_feet_available_from_roll_weight(
        v_resolved_last_roll_weight,
        v_resolved_core_weight,
        v_resolved_lf_weight,
        v_initial_feet
      );

      if v_physical_feet_available < v_active_allocated_feet then
        perform app_api.raise_http(
          400,
          format(
            'Received physical LF cannot be lower than the box''s active allocated feet (%s).',
            v_active_allocated_feet
          )
        );
      end if;

      v_should_repair_stale_feet :=
        v_existing.received_date is not null
        and coalesce(v_existing.feet_available, 0) <= 0
        and v_physical_feet_available > 0;

      if v_is_first_receipt then
        v_feet_available := greatest(v_initial_feet - v_active_allocated_feet, 0);
      elsif v_should_recalculate_received_feet or v_should_repair_stale_feet then
        v_feet_available := greatest(v_physical_feet_available - v_active_allocated_feet, 0);
      else
        v_feet_available := least(greatest(coalesce(v_existing.feet_available, v_feet_available), 0), v_initial_feet);
      end if;
    end if;
  else
    v_resolved_initial_weight := null;
    v_resolved_last_roll_weight := null;
    v_resolved_last_weighed_date := null;
    v_resolved_core_type := '';
    v_resolved_core_weight := null;
    v_resolved_lf_weight := null;
  end if;

  v_box.id := v_existing.id;
  v_box.org_id := p_org_id;
  v_box.box_id := v_box_id;
  v_box.warehouse := v_resolved_warehouse;
  v_box.manufacturer := v_manufacturer;
  v_box.film_name := v_film_name;
  v_box.width_in := v_width_in;
  v_box.initial_feet := v_initial_feet;
  v_box.feet_available := v_feet_available;
  v_box.lot_run := app_api.trim_text(p_payload->>'lotRun');
  v_box.status := case
    when v_existing.status in ('CHECKED_OUT', 'ZEROED', 'RETIRED') then v_existing.status
    else app_api.derive_lifecycle_status(v_received_date)
  end;
  v_box.order_date := v_order_date;
  v_box.received_date := v_received_date;
  v_box.initial_weight_lbs := v_resolved_initial_weight;
  v_box.last_roll_weight_lbs := v_resolved_last_roll_weight;
  v_box.last_weighed_date := v_resolved_last_weighed_date;
  v_box.film_key := v_film_key;
  v_box.core_type := v_resolved_core_type;
  v_box.core_weight_lbs := v_resolved_core_weight;
  v_box.lf_weight_lbs_per_ft := v_resolved_lf_weight;
  v_box.purchase_cost := nullif(app_api.trim_text(p_payload->>'purchaseCost'), '')::numeric;
  if v_box.purchase_cost is not null and v_box.purchase_cost < 0 then
    perform app_api.raise_http(400, 'PurchaseCost must be zero or greater.');
  end if;
  if v_box.purchase_cost is not null and v_initial_feet <= 0 then
    perform app_api.raise_http(400, 'PurchaseCost requires InitialFeet > 0 to derive PricePerLf.');
  end if;

  if v_box.purchase_cost is not null then
    v_box.price_per_lf := round(v_box.purchase_cost / v_initial_feet, 4);
  elsif v_has_price_per_lf then
    v_box.price_per_lf := nullif(app_api.trim_text(p_payload->>'pricePerLf'), '')::numeric;
    if v_box.price_per_lf is not null and v_box.price_per_lf < 0 then
      perform app_api.raise_http(400, 'PricePerLf must be zero or greater.');
    end if;
  else
    v_box.price_per_lf := v_existing.price_per_lf;
  end if;
  v_box.notes := app_api.trim_text(p_payload->>'notes');
  v_box.has_ever_been_checked_out := coalesce(v_existing.has_ever_been_checked_out, false);
  v_box.last_checkout_job := coalesce(v_existing.last_checkout_job, '');
  v_box.last_checkout_date := v_existing.last_checkout_date;
  v_box.zeroed_date := null;
  v_box.zeroed_reason := '';
  v_box.zeroed_by := '';

  return jsonb_build_object(
    'box', to_jsonb(v_box),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function public.api_boxes_set_status(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_box app.boxes;
  v_status text := upper(app_api.require_text(p_payload->>'status', 'Status'));
  v_log_id text;
  v_public_before jsonb;
  v_public_after jsonb;
  v_warnings text[] := array[]::text[];
  v_checkout_job text;
  v_resolution jsonb;
  v_physical_feet integer;
  v_active_allocated_feet integer := 0;
  v_checkout_audit app.audit_log;
  v_checkout_user text := '';
  v_checkout_date text := '';
  v_weight_delta numeric;
begin
  perform app_api.require_org_member(p_org_id);

  if v_status not in ('IN_STOCK', 'CHECKED_OUT') then
    perform app_api.raise_http(400, 'Status must be IN_STOCK or CHECKED_OUT.');
  end if;

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_existing.received_date is null then
    perform app_api.raise_http(400, 'Add a ReceivedDate on or before today before changing status.');
  end if;

  if v_existing.status in ('ZEROED', 'RETIRED') then
    perform app_api.raise_http(400, 'This box cannot change status directly. Use audit undo instead.');
  end if;

  v_box := v_existing;
  v_public_before := app_api.public_box_json(v_existing);

  if v_status = 'CHECKED_OUT' then
    v_checkout_job := app_api.parse_checkout_job_from_note(p_payload->>'auditNote');
    if v_checkout_job = '' then
      perform app_api.raise_http(400, 'A checkout job number is required.');
    end if;

    v_box.status := 'CHECKED_OUT';
    v_box.has_ever_been_checked_out := true;
    v_box.last_checkout_job := v_checkout_job;
    v_box.last_checkout_date := app_api.today_date();
    v_box.zeroed_date := null;
    v_box.zeroed_reason := '';
    v_box.zeroed_by := '';

    v_resolution := app_api.resolve_allocations_for_checkout(p_org_id, v_box.box_id, v_checkout_job, p_actor);
    if coalesce((v_resolution->>'fulfilledCount')::integer, 0) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Kept %s allocation%s totaling %s LF linked to job %s after checkout.',
          (v_resolution->>'fulfilledCount')::integer,
          case when (v_resolution->>'fulfilledCount')::integer = 1 then '' else 's' end,
          (v_resolution->>'fulfilledFeet')::integer,
          v_checkout_job
        )
      );
    end if;

    if jsonb_array_length(coalesce(v_resolution->'otherJobs', '[]'::jsonb)) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'This box still has active allocations for ' ||
          array_to_string(array(select jsonb_array_elements_text(v_resolution->'otherJobs')), ', ') || '.'
      );
    end if;
  else
    v_box.status := 'IN_STOCK';
    v_box.last_roll_weight_lbs := nullif(app_api.trim_text(p_payload->>'lastRollWeightLbs'), '')::numeric;
    if v_box.last_roll_weight_lbs is null then
      perform app_api.raise_http(400, 'LastRollWeightLbs is required.');
    end if;

    v_box.last_weighed_date := app_api.today_date();

    if v_box.core_weight_lbs is not null and v_box.lf_weight_lbs_per_ft is not null and v_box.lf_weight_lbs_per_ft > 0 then
      v_physical_feet := app_api.derive_feet_available_from_roll_weight(
        v_box.last_roll_weight_lbs,
        v_box.core_weight_lbs,
        v_box.lf_weight_lbs_per_ft,
        v_box.initial_feet
      );
    else
      v_physical_feet := v_box.feet_available;
      v_warnings := app_api.push_warning(
        v_warnings,
        'Available Feet could not be recalculated because this box is missing core or LF weight metadata.'
      );
    end if;

    select coalesce(sum(a.allocated_feet), 0)::integer
    into v_active_allocated_feet
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_box.box_id
      and a.status = 'ACTIVE';

    if v_active_allocated_feet > v_physical_feet then
      perform app_api.raise_http(
        400,
        format(
          'Received physical LF cannot be lower than the box''s active allocated feet (%s).',
          v_active_allocated_feet
        )
      );
    end if;

    v_box.feet_available := greatest(v_physical_feet - v_active_allocated_feet, 0);

    if v_active_allocated_feet > 0 and v_box.feet_available = 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'All remaining LF on this box is reserved by active allocations.'
      );
    end if;

    select *
    into v_checkout_audit
    from app.audit_log a
    where a.org_id = p_org_id
      and a.box_id = v_box.box_id
      and a.action = 'SET_STATUS'
      and coalesce(a.after_state->>'status', '') = 'CHECKED_OUT'
    order by a.created_at desc, a.log_id desc
    limit 1;

    v_checkout_user := coalesce(v_checkout_audit.actor, '');
    v_checkout_date := coalesce(substr(v_checkout_audit.created_at::text, 1, 10), '');
    v_checkout_job := coalesce(nullif(v_box.last_checkout_job, ''), app_api.parse_checkout_job_from_note(v_checkout_audit.notes));

    if v_checkout_job = '' then
      v_checkout_job := 'UNKNOWN';
      v_warnings := app_api.push_warning(
        v_warnings,
        'Roll history was logged with UNKNOWN job number because no checkout job was saved.'
      );
    end if;

    v_weight_delta := case
      when v_existing.last_roll_weight_lbs is null then null
      else round(v_existing.last_roll_weight_lbs - v_box.last_roll_weight_lbs, 2)
    end;

    perform app_api.append_roll_history_entry(
      p_org_id,
      row(
        gen_random_uuid(),
        p_org_id,
        app_api.create_log_id(),
        v_box.box_id,
        v_box.warehouse,
        v_box.manufacturer,
        v_box.film_name,
        v_box.width_in,
        v_checkout_job,
        coalesce(nullif(v_checkout_date, '')::timestamptz, now()),
        v_checkout_user,
        v_existing.last_roll_weight_lbs,
        now(),
        app_api.trim_text(p_actor),
        v_box.last_roll_weight_lbs,
        v_weight_delta,
        v_existing.feet_available,
        v_box.feet_available,
        app_api.trim_text(p_payload->>'auditNote')
      )::app.roll_weight_log
    );

    v_box.last_checkout_job := '';
    v_box.last_checkout_date := null;

    if app_api.has_positive_physical_feet(v_existing)
      and (v_box.feet_available = 0 or coalesce(v_box.last_roll_weight_lbs, 0) = 0) then
      v_box.status := 'ZEROED';
      v_box.feet_available := 0;
      v_box.zeroed_date := app_api.today_date();
      v_box.zeroed_reason := app_api.determine_zeroed_reason(v_box.feet_available, v_box.last_roll_weight_lbs);
      v_box.zeroed_by := app_api.trim_text(p_actor);
      perform app_api.cancel_active_allocations_for_box(
        p_org_id,
        v_box.box_id,
        p_actor,
        'Auto-cancelled because the box was moved to zeroed out inventory.'
      );
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was automatically moved to zeroed out inventory because Available Feet or Last Roll Weight reached 0.'
      );
    end if;
  end if;

  v_box := app_api.save_box(v_box);
  v_public_after := app_api.public_box_json(v_box);
  v_log_id := app_api.append_audit_entry(
    p_org_id,
    case when v_box.status = 'ZEROED' then 'ZERO_OUT_BOX' else 'SET_STATUS' end,
    v_box.box_id,
    v_public_before,
    v_public_after,
    p_actor,
    app_api.trim_text(p_payload->>'auditNote')
  );

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function public.api_allocations_apply(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_source app.boxes;
  v_candidate app.boxes;
  v_job_context jsonb;
  v_requested_feet integer := coalesce(floor(nullif(app_api.trim_text(p_payload->>'requestedFeet'), '')::numeric), 0);
  v_requested_width_in numeric := nullif(app_api.trim_text(p_payload->>'requestedWidthIn'), '')::numeric;
  v_requirement_id_text text := app_api.trim_text(p_payload->>'requirementId');
  v_requirement_id uuid;
  v_requirement app.job_requirements;
  v_source_film_key text;
  v_requirement_is_exterior boolean := false;
  v_remaining integer := 0;
  v_source_planning_feet integer := 0;
  v_source_suggested integer := 0;
  v_source_suggested_covered integer := 0;
  v_candidate_planning_feet integer := 0;
  v_candidate_suggested integer := 0;
  v_candidate_suggested_covered integer := 0;
  v_cross_warehouse boolean := coalesce((p_payload->>'crossWarehouse')::boolean, false);
  v_selected_box_ids text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'selectedSuggestionBoxIds', '[]'::jsonb))),
    array[]::text[]
  );
  v_extra_allocations jsonb := coalesce(p_payload->'extraAllocations', '[]'::jsonb);
  v_extra_entry jsonb;
  v_extra_box_id text;
  v_extra_feet integer;
  v_extra_processed_box_ids text[] := array[]::text[];
  v_allocation app.allocations;
  v_allocation_ids text[] := array[]::text[];
  v_film_order app.film_orders;
  v_conflict_count integer;
  v_job_warehouse text;
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_org_member(p_org_id);

  if v_requested_feet < 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be zero or greater.');
  end if;

  if coalesce(jsonb_typeof(v_extra_allocations), '') not in ('', 'array') then
    perform app_api.raise_http(400, 'extraAllocations must be an array.');
  end if;

  select *
  into v_source
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if coalesce(v_source.status::text, '') not in ('IN_STOCK', 'ORDERED') then
    perform app_api.raise_http(400, 'Only in-stock or ordered boxes can be allocated.');
  end if;

  v_job_context := app_api.resolve_job_context(
    p_org_id,
    p_payload->>'jobNumber',
    p_payload->>'jobDate',
    p_payload->>'crewLeader'
  );

  v_source_film_key := app_api.normalize_requirement_film_key(
    p_org_id,
    v_source.manufacturer,
    v_source.film_name
  );

  if v_requested_feet > 0 then
    if v_requirement_id_text = '' then
      perform app_api.raise_http(400, 'RequirementId is required for film allocations.');
    end if;

    begin
      v_requirement_id := v_requirement_id_text::uuid;
    exception
      when others then
        perform app_api.raise_http(400, 'RequirementId must be a valid UUID.');
    end;

    select r.*
    into v_requirement
    from app.job_requirements r
    where r.org_id = p_org_id
      and r.job_id = app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber')
      and r.id = v_requirement_id;

    if not found then
      perform app_api.raise_http(
        400,
        format('Requirement %s does not belong to job %s.', v_requirement_id, v_job_context->>'jobNumber')
      );
    end if;

    v_requirement_is_exterior := app_api.requirement_film_is_exterior(
      p_org_id,
      v_requirement.manufacturer,
      v_requirement.film_name
    );

    if not app_api.requirement_film_is_compatible(
      p_org_id,
      v_source.manufacturer,
      v_source.film_name,
      v_requirement.manufacturer,
      v_requirement.film_name
    ) then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    if v_source.width_in < v_requirement.width_in then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    v_requested_width_in := v_requirement.width_in;
  elsif v_requested_width_in is null or v_requested_width_in <= 0 then
    v_requested_width_in := v_source.width_in;
  end if;

  if v_source.width_in < v_requested_width_in then
    perform app_api.raise_http(400, 'Source box width must meet or exceed the requested width.');
  end if;

  v_remaining := greatest(v_requested_feet, 0);
  v_source_planning_feet := app_api.allocation_planning_feet_for_box(v_source);

  if v_requested_feet > 0 then
    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_source.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count = 0 then
      select
        p.allocated_feet,
        p.covered_feet,
        p.remaining_covered_feet
      into
        v_source_suggested,
        v_source_suggested_covered,
        v_remaining
      from app_api.plan_allocation_coverage(
        v_remaining,
        v_source_planning_feet,
        v_source.width_in,
        v_requested_width_in
      ) p;
    end if;
  end if;

  if v_source_suggested > 0 then
    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_source,
      v_job_context,
      v_source_suggested,
      v_source_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    if coalesce(v_source.status::text, '') = 'IN_STOCK' then
      v_source.feet_available := greatest(v_source.feet_available - v_source_suggested, 0);
      v_source := app_api.save_box(v_source);
    end if;
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end if;

  for v_candidate in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id <> v_source.box_id
      and coalesce(b.status::text, '') in ('IN_STOCK', 'ORDERED')
      and app_api.compute_allocation_planning_feet(
        coalesce(b.status::text, ''),
        b.feet_available,
        b.initial_feet,
        app_api.active_allocated_feet_for_box(p_org_id, b.box_id)
      ) > 0
      and case
        when v_requirement_id is not null then app_api.requirement_film_is_compatible(
          p_org_id,
          b.manufacturer,
          b.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        )
        else app_api.normalize_requirement_film_key(p_org_id, b.manufacturer, b.film_name) = v_source_film_key
      end
      and b.width_in >= v_requested_width_in
      and (v_cross_warehouse or b.warehouse = v_source.warehouse)
    order by
      case
        when coalesce(b.status::text, '') = 'IN_STOCK' then 0
        when coalesce(b.status::text, '') = 'ORDERED' then 1
        else 2
      end,
      case
        when b.width_in = v_requested_width_in then 0
        when app_api.allocation_coverage_multiplier(b.width_in, v_requested_width_in) > 1 then 1
        else 2
      end,
      (b.width_in - v_requested_width_in),
      case
        when v_requirement_id is not null
          and not v_requirement_is_exterior
          and app_api.requirement_film_is_exterior(p_org_id, b.manufacturer, b.film_name)
        then 1
        else 0
      end,
      coalesce(b.received_date, b.order_date, '9999-12-31'::date),
      b.box_id
    for update
  loop
    exit when v_remaining <= 0;

    if coalesce(array_length(v_selected_box_ids, 1), 0) > 0 and array_position(v_selected_box_ids, v_candidate.box_id) is null then
      continue;
    end if;

    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_candidate.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count > 0 then
      continue;
    end if;

    v_candidate_planning_feet := app_api.allocation_planning_feet_for_box(v_candidate);

    select
      p.allocated_feet,
      p.covered_feet,
      p.remaining_covered_feet
    into
      v_candidate_suggested,
      v_candidate_suggested_covered,
      v_remaining
    from app_api.plan_allocation_coverage(
      v_remaining,
      v_candidate_planning_feet,
      v_candidate.width_in,
      v_requested_width_in
    ) p;

    if v_candidate_suggested <= 0 or v_candidate_suggested_covered <= 0 then
      continue;
    end if;

    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_candidate,
      v_job_context,
      v_candidate_suggested,
      v_candidate_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    if coalesce(v_candidate.status::text, '') = 'IN_STOCK' then
      v_candidate.feet_available := greatest(v_candidate.feet_available - v_allocation.allocated_feet, 0);
      perform app_api.save_box(v_candidate);
    end if;
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end loop;

  if coalesce(jsonb_typeof(v_extra_allocations), '') = 'array' then
    for v_extra_entry in
      select value
      from jsonb_array_elements(v_extra_allocations)
    loop
      if coalesce(jsonb_typeof(v_extra_entry), '') <> 'object' then
        perform app_api.raise_http(400, 'Each extra allocation entry must be an object.');
      end if;

      v_extra_box_id := app_api.require_text(v_extra_entry->>'boxId', 'extraAllocations[].boxId');
      v_extra_feet := floor(nullif(app_api.trim_text(v_extra_entry->>'allocatedFeet'), '')::numeric);

      if v_extra_feet is null or v_extra_feet <= 0 then
        perform app_api.raise_http(400, format('Extra allocation for box %s must be greater than zero.', v_extra_box_id));
      end if;

      if array_position(v_extra_processed_box_ids, v_extra_box_id) is not null then
        perform app_api.raise_http(400, format('Duplicate extra allocation entry for box %s.', v_extra_box_id));
      end if;

      select *
      into v_candidate
      from app.boxes b
      where b.org_id = p_org_id
        and b.box_id = v_extra_box_id
      for update;

      if not found then
        perform app_api.raise_http(404, format('Box not found: %s', v_extra_box_id));
      end if;

      if coalesce(v_candidate.status::text, '') not in ('IN_STOCK', 'ORDERED') then
        perform app_api.raise_http(400, format('Box %s is no longer allocatable.', v_candidate.box_id));
      end if;

      if v_requirement_id is not null then
        if not app_api.requirement_film_is_compatible(
          p_org_id,
          v_candidate.manufacturer,
          v_candidate.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        ) or v_candidate.width_in < v_requested_width_in then
          perform app_api.raise_http(
            400,
            format(
              'Extra box %s must use a compatible film and meet the requested width for this allocation.',
              v_candidate.box_id
            )
          );
        end if;
      elsif app_api.normalize_requirement_film_key(p_org_id, v_candidate.manufacturer, v_candidate.film_name) <> v_source_film_key
        or v_candidate.width_in < v_requested_width_in then
        perform app_api.raise_http(
          400,
          format(
            'Extra box %s must match film and meet the requested width for this allocation.',
            v_candidate.box_id
          )
        );
      end if;

      v_candidate_planning_feet := app_api.allocation_planning_feet_for_box(v_candidate);
      if v_candidate_planning_feet < v_extra_feet then
        perform app_api.raise_http(400, format('Box %s no longer has enough planning LF.', v_candidate.box_id));
      end if;

      v_allocation := app_api.create_allocation(
        p_org_id,
        v_candidate,
        v_job_context,
        v_extra_feet,
        p_actor,
        '',
        'EXTRA',
        null
      );
      if coalesce(v_candidate.status::text, '') = 'IN_STOCK' then
        v_candidate.feet_available := greatest(v_candidate.feet_available - v_extra_feet, 0);
        perform app_api.save_box(v_candidate);
      end if;
      v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
      v_extra_processed_box_ids := array_append(v_extra_processed_box_ids, v_extra_box_id);
    end loop;
  end if;

  if v_requested_feet = 0 and coalesce(array_length(v_extra_processed_box_ids, 1), 0) = 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be greater than zero unless extraAllocations are provided.');
  end if;

  if v_remaining > 0 then
    if app_api.trim_text(p_payload->>'jobWarehouse') <> '' then
      v_job_warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'jobWarehouse', 'Job warehouse');
    else
      v_job_warehouse := v_source.warehouse;
    end if;

    v_film_order.id := gen_random_uuid();
    v_film_order.org_id := p_org_id;
    v_film_order.film_order_id := app_api.create_log_id();
    v_film_order.job_id := app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber');
    v_film_order.job_number := v_job_context->>'jobNumber';
    v_film_order.warehouse := v_job_warehouse;
    v_film_order.manufacturer := coalesce(v_requirement.manufacturer, v_source.manufacturer);
    v_film_order.film_name := coalesce(v_requirement.film_name, v_source.film_name);
    v_film_order.width_in := v_requested_width_in;
    v_film_order.requested_feet := v_remaining;
    v_film_order.covered_feet := 0;
    v_film_order.ordered_feet := 0;
    v_film_order.remaining_to_order_feet := v_remaining;
    v_film_order.job_date := nullif(v_job_context->>'jobDate', '')::date;
    v_film_order.crew_leader := coalesce(v_job_context->>'crewLeader', '');
    v_film_order.status := 'FILM_ORDER';
    v_film_order.source_box_id := v_source.box_id;
    v_film_order.resolved_at := null;
    v_film_order.resolved_by := '';
    v_film_order.notes := format('Created from a shortage while trying to allocate %s LF.', v_requested_feet);
    v_film_order.created_at := now();
    v_film_order.created_by := app_api.trim_text(p_actor);
    v_film_order := app_api.save_film_order(v_film_order);
    v_warnings := app_api.push_warning(
      v_warnings,
      format('Film Order %s was created for the remaining %s LF.', v_film_order.film_order_id, v_remaining)
    );
  end if;

  return jsonb_build_object(
    'allocationIds', to_jsonb(v_allocation_ids),
    'filmOrderId', coalesce(v_film_order.film_order_id, ''),
    'remainingUncoveredFeet', greatest(v_remaining, 0),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function public.api_film_orders_cancel(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job_number text := app_api.require_text(p_payload->>'jobNumber', 'JobNumber');
  v_reason text := coalesce(nullif(app_api.trim_text(p_payload->>'reason'), ''), 'Job cancelled.');
  v_entry app.allocations;
  v_order app.film_orders;
  v_box app.boxes;
  v_released_by_box jsonb := '{}'::jsonb;
  v_released_count integer := 0;
  v_affected_box_count integer := 0;
  v_deleted_film_order_count integer := 0;
  v_caulk_result jsonb;
  v_caulk_cancelled_count integer := 0;
  v_caulk_released_reserved_tubes integer := 0;
begin
  perform app_api.require_org_member(p_org_id);

  v_caulk_result := app_api.cancel_active_caulk_allocations_for_job(
    p_org_id,
    p_actor,
    v_job_number,
    v_reason,
    true
  );
  v_caulk_cancelled_count := coalesce((v_caulk_result->>'cancelledAllocationCount')::integer, 0);
  v_caulk_released_reserved_tubes := coalesce((v_caulk_result->>'releasedReservedTubes')::integer, 0);

  for v_entry in
    select *
    from app.allocations a
    where a.org_id = p_org_id
      and upper(a.job_number) = upper(v_job_number)
      and a.status = 'ACTIVE'
    for update
  loop
    v_released_by_box := jsonb_set(
      v_released_by_box,
      array[v_entry.box_id],
      to_jsonb(coalesce((v_released_by_box->>v_entry.box_id)::integer, 0) + v_entry.allocated_feet),
      true
    );
    v_entry.status := 'CANCELLED';
    v_entry.resolved_at := now();
    v_entry.resolved_by := app_api.trim_text(p_actor);
    v_entry.notes := v_reason;
    perform app_api.save_allocation(v_entry);
    v_released_count := v_released_count + 1;
  end loop;

  for v_box in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and v_released_by_box ? b.box_id
    for update
  loop
    if v_box.status not in ('ZEROED', 'RETIRED') then
      v_box.feet_available := app_api.next_feet_available_after_allocation_release(
        coalesce(v_box.status::text, ''),
        v_box.feet_available,
        coalesce((v_released_by_box->>v_box.box_id)::integer, 0),
        v_box.initial_feet
      );
      perform app_api.save_box(v_box);
    end if;
    v_affected_box_count := v_affected_box_count + 1;
  end loop;

  for v_order in
    select *
    from app.film_orders f
    where f.org_id = p_org_id
      and upper(f.job_number) = upper(v_job_number)
    for update
  loop
    perform app_api.delete_film_order_links_by_film_order_id(p_org_id, v_order.film_order_id);
    perform app_api.delete_film_order(p_org_id, v_order.film_order_id);
    v_deleted_film_order_count := v_deleted_film_order_count + 1;
  end loop;

  update app.jobs
  set lifecycle_status = 'CANCELLED',
      updated_at = now(),
      updated_by = app_api.trim_text(p_actor)
  where org_id = p_org_id
    and job_number = v_job_number;

  return jsonb_build_object(
    'jobNumber', v_job_number,
    'warnings', jsonb_build_array(
      format(
        'Cancelled job %s. Released %s active film allocation%s across %s box%s, released %s reserved caulk tube%s across %s caulk allocation%s, and deleted %s film order%s.',
        v_job_number,
        v_released_count,
        case when v_released_count = 1 then '' else 's' end,
        v_affected_box_count,
        case when v_affected_box_count = 1 then '' else 'es' end,
        v_caulk_released_reserved_tubes,
        case when v_caulk_released_reserved_tubes = 1 then '' else 's' end,
        v_caulk_cancelled_count,
        case when v_caulk_cancelled_count = 1 then '' else 's' end,
        v_deleted_film_order_count,
        case when v_deleted_film_order_count = 1 then '' else 's' end
      )
    )
  );
end;
$$;

with target_orgs as (
  select distinct c.org_id
  from app.film_catalog c
  where app_api.normalize_catalog_lookup_key(c.manufacturer) = app_api.normalize_catalog_lookup_key('SOLYX')

  union

  select distinct b.org_id
  from app.boxes b
  where app_api.normalize_catalog_lookup_key(b.manufacturer) = app_api.normalize_catalog_lookup_key('SOLYX')
)
insert into app.film_catalog (
  org_id,
  film_key,
  manufacturer,
  film_name,
  source_width_in,
  source_initial_feet,
  source_initial_weight_lbs,
  source_box_id,
  notes,
  updated_at
)
select
  target_orgs.org_id,
  upper('SOLYX') || '|' || upper('Frosted Stripes SXC-3511'),
  'SOLYX',
  'Frosted Stripes SXC-3511',
  null,
  null,
  null,
  null,
  'Added by migration to preserve the SOLYX Frosted Stripes SXC-3511 catalog suggestion as a distinct film key.',
  now()
from target_orgs
on conflict (org_id, film_key) do update
set
  manufacturer = excluded.manufacturer,
  film_name = excluded.film_name,
  notes = excluded.notes,
  updated_at = now();

create or replace function public.api_acl_list_caulk_transactions(
  p_org_id uuid,
  p_warehouse text default '',
  p_product_id uuid default null,
  p_limit integer default 200
)
returns table (
  transaction_id text,
  product_id uuid,
  warehouse text,
  manufacturer text,
  product_name text,
  product_code text,
  action text,
  delta_tubes integer,
  resulting_tubes_on_hand integer,
  tubes_per_case integer,
  reason text,
  notes text,
  transfer_id text,
  source_box_id text,
  created_at timestamptz,
  created_by text
)
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_warehouse text := upper(btrim(coalesce(p_warehouse, '')));
  v_limit integer := greatest(1, least(coalesce(p_limit, 200), 1000));
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'read');

  if v_warehouse <> '' and v_warehouse <> 'ALL' then
    v_warehouse := app_api.caulk_require_warehouse(p_org_id, v_warehouse);
  end if;

  return query
  select
    t.transaction_id,
    t.product_id,
    t.warehouse,
    m.name,
    p.name,
    p.code,
    t.action,
    t.delta_tubes,
    t.resulting_tubes_on_hand,
    t.tubes_per_case,
    case
      when t.action = 'JOB_CHECKIN_UNUSED'
        and btrim(coalesce(a.job_number, '')) <> ''
        then format('Checked in unused caulk from job %s.', a.job_number)
      else t.reason
    end,
    t.notes,
    t.transfer_id,
    t.source_box_id,
    t.created_at,
    t.created_by
  from app.caulk_transactions t
  join app.caulk_products p
    on p.org_id = t.org_id
   and p.id = t.product_id
  join app.caulk_manufacturers m
    on m.org_id = p.org_id
   and m.id = p.manufacturer_id
  left join app.caulk_job_allocations a
    on a.org_id = t.org_id
   and a.caulk_allocation_id = t.source_box_id
  where t.org_id = p_org_id
    and (v_warehouse = '' or v_warehouse = 'ALL' or t.warehouse = v_warehouse)
    and (p_product_id is null or t.product_id = p_product_id)
  order by t.created_at desc
  limit v_limit;
end;
$$;

create or replace function public.api_acl_allocations_caulk_checkin(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_checkout app.caulk_job_checkouts;
  v_allocation app.caulk_job_allocations;
  v_actor text := app_api.trim_text(p_actor);
  v_caulk_checkout_id text := app_api.require_text(p_payload->>'caulkCheckoutId', 'CaulkCheckoutId');
  v_unused_loose_tubes integer := floor(nullif(app_api.trim_text(p_payload->>'unusedLooseTubes'), '')::numeric);
  v_unused_cases integer := floor(nullif(app_api.trim_text(p_payload->>'unusedCases'), '')::numeric);
  v_unused_tubes_legacy integer := floor(nullif(app_api.trim_text(p_payload->>'unusedTubes'), '')::numeric);
  v_tubes_per_case integer;
  v_total_returned_tubes integer;
  v_used_tubes integer;
  v_notes text := app_api.trim_text(p_payload->>'notes');
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  select *
  into v_checkout
  from app.caulk_job_checkouts c
  where c.org_id = p_org_id
    and c.caulk_checkout_id = v_caulk_checkout_id
  for update;

  if not found then
    perform app_api.raise_http(404, format('Caulk checkout %s was not found.', v_caulk_checkout_id));
  end if;

  if v_checkout.status <> 'OPEN' then
    perform app_api.raise_http(400, format('Caulk checkout %s is already closed.', v_caulk_checkout_id));
  end if;

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.id = v_checkout.caulk_allocation_id
  for update;

  if not found then
    perform app_api.raise_http(404, 'Parent caulk allocation was not found.');
  end if;

  if v_allocation.status <> 'ACTIVE' then
    perform app_api.raise_http(400, 'Parent caulk allocation is no longer active.');
  end if;

  select p.tubes_per_case
  into v_tubes_per_case
  from app.caulk_products p
  where p.org_id = p_org_id
    and p.id = v_allocation.product_id;

  if v_tubes_per_case is null or v_tubes_per_case <= 0 then
    perform app_api.raise_http(400, 'This caulk product is missing a valid tubesPerCase value.');
  end if;

  if v_unused_loose_tubes is null and v_unused_cases is null then
    if v_unused_tubes_legacy is null or v_unused_tubes_legacy < 0 then
      perform app_api.raise_http(400, 'unusedTubes must be zero or greater.');
    end if;

    v_total_returned_tubes := v_unused_tubes_legacy;
  else
    v_unused_loose_tubes := coalesce(v_unused_loose_tubes, 0);
    v_unused_cases := coalesce(v_unused_cases, 0);

    if v_unused_loose_tubes < 0 then
      perform app_api.raise_http(400, 'unusedLooseTubes must be zero or greater.');
    end if;

    if v_unused_cases < 0 then
      perform app_api.raise_http(400, 'unusedCases must be zero or greater.');
    end if;

    if v_unused_loose_tubes >= v_tubes_per_case then
      perform app_api.raise_http(
        400,
        format('unusedLooseTubes must be less than tubesPerCase (%s).', v_tubes_per_case)
      );
    end if;

    v_total_returned_tubes := v_unused_loose_tubes + (v_unused_cases * v_tubes_per_case);
  end if;

  if v_total_returned_tubes > v_checkout.checkout_tubes then
    perform app_api.raise_http(400, 'Returned caulk cannot exceed checked-out tubes.');
  end if;

  v_used_tubes := v_checkout.checkout_tubes - v_total_returned_tubes;

  if v_total_returned_tubes > 0 then
    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_allocation.product_id,
      v_allocation.warehouse,
      'JOB_CHECKIN_UNUSED',
      v_total_returned_tubes,
      format('Checked in unused caulk from job %s.', v_allocation.job_number),
      '',
      v_allocation.caulk_allocation_id,
      v_notes
    );
  end if;

  update app.caulk_job_checkouts
  set
    status = 'CLOSED',
    checked_in_at = now(),
    checked_in_by = v_actor,
    unused_tubes = v_total_returned_tubes,
    used_tubes = v_used_tubes,
    notes = v_notes
  where id = v_checkout.id
    and org_id = p_org_id;

  update app.caulk_job_allocations
  set
    returned_unused_tubes_total = v_allocation.returned_unused_tubes_total + v_total_returned_tubes,
    used_tubes_total = v_allocation.used_tubes_total + v_used_tubes,
    updated_at = now(),
    updated_by = v_actor
  where id = v_allocation.id
    and org_id = p_org_id;

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'caulkCheckoutId', v_checkout.caulk_checkout_id,
    'warnings', '[]'::jsonb
  );
end;
$$;

select app_api.grant_execute_if_exists('public.api_acl_list_caulk_transactions(uuid, text, uuid, integer)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_checkin(uuid, text, jsonb)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_list_caulk_transactions(uuid, text, uuid, integer)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_allocations_caulk_checkin(uuid, text, jsonb)', 'service_role');

create or replace function public.api_acl_list_caulk_transactions(
  p_org_id uuid,
  p_warehouse text default '',
  p_product_id uuid default null,
  p_limit integer default 200
)
returns table (
  transaction_id text,
  product_id uuid,
  warehouse text,
  manufacturer text,
  product_name text,
  product_code text,
  action text,
  delta_tubes integer,
  resulting_tubes_on_hand integer,
  tubes_per_case integer,
  reason text,
  notes text,
  transfer_id text,
  source_box_id text,
  created_at timestamptz,
  created_by text
)
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_warehouse text := upper(btrim(coalesce(p_warehouse, '')));
  v_limit integer := greatest(1, least(coalesce(p_limit, 200), 1000));
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'read');

  if v_warehouse <> '' and v_warehouse <> 'ALL' then
    v_warehouse := app_api.caulk_require_warehouse(p_org_id, v_warehouse);
  end if;

  return query
  select
    t.transaction_id,
    t.product_id,
    t.warehouse,
    m.name,
    p.name,
    p.code,
    t.action,
    t.delta_tubes,
    t.resulting_tubes_on_hand,
    t.tubes_per_case,
    case
      when t.action = 'JOB_CHECKIN_UNUSED'
        and btrim(coalesce(a.job_number, '')) <> ''
        then format('Checked in unused caulk from job %s.', a.job_number)
      when t.action = 'ADJUST'
        and lower(btrim(coalesce(t.reason, ''))) = 'inventory edit'
        and btrim(coalesce(t.notes, '')) <> ''
        then btrim(t.notes)
      else t.reason
    end,
    t.notes,
    t.transfer_id,
    t.source_box_id,
    t.created_at,
    t.created_by
  from app.caulk_transactions t
  join app.caulk_products p
    on p.org_id = t.org_id
   and p.id = t.product_id
  join app.caulk_manufacturers m
    on m.org_id = p.org_id
   and m.id = p.manufacturer_id
  left join app.caulk_job_allocations a
    on a.org_id = t.org_id
   and a.caulk_allocation_id = t.source_box_id
  where t.org_id = p_org_id
    and (v_warehouse = '' or v_warehouse = 'ALL' or t.warehouse = v_warehouse)
    and (p_product_id is null or t.product_id = p_product_id)
  order by t.created_at desc
  limit v_limit;
end;
$$;

create or replace function public.api_acl_caulk_mutate_stock(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_action text := upper(app_api.trim_text(p_payload->>'action'));
  v_product_id uuid := nullif(app_api.trim_text(p_payload->>'productId'), '')::uuid;
  v_warehouse text := p_payload->>'warehouse';
  v_cases integer := coalesce(nullif(app_api.trim_text(p_payload->>'cases'), '')::integer, 0);
  v_tubes integer := coalesce(nullif(app_api.trim_text(p_payload->>'tubes'), '')::integer, 0);
  v_delta_override integer := nullif(app_api.trim_text(p_payload->>'deltaTubes'), '')::integer;
  v_reason text := app_api.trim_text(coalesce(p_payload->>'reason', v_action));
  v_notes text := app_api.trim_text(coalesce(p_payload->>'notes', ''));
  v_tubes_per_case integer;
  v_delta integer;
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'write');

  if v_product_id is null then
    perform app_api.raise_http(400, 'ProductId is required.');
  end if;

  if v_action not in ('RECEIVE', 'USE', 'ADJUST') then
    perform app_api.raise_http(400, 'Action must be RECEIVE, USE, or ADJUST.');
  end if;

  if v_action = 'ADJUST' and v_notes <> '' and lower(v_reason) = 'inventory edit' then
    v_reason := v_notes;
  end if;

  select p.tubes_per_case
  into v_tubes_per_case
  from app.caulk_products p
  where p.org_id = p_org_id
    and p.id = v_product_id
  limit 1;

  if not found then
    perform app_api.raise_http(400, 'Product was not found.');
  end if;

  if v_delta_override is null then
    v_delta := (v_cases * v_tubes_per_case) + v_tubes;
  else
    v_delta := v_delta_override;
  end if;

  if v_action = 'RECEIVE' then
    if v_delta <= 0 then
      perform app_api.raise_http(400, 'Receive requires a positive quantity.');
    end if;
    return app_api.caulk_apply_stock_delta(
      p_org_id,
      p_actor,
      v_product_id,
      v_warehouse,
      'RECEIVE',
      v_delta,
      v_reason,
      '',
      '',
      v_notes
    );
  end if;

  if v_action = 'USE' then
    if v_delta <= 0 then
      perform app_api.raise_http(400, 'Use requires a positive quantity.');
    end if;
    return app_api.caulk_apply_stock_delta(
      p_org_id,
      p_actor,
      v_product_id,
      v_warehouse,
      'USE',
      -v_delta,
      v_reason,
      '',
      '',
      v_notes
    );
  end if;

  if v_delta = 0 then
    perform app_api.raise_http(400, 'Adjust requires a non-zero delta.');
  end if;

  return app_api.caulk_apply_stock_delta(
    p_org_id,
    p_actor,
    v_product_id,
    v_warehouse,
    'ADJUST',
    v_delta,
    v_reason,
    '',
    '',
    v_notes
  );
end;
$$;

select app_api.grant_execute_if_exists('public.api_acl_list_caulk_transactions(uuid, text, uuid, integer)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_caulk_mutate_stock(uuid, text, jsonb)', 'authenticated');
select app_api.grant_execute_if_exists('public.api_acl_list_caulk_transactions(uuid, text, uuid, integer)', 'service_role');
select app_api.grant_execute_if_exists('public.api_acl_caulk_mutate_stock(uuid, text, jsonb)', 'service_role');

-- Reassert allocation apply so extra-only film allocations still validate the selected job requirement.

create or replace function public.api_allocations_apply(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_source app.boxes;
  v_candidate app.boxes;
  v_job_context jsonb;
  v_requested_feet integer := coalesce(floor(nullif(app_api.trim_text(p_payload->>'requestedFeet'), '')::numeric), 0);
  v_requested_width_in numeric := nullif(app_api.trim_text(p_payload->>'requestedWidthIn'), '')::numeric;
  v_requirement_id_text text := app_api.trim_text(p_payload->>'requirementId');
  v_should_validate_requirement boolean := false;
  v_requirement_id uuid;
  v_requirement app.job_requirements;
  v_source_film_key text;
  v_requirement_is_exterior boolean := false;
  v_remaining integer := 0;
  v_source_planning_feet integer := 0;
  v_source_suggested integer := 0;
  v_source_suggested_covered integer := 0;
  v_candidate_planning_feet integer := 0;
  v_candidate_suggested integer := 0;
  v_candidate_suggested_covered integer := 0;
  v_cross_warehouse boolean := coalesce((p_payload->>'crossWarehouse')::boolean, false);
  v_selected_box_ids text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'selectedSuggestionBoxIds', '[]'::jsonb))),
    array[]::text[]
  );
  v_extra_allocations jsonb := coalesce(p_payload->'extraAllocations', '[]'::jsonb);
  v_extra_entry jsonb;
  v_extra_box_id text;
  v_extra_feet integer;
  v_extra_processed_box_ids text[] := array[]::text[];
  v_allocation app.allocations;
  v_allocation_ids text[] := array[]::text[];
  v_film_order app.film_orders;
  v_conflict_count integer;
  v_job_warehouse text;
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_org_member(p_org_id);

  if v_requested_feet < 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be zero or greater.');
  end if;

  if coalesce(jsonb_typeof(v_extra_allocations), '') not in ('', 'array') then
    perform app_api.raise_http(400, 'extraAllocations must be an array.');
  end if;

  select *
  into v_source
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if coalesce(v_source.status::text, '') not in ('IN_STOCK', 'ORDERED') then
    perform app_api.raise_http(400, 'Only in-stock or ordered boxes can be allocated.');
  end if;

  v_job_context := app_api.resolve_job_context(
    p_org_id,
    p_payload->>'jobNumber',
    p_payload->>'jobDate',
    p_payload->>'crewLeader'
  );

  v_source_film_key := app_api.normalize_requirement_film_key(
    p_org_id,
    v_source.manufacturer,
    v_source.film_name
  );

  v_should_validate_requirement := v_requested_feet > 0 or v_requirement_id_text <> '';

  if v_should_validate_requirement then
    if v_requirement_id_text = '' then
      perform app_api.raise_http(400, 'RequirementId is required for film allocations.');
    end if;

    begin
      v_requirement_id := v_requirement_id_text::uuid;
    exception
      when others then
        perform app_api.raise_http(400, 'RequirementId must be a valid UUID.');
    end;

    select r.*
    into v_requirement
    from app.job_requirements r
    where r.org_id = p_org_id
      and r.job_id = app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber')
      and r.id = v_requirement_id;

    if not found then
      perform app_api.raise_http(
        400,
        format('Requirement %s does not belong to job %s.', v_requirement_id, v_job_context->>'jobNumber')
      );
    end if;

    v_requirement_is_exterior := app_api.requirement_film_is_exterior(
      p_org_id,
      v_requirement.manufacturer,
      v_requirement.film_name
    );

    if not app_api.requirement_film_is_compatible(
      p_org_id,
      v_source.manufacturer,
      v_source.film_name,
      v_requirement.manufacturer,
      v_requirement.film_name
    ) then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    if v_source.width_in < v_requirement.width_in then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    v_requested_width_in := v_requirement.width_in;
  elsif v_requested_width_in is null or v_requested_width_in <= 0 then
    v_requested_width_in := v_source.width_in;
  end if;

  if v_source.width_in < v_requested_width_in then
    perform app_api.raise_http(400, 'Source box width must meet or exceed the requested width.');
  end if;

  v_remaining := greatest(v_requested_feet, 0);
  v_source_planning_feet := app_api.allocation_planning_feet_for_box(v_source);

  if v_requested_feet > 0 then
    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_source.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count = 0 then
      select
        p.allocated_feet,
        p.covered_feet,
        p.remaining_covered_feet
      into
        v_source_suggested,
        v_source_suggested_covered,
        v_remaining
      from app_api.plan_allocation_coverage(
        v_remaining,
        v_source_planning_feet,
        v_source.width_in,
        v_requested_width_in
      ) p;
    end if;
  end if;

  if v_source_suggested > 0 then
    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_source,
      v_job_context,
      v_source_suggested,
      v_source_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    if coalesce(v_source.status::text, '') = 'IN_STOCK' then
      v_source.feet_available := greatest(v_source.feet_available - v_source_suggested, 0);
      v_source := app_api.save_box(v_source);
    end if;
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end if;

  for v_candidate in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id <> v_source.box_id
      and coalesce(b.status::text, '') in ('IN_STOCK', 'ORDERED')
      and app_api.compute_allocation_planning_feet(
        coalesce(b.status::text, ''),
        b.feet_available,
        b.initial_feet,
        app_api.active_allocated_feet_for_box(p_org_id, b.box_id)
      ) > 0
      and case
        when v_requirement_id is not null then app_api.requirement_film_is_compatible(
          p_org_id,
          b.manufacturer,
          b.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        )
        else app_api.normalize_requirement_film_key(p_org_id, b.manufacturer, b.film_name) = v_source_film_key
      end
      and b.width_in >= v_requested_width_in
      and (v_cross_warehouse or b.warehouse = v_source.warehouse)
    order by
      case
        when coalesce(b.status::text, '') = 'IN_STOCK' then 0
        when coalesce(b.status::text, '') = 'ORDERED' then 1
        else 2
      end,
      case
        when b.width_in = v_requested_width_in then 0
        when app_api.allocation_coverage_multiplier(b.width_in, v_requested_width_in) > 1 then 1
        else 2
      end,
      (b.width_in - v_requested_width_in),
      case
        when v_requirement_id is not null
          and not v_requirement_is_exterior
          and app_api.requirement_film_is_exterior(p_org_id, b.manufacturer, b.film_name)
        then 1
        else 0
      end,
      coalesce(b.received_date, b.order_date, '9999-12-31'::date),
      b.box_id
    for update
  loop
    exit when v_remaining <= 0;

    if coalesce(array_length(v_selected_box_ids, 1), 0) > 0 and array_position(v_selected_box_ids, v_candidate.box_id) is null then
      continue;
    end if;

    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_candidate.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count > 0 then
      continue;
    end if;

    v_candidate_planning_feet := app_api.allocation_planning_feet_for_box(v_candidate);

    select
      p.allocated_feet,
      p.covered_feet,
      p.remaining_covered_feet
    into
      v_candidate_suggested,
      v_candidate_suggested_covered,
      v_remaining
    from app_api.plan_allocation_coverage(
      v_remaining,
      v_candidate_planning_feet,
      v_candidate.width_in,
      v_requested_width_in
    ) p;

    if v_candidate_suggested <= 0 or v_candidate_suggested_covered <= 0 then
      continue;
    end if;

    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_candidate,
      v_job_context,
      v_candidate_suggested,
      v_candidate_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    if coalesce(v_candidate.status::text, '') = 'IN_STOCK' then
      v_candidate.feet_available := greatest(v_candidate.feet_available - v_allocation.allocated_feet, 0);
      perform app_api.save_box(v_candidate);
    end if;
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end loop;

  if coalesce(jsonb_typeof(v_extra_allocations), '') = 'array' then
    for v_extra_entry in
      select value
      from jsonb_array_elements(v_extra_allocations)
    loop
      if coalesce(jsonb_typeof(v_extra_entry), '') <> 'object' then
        perform app_api.raise_http(400, 'Each extra allocation entry must be an object.');
      end if;

      v_extra_box_id := app_api.require_text(v_extra_entry->>'boxId', 'extraAllocations[].boxId');
      v_extra_feet := floor(nullif(app_api.trim_text(v_extra_entry->>'allocatedFeet'), '')::numeric);

      if v_extra_feet is null or v_extra_feet <= 0 then
        perform app_api.raise_http(400, format('Extra allocation for box %s must be greater than zero.', v_extra_box_id));
      end if;

      if array_position(v_extra_processed_box_ids, v_extra_box_id) is not null then
        perform app_api.raise_http(400, format('Duplicate extra allocation entry for box %s.', v_extra_box_id));
      end if;

      select *
      into v_candidate
      from app.boxes b
      where b.org_id = p_org_id
        and b.box_id = v_extra_box_id
      for update;

      if not found then
        perform app_api.raise_http(404, format('Box not found: %s', v_extra_box_id));
      end if;

      if coalesce(v_candidate.status::text, '') not in ('IN_STOCK', 'ORDERED') then
        perform app_api.raise_http(400, format('Box %s is no longer allocatable.', v_candidate.box_id));
      end if;

      if v_requirement_id is not null then
        if not app_api.requirement_film_is_compatible(
          p_org_id,
          v_candidate.manufacturer,
          v_candidate.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        ) or v_candidate.width_in < v_requested_width_in then
          perform app_api.raise_http(
            400,
            format(
              'Extra box %s must use a compatible film and meet the requested width for this allocation.',
              v_candidate.box_id
            )
          );
        end if;
      elsif app_api.normalize_requirement_film_key(p_org_id, v_candidate.manufacturer, v_candidate.film_name) <> v_source_film_key
        or v_candidate.width_in < v_requested_width_in then
        perform app_api.raise_http(
          400,
          format(
            'Extra box %s must match film and meet the requested width for this allocation.',
            v_candidate.box_id
          )
        );
      end if;

      v_candidate_planning_feet := app_api.allocation_planning_feet_for_box(v_candidate);
      if v_candidate_planning_feet < v_extra_feet then
        perform app_api.raise_http(400, format('Box %s no longer has enough planning LF.', v_candidate.box_id));
      end if;

      v_allocation := app_api.create_allocation(
        p_org_id,
        v_candidate,
        v_job_context,
        v_extra_feet,
        p_actor,
        '',
        'EXTRA',
        null
      );
      if coalesce(v_candidate.status::text, '') = 'IN_STOCK' then
        v_candidate.feet_available := greatest(v_candidate.feet_available - v_extra_feet, 0);
        perform app_api.save_box(v_candidate);
      end if;
      v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
      v_extra_processed_box_ids := array_append(v_extra_processed_box_ids, v_extra_box_id);
    end loop;
  end if;

  if v_requested_feet = 0 and coalesce(array_length(v_extra_processed_box_ids, 1), 0) = 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be greater than zero unless extraAllocations are provided.');
  end if;

  if v_remaining > 0 then
    if app_api.trim_text(p_payload->>'jobWarehouse') <> '' then
      v_job_warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'jobWarehouse', 'Job warehouse');
    else
      v_job_warehouse := v_source.warehouse;
    end if;

    v_film_order.id := gen_random_uuid();
    v_film_order.org_id := p_org_id;
    v_film_order.film_order_id := app_api.create_log_id();
    v_film_order.job_id := app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber');
    v_film_order.job_number := v_job_context->>'jobNumber';
    v_film_order.warehouse := v_job_warehouse;
    v_film_order.manufacturer := coalesce(v_requirement.manufacturer, v_source.manufacturer);
    v_film_order.film_name := coalesce(v_requirement.film_name, v_source.film_name);
    v_film_order.width_in := v_requested_width_in;
    v_film_order.requested_feet := v_remaining;
    v_film_order.covered_feet := 0;
    v_film_order.ordered_feet := 0;
    v_film_order.remaining_to_order_feet := v_remaining;
    v_film_order.job_date := nullif(v_job_context->>'jobDate', '')::date;
    v_film_order.crew_leader := coalesce(v_job_context->>'crewLeader', '');
    v_film_order.status := 'FILM_ORDER';
    v_film_order.source_box_id := v_source.box_id;
    v_film_order.resolved_at := null;
    v_film_order.resolved_by := '';
    v_film_order.notes := format('Created from a shortage while trying to allocate %s LF.', v_requested_feet);
    v_film_order.created_at := now();
    v_film_order.created_by := app_api.trim_text(p_actor);
    v_film_order := app_api.save_film_order(v_film_order);
    v_warnings := app_api.push_warning(
      v_warnings,
      format('Film Order %s was created for the remaining %s LF.', v_film_order.film_order_id, v_remaining)
    );
  end if;

  return jsonb_build_object(
    'allocationIds', to_jsonb(v_allocation_ids),
    'filmOrderId', coalesce(v_film_order.film_order_id, ''),
    'remainingUncoveredFeet', greatest(v_remaining, 0),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

-- Auto-remove stale auto-generated shortage film orders when a requirement becomes fully covered.

create or replace function app_api.compute_allocation_planning_feet(
  p_status text,
  p_initial_feet integer,
  p_feet_available integer,
  p_active_allocated_feet integer
)
returns integer
language sql
immutable
as $$
  select
    case upper(coalesce(app_api.trim_text(p_status), ''))
      when 'IN_STOCK' then greatest(coalesce(p_feet_available, 0), 0)
      when 'TRANSFER' then greatest(coalesce(p_feet_available, 0), 0)
      when 'ORDERED' then greatest(coalesce(p_initial_feet, 0) - coalesce(p_active_allocated_feet, 0), 0)
      else 0
    end;
$$;

create or replace function public.api_allocations_apply(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_source app.boxes;
  v_candidate app.boxes;
  v_job_context jsonb;
  v_requested_feet integer := coalesce(floor(nullif(app_api.trim_text(p_payload->>'requestedFeet'), '')::numeric), 0);
  v_requested_width_in numeric := nullif(app_api.trim_text(p_payload->>'requestedWidthIn'), '')::numeric;
  v_requirement_id_text text := app_api.trim_text(p_payload->>'requirementId');
  v_should_validate_requirement boolean := false;
  v_requirement_id uuid;
  v_requirement app.job_requirements;
  v_source_film_key text;
  v_requirement_is_exterior boolean := false;
  v_remaining integer := 0;
  v_requirement_remaining_feet integer := 0;
  v_source_planning_feet integer := 0;
  v_source_suggested integer := 0;
  v_source_suggested_covered integer := 0;
  v_candidate_planning_feet integer := 0;
  v_candidate_suggested integer := 0;
  v_candidate_suggested_covered integer := 0;
  v_cross_warehouse boolean := coalesce((p_payload->>'crossWarehouse')::boolean, false);
  v_selected_box_ids text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'selectedSuggestionBoxIds', '[]'::jsonb))),
    array[]::text[]
  );
  v_extra_allocations jsonb := coalesce(p_payload->'extraAllocations', '[]'::jsonb);
  v_extra_entry jsonb;
  v_extra_box_id text;
  v_extra_feet integer;
  v_extra_processed_box_ids text[] := array[]::text[];
  v_allocation app.allocations;
  v_allocation_ids text[] := array[]::text[];
  v_film_order app.film_orders;
  v_cleanup_order app.film_orders;
  v_cleanup_link_count integer := 0;
  v_cleanup_allocation_count integer := 0;
  v_deleted_shortage_film_order_count integer := 0;
  v_conflict_count integer;
  v_job_warehouse text;
  v_source_transfer_destination text := '';
  v_candidate_transfer_destination text := '';
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_org_member(p_org_id);

  if v_requested_feet < 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be zero or greater.');
  end if;

  if coalesce(jsonb_typeof(v_extra_allocations), '') not in ('', 'array') then
    perform app_api.raise_http(400, 'extraAllocations must be an array.');
  end if;

  select *
  into v_source
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  v_job_context := app_api.resolve_job_context(
    p_org_id,
    p_payload->>'jobNumber',
    p_payload->>'jobDate',
    p_payload->>'crewLeader'
  );

  if app_api.trim_text(p_payload->>'jobWarehouse') <> '' then
    v_job_warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'jobWarehouse', 'Job warehouse');
  else
    select coalesce(j.warehouse::text, '')
    into v_job_warehouse
    from app.jobs j
    where j.org_id = p_org_id
      and upper(trim(j.job_number)) = upper(trim(v_job_context->>'jobNumber'))
    limit 1;
  end if;

  if coalesce(v_source.status::text, '') = 'TRANSFER' then
    select coalesce(t.destination_warehouse::text, '')
    into v_source_transfer_destination
    from app.box_transfers t
    where t.org_id = p_org_id
      and t.box_record_id = v_source.id
      and t.status = 'PENDING'
    order by t.created_at desc, t.id desc
    limit 1;

    if coalesce(v_job_warehouse, '') = '' then
      perform app_api.raise_http(
        400,
        format('Box %s is in transfer status and needs a job warehouse before it can be allocated.', v_source.box_id)
      );
    end if;

    if v_source_transfer_destination = '' then
      perform app_api.raise_http(
        400,
        format('Box %s is in transfer status but no pending transfer was found.', v_source.box_id)
      );
    end if;

    if upper(v_source_transfer_destination) <> upper(v_job_warehouse) then
      perform app_api.raise_http(
        400,
        format(
          'Box %s is transferring to %s and cannot be allocated to a job in %s.',
          v_source.box_id,
          v_source_transfer_destination,
          v_job_warehouse
        )
      );
    end if;
  elsif coalesce(v_source.status::text, '') not in ('IN_STOCK', 'ORDERED') then
    perform app_api.raise_http(400, 'Only in-stock, ordered, or matching transfer boxes can be allocated.');
  end if;

  v_source_film_key := app_api.normalize_requirement_film_key(
    p_org_id,
    v_source.manufacturer,
    v_source.film_name
  );

  v_should_validate_requirement := v_requested_feet > 0 or v_requirement_id_text <> '';

  if v_should_validate_requirement then
    if v_requirement_id_text = '' then
      perform app_api.raise_http(400, 'RequirementId is required for film allocations.');
    end if;

    begin
      v_requirement_id := v_requirement_id_text::uuid;
    exception
      when others then
        perform app_api.raise_http(400, 'RequirementId must be a valid UUID.');
    end;

    select r.*
    into v_requirement
    from app.job_requirements r
    where r.org_id = p_org_id
      and r.job_id = app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber')
      and r.id = v_requirement_id;

    if not found then
      perform app_api.raise_http(
        400,
        format('Requirement %s does not belong to job %s.', v_requirement_id, v_job_context->>'jobNumber')
      );
    end if;

    v_requirement_is_exterior := app_api.requirement_film_is_exterior(
      p_org_id,
      v_requirement.manufacturer,
      v_requirement.film_name
    );

    if not app_api.requirement_film_is_compatible(
      p_org_id,
      v_source.manufacturer,
      v_source.film_name,
      v_requirement.manufacturer,
      v_requirement.film_name
    ) then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    if v_source.width_in < v_requirement.width_in then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    v_requested_width_in := v_requirement.width_in;
  elsif v_requested_width_in is null or v_requested_width_in <= 0 then
    v_requested_width_in := v_source.width_in;
  end if;

  if v_source.width_in < v_requested_width_in then
    perform app_api.raise_http(400, 'Source box width must meet or exceed the requested width.');
  end if;

  v_remaining := greatest(v_requested_feet, 0);
  v_source_planning_feet := app_api.allocation_planning_feet_for_box(v_source);

  if v_requested_feet > 0 then
    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_source.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count = 0 then
      select
        p.allocated_feet,
        p.covered_feet,
        p.remaining_covered_feet
      into
        v_source_suggested,
        v_source_suggested_covered,
        v_remaining
      from app_api.plan_allocation_coverage(
        v_remaining,
        v_source_planning_feet,
        v_source.width_in,
        v_requested_width_in
      ) p;
    end if;
  end if;

  if v_source_suggested > 0 then
    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_source,
      v_job_context,
      v_source_suggested,
      v_source_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    if coalesce(v_source.status::text, '') in ('IN_STOCK', 'TRANSFER') then
      v_source.feet_available := greatest(v_source.feet_available - v_source_suggested, 0);
      v_source := app_api.save_box(v_source);
    end if;
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end if;

  for v_candidate in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id <> v_source.box_id
      and (
        coalesce(b.status::text, '') in ('IN_STOCK', 'ORDERED')
        or (
          coalesce(b.status::text, '') = 'TRANSFER'
          and coalesce(v_job_warehouse, '') <> ''
          and exists (
            select 1
            from app.box_transfers t
            where t.org_id = p_org_id
              and t.box_record_id = b.id
              and t.status = 'PENDING'
              and upper(coalesce(t.destination_warehouse, '')) = upper(v_job_warehouse)
          )
        )
      )
      and app_api.compute_allocation_planning_feet(
        coalesce(b.status::text, ''),
        b.initial_feet,
        b.feet_available,
        app_api.active_allocated_feet_for_box(p_org_id, b.box_id)
      ) > 0
      and case
        when v_requirement_id is not null then app_api.requirement_film_is_compatible(
          p_org_id,
          b.manufacturer,
          b.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        )
        else app_api.normalize_requirement_film_key(p_org_id, b.manufacturer, b.film_name) = v_source_film_key
      end
      and b.width_in >= v_requested_width_in
      and (v_cross_warehouse or b.warehouse = v_source.warehouse)
    order by
      case
        when coalesce(b.status::text, '') = 'IN_STOCK' then 0
        when coalesce(b.status::text, '') = 'TRANSFER' then 1
        when coalesce(b.status::text, '') = 'ORDERED' then 2
        else 3
      end,
      case
        when b.width_in = v_requested_width_in then 0
        when app_api.allocation_coverage_multiplier(b.width_in, v_requested_width_in) > 1 then 1
        else 2
      end,
      (b.width_in - v_requested_width_in),
      case
        when v_requirement_id is not null
          and not v_requirement_is_exterior
          and app_api.requirement_film_is_exterior(p_org_id, b.manufacturer, b.film_name)
        then 1
        else 0
      end,
      coalesce(b.received_date, b.order_date, '9999-12-31'::date),
      b.box_id
    for update
  loop
    exit when v_remaining <= 0;

    if coalesce(array_length(v_selected_box_ids, 1), 0) > 0 and array_position(v_selected_box_ids, v_candidate.box_id) is null then
      continue;
    end if;

    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_candidate.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count > 0 then
      continue;
    end if;

    v_candidate_planning_feet := app_api.allocation_planning_feet_for_box(v_candidate);

    select
      p.allocated_feet,
      p.covered_feet,
      p.remaining_covered_feet
    into
      v_candidate_suggested,
      v_candidate_suggested_covered,
      v_remaining
    from app_api.plan_allocation_coverage(
      v_remaining,
      v_candidate_planning_feet,
      v_candidate.width_in,
      v_requested_width_in
    ) p;

    if v_candidate_suggested <= 0 or v_candidate_suggested_covered <= 0 then
      continue;
    end if;

    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_candidate,
      v_job_context,
      v_candidate_suggested,
      v_candidate_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    if coalesce(v_candidate.status::text, '') in ('IN_STOCK', 'TRANSFER') then
      v_candidate.feet_available := greatest(v_candidate.feet_available - v_allocation.allocated_feet, 0);
      perform app_api.save_box(v_candidate);
    end if;
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end loop;

  if coalesce(jsonb_typeof(v_extra_allocations), '') = 'array' then
    for v_extra_entry in
      select value
      from jsonb_array_elements(v_extra_allocations)
    loop
      if coalesce(jsonb_typeof(v_extra_entry), '') <> 'object' then
        perform app_api.raise_http(400, 'Each extra allocation entry must be an object.');
      end if;

      v_extra_box_id := app_api.require_text(v_extra_entry->>'boxId', 'extraAllocations[].boxId');
      v_extra_feet := floor(nullif(app_api.trim_text(v_extra_entry->>'allocatedFeet'), '')::numeric);

      if v_extra_feet is null or v_extra_feet <= 0 then
        perform app_api.raise_http(400, format('Extra allocation for box %s must be greater than zero.', v_extra_box_id));
      end if;

      if array_position(v_extra_processed_box_ids, v_extra_box_id) is not null then
        perform app_api.raise_http(400, format('Duplicate extra allocation entry for box %s.', v_extra_box_id));
      end if;

      select *
      into v_candidate
      from app.boxes b
      where b.org_id = p_org_id
        and b.box_id = v_extra_box_id
      for update;

      if not found then
        perform app_api.raise_http(404, format('Box not found: %s', v_extra_box_id));
      end if;

      if coalesce(v_candidate.status::text, '') = 'TRANSFER' then
        select coalesce(t.destination_warehouse::text, '')
        into v_candidate_transfer_destination
        from app.box_transfers t
        where t.org_id = p_org_id
          and t.box_record_id = v_candidate.id
          and t.status = 'PENDING'
        order by t.created_at desc, t.id desc
        limit 1;

        if coalesce(v_job_warehouse, '') = '' then
          perform app_api.raise_http(
            400,
            format('Box %s is in transfer status and needs a job warehouse before it can be allocated.', v_candidate.box_id)
          );
        end if;

        if v_candidate_transfer_destination = '' then
          perform app_api.raise_http(
            400,
            format('Box %s is in transfer status but no pending transfer was found.', v_candidate.box_id)
          );
        end if;

        if upper(v_candidate_transfer_destination) <> upper(v_job_warehouse) then
          perform app_api.raise_http(
            400,
            format(
              'Box %s is transferring to %s and cannot be allocated to a job in %s.',
              v_candidate.box_id,
              v_candidate_transfer_destination,
              v_job_warehouse
            )
          );
        end if;
      elsif coalesce(v_candidate.status::text, '') not in ('IN_STOCK', 'ORDERED') then
        perform app_api.raise_http(400, format('Box %s is no longer allocatable.', v_candidate.box_id));
      end if;

      if v_requirement_id is not null then
        if not app_api.requirement_film_is_compatible(
          p_org_id,
          v_candidate.manufacturer,
          v_candidate.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        ) or v_candidate.width_in < v_requested_width_in then
          perform app_api.raise_http(
            400,
            format(
              'Extra box %s must use a compatible film and meet the requested width for this allocation.',
              v_candidate.box_id
            )
          );
        end if;
      elsif app_api.normalize_requirement_film_key(p_org_id, v_candidate.manufacturer, v_candidate.film_name) <> v_source_film_key
        or v_candidate.width_in < v_requested_width_in then
        perform app_api.raise_http(
          400,
          format(
            'Extra box %s must match film and meet the requested width for this allocation.',
            v_candidate.box_id
          )
        );
      end if;

      v_candidate_planning_feet := app_api.allocation_planning_feet_for_box(v_candidate);
      if v_candidate_planning_feet < v_extra_feet then
        perform app_api.raise_http(400, format('Box %s no longer has enough planning LF.', v_candidate.box_id));
      end if;

      v_allocation := app_api.create_allocation(
        p_org_id,
        v_candidate,
        v_job_context,
        v_extra_feet,
        p_actor,
        '',
        'EXTRA',
        null
      );
      if coalesce(v_candidate.status::text, '') in ('IN_STOCK', 'TRANSFER') then
        v_candidate.feet_available := greatest(v_candidate.feet_available - v_extra_feet, 0);
        perform app_api.save_box(v_candidate);
      end if;
      v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
      v_extra_processed_box_ids := array_append(v_extra_processed_box_ids, v_extra_box_id);
    end loop;
  end if;

  if v_requested_feet = 0 and coalesce(array_length(v_extra_processed_box_ids, 1), 0) = 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be greater than zero unless extraAllocations are provided.');
  end if;

  if v_requirement_id is not null and v_requested_feet > 0 then
    select greatest(
      coalesce(v_requirement.required_feet, 0) - least(
        coalesce(v_requirement.required_feet, 0),
        coalesce(sum(
          case
            when coalesce(a.covered_feet, 0) > 0 then a.covered_feet
            else a.allocated_feet
          end
        ), 0)
      ),
      0
    )::integer
    into v_requirement_remaining_feet
    from app.allocations a
    join app.boxes b
      on b.org_id = a.org_id
     and upper(b.box_id) = upper(a.box_id)
    where a.org_id = p_org_id
      and a.requirement_id = v_requirement_id
      and a.status <> 'CANCELLED'
      and coalesce(a.allocation_kind::text, 'REQUIREMENT') <> 'EXTRA'
      and not (
        a.status = 'ACTIVE'
        and coalesce(b.status::text, '') in ('ZEROED', 'RETIRED')
      )
      and app_api.requirement_film_is_compatible(
        p_org_id,
        b.manufacturer,
        b.film_name,
        v_requirement.manufacturer,
        v_requirement.film_name
      )
      and coalesce(b.width_in, 0) >= coalesce(v_requirement.width_in, 0);

    if v_requirement_remaining_feet <= 0 then
      for v_cleanup_order in
        select fo.*
        from app.film_orders fo
        where fo.org_id = p_org_id
          and upper(trim(fo.job_number)) = upper(trim(v_job_context->>'jobNumber'))
          and coalesce(fo.status::text, '') in ('FILM_ORDER', 'FILM_ON_THE_WAY')
          and coalesce(trim(fo.source_box_id), '') <> ''
          and app_api.normalize_job_requirement_lookup_key(
            fo.manufacturer,
            fo.film_name,
            fo.width_in
          ) = app_api.normalize_job_requirement_lookup_key(
            v_requirement.manufacturer,
            v_requirement.film_name,
            v_requirement.width_in
          )
      loop
        select count(*)
        into v_cleanup_link_count
        from app.film_order_box_links l
        where l.org_id = p_org_id
          and l.film_order_id = v_cleanup_order.film_order_id;

        if v_cleanup_link_count > 0 then
          continue;
        end if;

        select count(*)
        into v_cleanup_allocation_count
        from app.allocations a
        where a.org_id = p_org_id
          and a.film_order_id = v_cleanup_order.film_order_id;

        if v_cleanup_allocation_count > 0 then
          continue;
        end if;

        perform app_api.delete_film_order_links_by_film_order_id(p_org_id, v_cleanup_order.film_order_id);
        perform app_api.delete_film_order(p_org_id, v_cleanup_order.film_order_id);
        v_deleted_shortage_film_order_count := v_deleted_shortage_film_order_count + 1;
      end loop;
    end if;

    if v_deleted_shortage_film_order_count > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Removed %s stale shortage film order%s for job %s after fulfilling the selected requirement.',
          v_deleted_shortage_film_order_count,
          case when v_deleted_shortage_film_order_count = 1 then '' else 's' end,
          v_job_context->>'jobNumber'
        )
      );
    end if;
  end if;

  if v_remaining > 0 then
    if coalesce(v_job_warehouse, '') = '' then
      v_job_warehouse := v_source.warehouse;
    end if;

    v_film_order.id := gen_random_uuid();
    v_film_order.org_id := p_org_id;
    v_film_order.film_order_id := app_api.create_log_id();
    v_film_order.job_id := app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber');
    v_film_order.job_number := v_job_context->>'jobNumber';
    v_film_order.warehouse := v_job_warehouse;
    v_film_order.manufacturer := coalesce(v_requirement.manufacturer, v_source.manufacturer);
    v_film_order.film_name := coalesce(v_requirement.film_name, v_source.film_name);
    v_film_order.width_in := v_requested_width_in;
    v_film_order.requested_feet := v_remaining;
    v_film_order.covered_feet := 0;
    v_film_order.ordered_feet := 0;
    v_film_order.remaining_to_order_feet := v_remaining;
    v_film_order.job_date := nullif(v_job_context->>'jobDate', '')::date;
    v_film_order.crew_leader := coalesce(v_job_context->>'crewLeader', '');
    v_film_order.status := 'FILM_ORDER';
    v_film_order.source_box_id := v_source.box_id;
    v_film_order.resolved_at := null;
    v_film_order.resolved_by := '';
    v_film_order.notes := format('Created from a shortage while trying to allocate %s LF.', v_requested_feet);
    v_film_order.created_at := now();
    v_film_order.created_by := app_api.trim_text(p_actor);
    v_film_order := app_api.save_film_order(v_film_order);
    v_warnings := app_api.push_warning(
      v_warnings,
      format('Film Order %s was created for the remaining %s LF.', v_film_order.film_order_id, v_remaining)
    );
  end if;

  return jsonb_build_object(
    'allocationIds', to_jsonb(v_allocation_ids),
    'filmOrderId', coalesce(v_film_order.film_order_id, ''),
    'remainingUncoveredFeet', greatest(v_remaining, 0),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function app_api.plan_transfer_destination_box_id(
  p_org_id uuid,
  p_box_id text,
  p_source_prefix text,
  p_destination_prefix text
)
returns text
language plpgsql
stable
security definer
set search_path = public, app, app_api
as $$
declare
  v_box_id text := upper(app_api.require_text(p_box_id, 'BoxID'));
  v_source_prefix text := upper(app_api.require_text(p_source_prefix, 'Source box prefix'));
  v_destination_prefix text := upper(app_api.require_text(p_destination_prefix, 'Destination box prefix'));
  v_remainder text;
  v_segments text[];
  v_origin_index integer := 0;
  v_origin_prefix text := '';
  v_local_segments text[];
  v_extra_segments text[] := '{}'::text[];
  v_result_segments text[];
  v_index integer;
  v_candidate text;
begin
  if left(v_box_id, length(v_source_prefix) + 1) = v_source_prefix || '-' then
    v_remainder := substr(v_box_id, length(v_source_prefix) + 2);
  elsif strpos(v_box_id, '-') > 0 then
    v_remainder := substr(v_box_id, strpos(v_box_id, '-') + 1);
  else
    v_remainder := v_box_id;
  end if;

  v_segments := array_remove(regexp_split_to_array(v_remainder, '-'), '');
  if coalesce(array_length(v_segments, 1), 0) = 0 then
    v_segments := array[v_box_id];
  end if;

  if coalesce(array_length(v_segments, 1), 0) >= 2 then
    for v_index in 2..array_length(v_segments, 1) loop
      v_candidate := upper(coalesce(v_segments[v_index], ''));
      if v_candidate = v_source_prefix then
        continue;
      end if;

      if exists (
        select 1
        from app.warehouses w
        where w.org_id = p_org_id
          and coalesce(nullif(upper(btrim(w.box_id_prefix)), ''), upper(btrim(w.code))) = v_candidate
      ) then
        v_origin_index := v_index;
        exit;
      end if;
    end loop;
  end if;

  if v_origin_index > 0 then
    v_origin_prefix := upper(v_segments[v_origin_index]);
    v_local_segments := v_segments[1:v_origin_index - 1];
    if array_length(v_segments, 1) > v_origin_index then
      v_extra_segments := v_segments[v_origin_index + 1:array_length(v_segments, 1)];
    end if;
  else
    v_local_segments := v_segments;
  end if;

  if coalesce(array_length(v_local_segments, 1), 0) = 0 then
    v_local_segments := array[v_box_id];
  end if;

  if v_origin_prefix <> '' and v_origin_prefix = v_destination_prefix then
    v_result_segments := array_cat(v_local_segments, v_extra_segments);
  elsif v_origin_prefix <> '' then
    v_result_segments := array_cat(v_local_segments, array[v_origin_prefix]);
    v_result_segments := array_cat(v_result_segments, v_extra_segments);
  else
    v_result_segments := array_cat(v_local_segments, array[v_source_prefix]);
  end if;

  return v_destination_prefix || '-' || array_to_string(v_result_segments, '-');
end;
$$;

with pending_transfer_destinations as (
  select
    t.id,
    app_api.plan_transfer_destination_box_id(
      t.org_id,
      t.source_box_id,
      coalesce(nullif(upper(btrim(sw.box_id_prefix)), ''), upper(btrim(sw.code))),
      coalesce(nullif(upper(btrim(dw.box_id_prefix)), ''), upper(btrim(dw.code)))
    ) as destination_box_id
  from app.box_transfers t
  join app.warehouses sw
    on sw.org_id = t.org_id
   and sw.code = t.source_warehouse
  join app.warehouses dw
    on dw.org_id = t.org_id
   and dw.code = t.destination_warehouse
  where t.status = 'PENDING'
)
update app.box_transfers t
set
  destination_box_id = p.destination_box_id,
  updated_at = now()
from pending_transfer_destinations p
where t.id = p.id
  and t.destination_box_id <> p.destination_box_id;

create unique index if not exists idx_box_transfers_one_pending_destination_box
  on app.box_transfers (org_id, destination_box_id)
  where status = 'PENDING';

create or replace function public.api_jobs_create(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_now timestamptz := now();
  v_has_film_requirements boolean := exists (
    select 1
    from app_api.requirement_rows_from_payload(p_payload->'requirements')
  );
  v_has_caulk_requirements boolean := exists (
    select 1
    from app_api.caulk_requirement_rows_from_payload(p_payload->'caulkRequirements')
  );
  v_has_labor_only_input boolean := coalesce(p_payload ? 'isLaborOnly', false) or coalesce(p_payload ? 'is_labor_only', false);
  v_labor_only_text text := lower(
    app_api.trim_text(coalesce(p_payload->>'isLaborOnly', p_payload->>'is_labor_only'))
  );
  v_is_labor_only boolean := false;
  v_had_labor_only boolean := false;
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and j.job_number = app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number')
  for update;

  if not found then
    v_job.id := gen_random_uuid();
    v_job.created_at := v_now;
    v_job.created_by := app_api.trim_text(p_actor);
    v_job.is_staged_for_pickup := false;
    v_job.is_labor_only := false;
  end if;

  v_had_labor_only := coalesce(v_job.is_labor_only, false);

  v_job.org_id := p_org_id;
  v_job.job_number := app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number');
  v_job.warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'warehouse', 'Warehouse');
  v_job.sections := app_api.normalize_job_sections(p_payload->>'sections');
  v_job.due_date := nullif(
    app_api.trim_text(coalesce(p_payload->>'installDate', p_payload->>'dueDate')),
    ''
  )::date;
  v_job.crew_leader := app_api.trim_text(p_payload->>'crewLeader');
  v_job.lifecycle_status := app_api.normalize_job_lifecycle_status(p_payload->>'lifecycleStatus');
  v_job.notes := app_api.trim_text(p_payload->>'notes');

  if v_has_labor_only_input then
    if v_labor_only_text in ('true', 't', '1', 'yes', 'on') then
      v_is_labor_only := true;
    elsif v_labor_only_text in ('false', 'f', '0', 'no', 'off') then
      v_is_labor_only := false;
    else
      perform app_api.raise_http(400, 'isLaborOnly must be true or false.');
    end if;
  else
    v_is_labor_only := v_had_labor_only;
  end if;

  if v_has_film_requirements or v_has_caulk_requirements then
    v_is_labor_only := false;
    if v_had_labor_only then
      v_job.is_staged_for_pickup := false;
    end if;
  elsif v_is_labor_only then
    v_job.is_staged_for_pickup := true;
  elsif v_has_labor_only_input and not v_is_labor_only and v_had_labor_only then
    v_job.is_staged_for_pickup := false;
  end if;

  v_job.is_labor_only := v_is_labor_only;
  v_job.updated_at := v_now;
  v_job.updated_by := app_api.trim_text(p_actor);

  v_job := app_api.save_job(v_job);
  perform app_api.replace_job_requirements(p_org_id, v_job, p_payload->'requirements', p_actor, v_now);
  perform app_api.replace_job_caulk_requirements(p_org_id, v_job, p_payload->'caulkRequirements', p_actor, v_now);

  return jsonb_build_object(
    'jobNumber', v_job.job_number,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_jobs_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_now timestamptz := now();
  v_has_film_requirements boolean := exists (
    select 1
    from app_api.requirement_rows_from_payload(p_payload->'requirements')
  );
  v_has_caulk_requirements boolean := exists (
    select 1
    from app_api.caulk_requirement_rows_from_payload(p_payload->'caulkRequirements')
  );
  v_has_labor_only_input boolean := coalesce(p_payload ? 'isLaborOnly', false) or coalesce(p_payload ? 'is_labor_only', false);
  v_labor_only_text text := lower(
    app_api.trim_text(coalesce(p_payload->>'isLaborOnly', p_payload->>'is_labor_only'))
  );
  v_is_labor_only boolean := false;
  v_had_labor_only boolean := false;
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and j.job_number = app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number')
  for update;

  if not found then
    v_job.id := gen_random_uuid();
    v_job.org_id := p_org_id;
    v_job.job_number := app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number');
    v_job.warehouse := coalesce(
      case
        when app_api.trim_text(p_payload->>'warehouse') <> ''
          then app_api.require_org_warehouse(p_org_id, p_payload->>'warehouse', 'Warehouse')
        else null
      end,
      (
        select w.code
        from app.warehouses w
        where w.org_id = p_org_id
          and w.box_id_prefix = ''
        order by case when w.code = 'IL' then 0 else 1 end, w.code
        limit 1
      ),
      (
        select w.code
        from app.warehouses w
        where w.org_id = p_org_id
        order by w.code
        limit 1
      )
    );
    if v_job.warehouse is null then
      perform app_api.raise_http(400, 'No warehouse is configured for this organization.');
    end if;
    v_job.sections := null;
    v_job.due_date := null;
    v_job.crew_leader := '';
    v_job.lifecycle_status := 'ACTIVE';
    v_job.is_staged_for_pickup := false;
    v_job.is_labor_only := false;
    v_job.notes := '';
    v_job.created_at := v_now;
    v_job.created_by := app_api.trim_text(p_actor);
  end if;

  v_had_labor_only := coalesce(v_job.is_labor_only, false);

  if p_payload ? 'warehouse' then
    v_job.warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'warehouse', 'Warehouse');
  end if;
  if p_payload ? 'sections' then
    v_job.sections := app_api.normalize_job_sections(p_payload->>'sections');
  end if;
  if p_payload ? 'installDate' or p_payload ? 'dueDate' then
    v_job.due_date := nullif(
      app_api.trim_text(coalesce(p_payload->>'installDate', p_payload->>'dueDate')),
      ''
    )::date;
  end if;
  if p_payload ? 'crewLeader' then
    v_job.crew_leader := app_api.trim_text(p_payload->>'crewLeader');
  end if;
  if p_payload ? 'lifecycleStatus' then
    v_job.lifecycle_status := app_api.normalize_job_lifecycle_status(p_payload->>'lifecycleStatus');
  end if;
  if p_payload ? 'notes' then
    v_job.notes := app_api.trim_text(p_payload->>'notes');
  end if;

  if v_has_labor_only_input then
    if v_labor_only_text in ('true', 't', '1', 'yes', 'on') then
      v_is_labor_only := true;
    elsif v_labor_only_text in ('false', 'f', '0', 'no', 'off') then
      v_is_labor_only := false;
    else
      perform app_api.raise_http(400, 'isLaborOnly must be true or false.');
    end if;
  else
    v_is_labor_only := v_had_labor_only;
  end if;

  if v_has_film_requirements or v_has_caulk_requirements then
    v_is_labor_only := false;
    if v_had_labor_only then
      v_job.is_staged_for_pickup := false;
    end if;
  elsif v_is_labor_only then
    v_job.is_staged_for_pickup := true;
  elsif v_has_labor_only_input and not v_is_labor_only and v_had_labor_only then
    v_job.is_staged_for_pickup := false;
  end if;

  v_job.is_labor_only := v_is_labor_only;
  v_job.updated_at := v_now;
  v_job.updated_by := app_api.trim_text(p_actor);
  v_job := app_api.save_job(v_job);
  perform app_api.replace_job_requirements(p_org_id, v_job, p_payload->'requirements', p_actor, v_now);
  perform app_api.replace_job_caulk_requirements(p_org_id, v_job, p_payload->'caulkRequirements', p_actor, v_now);

  return jsonb_build_object(
    'jobNumber', v_job.job_number,
    'warnings', '[]'::jsonb
  );
end;
$$;

-- Missing-initial-weight film return check-in parity:
-- - allow check-ins to calibrate from return weight + current LF when initial weight history is incomplete
-- - release the checked-out job's planning allocation rows during return
-- - log roll-history usage against physical feet before/after the return instead of reservation-adjusted feet

create or replace function app_api.box_can_derive_checkin_feet_from_weight(p_box app.boxes)
returns boolean
language sql
immutable
as $$
  select
    p_box.core_weight_lbs is not null
    and p_box.lf_weight_lbs_per_ft is not null
    and p_box.lf_weight_lbs_per_ft > 0;
$$;

create or replace function app_api.box_can_derive_stored_physical_feet_from_weight(p_box app.boxes)
returns boolean
language sql
immutable
as $$
  select
    app_api.box_can_derive_checkin_feet_from_weight(p_box)
    and p_box.last_roll_weight_lbs is not null;
$$;

create or replace function app_api.derive_box_physical_feet_before_checkin(
  p_box app.boxes,
  p_active_allocated_feet integer
)
returns integer
language sql
immutable
as $$
  select
    case
      when app_api.box_can_derive_stored_physical_feet_from_weight(p_box) then
        app_api.derive_feet_available_from_roll_weight(
          p_box.last_roll_weight_lbs,
          p_box.core_weight_lbs,
          p_box.lf_weight_lbs_per_ft,
          p_box.initial_feet
        )
      else
        app_api.clamp_feet_to_initial_range(
          coalesce(p_box.feet_available, 0) + coalesce(p_active_allocated_feet, 0),
          p_box.initial_feet
        )
    end;
$$;

create or replace function app_api.cancel_active_allocations_for_box_job_checkin(
  p_org_id uuid,
  p_actor text,
  p_box_id text,
  p_job_number text,
  p_reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_entry app.allocations;
  v_reason text := coalesce(
    nullif(app_api.trim_text(p_reason), ''),
    format('Returned to stock during check-in for job %s.', app_api.trim_text(p_job_number))
  );
  v_cancelled_count integer := 0;
  v_cancelled_feet integer := 0;
  v_affected_film_order_ids text[] := array[]::text[];
  v_film_order_id text;
begin
  if app_api.trim_text(p_job_number) = '' then
    return jsonb_build_object(
      'cancelledCount', 0,
      'cancelledFeet', 0
    );
  end if;

  for v_entry in
    select *
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = app_api.trim_text(p_box_id)
      and a.status = 'ACTIVE'
      and upper(coalesce(a.job_number, '')) = upper(app_api.trim_text(p_job_number))
    for update
  loop
    v_entry.status := 'CANCELLED';
    v_entry.resolved_at := now();
    v_entry.resolved_by := app_api.trim_text(p_actor);
    v_entry.notes := v_reason;
    perform app_api.save_allocation(v_entry);

    if coalesce(v_entry.film_order_id, '') <> ''
      and not (v_entry.film_order_id = any(v_affected_film_order_ids)) then
      v_affected_film_order_ids := array_append(v_affected_film_order_ids, v_entry.film_order_id);
    end if;

    v_cancelled_count := v_cancelled_count + 1;
    v_cancelled_feet := v_cancelled_feet + coalesce(v_entry.allocated_feet, 0);
  end loop;

  foreach v_film_order_id in array v_affected_film_order_ids
  loop
    perform app_api.recalculate_film_order(p_org_id, v_film_order_id, p_actor);
  end loop;

  return jsonb_build_object(
    'cancelledCount', v_cancelled_count,
    'cancelledFeet', v_cancelled_feet
  );
end;
$$;

create or replace function public.api_boxes_set_status(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_box app.boxes;
  v_status text := upper(app_api.require_text(p_payload->>'status', 'Status'));
  v_log_id text;
  v_public_before jsonb;
  v_public_after jsonb;
  v_warnings text[] := array[]::text[];
  v_checkout_job text := '';
  v_resolution jsonb;
  v_checkout_audit app.audit_log;
  v_checkout_user text := '';
  v_checkout_date text := '';
  v_weight_delta numeric;
  v_last_roll_weight numeric;
  v_current_feet_text text := app_api.trim_text(p_payload->>'currentFeetOnRoll');
  v_current_feet_on_roll integer := null;
  v_submitted_core_type text := app_api.normalize_core_type(p_payload->>'coreType', true);
  v_resolved_core_type text := '';
  v_resolved_core_weight numeric := null;
  v_resolved_lf_weight numeric := null;
  v_active_allocated_feet_before integer := 0;
  v_same_job_active_allocation_count integer := 0;
  v_same_job_active_allocated_feet integer := 0;
  v_other_active_allocated_feet integer := 0;
  v_other_jobs text[] := array[]::text[];
  v_physical_feet_before integer := 0;
  v_physical_feet_after integer := 0;
  v_auto_move_to_zeroed boolean := false;
  v_reached_zero_state boolean := false;
  v_same_job_release jsonb := jsonb_build_object(
    'cancelledCount', 0,
    'cancelledFeet', 0
  );
begin
  perform app_api.require_org_member(p_org_id);

  if v_status not in ('IN_STOCK', 'CHECKED_OUT') then
    perform app_api.raise_http(400, 'Status must be IN_STOCK or CHECKED_OUT.');
  end if;

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_existing.received_date is null then
    perform app_api.raise_http(400, 'Add a ReceivedDate on or before today before changing status.');
  end if;

  if v_existing.status in ('ZEROED', 'RETIRED') then
    perform app_api.raise_http(400, 'This box cannot change status directly. Use audit undo instead.');
  end if;

  v_box := v_existing;
  v_public_before := app_api.public_box_json(v_existing);

  if v_status = 'CHECKED_OUT' then
    v_checkout_job := app_api.parse_checkout_job_from_note(p_payload->>'auditNote');
    if v_checkout_job = '' then
      perform app_api.raise_http(400, 'A checkout job number is required.');
    end if;

    v_box.status := 'CHECKED_OUT';
    v_box.has_ever_been_checked_out := true;
    v_box.last_checkout_job := v_checkout_job;
    v_box.last_checkout_date := app_api.today_date();
    v_box.zeroed_date := null;
    v_box.zeroed_reason := '';
    v_box.zeroed_by := '';

    v_resolution := app_api.resolve_allocations_for_checkout(p_org_id, v_box.box_id, v_checkout_job, p_actor);
    if coalesce((v_resolution->>'fulfilledCount')::integer, 0) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Kept %s allocation%s totaling %s LF linked to job %s after checkout.',
          (v_resolution->>'fulfilledCount')::integer,
          case when (v_resolution->>'fulfilledCount')::integer = 1 then '' else 's' end,
          (v_resolution->>'fulfilledFeet')::integer,
          v_checkout_job
        )
      );
    end if;

    if jsonb_array_length(coalesce(v_resolution->'otherJobs', '[]'::jsonb)) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'This box still has active allocations for ' ||
          array_to_string(array(select jsonb_array_elements_text(v_resolution->'otherJobs')), ', ') || '.'
      );
    end if;
  else
    v_last_roll_weight := nullif(app_api.trim_text(p_payload->>'lastRollWeightLbs'), '')::numeric;
    if v_last_roll_weight is null then
      perform app_api.raise_http(400, 'LastRollWeightLbs is required.');
    end if;

    if v_last_roll_weight < 0 then
      perform app_api.raise_http(400, 'LastRollWeightLbs must be zero or greater.');
    end if;

    if v_current_feet_text <> '' and v_current_feet_text !~ '^[0-9]+$' then
      perform app_api.raise_http(400, 'CurrentFeetOnRoll must be a whole number greater than or equal to 0.');
    end if;

    if v_current_feet_text <> '' then
      v_current_feet_on_roll := v_current_feet_text::integer;
    end if;

    v_box.status := 'IN_STOCK';
    v_box.last_roll_weight_lbs := v_last_roll_weight;
    v_box.last_weighed_date := app_api.today_date();

    select *
    into v_checkout_audit
    from app.audit_log a
    where a.org_id = p_org_id
      and a.box_id = v_box.box_id
      and a.action = 'SET_STATUS'
      and coalesce(a.after_state->>'status', '') = 'CHECKED_OUT'
    order by a.created_at desc, a.log_id desc
    limit 1;

    v_checkout_job := coalesce(nullif(v_existing.last_checkout_job, ''), app_api.parse_checkout_job_from_note(v_checkout_audit.notes));
    v_checkout_date := coalesce(to_char(v_existing.last_checkout_date, 'YYYY-MM-DD'), '');
    if v_checkout_date = '' then
      v_checkout_date := coalesce(substr(v_checkout_audit.created_at::text, 1, 10), '');
    end if;
    v_checkout_user := coalesce(v_checkout_audit.actor, '');

    if v_checkout_date = '' then
      v_checkout_date := app_api.today_date()::text;
    end if;

    select coalesce(sum(a.allocated_feet), 0)::integer
    into v_active_allocated_feet_before
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_box.box_id
      and a.status = 'ACTIVE';

    if v_checkout_job <> '' then
      select
        count(*)::integer,
        coalesce(sum(a.allocated_feet), 0)::integer
      into v_same_job_active_allocation_count, v_same_job_active_allocated_feet
      from app.allocations a
      where a.org_id = p_org_id
        and a.box_id = v_box.box_id
        and a.status = 'ACTIVE'
        and upper(coalesce(a.job_number, '')) = upper(v_checkout_job);

      select
        coalesce(sum(a.allocated_feet), 0)::integer,
        coalesce(
          array_agg(distinct a.job_number) filter (
            where coalesce(a.job_number, '') <> ''
          ),
          array[]::text[]
        )
      into v_other_active_allocated_feet, v_other_jobs
      from app.allocations a
      where a.org_id = p_org_id
        and a.box_id = v_box.box_id
        and a.status = 'ACTIVE'
        and upper(coalesce(a.job_number, '')) <> upper(v_checkout_job);
    else
      v_same_job_active_allocation_count := 0;
      v_same_job_active_allocated_feet := 0;

      select
        coalesce(sum(a.allocated_feet), 0)::integer,
        coalesce(
          array_agg(distinct a.job_number) filter (
            where coalesce(a.job_number, '') <> ''
          ),
          array[]::text[]
        )
      into v_other_active_allocated_feet, v_other_jobs
      from app.allocations a
      where a.org_id = p_org_id
        and a.box_id = v_box.box_id
        and a.status = 'ACTIVE';
    end if;

    v_physical_feet_before := app_api.derive_box_physical_feet_before_checkin(
      v_existing,
      v_active_allocated_feet_before
    );

    if app_api.box_can_derive_checkin_feet_from_weight(v_existing) then
      v_physical_feet_after := app_api.derive_feet_available_from_roll_weight(
        v_last_roll_weight,
        v_existing.core_weight_lbs,
        v_existing.lf_weight_lbs_per_ft,
        v_existing.initial_feet
      );
      v_resolved_core_type := coalesce(app_api.normalize_core_type(v_existing.core_type, true), '');
      v_resolved_core_weight := v_existing.core_weight_lbs;
      v_resolved_lf_weight := v_existing.lf_weight_lbs_per_ft;
    else
      if v_current_feet_on_roll is null then
        perform app_api.raise_http(
          400,
          'CurrentFeetOnRoll is required when this box cannot derive feet from weight alone.'
        );
      end if;

      if v_current_feet_on_roll > v_existing.initial_feet then
        perform app_api.raise_http(
          400,
          format(
            'CurrentFeetOnRoll cannot be greater than this box''s InitialFeet (%s).',
            v_existing.initial_feet
          )
        );
      end if;

      v_physical_feet_after := v_current_feet_on_roll;

      if v_current_feet_on_roll = 0 then
        if v_last_roll_weight > 0 then
          perform app_api.raise_http(
            400,
            'CurrentFeetOnRoll cannot be 0 while LastRollWeightLbs is still above 0.'
          );
        end if;

        v_resolved_core_type := coalesce(
          nullif(v_submitted_core_type, ''),
          app_api.normalize_core_type(v_existing.core_type, true),
          ''
        );
        if v_existing.core_weight_lbs is not null then
          v_resolved_core_weight := v_existing.core_weight_lbs;
        elsif v_resolved_core_type <> '' then
          v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_existing.width_in);
        else
          v_resolved_core_weight := null;
        end if;
        v_resolved_lf_weight := v_existing.lf_weight_lbs_per_ft;
      else
        if v_submitted_core_type <> '' then
          v_resolved_core_type := v_submitted_core_type;
          v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_existing.width_in);
        elsif v_existing.core_weight_lbs is not null then
          v_resolved_core_type := coalesce(app_api.normalize_core_type(v_existing.core_type, true), '');
          v_resolved_core_weight := v_existing.core_weight_lbs;
        elsif coalesce(app_api.normalize_core_type(v_existing.core_type, true), '') <> '' then
          v_resolved_core_type := app_api.normalize_core_type(v_existing.core_type, true);
          v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_existing.width_in);
        else
          perform app_api.raise_http(
            400,
            'CoreType is required before this return can establish future weight-based LF math.'
          );
        end if;

        if v_last_roll_weight <= v_resolved_core_weight then
          perform app_api.raise_http(
            400,
            'LastRollWeightLbs must be greater than the core weight when CurrentFeetOnRoll is above 0.'
          );
        end if;

        v_resolved_lf_weight := round(
          ((v_last_roll_weight - v_resolved_core_weight) / v_current_feet_on_roll)::numeric,
          6
        );
      end if;
    end if;

    if v_other_active_allocated_feet > v_physical_feet_after then
      perform app_api.raise_http(
        400,
        format(
          'Received physical LF cannot be lower than the box''s active allocated feet (%s).',
          v_other_active_allocated_feet
        )
      );
    end if;

    if v_same_job_active_allocation_count > 0 and v_checkout_job <> '' then
      v_same_job_release := app_api.cancel_active_allocations_for_box_job_checkin(
        p_org_id,
        p_actor,
        v_box.box_id,
        v_checkout_job
      );

      if coalesce((v_same_job_release->>'cancelledCount')::integer, 0) > 0 then
        v_warnings := app_api.push_warning(
          v_warnings,
          format(
            'Released %s active planning allocation%s totaling %s LF for job %s during check-in.',
            coalesce((v_same_job_release->>'cancelledCount')::integer, 0),
            case when coalesce((v_same_job_release->>'cancelledCount')::integer, 0) = 1 then '' else 's' end,
            coalesce((v_same_job_release->>'cancelledFeet')::integer, 0),
            v_checkout_job
          )
        );
      end if;
    end if;

    if coalesce(array_length(v_other_jobs, 1), 0) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'This box still has active allocations for ' || array_to_string(v_other_jobs, ', ') || '.'
      );
    end if;

    if v_resolved_core_type <> '' then
      v_box.core_type := v_resolved_core_type;
    end if;
    v_box.core_weight_lbs := v_resolved_core_weight;
    v_box.lf_weight_lbs_per_ft := v_resolved_lf_weight;
    v_box.feet_available := greatest(v_physical_feet_after - v_other_active_allocated_feet, 0);

    if v_existing.last_roll_weight_lbs is not null and v_box.last_roll_weight_lbs > v_existing.last_roll_weight_lbs then
      v_warnings := app_api.push_warning(
        v_warnings,
        'The new Last Roll Weight is greater than the box''s previous Last Roll Weight.'
      );
    end if;

    if v_existing.initial_weight_lbs is not null and v_box.last_roll_weight_lbs > v_existing.initial_weight_lbs then
      v_warnings := app_api.push_warning(
        v_warnings,
        'The new Last Roll Weight is greater than the box''s Initial Weight.'
      );
    end if;

    if
      v_box.last_roll_weight_lbs is not null
      and v_box.last_roll_weight_lbs > 0
      and v_box.core_weight_lbs is not null
      and v_box.last_roll_weight_lbs < v_box.core_weight_lbs
    then
      v_warnings := app_api.push_warning(
        v_warnings,
        'The new Last Roll Weight is below the derived core weight.'
      );
    end if;

    if v_physical_feet_after > v_physical_feet_before then
      v_warnings := app_api.push_warning(
        v_warnings,
        'The recalculated Available Feet would increase compared with the current box.'
      );
    end if;

    v_auto_move_to_zeroed :=
      v_box.received_date is not null
      and v_existing.initial_feet > 0
      and (v_physical_feet_after = 0 or coalesce(v_box.last_roll_weight_lbs, 0) = 0);

    if v_auto_move_to_zeroed then
      v_warnings := app_api.push_warning(
        v_warnings,
        'This check-in will auto-move the box into zeroed out inventory.'
      );
    end if;

    if v_other_active_allocated_feet > 0 and v_box.feet_available = 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'All remaining LF on this box is reserved by active allocations.'
      );
    end if;

    if v_checkout_job = '' then
      v_checkout_job := 'UNKNOWN';
      v_warnings := app_api.push_warning(
        v_warnings,
        'Roll history was logged with UNKNOWN job number because no checkout job was saved.'
      );
    end if;

    v_weight_delta := case
      when v_existing.last_roll_weight_lbs is null then null
      else round(v_existing.last_roll_weight_lbs - v_box.last_roll_weight_lbs, 2)
    end;

    if v_existing.last_roll_weight_lbs is null then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Roll history was logged without an outbound weight because no Last Roll Weight was saved at checkout.'
      );
    end if;

    perform app_api.append_roll_history_entry(
      p_org_id,
      row(
        gen_random_uuid(),
        p_org_id,
        app_api.create_log_id(),
        v_box.box_id,
        v_box.warehouse,
        v_box.manufacturer,
        v_box.film_name,
        v_box.width_in,
        v_checkout_job,
        coalesce(nullif(v_checkout_date, '')::timestamptz, now()),
        v_checkout_user,
        v_existing.last_roll_weight_lbs,
        now(),
        app_api.trim_text(p_actor),
        v_box.last_roll_weight_lbs,
        v_weight_delta,
        v_physical_feet_before,
        v_physical_feet_after,
        app_api.trim_text(p_payload->>'auditNote')
      )::app.roll_weight_log
    );

    v_box.last_checkout_job := '';
    v_box.last_checkout_date := null;

    v_reached_zero_state :=
      v_box.received_date is not null
      and (v_physical_feet_after = 0 or coalesce(v_box.last_roll_weight_lbs, 0) = 0);

    if v_auto_move_to_zeroed then
      v_box.status := 'ZEROED';
      v_box.feet_available := 0;
      v_box.zeroed_date := app_api.today_date();
      v_box.zeroed_reason := app_api.determine_zeroed_reason(v_box.feet_available, v_box.last_roll_weight_lbs);
      v_box.zeroed_by := app_api.trim_text(p_actor);
      perform app_api.cancel_active_allocations_for_box(
        p_org_id,
        v_box.box_id,
        p_actor,
        'Auto-cancelled because the box was moved to zeroed out inventory.'
      );
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was automatically moved to zeroed out inventory because Available Feet or Last Roll Weight reached 0.'
      );
    elsif v_reached_zero_state and coalesce(v_existing.feet_available, 0) <= 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box stayed in active inventory because it has not had Available Feet above 0 yet.'
      );
    end if;
  end if;

  v_box := app_api.save_box(v_box);
  v_public_after := app_api.public_box_json(v_box);
  v_log_id := app_api.append_audit_entry(
    p_org_id,
    case when v_box.status = 'ZEROED' and v_status = 'IN_STOCK' then 'ZERO_OUT_BOX' else 'SET_STATUS' end,
    v_box.box_id,
    v_public_before,
    v_public_after,
    p_actor,
    app_api.trim_text(p_payload->>'auditNote')
  );

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

-- Restore linked film-order receipt resolution during box check-in.

create or replace function public.api_boxes_set_status(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_box app.boxes;
  v_status text := upper(app_api.require_text(p_payload->>'status', 'Status'));
  v_log_id text;
  v_public_before jsonb;
  v_public_after jsonb;
  v_warnings text[] := array[]::text[];
  v_checkout_job text := '';
  v_resolution jsonb;
  v_checkout_audit app.audit_log;
  v_checkout_user text := '';
  v_checkout_date text := '';
  v_weight_delta numeric;
  v_last_roll_weight numeric;
  v_current_feet_text text := app_api.trim_text(p_payload->>'currentFeetOnRoll');
  v_current_feet_on_roll integer := null;
  v_submitted_core_type text := app_api.normalize_core_type(p_payload->>'coreType', true);
  v_resolved_core_type text := '';
  v_resolved_core_weight numeric := null;
  v_resolved_lf_weight numeric := null;
  v_active_allocated_feet_before integer := 0;
  v_same_job_active_allocation_count integer := 0;
  v_same_job_active_allocated_feet integer := 0;
  v_other_active_allocated_feet integer := 0;
  v_other_jobs text[] := array[]::text[];
  v_physical_feet_before integer := 0;
  v_physical_feet_after integer := 0;
  v_auto_move_to_zeroed boolean := false;
  v_reached_zero_state boolean := false;
  v_same_job_release jsonb := jsonb_build_object(
    'cancelledCount', 0,
    'cancelledFeet', 0
  );
  v_receipt_result jsonb := jsonb_build_object('warnings', '[]'::jsonb);
begin
  perform app_api.require_org_member(p_org_id);

  if v_status not in ('IN_STOCK', 'CHECKED_OUT') then
    perform app_api.raise_http(400, 'Status must be IN_STOCK or CHECKED_OUT.');
  end if;

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if v_existing.received_date is null then
    perform app_api.raise_http(400, 'Add a ReceivedDate on or before today before changing status.');
  end if;

  if v_existing.status in ('ZEROED', 'RETIRED') then
    perform app_api.raise_http(400, 'This box cannot change status directly. Use audit undo instead.');
  end if;

  v_box := v_existing;
  v_public_before := app_api.public_box_json(v_existing);

  if v_status = 'CHECKED_OUT' then
    v_checkout_job := app_api.parse_checkout_job_from_note(p_payload->>'auditNote');
    if v_checkout_job = '' then
      perform app_api.raise_http(400, 'A checkout job number is required.');
    end if;

    v_box.status := 'CHECKED_OUT';
    v_box.has_ever_been_checked_out := true;
    v_box.last_checkout_job := v_checkout_job;
    v_box.last_checkout_date := app_api.today_date();
    v_box.zeroed_date := null;
    v_box.zeroed_reason := '';
    v_box.zeroed_by := '';

    v_resolution := app_api.resolve_allocations_for_checkout(p_org_id, v_box.box_id, v_checkout_job, p_actor);
    if coalesce((v_resolution->>'fulfilledCount')::integer, 0) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Kept %s allocation%s totaling %s LF linked to job %s after checkout.',
          (v_resolution->>'fulfilledCount')::integer,
          case when (v_resolution->>'fulfilledCount')::integer = 1 then '' else 's' end,
          (v_resolution->>'fulfilledFeet')::integer,
          v_checkout_job
        )
      );
    end if;

    if jsonb_array_length(coalesce(v_resolution->'otherJobs', '[]'::jsonb)) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'This box still has active allocations for ' ||
          array_to_string(array(select jsonb_array_elements_text(v_resolution->'otherJobs')), ', ') || '.'
      );
    end if;
  else
    v_last_roll_weight := nullif(app_api.trim_text(p_payload->>'lastRollWeightLbs'), '')::numeric;
    if v_last_roll_weight is null then
      perform app_api.raise_http(400, 'LastRollWeightLbs is required.');
    end if;

    if v_last_roll_weight < 0 then
      perform app_api.raise_http(400, 'LastRollWeightLbs must be zero or greater.');
    end if;

    if v_current_feet_text <> '' and v_current_feet_text !~ '^[0-9]+$' then
      perform app_api.raise_http(400, 'CurrentFeetOnRoll must be a whole number greater than or equal to 0.');
    end if;

    if v_current_feet_text <> '' then
      v_current_feet_on_roll := v_current_feet_text::integer;
    end if;

    v_box.status := 'IN_STOCK';
    v_box.last_roll_weight_lbs := v_last_roll_weight;
    v_box.last_weighed_date := app_api.today_date();

    select *
    into v_checkout_audit
    from app.audit_log a
    where a.org_id = p_org_id
      and a.box_id = v_box.box_id
      and a.action = 'SET_STATUS'
      and coalesce(a.after_state->>'status', '') = 'CHECKED_OUT'
    order by a.created_at desc, a.log_id desc
    limit 1;

    v_checkout_job := coalesce(nullif(v_existing.last_checkout_job, ''), app_api.parse_checkout_job_from_note(v_checkout_audit.notes));
    v_checkout_date := coalesce(to_char(v_existing.last_checkout_date, 'YYYY-MM-DD'), '');
    if v_checkout_date = '' then
      v_checkout_date := coalesce(substr(v_checkout_audit.created_at::text, 1, 10), '');
    end if;
    v_checkout_user := coalesce(v_checkout_audit.actor, '');

    if v_checkout_date = '' then
      v_checkout_date := app_api.today_date()::text;
    end if;

    select coalesce(sum(a.allocated_feet), 0)::integer
    into v_active_allocated_feet_before
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_box.box_id
      and a.status = 'ACTIVE';

    if v_checkout_job <> '' then
      select
        count(*)::integer,
        coalesce(sum(a.allocated_feet), 0)::integer
      into v_same_job_active_allocation_count, v_same_job_active_allocated_feet
      from app.allocations a
      where a.org_id = p_org_id
        and a.box_id = v_box.box_id
        and a.status = 'ACTIVE'
        and upper(coalesce(a.job_number, '')) = upper(v_checkout_job);

      select
        coalesce(sum(a.allocated_feet), 0)::integer,
        coalesce(
          array_agg(distinct a.job_number) filter (
            where coalesce(a.job_number, '') <> ''
          ),
          array[]::text[]
        )
      into v_other_active_allocated_feet, v_other_jobs
      from app.allocations a
      where a.org_id = p_org_id
        and a.box_id = v_box.box_id
        and a.status = 'ACTIVE'
        and upper(coalesce(a.job_number, '')) <> upper(v_checkout_job);
    else
      v_same_job_active_allocation_count := 0;
      v_same_job_active_allocated_feet := 0;

      select
        coalesce(sum(a.allocated_feet), 0)::integer,
        coalesce(
          array_agg(distinct a.job_number) filter (
            where coalesce(a.job_number, '') <> ''
          ),
          array[]::text[]
        )
      into v_other_active_allocated_feet, v_other_jobs
      from app.allocations a
      where a.org_id = p_org_id
        and a.box_id = v_box.box_id
        and a.status = 'ACTIVE';
    end if;

    v_physical_feet_before := app_api.derive_box_physical_feet_before_checkin(
      v_existing,
      v_active_allocated_feet_before
    );

    if app_api.box_can_derive_checkin_feet_from_weight(v_existing) then
      v_physical_feet_after := app_api.derive_feet_available_from_roll_weight(
        v_last_roll_weight,
        v_existing.core_weight_lbs,
        v_existing.lf_weight_lbs_per_ft,
        v_existing.initial_feet
      );
      v_resolved_core_type := coalesce(app_api.normalize_core_type(v_existing.core_type, true), '');
      v_resolved_core_weight := v_existing.core_weight_lbs;
      v_resolved_lf_weight := v_existing.lf_weight_lbs_per_ft;
    else
      if v_current_feet_on_roll is null then
        perform app_api.raise_http(
          400,
          'CurrentFeetOnRoll is required when this box cannot derive feet from weight alone.'
        );
      end if;

      if v_current_feet_on_roll > v_existing.initial_feet then
        perform app_api.raise_http(
          400,
          format(
            'CurrentFeetOnRoll cannot be greater than this box''s InitialFeet (%s).',
            v_existing.initial_feet
          )
        );
      end if;

      v_physical_feet_after := v_current_feet_on_roll;

      if v_current_feet_on_roll = 0 then
        if v_last_roll_weight > 0 then
          perform app_api.raise_http(
            400,
            'CurrentFeetOnRoll cannot be 0 while LastRollWeightLbs is still above 0.'
          );
        end if;

        v_resolved_core_type := coalesce(
          nullif(v_submitted_core_type, ''),
          app_api.normalize_core_type(v_existing.core_type, true),
          ''
        );
        if v_existing.core_weight_lbs is not null then
          v_resolved_core_weight := v_existing.core_weight_lbs;
        elsif v_resolved_core_type <> '' then
          v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_existing.width_in);
        else
          v_resolved_core_weight := null;
        end if;
        v_resolved_lf_weight := v_existing.lf_weight_lbs_per_ft;
      else
        if v_submitted_core_type <> '' then
          v_resolved_core_type := v_submitted_core_type;
          v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_existing.width_in);
        elsif v_existing.core_weight_lbs is not null then
          v_resolved_core_type := coalesce(app_api.normalize_core_type(v_existing.core_type, true), '');
          v_resolved_core_weight := v_existing.core_weight_lbs;
        elsif coalesce(app_api.normalize_core_type(v_existing.core_type, true), '') <> '' then
          v_resolved_core_type := app_api.normalize_core_type(v_existing.core_type, true);
          v_resolved_core_weight := app_api.derive_core_weight_lbs(v_resolved_core_type, v_existing.width_in);
        else
          perform app_api.raise_http(
            400,
            'CoreType is required before this return can establish future weight-based LF math.'
          );
        end if;

        if v_last_roll_weight <= v_resolved_core_weight then
          perform app_api.raise_http(
            400,
            'LastRollWeightLbs must be greater than the core weight when CurrentFeetOnRoll is above 0.'
          );
        end if;

        v_resolved_lf_weight := round(
          ((v_last_roll_weight - v_resolved_core_weight) / v_current_feet_on_roll)::numeric,
          6
        );
      end if;
    end if;

    if v_other_active_allocated_feet > v_physical_feet_after then
      perform app_api.raise_http(
        400,
        format(
          'Received physical LF cannot be lower than the box''s active allocated feet (%s).',
          v_other_active_allocated_feet
        )
      );
    end if;

    if v_same_job_active_allocation_count > 0 and v_checkout_job <> '' then
      v_same_job_release := app_api.cancel_active_allocations_for_box_job_checkin(
        p_org_id,
        p_actor,
        v_box.box_id,
        v_checkout_job
      );

      if coalesce((v_same_job_release->>'cancelledCount')::integer, 0) > 0 then
        v_warnings := app_api.push_warning(
          v_warnings,
          format(
            'Released %s active planning allocation%s totaling %s LF for job %s during check-in.',
            coalesce((v_same_job_release->>'cancelledCount')::integer, 0),
            case when coalesce((v_same_job_release->>'cancelledCount')::integer, 0) = 1 then '' else 's' end,
            coalesce((v_same_job_release->>'cancelledFeet')::integer, 0),
            v_checkout_job
          )
        );
      end if;
    end if;

    if coalesce(array_length(v_other_jobs, 1), 0) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'This box still has active allocations for ' || array_to_string(v_other_jobs, ', ') || '.'
      );
    end if;

    if v_resolved_core_type <> '' then
      v_box.core_type := v_resolved_core_type;
    end if;
    v_box.core_weight_lbs := v_resolved_core_weight;
    v_box.lf_weight_lbs_per_ft := v_resolved_lf_weight;
    v_box.feet_available := greatest(v_physical_feet_after - v_other_active_allocated_feet, 0);

    if v_existing.last_roll_weight_lbs is not null and v_box.last_roll_weight_lbs > v_existing.last_roll_weight_lbs then
      v_warnings := app_api.push_warning(
        v_warnings,
        'The new Last Roll Weight is greater than the box''s previous Last Roll Weight.'
      );
    end if;

    if v_existing.initial_weight_lbs is not null and v_box.last_roll_weight_lbs > v_existing.initial_weight_lbs then
      v_warnings := app_api.push_warning(
        v_warnings,
        'The new Last Roll Weight is greater than the box''s Initial Weight.'
      );
    end if;

    if
      v_box.last_roll_weight_lbs is not null
      and v_box.last_roll_weight_lbs > 0
      and v_box.core_weight_lbs is not null
      and v_box.last_roll_weight_lbs < v_box.core_weight_lbs
    then
      v_warnings := app_api.push_warning(
        v_warnings,
        'The new Last Roll Weight is below the derived core weight.'
      );
    end if;

    if v_physical_feet_after > v_physical_feet_before then
      v_warnings := app_api.push_warning(
        v_warnings,
        'The recalculated Available Feet would increase compared with the current box.'
      );
    end if;

    v_auto_move_to_zeroed :=
      v_box.received_date is not null
      and v_existing.initial_feet > 0
      and (v_physical_feet_after = 0 or coalesce(v_box.last_roll_weight_lbs, 0) = 0);

    if v_auto_move_to_zeroed then
      v_warnings := app_api.push_warning(
        v_warnings,
        'This check-in will auto-move the box into zeroed out inventory.'
      );
    end if;

    if v_other_active_allocated_feet > 0 and v_box.feet_available = 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'All remaining LF on this box is reserved by active allocations.'
      );
    end if;

    if v_checkout_job = '' then
      v_checkout_job := 'UNKNOWN';
      v_warnings := app_api.push_warning(
        v_warnings,
        'Roll history was logged with UNKNOWN job number because no checkout job was saved.'
      );
    end if;

    v_weight_delta := case
      when v_existing.last_roll_weight_lbs is null then null
      else round(v_existing.last_roll_weight_lbs - v_box.last_roll_weight_lbs, 2)
    end;

    if v_existing.last_roll_weight_lbs is null then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Roll history was logged without an outbound weight because no Last Roll Weight was saved at checkout.'
      );
    end if;

    perform app_api.append_roll_history_entry(
      p_org_id,
      row(
        gen_random_uuid(),
        p_org_id,
        app_api.create_log_id(),
        v_box.box_id,
        v_box.warehouse,
        v_box.manufacturer,
        v_box.film_name,
        v_box.width_in,
        v_checkout_job,
        coalesce(nullif(v_checkout_date, '')::timestamptz, now()),
        v_checkout_user,
        v_existing.last_roll_weight_lbs,
        now(),
        app_api.trim_text(p_actor),
        v_box.last_roll_weight_lbs,
        v_weight_delta,
        v_physical_feet_before,
        v_physical_feet_after,
        app_api.trim_text(p_payload->>'auditNote')
      )::app.roll_weight_log
    );

    v_box.last_checkout_job := '';
    v_box.last_checkout_date := null;

    v_reached_zero_state :=
      v_box.received_date is not null
      and (v_physical_feet_after = 0 or coalesce(v_box.last_roll_weight_lbs, 0) = 0);

    if v_auto_move_to_zeroed then
      v_box.status := 'ZEROED';
      v_box.feet_available := 0;
      v_box.zeroed_date := app_api.today_date();
      v_box.zeroed_reason := app_api.determine_zeroed_reason(v_box.feet_available, v_box.last_roll_weight_lbs);
      v_box.zeroed_by := app_api.trim_text(p_actor);
      perform app_api.cancel_active_allocations_for_box(
        p_org_id,
        v_box.box_id,
        p_actor,
        'Auto-cancelled because the box was moved to zeroed out inventory.'
      );
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was automatically moved to zeroed out inventory because Available Feet or Last Roll Weight reached 0.'
      );
    elsif v_reached_zero_state and coalesce(v_existing.feet_available, 0) <= 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box stayed in active inventory because it has not had Available Feet above 0 yet.'
      );
    end if;

    if v_box.status = 'IN_STOCK' then
      v_receipt_result := app_api.process_linked_box_receipt(p_org_id, v_box, p_actor);
      if coalesce(v_receipt_result, '{}'::jsonb) ? 'box' then
        v_box := jsonb_populate_record(null::app.boxes, v_receipt_result->'box');
      end if;
      if jsonb_typeof(coalesce(v_receipt_result->'warnings', '[]'::jsonb)) = 'array' then
        v_warnings := v_warnings || array(
          select jsonb_array_elements_text(coalesce(v_receipt_result->'warnings', '[]'::jsonb))
        );
      end if;
    end if;
  end if;

  v_box := app_api.save_box(v_box);
  v_public_after := app_api.public_box_json(v_box);
  v_log_id := app_api.append_audit_entry(
    p_org_id,
    case when v_box.status = 'ZEROED' and v_status = 'IN_STOCK' then 'ZERO_OUT_BOX' else 'SET_STATUS' end,
    v_box.box_id,
    v_public_before,
    v_public_after,
    p_actor,
    app_api.trim_text(p_payload->>'auditNote')
  );

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

-- Avoid overloaded create_allocation ambiguity during linked box receipt processing.

create or replace function app_api.process_linked_box_receipt(
  p_org_id uuid,
  p_box app.boxes,
  p_actor text
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_box app.boxes := p_box;
  v_link app.film_order_box_links;
  v_order app.film_orders;
  v_remaining_need integer;
  v_link_capacity integer;
  v_allocation_feet integer;
  v_job_context jsonb;
  v_warnings text[] := array[]::text[];
begin
  if v_box.received_date is null or v_box.status <> 'IN_STOCK' or v_box.feet_available <= 0 then
    return jsonb_build_object('box', to_jsonb(v_box), 'warnings', to_jsonb(v_warnings));
  end if;

  for v_link in
    select *
    from app.film_order_box_links l
    where l.org_id = p_org_id
      and l.box_id = v_box.box_id
    for update
  loop
    select *
    into v_order
    from app.film_orders f
    where f.org_id = p_org_id
      and f.film_order_id = v_link.film_order_id
    for update;

    if not found or v_order.status in ('CANCELLED', 'FULFILLED') then
      continue;
    end if;

    v_remaining_need := greatest(v_order.requested_feet - v_order.covered_feet, 0);
    v_link_capacity := greatest(v_link.ordered_feet - v_link.auto_allocated_feet, 0);
    v_allocation_feet := least(v_remaining_need, v_link_capacity, v_box.feet_available);

    if v_allocation_feet <= 0 then
      continue;
    end if;

    v_job_context := jsonb_build_object(
      'jobNumber', v_order.job_number,
      'jobDate', coalesce(to_char(v_order.job_date, 'YYYY-MM-DD'), ''),
      'crewLeader', coalesce(v_order.crew_leader, '')
    );
    perform app_api.create_allocation(
      p_org_id,
      v_box,
      v_job_context,
      v_allocation_feet,
      p_actor,
      v_order.film_order_id,
      'REQUIREMENT',
      null
    );

    v_box.feet_available := greatest(v_box.feet_available - v_allocation_feet, 0);
    v_link.auto_allocated_feet := v_link.auto_allocated_feet + v_allocation_feet;
    perform app_api.save_film_order_link(v_link);
    perform app_api.recalculate_film_order(p_org_id, v_order.film_order_id, p_actor);
    v_warnings := app_api.push_warning(
      v_warnings,
      format(
        '%s LF from %s was automatically allocated to job %s for Film Order %s.',
        v_allocation_feet,
        v_box.box_id,
        v_order.job_number,
        v_order.film_order_id
      )
    );
  end loop;

  return jsonb_build_object('box', to_jsonb(v_box), 'warnings', to_jsonb(v_warnings));
end;
$$;

-- Backfill legacy linked film-order allocations that were received before the
-- receipt-resolution flow started attaching film_order_id to the active allocation rows.

do $$
declare
  v_candidate record;
  v_actor text := 'migration: backfill legacy linked film-order receipts';
begin
  for v_candidate in
    with stale_candidates as (
      select
        fo.org_id,
        fo.film_order_id,
        l.id as link_row_id,
        array_agg(a.id order by a.created_at asc nulls first, a.id asc) as allocation_row_ids,
        coalesce(sum(a.allocated_feet), 0)::integer as matched_allocated_feet
      from app.film_orders fo
      join app.film_order_box_links l
        on l.org_id = fo.org_id
       and l.film_order_id = fo.film_order_id
      join app.boxes b
        on b.org_id = l.org_id
       and b.box_id = l.box_id
      join app.allocations a
        on a.org_id = fo.org_id
       and a.job_number = fo.job_number
       and a.box_id = l.box_id
      where fo.status in ('FILM_ORDER', 'FILM_ON_THE_WAY')
        and b.status = 'IN_STOCK'
        and b.received_date is not null
        and upper(trim(coalesce(a.status::text, ''))) = 'ACTIVE'
        and upper(trim(coalesce(a.allocation_kind::text, ''))) = 'REQUIREMENT'
        and app_api.trim_text(coalesce(a.film_order_id, '')) = ''
        and upper(trim(coalesce(b.manufacturer, ''))) = upper(trim(coalesce(fo.manufacturer, '')))
        and upper(trim(coalesce(b.film_name, ''))) = upper(trim(coalesce(fo.film_name, '')))
        and b.width_in = fo.width_in
        and l.auto_allocated_feet = 0
        and (
          select count(*)
          from app.film_order_box_links l2
          join app.film_orders fo2
            on fo2.org_id = l2.org_id
           and fo2.film_order_id = l2.film_order_id
          where l2.org_id = fo.org_id
            and l2.box_id = l.box_id
            and fo2.job_number = fo.job_number
            and fo2.status in ('FILM_ORDER', 'FILM_ON_THE_WAY')
        ) = 1
      group by
        fo.org_id,
        fo.film_order_id,
        l.id,
        l.ordered_feet,
        fo.requested_feet,
        fo.covered_feet
      having coalesce(sum(a.allocated_feet), 0)::integer > 0
         and coalesce(sum(a.allocated_feet), 0)::integer = l.ordered_feet
         and coalesce(sum(a.allocated_feet), 0)::integer = greatest(fo.requested_feet - fo.covered_feet, 0)
    )
    select *
    from stale_candidates
  loop
    update app.allocations
    set film_order_id = v_candidate.film_order_id
    where org_id = v_candidate.org_id
      and id = any(v_candidate.allocation_row_ids)
      and app_api.trim_text(coalesce(film_order_id, '')) = '';

    update app.film_order_box_links
    set auto_allocated_feet = v_candidate.matched_allocated_feet
    where org_id = v_candidate.org_id
      and id = v_candidate.link_row_id
      and auto_allocated_feet = 0;

    perform app_api.recalculate_film_order(
      v_candidate.org_id,
      v_candidate.film_order_id,
      v_actor
    );
  end loop;
end;
$$;

-- Adds zero-stock warehouse seeding for new caulk products and a pending transfer workflow for job allocations.

do $$
begin
  create type app.caulk_transfer_status as enum ('PENDING', 'RECEIVED', 'CANCELLED');
exception
  when duplicate_object then
    null;
end;
$$;

alter table app.caulk_job_allocations
  drop constraint if exists caulk_job_allocations_org_id_id_key;
alter table app.caulk_job_allocations
  add constraint caulk_job_allocations_org_id_id_key unique (org_id, id);

create table if not exists app.caulk_transfers (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references app.organizations(id) on delete cascade,
  transfer_id text not null,
  caulk_allocation_id uuid not null,
  job_id uuid references app.jobs(id) on delete set null,
  job_number text not null,
  product_id uuid not null,
  source_warehouse text not null,
  destination_warehouse text not null,
  pending_tubes integer not null,
  status app.caulk_transfer_status not null default 'PENDING',
  notes text not null default '',
  created_at timestamptz not null default now(),
  created_by text not null default '',
  received_at timestamptz,
  received_by text not null default '',
  cancelled_at timestamptz,
  cancelled_by text not null default '',
  updated_at timestamptz not null default now(),
  updated_by text not null default '',
  unique (org_id, transfer_id),
  foreign key (org_id, caulk_allocation_id)
    references app.caulk_job_allocations(org_id, id)
    on delete cascade,
  foreign key (org_id, product_id)
    references app.caulk_products(org_id, id)
    on delete restrict,
  foreign key (org_id, source_warehouse)
    references app.warehouses(org_id, code)
    on delete restrict,
  foreign key (org_id, destination_warehouse)
    references app.warehouses(org_id, code)
    on delete restrict
);

alter table app.caulk_transfers
  drop constraint if exists caulk_transfers_value_format;
alter table app.caulk_transfers
  add constraint caulk_transfers_value_format check (
    transfer_id = upper(btrim(transfer_id))
    and btrim(transfer_id) <> ''
    and btrim(job_number) <> ''
    and source_warehouse = upper(btrim(source_warehouse))
    and destination_warehouse = upper(btrim(destination_warehouse))
    and source_warehouse ~ '^[A-Z]{2}[1-9][0-9]{0,6}$'
    and destination_warehouse ~ '^[A-Z]{2}[1-9][0-9]{0,6}$'
    and source_warehouse <> destination_warehouse
    and pending_tubes > 0
  );

create index if not exists idx_caulk_transfers_org_status_created
  on app.caulk_transfers (org_id, status, created_at desc, id desc);

create index if not exists idx_caulk_transfers_org_allocation_created
  on app.caulk_transfers (org_id, caulk_allocation_id, created_at desc, id desc);

create index if not exists idx_caulk_transfers_destination_product_status
  on app.caulk_transfers (org_id, destination_warehouse, product_id, status, created_at desc, id desc);

create unique index if not exists idx_caulk_transfers_one_pending_per_allocation
  on app.caulk_transfers (org_id, caulk_allocation_id)
  where status = 'PENDING';

create or replace function app_api.caulk_seed_stock_row(
  p_org_id uuid,
  p_actor text,
  p_product_id uuid,
  p_warehouse text
)
returns text
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_actor text := app_api.trim_text(p_actor);
  v_warehouse text := app_api.caulk_require_warehouse(p_org_id, p_warehouse);
begin
  insert into app.caulk_stock (
    org_id,
    product_id,
    warehouse,
    tubes_on_hand,
    updated_by
  )
  values (
    p_org_id,
    p_product_id,
    v_warehouse,
    0,
    v_actor
  )
  on conflict (org_id, product_id, warehouse) do nothing;

  return v_warehouse;
end;
$$;

create or replace function app_api.caulk_save_transfer_record(
  p_org_id uuid,
  p_transfer_id text,
  p_caulk_allocation_id uuid,
  p_job_id uuid,
  p_job_number text,
  p_product_id uuid,
  p_source_warehouse text,
  p_destination_warehouse text,
  p_pending_tubes integer,
  p_status app.caulk_transfer_status,
  p_notes text default '',
  p_created_at timestamptz default now(),
  p_created_by text default '',
  p_received_at timestamptz default null,
  p_received_by text default '',
  p_cancelled_at timestamptz default null,
  p_cancelled_by text default '',
  p_updated_at timestamptz default now(),
  p_updated_by text default ''
)
returns app.caulk_transfers
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_row app.caulk_transfers;
begin
  insert into app.caulk_transfers (
    org_id,
    transfer_id,
    caulk_allocation_id,
    job_id,
    job_number,
    product_id,
    source_warehouse,
    destination_warehouse,
    pending_tubes,
    status,
    notes,
    created_at,
    created_by,
    received_at,
    received_by,
    cancelled_at,
    cancelled_by,
    updated_at,
    updated_by
  )
  values (
    p_org_id,
    upper(btrim(p_transfer_id)),
    p_caulk_allocation_id,
    p_job_id,
    app_api.trim_text(p_job_number),
    p_product_id,
    upper(btrim(p_source_warehouse)),
    upper(btrim(p_destination_warehouse)),
    p_pending_tubes,
    p_status,
    app_api.trim_text(p_notes),
    coalesce(p_created_at, now()),
    app_api.trim_text(p_created_by),
    p_received_at,
    app_api.trim_text(p_received_by),
    p_cancelled_at,
    app_api.trim_text(p_cancelled_by),
    coalesce(p_updated_at, now()),
    app_api.trim_text(p_updated_by)
  )
  on conflict (org_id, transfer_id) do update
  set
    caulk_allocation_id = excluded.caulk_allocation_id,
    job_id = excluded.job_id,
    job_number = excluded.job_number,
    product_id = excluded.product_id,
    source_warehouse = excluded.source_warehouse,
    destination_warehouse = excluded.destination_warehouse,
    pending_tubes = excluded.pending_tubes,
    status = excluded.status,
    notes = excluded.notes,
    received_at = excluded.received_at,
    received_by = excluded.received_by,
    cancelled_at = excluded.cancelled_at,
    cancelled_by = excluded.cancelled_by,
    updated_at = excluded.updated_at,
    updated_by = excluded.updated_by
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function app_api.caulk_reserve_local_tubes(
  p_org_id uuid,
  p_actor text,
  p_product_id uuid,
  p_target_warehouse text,
  p_reserve_tubes integer,
  p_reserve_action text,
  p_reserve_reason text,
  p_source_box_id text default '',
  p_notes text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_actor text := app_api.trim_text(p_actor);
  v_notes text := app_api.trim_text(p_notes);
  v_source_box_id text := app_api.trim_text(p_source_box_id);
  v_target_warehouse text := app_api.caulk_seed_stock_row(
    p_org_id,
    p_actor,
    p_product_id,
    p_target_warehouse
  );
  v_target_stock app.caulk_stock;
  v_target_available integer := 0;
  v_reserved_tubes integer := 0;
  v_shortage_tubes integer := 0;
begin
  if p_reserve_tubes is null or p_reserve_tubes <= 0 then
    perform app_api.raise_http(400, 'Reserve quantity must be greater than zero.');
  end if;

  select *
  into v_target_stock
  from app.caulk_stock s
  where s.org_id = p_org_id
    and s.product_id = p_product_id
    and s.warehouse = v_target_warehouse
  for update;

  v_target_available := coalesce(v_target_stock.tubes_on_hand, 0);
  v_reserved_tubes := least(v_target_available, p_reserve_tubes);
  v_shortage_tubes := greatest(p_reserve_tubes - v_reserved_tubes, 0);

  if v_reserved_tubes > 0 then
    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      p_product_id,
      v_target_warehouse,
      p_reserve_action,
      -v_reserved_tubes,
      p_reserve_reason,
      '',
      v_source_box_id,
      v_notes
    );
  end if;

  return jsonb_build_object(
    'warehouse', v_target_warehouse,
    'reservedTubes', v_reserved_tubes,
    'shortageTubes', v_shortage_tubes
  );
end;
$$;

create or replace function app_api.caulk_start_pending_transfer(
  p_org_id uuid,
  p_actor text,
  p_allocation_row_id uuid,
  p_allocation_public_id text,
  p_job_id uuid,
  p_job_number text,
  p_product_id uuid,
  p_from_warehouse text,
  p_to_warehouse text,
  p_pending_tubes integer,
  p_notes text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_actor text := app_api.trim_text(p_actor);
  v_notes text := app_api.trim_text(p_notes);
  v_destination_warehouse text;
  v_requested_source_warehouse text := app_api.trim_text(p_from_warehouse);
  v_source_warehouse text;
  v_source_stock app.caulk_stock;
  v_source_available integer := 0;
  v_transfer_id text := '';
begin
  if coalesce(p_pending_tubes, 0) <= 0 then
    return jsonb_build_object(
      'transferId', '',
      'warnings', '[]'::jsonb
    );
  end if;

  v_destination_warehouse := app_api.caulk_seed_stock_row(
    p_org_id,
    p_actor,
    p_product_id,
    p_to_warehouse
  );

  if v_requested_source_warehouse = '' then
    perform app_api.raise_http(
      400,
      format(
        '%s still needs %s tube%s transferred in before this allocation can be saved. Select a source warehouse first.',
        v_destination_warehouse,
        p_pending_tubes,
        case when p_pending_tubes = 1 then '' else 's' end
      )
    );
  end if;

  v_source_warehouse := app_api.caulk_seed_stock_row(
    p_org_id,
    p_actor,
    p_product_id,
    v_requested_source_warehouse
  );

  if v_source_warehouse = v_destination_warehouse then
    perform app_api.raise_http(400, 'Transfer source and destination warehouse must differ.');
  end if;

  select *
  into v_source_stock
  from app.caulk_stock s
  where s.org_id = p_org_id
    and s.product_id = p_product_id
    and s.warehouse = v_source_warehouse
  for update;

  v_source_available := coalesce(v_source_stock.tubes_on_hand, 0);
  if v_source_available < p_pending_tubes then
    perform app_api.raise_http(
      400,
      format(
        '%s only has %s tube%s available; %s tube%s needed to cover the shortage at %s.',
        v_source_warehouse,
        v_source_available,
        case when v_source_available = 1 then '' else 's' end,
        p_pending_tubes,
        case when p_pending_tubes = 1 then '' else 's' end,
        v_destination_warehouse
      )
    );
  end if;

  v_transfer_id := app_api.caulk_create_transaction_id();

  perform app_api.caulk_apply_stock_delta(
    p_org_id,
    v_actor,
    p_product_id,
    v_source_warehouse,
    'TRANSFER_OUT',
    -p_pending_tubes,
    format(
      'Started caulk transfer from %s to %s for job %s.',
      v_source_warehouse,
      v_destination_warehouse,
      app_api.trim_text(p_job_number)
    ),
    v_transfer_id,
    app_api.trim_text(p_allocation_public_id),
    v_notes
  );

  perform app_api.caulk_save_transfer_record(
    p_org_id,
    v_transfer_id,
    p_allocation_row_id,
    p_job_id,
    p_job_number,
    p_product_id,
    v_source_warehouse,
    v_destination_warehouse,
    p_pending_tubes,
    'PENDING',
    v_notes,
    now(),
    v_actor,
    null,
    '',
    null,
    '',
    now(),
    v_actor
  );

  return jsonb_build_object(
    'transferId', v_transfer_id,
    'warnings', jsonb_build_array(
      format(
        'Started transfer of %s tube%s from %s to %s. Receive it before checkout or staging.',
        p_pending_tubes,
        case when p_pending_tubes = 1 then '' else 's' end,
        v_source_warehouse,
        v_destination_warehouse
      )
    )
  );
end;
$$;

create or replace function app_api.caulk_cancel_pending_transfer_internal(
  p_org_id uuid,
  p_actor text,
  p_transfer_id text,
  p_reason text default ''
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_transfer app.caulk_transfers;
  v_allocation app.caulk_job_allocations;
  v_actor text := app_api.trim_text(p_actor);
  v_pending_tubes integer := 0;
  v_reason text;
begin
  select *
  into v_transfer
  from app.caulk_transfers t
  where t.org_id = p_org_id
    and t.transfer_id = app_api.require_text(p_transfer_id, 'TransferId')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Caulk transfer not found.');
  end if;

  if v_transfer.status <> 'PENDING' then
    perform app_api.raise_http(
      400,
      format('Caulk transfer %s is already %s.', v_transfer.transfer_id, lower(v_transfer.status::text))
    );
  end if;

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.id = v_transfer.caulk_allocation_id
  for update;

  v_pending_tubes := coalesce(v_transfer.pending_tubes, 0);
  v_reason := coalesce(
    nullif(app_api.trim_text(p_reason), ''),
    format(
      'Cancelled caulk transfer from %s to %s for job %s.',
      v_transfer.source_warehouse,
      v_transfer.destination_warehouse,
      v_transfer.job_number
    )
  );

  if v_pending_tubes > 0 then
    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_transfer.product_id,
      v_transfer.source_warehouse,
      'TRANSFER_IN',
      v_pending_tubes,
      v_reason,
      v_transfer.transfer_id,
      '',
      v_reason
    );
  end if;

  perform app_api.caulk_save_transfer_record(
    p_org_id,
    v_transfer.transfer_id,
    v_transfer.caulk_allocation_id,
    v_transfer.job_id,
    v_transfer.job_number,
    v_transfer.product_id,
    v_transfer.source_warehouse,
    v_transfer.destination_warehouse,
    v_transfer.pending_tubes,
    'CANCELLED',
    v_reason,
    v_transfer.created_at,
    v_transfer.created_by,
    v_transfer.received_at,
    v_transfer.received_by,
    now(),
    v_actor,
    now(),
    v_actor
  );

  return jsonb_build_object(
    'jobNumber', coalesce(v_allocation.job_number, v_transfer.job_number),
    'caulkAllocationId', coalesce(v_allocation.caulk_allocation_id, ''),
    'transferId', v_transfer.transfer_id,
    'warnings',
      case
        when v_pending_tubes > 0 then jsonb_build_array(
          format(
            'Cancelled transfer %s and returned %s tube%s to %s.',
            v_transfer.transfer_id,
            v_pending_tubes,
            case when v_pending_tubes = 1 then '' else 's' end,
            v_transfer.source_warehouse
          )
        )
        else '[]'::jsonb
      end
  );
end;
$$;

create or replace function app_api.caulk_receive_pending_transfer_internal(
  p_org_id uuid,
  p_actor text,
  p_transfer_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_transfer app.caulk_transfers;
  v_allocation app.caulk_job_allocations;
  v_actor text := app_api.trim_text(p_actor);
  v_pending_tubes integer := 0;
  v_destination_warehouse text := '';
begin
  select *
  into v_transfer
  from app.caulk_transfers t
  where t.org_id = p_org_id
    and t.transfer_id = app_api.require_text(p_transfer_id, 'TransferId')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Caulk transfer not found.');
  end if;

  if v_transfer.status <> 'PENDING' then
    perform app_api.raise_http(
      400,
      format('Caulk transfer %s is already %s.', v_transfer.transfer_id, lower(v_transfer.status::text))
    );
  end if;

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.id = v_transfer.caulk_allocation_id
  for update;

  if not found then
    perform app_api.raise_http(404, 'Parent caulk allocation was not found.');
  end if;

  if v_allocation.status <> 'ACTIVE' then
    perform app_api.raise_http(400, 'Parent caulk allocation is no longer active.');
  end if;

  v_destination_warehouse := app_api.caulk_seed_stock_row(
    p_org_id,
    p_actor,
    v_transfer.product_id,
    v_transfer.destination_warehouse
  );
  v_pending_tubes := coalesce(v_transfer.pending_tubes, 0);

  if v_pending_tubes > 0 then
    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_transfer.product_id,
      v_destination_warehouse,
      'TRANSFER_IN',
      v_pending_tubes,
      format(
        'Received caulk transfer into %s for job %s.',
        v_destination_warehouse,
        v_allocation.job_number
      ),
      v_transfer.transfer_id,
      v_allocation.caulk_allocation_id,
      v_transfer.notes
    );

    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_transfer.product_id,
      v_destination_warehouse,
      'JOB_ALLOCATE_EDIT_INC',
      -v_pending_tubes,
      format(
        'Received pending caulk transfer for allocation %s.',
        v_allocation.caulk_allocation_id
      ),
      '',
      v_allocation.caulk_allocation_id,
      v_transfer.notes
    );
  end if;

  update app.caulk_job_allocations
  set
    reserved_tubes_remaining = reserved_tubes_remaining + v_pending_tubes,
    updated_at = now(),
    updated_by = v_actor
  where id = v_allocation.id
    and org_id = p_org_id;

  perform app_api.caulk_save_transfer_record(
    p_org_id,
    v_transfer.transfer_id,
    v_transfer.caulk_allocation_id,
    v_transfer.job_id,
    v_transfer.job_number,
    v_transfer.product_id,
    v_transfer.source_warehouse,
    v_transfer.destination_warehouse,
    v_transfer.pending_tubes,
    'RECEIVED',
    v_transfer.notes,
    v_transfer.created_at,
    v_transfer.created_by,
    now(),
    v_actor,
    v_transfer.cancelled_at,
    v_transfer.cancelled_by,
    now(),
    v_actor
  );

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'transferId', v_transfer.transfer_id,
    'warnings', jsonb_build_array(
      format(
        'Received %s tube%s into %s and reserved it for allocation %s.',
        v_pending_tubes,
        case when v_pending_tubes = 1 then '' else 's' end,
        v_destination_warehouse,
        v_allocation.caulk_allocation_id
      )
    )
  );
end;
$$;

create or replace function app_api.cancel_active_caulk_allocations_for_job(
  p_org_id uuid,
  p_actor text,
  p_job_number text,
  p_reason text,
  p_fail_on_open_checkouts boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_entry app.caulk_job_allocations;
  v_actor text := app_api.trim_text(p_actor);
  v_job_number text := app_api.require_job_number_digits(p_job_number, 'Job ID number');
  v_reason text := coalesce(nullif(app_api.trim_text(p_reason), ''), format('Cancelled job %s.', v_job_number));
  v_pending_transfer_id text := '';
  v_open_checkout_count integer := 0;
  v_cancelled_count integer := 0;
  v_released_reserved_tubes integer := 0;
begin
  select count(*)
  into v_open_checkout_count
  from app.caulk_job_checkouts c
  join app.caulk_job_allocations a
    on a.id = c.caulk_allocation_id
   and a.org_id = c.org_id
  where c.org_id = p_org_id
    and upper(c.job_number) = upper(v_job_number)
    and c.status = 'OPEN'
    and a.status = 'ACTIVE';

  if p_fail_on_open_checkouts and v_open_checkout_count > 0 then
    perform app_api.raise_http(
      400,
      format(
        'Job %s cannot be closed while %s caulk checkout%s remain open.',
        v_job_number,
        v_open_checkout_count,
        case when v_open_checkout_count = 1 then '' else 's' end
      )
    );
  end if;

  for v_entry in
    select *
    from app.caulk_job_allocations a
    where a.org_id = p_org_id
      and upper(a.job_number) = upper(v_job_number)
      and a.status = 'ACTIVE'
    for update
  loop
    select t.transfer_id
    into v_pending_transfer_id
    from app.caulk_transfers t
    where t.org_id = p_org_id
      and t.caulk_allocation_id = v_entry.id
      and t.status = 'PENDING'
    order by t.created_at desc, t.id desc
    limit 1
    for update;

    if coalesce(v_pending_transfer_id, '') <> '' then
      perform app_api.caulk_cancel_pending_transfer_internal(
        p_org_id,
        v_actor,
        v_pending_transfer_id,
        format(
          'Cancelled pending transfer %s while closing job %s.',
          v_pending_transfer_id,
          v_job_number
        )
      );
    end if;

    if v_entry.reserved_tubes_remaining > 0 then
      perform app_api.caulk_apply_stock_delta(
        p_org_id,
        v_actor,
        v_entry.product_id,
        v_entry.warehouse,
        'JOB_ALLOCATION_CANCEL_RETURN',
        v_entry.reserved_tubes_remaining,
        v_reason,
        '',
        v_entry.caulk_allocation_id,
        v_reason
      );
      v_released_reserved_tubes := v_released_reserved_tubes + v_entry.reserved_tubes_remaining;
    end if;

    update app.caulk_job_allocations
    set
      status = 'CANCELLED',
      reserved_tubes_remaining = 0,
      resolved_at = now(),
      resolved_by = v_actor,
      notes = v_reason,
      updated_at = now(),
      updated_by = v_actor
    where id = v_entry.id
      and org_id = p_org_id;

    v_cancelled_count := v_cancelled_count + 1;
  end loop;

  return jsonb_build_object(
    'jobNumber', v_job_number,
    'openCheckoutCount', v_open_checkout_count,
    'cancelledAllocationCount', v_cancelled_count,
    'releasedReservedTubes', v_released_reserved_tubes
  );
end;
$$;

drop function if exists public.api_acl_list_caulk_job_allocations_by_job(uuid, text);

create or replace function public.api_acl_list_caulk_job_allocations_by_job(
  p_org_id uuid,
  p_job_number text
)
returns table (
  caulk_allocation_id text,
  requirement_id uuid,
  product_id uuid,
  manufacturer_id uuid,
  manufacturer text,
  product_name text,
  product_code text,
  tubes_per_case integer,
  warehouse text,
  allocated_tubes integer,
  reserved_tubes_remaining integer,
  checked_out_tubes_total integer,
  returned_unused_tubes_total integer,
  used_tubes_total integer,
  overage_tubes_total integer,
  outstanding_checkout_tubes integer,
  open_checkout_count integer,
  status text,
  created_at timestamptz,
  created_by text,
  updated_at timestamptz,
  updated_by text,
  resolved_at timestamptz,
  resolved_by text,
  notes text,
  pending_transfer_id text,
  pending_transfer_source_warehouse text,
  pending_transfer_destination_warehouse text,
  pending_transfer_tubes integer,
  pending_transfer_started_at timestamptz,
  pending_transfer_started_by text,
  pending_transfer_notes text
)
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  perform app_api.require_org_member(p_org_id);

  return query
  with open_counts as (
    select
      c.caulk_allocation_id,
      count(*)::integer as open_checkout_count
    from app.caulk_job_checkouts c
    where c.org_id = p_org_id
      and c.status = 'OPEN'
    group by c.caulk_allocation_id
  ),
  pending_transfers as (
    select distinct on (t.caulk_allocation_id)
      t.caulk_allocation_id,
      t.transfer_id,
      t.source_warehouse,
      t.destination_warehouse,
      t.pending_tubes,
      t.created_at,
      t.created_by,
      t.notes
    from app.caulk_transfers t
    where t.org_id = p_org_id
      and t.status = 'PENDING'
    order by t.caulk_allocation_id, t.created_at desc, t.id desc
  )
  select
    a.caulk_allocation_id,
    a.requirement_id,
    a.product_id,
    p.manufacturer_id,
    m.name,
    p.name,
    p.code,
    p.tubes_per_case,
    a.warehouse,
    a.allocated_tubes,
    a.reserved_tubes_remaining,
    a.checked_out_tubes_total,
    a.returned_unused_tubes_total,
    a.used_tubes_total,
    a.overage_tubes_total,
    greatest(a.checked_out_tubes_total - a.returned_unused_tubes_total - a.used_tubes_total, 0)::integer,
    coalesce(o.open_checkout_count, 0),
    a.status::text,
    a.created_at,
    a.created_by,
    a.updated_at,
    a.updated_by,
    a.resolved_at,
    a.resolved_by,
    a.notes,
    pt.transfer_id,
    pt.source_warehouse,
    pt.destination_warehouse,
    pt.pending_tubes,
    pt.created_at,
    pt.created_by,
    pt.notes
  from app.caulk_job_allocations a
  join app.caulk_products p
    on p.id = a.product_id
   and p.org_id = a.org_id
  join app.caulk_manufacturers m
    on m.id = p.manufacturer_id
   and m.org_id = p.org_id
  left join open_counts o
    on o.caulk_allocation_id = a.id
  left join pending_transfers pt
    on pt.caulk_allocation_id = a.id
  where a.org_id = p_org_id
    and upper(a.job_number) = upper(app_api.require_job_number_digits(p_job_number, 'Job ID number'))
  order by a.created_at desc, a.caulk_allocation_id desc;
end;
$$;

create or replace function public.api_acl_list_caulk_transfers(
  p_org_id uuid,
  p_warehouse text,
  p_product_id uuid default null
)
returns table (
  transfer_id text,
  caulk_allocation_id text,
  job_number text,
  product_id uuid,
  manufacturer_id uuid,
  manufacturer text,
  product_name text,
  product_code text,
  tubes_per_case integer,
  source_warehouse text,
  destination_warehouse text,
  pending_tubes integer,
  status text,
  created_at timestamptz,
  created_by text,
  received_at timestamptz,
  received_by text,
  cancelled_at timestamptz,
  cancelled_by text,
  updated_at timestamptz,
  updated_by text,
  notes text
)
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_warehouse text := app_api.caulk_require_warehouse(p_org_id, p_warehouse);
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'read');

  return query
  select
    t.transfer_id,
    a.caulk_allocation_id,
    a.job_number,
    p.id,
    p.manufacturer_id,
    m.name,
    p.name,
    p.code,
    p.tubes_per_case,
    t.source_warehouse,
    t.destination_warehouse,
    t.pending_tubes,
    t.status::text,
    t.created_at,
    t.created_by,
    t.received_at,
    t.received_by,
    t.cancelled_at,
    t.cancelled_by,
    t.updated_at,
    t.updated_by,
    t.notes
  from app.caulk_transfers t
  join app.caulk_job_allocations a
    on a.org_id = t.org_id
   and a.id = t.caulk_allocation_id
  join app.caulk_products p
    on p.org_id = t.org_id
   and p.id = t.product_id
  join app.caulk_manufacturers m
    on m.org_id = p.org_id
   and m.id = p.manufacturer_id
  where t.org_id = p_org_id
    and t.status = 'PENDING'
    and t.destination_warehouse = v_warehouse
    and (p_product_id is null or t.product_id = p_product_id)
  order by t.created_at desc, t.id desc;
end;
$$;

create or replace function public.api_acl_caulk_upsert_product(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_product_id uuid := nullif(app_api.trim_text(p_payload->>'productId'), '')::uuid;
  v_manufacturer_id uuid := nullif(app_api.trim_text(p_payload->>'manufacturerId'), '')::uuid;
  v_name text := p_payload->>'productName';
  v_code text := coalesce(p_payload->>'productCode', '');
  v_warehouse text := app_api.trim_text(p_payload->>'warehouse');
  v_tubes_per_case integer := coalesce(nullif(app_api.trim_text(p_payload->>'tubesPerCase'), '')::integer, 16);
  v_is_active boolean := coalesce((p_payload->>'isActive')::boolean, true);
  v_notes text := coalesce(p_payload->>'notes', '');
  v_row app.caulk_products;
  v_manufacturer_name text := '';
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'write');

  if v_manufacturer_id is null then
    perform app_api.raise_http(400, 'ManufacturerId is required.');
  end if;

  v_row := app_api.caulk_upsert_product(
    p_org_id,
    p_actor,
    v_product_id,
    v_manufacturer_id,
    v_name,
    v_code,
    v_tubes_per_case,
    v_is_active,
    v_notes
  );

  if v_warehouse <> '' then
    perform app_api.caulk_seed_stock_row(
      p_org_id,
      p_actor,
      v_row.id,
      v_warehouse
    );
  end if;

  select m.name
  into v_manufacturer_name
  from app.caulk_manufacturers m
  where m.org_id = p_org_id
    and m.id = v_row.manufacturer_id
  limit 1;

  return jsonb_build_object(
    'productId', v_row.id,
    'manufacturerId', v_row.manufacturer_id,
    'manufacturer', coalesce(v_manufacturer_name, ''),
    'productName', v_row.name,
    'productCode', v_row.code,
    'lookupKey', v_row.lookup_key,
    'tubesPerCase', v_row.tubes_per_case,
    'isActive', v_row.is_active,
    'notes', v_row.notes,
    'updatedAt', v_row.updated_at
  );
end;
$$;

create or replace function public.api_acl_allocations_caulk_add(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_product app.caulk_products;
  v_requirement app.job_caulk_requirements;
  v_allocation_id text := app_api.create_log_id();
  v_allocation_row_id uuid := gen_random_uuid();
  v_job_number text := app_api.require_job_number_digits(p_payload->>'jobNumber', 'Job ID number');
  v_requirement_id uuid := nullif(app_api.trim_text(p_payload->>'requirementId'), '')::uuid;
  v_product_id uuid := nullif(app_api.trim_text(p_payload->>'productId'), '')::uuid;
  v_warehouse text := app_api.caulk_require_warehouse(p_org_id, p_payload->>'warehouse');
  v_allocated_tubes integer := floor(nullif(app_api.trim_text(p_payload->>'allocatedTubes'), '')::numeric);
  v_actor text := app_api.trim_text(p_actor);
  v_notes text := app_api.trim_text(p_payload->>'notes');
  v_local_reservation jsonb := '{}'::jsonb;
  v_reserved_tubes integer := 0;
  v_shortage_tubes integer := 0;
  v_transfer_result jsonb := jsonb_build_object('warnings', '[]'::jsonb);
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  if v_product_id is null then
    perform app_api.raise_http(400, 'productId is required.');
  end if;

  if v_allocated_tubes is null or v_allocated_tubes <= 0 then
    perform app_api.raise_http(400, 'allocatedTubes must be greater than zero.');
  end if;

  v_job := app_api.require_active_job_for_caulk(p_org_id, v_job_number);

  select *
  into v_product
  from app.caulk_products p
  where p.org_id = p_org_id
    and p.id = v_product_id
  limit 1;

  if not found then
    perform app_api.raise_http(400, 'Product was not found.');
  end if;

  if v_requirement_id is not null then
    select *
    into v_requirement
    from app.job_caulk_requirements r
    where r.org_id = p_org_id
      and r.id = v_requirement_id
      and r.job_id = v_job.id
    for update;

    if not found then
      perform app_api.raise_http(400, 'RequirementId was not found for this job.');
    end if;
  end if;

  v_local_reservation := app_api.caulk_reserve_local_tubes(
    p_org_id,
    v_actor,
    v_product.id,
    v_warehouse,
    v_allocated_tubes,
    'JOB_ALLOCATE',
    format('Allocated caulk to job %s.', v_job.job_number),
    v_allocation_id,
    v_notes
  );
  v_reserved_tubes := coalesce((v_local_reservation->>'reservedTubes')::integer, 0);
  v_shortage_tubes := coalesce((v_local_reservation->>'shortageTubes')::integer, 0);

  insert into app.caulk_job_allocations (
    id,
    org_id,
    caulk_allocation_id,
    job_id,
    job_number,
    requirement_id,
    product_id,
    warehouse,
    allocated_tubes,
    reserved_tubes_remaining,
    checked_out_tubes_total,
    returned_unused_tubes_total,
    used_tubes_total,
    overage_tubes_total,
    status,
    created_at,
    created_by,
    updated_at,
    updated_by,
    notes
  )
  values (
    v_allocation_row_id,
    p_org_id,
    v_allocation_id,
    v_job.id,
    v_job.job_number,
    v_requirement_id,
    v_product.id,
    v_warehouse,
    v_allocated_tubes,
    v_reserved_tubes,
    0,
    0,
    0,
    0,
    'ACTIVE',
    now(),
    v_actor,
    now(),
    v_actor,
    v_notes
  );

  v_transfer_result := app_api.caulk_start_pending_transfer(
    p_org_id,
    v_actor,
    v_allocation_row_id,
    v_allocation_id,
    v_job.id,
    v_job.job_number,
    v_product.id,
    p_payload->>'transferFromWarehouse',
    v_warehouse,
    v_shortage_tubes,
    v_notes
  );

  return jsonb_build_object(
    'jobNumber', v_job.job_number,
    'caulkAllocationId', v_allocation_id,
    'warnings', coalesce(v_transfer_result->'warnings', '[]'::jsonb)
  );
end;
$$;

create or replace function public.api_acl_allocations_caulk_update(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_allocation app.caulk_job_allocations;
  v_pending_transfer_id text := '';
  v_actor text := app_api.trim_text(p_actor);
  v_caulk_allocation_id text := app_api.require_text(p_payload->>'caulkAllocationId', 'CaulkAllocationId');
  v_has_product_id boolean := p_payload ? 'productId';
  v_has_warehouse boolean := p_payload ? 'warehouse';
  v_has_allocated_tubes boolean := p_payload ? 'allocatedTubes';
  v_has_notes boolean := p_payload ? 'notes';
  v_has_transfer_selection boolean := app_api.trim_text(p_payload->>'transferFromWarehouse') <> '';
  v_has_material_edit boolean := false;
  v_next_product_id uuid;
  v_next_warehouse text;
  v_next_allocated_tubes integer;
  v_next_notes text;
  v_checked_out_tubes integer := 0;
  v_reserved_tubes integer := 0;
  v_allocated_tubes integer := 0;
  v_currently_covered integer := 0;
  v_additional_coverage_needed integer := 0;
  v_release_tubes integer := 0;
  v_next_reserved_tubes integer := 0;
  v_local_reservation jsonb := '{}'::jsonb;
  v_transfer_result jsonb := jsonb_build_object('warnings', '[]'::jsonb);
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.caulk_allocation_id = v_caulk_allocation_id
  for update;

  if not found then
    perform app_api.raise_http(404, format('Caulk allocation %s was not found.', v_caulk_allocation_id));
  end if;

  if v_allocation.status <> 'ACTIVE' then
    perform app_api.raise_http(400, format('Caulk allocation %s is not active.', v_caulk_allocation_id));
  end if;

  perform app_api.require_active_job_for_caulk(p_org_id, v_allocation.job_number);

  select t.transfer_id
  into v_pending_transfer_id
  from app.caulk_transfers t
  where t.org_id = p_org_id
    and t.caulk_allocation_id = v_allocation.id
    and t.status = 'PENDING'
  order by t.created_at desc, t.id desc
  limit 1
  for update;

  v_has_material_edit := v_has_product_id or v_has_warehouse or v_has_allocated_tubes or v_has_transfer_selection;
  if coalesce(v_pending_transfer_id, '') <> '' and v_has_material_edit then
    perform app_api.raise_http(
      400,
      format('Receive or cancel transfer %s before editing this allocation.', v_pending_transfer_id)
    );
  end if;

  v_next_product_id := case
    when v_has_product_id and app_api.trim_text(p_payload->>'productId') <> ''
      then nullif(app_api.trim_text(p_payload->>'productId'), '')::uuid
    else v_allocation.product_id
  end;
  v_next_warehouse := case
    when v_has_warehouse
      then app_api.caulk_require_warehouse(p_org_id, p_payload->>'warehouse')
    else v_allocation.warehouse
  end;
  v_next_allocated_tubes := case
    when v_has_allocated_tubes
      then floor(nullif(app_api.trim_text(p_payload->>'allocatedTubes'), '')::numeric)
    else v_allocation.allocated_tubes
  end;
  v_next_notes := case
    when v_has_notes then app_api.trim_text(p_payload->>'notes')
    else v_allocation.notes
  end;

  if v_next_allocated_tubes is null or v_next_allocated_tubes <= 0 then
    perform app_api.raise_http(400, 'allocatedTubes must be greater than zero.');
  end if;

  if v_next_product_id <> v_allocation.product_id then
    perform 1
    from app.caulk_products p
    where p.org_id = p_org_id
      and p.id = v_next_product_id;
    if not found then
      perform app_api.raise_http(400, 'Product was not found.');
    end if;
  end if;

  v_checked_out_tubes := coalesce(v_allocation.checked_out_tubes_total, 0);
  v_reserved_tubes := coalesce(v_allocation.reserved_tubes_remaining, 0);
  v_allocated_tubes := coalesce(v_allocation.allocated_tubes, 0);

  if v_checked_out_tubes > 0 then
    if v_next_product_id <> v_allocation.product_id or v_next_warehouse <> v_allocation.warehouse then
      perform app_api.raise_http(400, 'Product and warehouse cannot be changed after checkout starts.');
    end if;
    if v_next_allocated_tubes < v_allocated_tubes then
      perform app_api.raise_http(400, 'allocatedTubes can only increase after checkout starts.');
    end if;
  end if;

  if v_next_product_id <> v_allocation.product_id or v_next_warehouse <> v_allocation.warehouse then
    if v_checked_out_tubes > 0 then
      perform app_api.raise_http(400, 'Product and warehouse cannot be changed after checkout starts.');
    end if;

    if v_reserved_tubes > 0 then
      perform app_api.caulk_apply_stock_delta(
        p_org_id,
        v_actor,
        v_allocation.product_id,
        v_allocation.warehouse,
        'JOB_ALLOCATE_EDIT_DEC',
        v_reserved_tubes,
        format('Edited caulk allocation %s.', v_allocation.caulk_allocation_id),
        '',
        v_allocation.caulk_allocation_id,
        'Released prior reserved tubes during edit.'
      );
    end if;

    v_local_reservation := app_api.caulk_reserve_local_tubes(
      p_org_id,
      v_actor,
      v_next_product_id,
      v_next_warehouse,
      v_next_allocated_tubes,
      'JOB_ALLOCATE_EDIT_INC',
      format('Edited caulk allocation %s.', v_allocation.caulk_allocation_id),
      v_allocation.caulk_allocation_id,
      v_next_notes
    );

    update app.caulk_job_allocations
    set
      product_id = v_next_product_id,
      warehouse = v_next_warehouse,
      allocated_tubes = v_next_allocated_tubes,
      reserved_tubes_remaining = coalesce((v_local_reservation->>'reservedTubes')::integer, 0),
      notes = v_next_notes,
      updated_at = now(),
      updated_by = v_actor
    where id = v_allocation.id
      and org_id = p_org_id;

    v_transfer_result := app_api.caulk_start_pending_transfer(
      p_org_id,
      v_actor,
      v_allocation.id,
      v_allocation.caulk_allocation_id,
      v_allocation.job_id,
      v_allocation.job_number,
      v_next_product_id,
      p_payload->>'transferFromWarehouse',
      v_next_warehouse,
      coalesce((v_local_reservation->>'shortageTubes')::integer, 0),
      v_next_notes
    );
  else
    v_currently_covered := v_reserved_tubes + v_checked_out_tubes;
    v_next_reserved_tubes := v_reserved_tubes;

    if v_next_allocated_tubes < v_checked_out_tubes then
      perform app_api.raise_http(400, 'allocatedTubes cannot drop below already checked-out amount.');
    end if;

    if v_next_allocated_tubes > v_currently_covered then
      v_additional_coverage_needed := v_next_allocated_tubes - v_currently_covered;

      v_local_reservation := app_api.caulk_reserve_local_tubes(
        p_org_id,
        v_actor,
        v_allocation.product_id,
        v_allocation.warehouse,
        v_additional_coverage_needed,
        'JOB_ALLOCATE_EDIT_INC',
        format('Increased caulk allocation %s.', v_allocation.caulk_allocation_id),
        v_allocation.caulk_allocation_id,
        v_next_notes
      );

      v_next_reserved_tubes := v_next_reserved_tubes + coalesce((v_local_reservation->>'reservedTubes')::integer, 0);
      v_transfer_result := app_api.caulk_start_pending_transfer(
        p_org_id,
        v_actor,
        v_allocation.id,
        v_allocation.caulk_allocation_id,
        v_allocation.job_id,
        v_allocation.job_number,
        v_allocation.product_id,
        p_payload->>'transferFromWarehouse',
        v_allocation.warehouse,
        coalesce((v_local_reservation->>'shortageTubes')::integer, 0),
        v_next_notes
      );
    elsif v_next_allocated_tubes < v_currently_covered then
      v_release_tubes := least(v_reserved_tubes, v_currently_covered - v_next_allocated_tubes);
      if v_release_tubes > 0 then
        perform app_api.caulk_apply_stock_delta(
          p_org_id,
          v_actor,
          v_allocation.product_id,
          v_allocation.warehouse,
          'JOB_ALLOCATE_EDIT_DEC',
          v_release_tubes,
          format('Reduced caulk allocation %s.', v_allocation.caulk_allocation_id),
          '',
          v_allocation.caulk_allocation_id,
          v_next_notes
        );
        v_next_reserved_tubes := greatest(v_reserved_tubes - v_release_tubes, 0);
      end if;
    end if;

    update app.caulk_job_allocations
    set
      allocated_tubes = v_next_allocated_tubes,
      reserved_tubes_remaining = v_next_reserved_tubes,
      notes = v_next_notes,
      updated_at = now(),
      updated_by = v_actor
    where id = v_allocation.id
      and org_id = p_org_id;
  end if;

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'warnings', coalesce(v_transfer_result->'warnings', '[]'::jsonb)
  );
end;
$$;

create or replace function public.api_acl_allocations_caulk_checkout(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_allocation app.caulk_job_allocations;
  v_checkout_id text := app_api.create_log_id();
  v_actor text := app_api.trim_text(p_actor);
  v_caulk_allocation_id text := app_api.require_text(p_payload->>'caulkAllocationId', 'CaulkAllocationId');
  v_checkout_tubes integer := floor(nullif(app_api.trim_text(p_payload->>'checkoutTubes'), '')::numeric);
  v_pending_transfer_id text := '';
  v_open_checkout_count integer := 0;
  v_shortage integer := 0;
  v_consume_reserved integer;
  v_overage integer;
  v_notes text := app_api.trim_text(p_payload->>'notes');
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  if v_checkout_tubes is null or v_checkout_tubes <= 0 then
    perform app_api.raise_http(400, 'checkoutTubes must be greater than zero.');
  end if;

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.caulk_allocation_id = v_caulk_allocation_id
  for update;

  if not found then
    perform app_api.raise_http(404, format('Caulk allocation %s was not found.', v_caulk_allocation_id));
  end if;

  if v_allocation.status <> 'ACTIVE' then
    perform app_api.raise_http(400, format('Caulk allocation %s is not active.', v_caulk_allocation_id));
  end if;

  perform app_api.require_active_job_for_caulk(p_org_id, v_allocation.job_number);

  select t.transfer_id
  into v_pending_transfer_id
  from app.caulk_transfers t
  where t.org_id = p_org_id
    and t.caulk_allocation_id = v_allocation.id
    and t.status = 'PENDING'
  order by t.created_at desc, t.id desc
  limit 1
  for update;

  if coalesce(v_pending_transfer_id, '') <> '' then
    perform app_api.raise_http(
      400,
      format('Receive or cancel transfer %s before checking out this allocation.', v_pending_transfer_id)
    );
  end if;

  v_shortage := greatest(
    v_allocation.allocated_tubes
      - v_allocation.checked_out_tubes_total
      - v_allocation.reserved_tubes_remaining,
    0
  );
  if v_shortage > 0 then
    perform app_api.raise_http(
      400,
      format(
        '%s still needs %s tube%s transferred in before this allocation can be checked out.',
        v_allocation.warehouse,
        v_shortage,
        case when v_shortage = 1 then '' else 's' end
      )
    );
  end if;

  select count(*)
  into v_open_checkout_count
  from app.caulk_job_checkouts c
  where c.org_id = p_org_id
    and c.caulk_allocation_id = v_allocation.id
    and c.status = 'OPEN';

  if v_open_checkout_count > 0 then
    perform app_api.raise_http(
      400,
      format(
        'Caulk allocation %s already has %s open checkout%s and cannot be checked out again until that cycle is closed.',
        v_caulk_allocation_id,
        v_open_checkout_count,
        case when v_open_checkout_count = 1 then '' else 's' end
      )
    );
  end if;

  v_consume_reserved := least(v_checkout_tubes, v_allocation.reserved_tubes_remaining);
  v_overage := greatest(v_checkout_tubes - v_consume_reserved, 0);

  if v_overage > 0 then
    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_allocation.product_id,
      v_allocation.warehouse,
      'JOB_CHECKOUT_OVERAGE',
      -v_overage,
      format('Over-checkout on caulk allocation %s.', v_allocation.caulk_allocation_id),
      '',
      v_allocation.caulk_allocation_id,
      v_notes
    );
  end if;

  insert into app.caulk_job_checkouts (
    id,
    org_id,
    caulk_checkout_id,
    caulk_allocation_id,
    job_number,
    product_id,
    warehouse,
    checkout_tubes,
    overage_tubes,
    status,
    checked_out_at,
    checked_out_by,
    notes
  )
  values (
    gen_random_uuid(),
    p_org_id,
    v_checkout_id,
    v_allocation.id,
    v_allocation.job_number,
    v_allocation.product_id,
    v_allocation.warehouse,
    v_checkout_tubes,
    v_overage,
    'OPEN',
    now(),
    v_actor,
    v_notes
  );

  update app.caulk_job_allocations
  set
    reserved_tubes_remaining = greatest(v_allocation.reserved_tubes_remaining - v_consume_reserved, 0),
    checked_out_tubes_total = v_allocation.checked_out_tubes_total + v_checkout_tubes,
    overage_tubes_total = v_allocation.overage_tubes_total + v_overage,
    updated_at = now(),
    updated_by = v_actor
  where id = v_allocation.id
    and org_id = p_org_id;

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'caulkCheckoutId', v_checkout_id,
    'warnings', '[]'::jsonb
  );
end;
$$;

create or replace function public.api_acl_allocations_caulk_remove(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_allocation app.caulk_job_allocations;
  v_open_checkout_count integer := 0;
  v_actor text := app_api.trim_text(p_actor);
  v_caulk_allocation_id text := app_api.require_text(p_payload->>'caulkAllocationId', 'CaulkAllocationId');
  v_reason text;
  v_released_reserved_tubes integer := 0;
  v_pending_transfer_id text := '';
  v_cancel_result jsonb := '{}'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');

  select *
  into v_allocation
  from app.caulk_job_allocations a
  where a.org_id = p_org_id
    and a.caulk_allocation_id = v_caulk_allocation_id
  for update;

  if not found then
    perform app_api.raise_http(404, format('Caulk allocation %s was not found.', v_caulk_allocation_id));
  end if;

  if v_allocation.status <> 'ACTIVE' then
    perform app_api.raise_http(400, format('Caulk allocation %s is not active.', v_caulk_allocation_id));
  end if;

  select count(*)
  into v_open_checkout_count
  from app.caulk_job_checkouts c
  where c.org_id = p_org_id
    and c.caulk_allocation_id = v_allocation.id
    and c.status = 'OPEN';

  if v_open_checkout_count > 0 then
    perform app_api.raise_http(
      400,
      format(
        'Caulk allocation %s has %s open checkout%s. Check in first.',
        v_caulk_allocation_id,
        v_open_checkout_count,
        case when v_open_checkout_count = 1 then '' else 's' end
      )
    );
  end if;

  v_reason := coalesce(
    nullif(app_api.trim_text(p_payload->>'reason'), ''),
    format('Removed from job %s.', v_allocation.job_number)
  );

  select t.transfer_id
  into v_pending_transfer_id
  from app.caulk_transfers t
  where t.org_id = p_org_id
    and t.caulk_allocation_id = v_allocation.id
    and t.status = 'PENDING'
  order by t.created_at desc, t.id desc
  limit 1
  for update;

  if coalesce(v_pending_transfer_id, '') <> '' then
    v_cancel_result := app_api.caulk_cancel_pending_transfer_internal(
      p_org_id,
      v_actor,
      v_pending_transfer_id,
      format(
        'Cancelled pending transfer %s while removing allocation %s.',
        v_pending_transfer_id,
        v_caulk_allocation_id
      )
    );
    v_warnings := v_warnings || coalesce(v_cancel_result->'warnings', '[]'::jsonb);
  end if;

  if v_allocation.reserved_tubes_remaining > 0 then
    perform app_api.caulk_apply_stock_delta(
      p_org_id,
      v_actor,
      v_allocation.product_id,
      v_allocation.warehouse,
      'JOB_ALLOCATION_CANCEL_RETURN',
      v_allocation.reserved_tubes_remaining,
      v_reason,
      '',
      v_allocation.caulk_allocation_id,
      v_reason
    );
    v_released_reserved_tubes := v_allocation.reserved_tubes_remaining;
  end if;

  update app.caulk_job_allocations
  set
    status = 'CANCELLED',
    reserved_tubes_remaining = 0,
    resolved_at = now(),
    resolved_by = v_actor,
    notes = v_reason,
    updated_at = now(),
    updated_by = v_actor
  where id = v_allocation.id
    and org_id = p_org_id;

  return jsonb_build_object(
    'jobNumber', v_allocation.job_number,
    'caulkAllocationId', v_allocation.caulk_allocation_id,
    'releasedReservedTubes', v_released_reserved_tubes,
    'warnings', v_warnings
  );
end;
$$;

