-- Keep backend and Supabase migration streams aligned for dealer spelling corrections.

create or replace function app_api.seed_default_box_dealers(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public, app, app_api
as $$
begin
  if p_org_id is null then
    return;
  end if;

  insert into app.box_dealers (
    org_id,
    name,
    lookup_key
  )
  select
    p_org_id,
    defaults.name,
    app_api.normalize_catalog_lookup_key(defaults.name)
  from (
    values
      ('Eastman Performance Films'::text),
      ('Energy Products Distribution'::text),
      ('Accent'::text),
      ('Decorative Films'::text),
      ('Kingston Coatings'::text)
  ) as defaults(name)
  on conflict (org_id, lookup_key) do update set
    name = excluded.name,
    updated_at = timezone('utc', now());
end;
$$;

with corrected_rows as (
  insert into app.box_dealers (
    org_id,
    name,
    lookup_key
  )
  select
    d.org_id,
    'Energy Products Distribution'::text,
    app_api.normalize_catalog_lookup_key('Energy Products Distribution'::text)
  from app.box_dealers d
  where d.lookup_key = app_api.normalize_catalog_lookup_key('Energy products Distrubution'::text)
  on conflict (org_id, lookup_key) do update set
    name = excluded.name,
    updated_at = timezone('utc', now())
  returning org_id
)
delete from app.box_dealers d
where d.lookup_key = app_api.normalize_catalog_lookup_key('Energy products Distrubution'::text);

update app.boxes
set dealer = 'Energy Products Distribution'
where dealer = 'Energy products Distrubution';

/**
 * PURPOSE:
 * Keep auto shortage film orders aligned with live reserved coverage for a job.
 *
 * AFFECTS:
 * Ordered-box receipt, allocation apply, box edit/status transitions, and job updates
 * that create, update, or delete auto shortage film orders.
 *
 * WHEN CHANGING THIS, ALSO CHECK:
 * app_api.reconcile_auto_shortage_film_orders_for_box(...),
 * public.api_acl_allocations_apply(...), public.api_acl_jobs_update(...),
 * public.api_acl_boxes_update(...), public.api_acl_boxes_set_status(...),
 * public.api_acl_boxes_receive_ordered(...), and
 * backend/scripts/verify-ordered-box-allocation-flow.mjs.
 *
 * COMMON FAILURE MODES:
 * Legacy enum casts reject indexed warehouses, orphan shortage rows drift from
 * active allocations, or wrapper routes stop re-running shortage reconciliation.
 */
create or replace function app_api.reconcile_auto_shortage_film_orders_for_job(
  p_org_id uuid,
  p_actor text,
  p_job_number text,
  p_allow_placeholder_shortages boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_job app.jobs;
  v_requirement record;
  v_primary_orphan app.film_orders;
  v_new_order app.film_orders;
  v_orphan_film_order_id text;
  v_orphan_film_order_ids text[] := array[]::text[];
  v_source_box_ids text[] := array[]::text[];
  v_source_box_id text := '';
  v_target_warehouse text := '';
  v_committed_requested_feet integer := 0;
  v_target_requested_feet integer := 0;
  v_target_orphan_requested_feet integer := 0;
  v_created_count integer := 0;
  v_updated_count integer := 0;
  v_deleted_count integer := 0;
  v_normalized_job_number text := app_api.trim_text(p_job_number);
  v_actor_name text := app_api.trim_text(p_actor);
begin
  if v_normalized_job_number = '' then
    return jsonb_build_object(
      'createdCount', 0,
      'updatedCount', 0,
      'deletedCount', 0
    );
  end if;

  select *
  into v_job
  from app.jobs j
  where j.org_id = p_org_id
    and upper(trim(j.job_number)) = upper(trim(v_normalized_job_number))
  limit 1;

  if not found then
    return jsonb_build_object(
      'createdCount', 0,
      'updatedCount', 0,
      'deletedCount', 0
    );
  end if;

  for v_requirement in
    with target_box_ids as (
      select distinct a.box_id
      from app.allocations a
      join app.boxes b
        on b.org_id = a.org_id
       and b.box_id = a.box_id
      where a.org_id = p_org_id
        and a.status = 'ACTIVE'
        and a.requirement_id is not null
        and upper(trim(a.job_number)) = upper(trim(v_normalized_job_number))
        and upper(coalesce(b.status::text, '')) in ('IN_STOCK', 'TRANSFER')
    ),
    reservation_allocations as (
      select
        a.allocation_id,
        a.box_id,
        a.job_number,
        a.job_date,
        a.allocated_feet,
        coalesce(a.covered_feet, a.allocated_feet) as stored_covered_feet,
        a.requirement_id,
        b.width_in as box_width_in,
        b.warehouse::text as box_warehouse,
        app_api.box_physical_feet_available(b) as physical_feet_available,
        coalesce(j.created_at, a.created_at) as job_created_at,
        a.created_at as allocation_created_at
      from app.allocations a
      join target_box_ids tb
        on tb.box_id = a.box_id
      join app.boxes b
        on b.org_id = a.org_id
       and b.box_id = a.box_id
      left join app.jobs j
        on j.org_id = a.org_id
       and upper(trim(j.job_number)) = upper(trim(a.job_number))
      where a.org_id = p_org_id
        and a.status = 'ACTIVE'
        and upper(coalesce(b.status::text, '')) in ('IN_STOCK', 'TRANSFER')
    ),
    reservation_snapshots as (
      select
        ra.*,
        greatest(
          least(
            ra.allocated_feet,
            greatest(
              coalesce(ra.physical_feet_available, 0)
              - coalesce(
                  sum(ra.allocated_feet) over (
                    partition by ra.box_id
                    order by
                      case when ra.job_date is null then 1 else 0 end,
                      ra.job_date asc nulls last,
                      ra.job_created_at asc,
                      ra.allocation_created_at asc,
                      ra.allocation_id asc
                    rows between unbounded preceding and 1 preceding
                  ),
                  0
                ),
              0
            )
          ),
          0
        )::integer as backed_physical_feet
      from reservation_allocations ra
    ),
    requirement_coverage as (
      select
        r.id as requirement_id,
        r.manufacturer,
        r.film_name,
        r.width_in,
        r.required_feet,
        coalesce(
          sum(
            case
              when rs.requirement_id = r.id then
                app_api.compute_covered_feet_from_allocation(
                  rs.backed_physical_feet,
                  rs.box_width_in,
                  r.width_in,
                  rs.stored_covered_feet
                )
              else 0
            end
          ),
          0
        )::integer as backed_covered_feet,
        array_remove(array_agg(distinct case when rs.requirement_id = r.id then rs.box_id end), null) as source_box_ids,
        min(case when rs.requirement_id = r.id then rs.box_id end) as source_box_id,
        min(case when rs.requirement_id = r.id then rs.box_warehouse end) as source_warehouse
      from app.job_requirements r
      left join reservation_snapshots rs
        on rs.requirement_id = r.id
       and upper(trim(rs.job_number)) = upper(trim(v_normalized_job_number))
      where r.org_id = p_org_id
        and r.job_id = v_job.id
      group by r.id, r.manufacturer, r.film_name, r.width_in, r.required_feet
    )
    select *
    from requirement_coverage
  loop
    v_source_box_ids := coalesce(v_requirement.source_box_ids, array[]::text[]);
    v_source_box_id := app_api.trim_text(v_requirement.source_box_id);

    if coalesce(array_length(v_source_box_ids, 1), 0) = 0 or v_source_box_id = '' then
      continue;
    end if;

    v_target_warehouse := app_api.require_org_warehouse(
      p_org_id,
      coalesce(
        nullif(app_api.trim_text(v_requirement.source_warehouse), ''),
        nullif(app_api.trim_text(v_job.warehouse::text), '')
      ),
      'Shortage film order warehouse'
    );
    v_target_requested_feet := greatest(
      case
        when v_job.due_date is not null or coalesce(p_allow_placeholder_shortages, false)
          then coalesce(v_requirement.required_feet, 0) - coalesce(v_requirement.backed_covered_feet, 0)
        else 0
      end,
      0
    );

    select coalesce(sum(fo.requested_feet), 0)::integer
    into v_committed_requested_feet
    from app.film_orders fo
    where fo.org_id = p_org_id
      and upper(trim(fo.job_number)) = upper(trim(v_normalized_job_number))
      and fo.status in ('FILM_ORDER', 'FILM_ON_THE_WAY')
      and fo.source_box_id = any(v_source_box_ids)
      and upper(trim(fo.manufacturer)) = upper(trim(coalesce(v_requirement.manufacturer, '')))
      and upper(trim(fo.film_name)) = upper(trim(coalesce(v_requirement.film_name, '')))
      and coalesce(fo.width_in, 0) = coalesce(v_requirement.width_in, 0)
      and (
        exists (
          select 1
          from app.film_order_box_links l
          where l.org_id = fo.org_id
            and l.film_order_id = fo.film_order_id
        )
        or exists (
          select 1
          from app.allocations a
          where a.org_id = fo.org_id
            and a.film_order_id = fo.film_order_id
            and a.status <> 'CANCELLED'
        )
      );

    v_target_orphan_requested_feet := greatest(v_target_requested_feet - v_committed_requested_feet, 0);

    select coalesce(array_agg(fo.film_order_id order by fo.created_at asc, fo.film_order_id asc), array[]::text[])
    into v_orphan_film_order_ids
    from app.film_orders fo
    where fo.org_id = p_org_id
      and upper(trim(fo.job_number)) = upper(trim(v_normalized_job_number))
      and fo.status in ('FILM_ORDER', 'FILM_ON_THE_WAY')
      and fo.source_box_id = any(v_source_box_ids)
      and upper(trim(fo.manufacturer)) = upper(trim(coalesce(v_requirement.manufacturer, '')))
      and upper(trim(fo.film_name)) = upper(trim(coalesce(v_requirement.film_name, '')))
      and coalesce(fo.width_in, 0) = coalesce(v_requirement.width_in, 0)
      and not exists (
        select 1
        from app.film_order_box_links l
        where l.org_id = fo.org_id
          and l.film_order_id = fo.film_order_id
      )
      and not exists (
        select 1
        from app.allocations a
        where a.org_id = fo.org_id
          and a.film_order_id = fo.film_order_id
          and a.status <> 'CANCELLED'
      );

    v_primary_orphan := null;
    select fo.*
    into v_primary_orphan
    from app.film_orders fo
    where fo.org_id = p_org_id
      and upper(trim(fo.job_number)) = upper(trim(v_normalized_job_number))
      and fo.status in ('FILM_ORDER', 'FILM_ON_THE_WAY')
      and fo.source_box_id = any(v_source_box_ids)
      and upper(trim(fo.manufacturer)) = upper(trim(coalesce(v_requirement.manufacturer, '')))
      and upper(trim(fo.film_name)) = upper(trim(coalesce(v_requirement.film_name, '')))
      and coalesce(fo.width_in, 0) = coalesce(v_requirement.width_in, 0)
      and not exists (
        select 1
        from app.film_order_box_links l
        where l.org_id = fo.org_id
          and l.film_order_id = fo.film_order_id
      )
      and not exists (
        select 1
        from app.allocations a
        where a.org_id = fo.org_id
          and a.film_order_id = fo.film_order_id
          and a.status <> 'CANCELLED'
      )
    order by fo.created_at asc, fo.film_order_id asc
    limit 1;

    if v_target_orphan_requested_feet > 0 and app_api.trim_text(coalesce(v_primary_orphan.film_order_id, '')) <> '' then
      if v_primary_orphan.requested_feet is distinct from v_target_orphan_requested_feet
        or coalesce(v_primary_orphan.covered_feet, 0) <> 0
        or coalesce(v_primary_orphan.ordered_feet, 0) <> 0
        or v_primary_orphan.remaining_to_order_feet is distinct from v_target_orphan_requested_feet
        or v_primary_orphan.job_date is distinct from v_job.due_date
        or coalesce(v_primary_orphan.crew_leader, '') is distinct from coalesce(v_job.crew_leader, '')
        or coalesce(v_primary_orphan.status::text, '') is distinct from 'FILM_ORDER'
        or coalesce(v_primary_orphan.source_box_id, '') is distinct from v_source_box_id
        or coalesce(v_primary_orphan.warehouse::text, '') is distinct from v_target_warehouse
      then
        v_primary_orphan.job_id := v_job.id;
        v_primary_orphan.job_number := v_job.job_number;
        v_primary_orphan.warehouse := v_target_warehouse;
        v_primary_orphan.manufacturer := v_requirement.manufacturer;
        v_primary_orphan.film_name := v_requirement.film_name;
        v_primary_orphan.width_in := v_requirement.width_in;
        v_primary_orphan.requested_feet := v_target_orphan_requested_feet;
        v_primary_orphan.covered_feet := 0;
        v_primary_orphan.ordered_feet := 0;
        v_primary_orphan.remaining_to_order_feet := v_target_orphan_requested_feet;
        v_primary_orphan.job_date := v_job.due_date;
        v_primary_orphan.crew_leader := coalesce(v_job.crew_leader, '');
        v_primary_orphan.status := 'FILM_ORDER';
        v_primary_orphan.source_box_id := v_source_box_id;
        v_primary_orphan.resolved_at := null;
        v_primary_orphan.resolved_by := '';
        perform app_api.save_film_order(v_primary_orphan);
        v_updated_count := v_updated_count + 1;
      end if;
    elsif v_target_orphan_requested_feet > 0 then
      v_new_order := null;
      v_new_order.org_id := p_org_id;
      v_new_order.film_order_id := app_api.create_log_id();
      v_new_order.job_id := v_job.id;
      v_new_order.job_number := v_job.job_number;
      v_new_order.warehouse := v_target_warehouse;
      v_new_order.manufacturer := v_requirement.manufacturer;
      v_new_order.film_name := v_requirement.film_name;
      v_new_order.width_in := v_requirement.width_in;
      v_new_order.requested_feet := v_target_orphan_requested_feet;
      v_new_order.covered_feet := 0;
      v_new_order.ordered_feet := 0;
      v_new_order.remaining_to_order_feet := v_target_orphan_requested_feet;
      v_new_order.job_date := v_job.due_date;
      v_new_order.crew_leader := coalesce(v_job.crew_leader, '');
      v_new_order.status := 'FILM_ORDER';
      v_new_order.source_box_id := v_source_box_id;
      v_new_order.resolved_at := null;
      v_new_order.resolved_by := '';
      v_new_order.notes := format(
        'Created from a shortage while reconciling reserved film for job %s.',
        v_job.job_number
      );
      v_new_order.created_at := now();
      v_new_order.created_by := v_actor_name;
      perform app_api.save_film_order(v_new_order);
      v_created_count := v_created_count + 1;
    end if;

    foreach v_orphan_film_order_id in array coalesce(v_orphan_film_order_ids, array[]::text[])
    loop
      if v_target_orphan_requested_feet > 0
        and v_orphan_film_order_id = app_api.trim_text(coalesce(v_primary_orphan.film_order_id, ''))
      then
        continue;
      end if;

      perform app_api.delete_film_order_links_by_film_order_id(p_org_id, v_orphan_film_order_id);
      perform app_api.delete_film_order(p_org_id, v_orphan_film_order_id);
      v_deleted_count := v_deleted_count + 1;
    end loop;
  end loop;

  return jsonb_build_object(
    'createdCount', v_created_count,
    'updatedCount', v_updated_count,
    'deletedCount', v_deleted_count
  );
end;
$$;

/**
 * PURPOSE:
 * Reassert the directional exterior-film compatibility rule in the SQL allocation matcher and
 * allocation apply wrappers so live mutation behavior stays aligned with preview/runtime logic.
 *
 * AFFECTS:
 * /allocations/add, /allocations/apply, requirement-bound allocation validation, shortage film
 * order creation/cleanup, and job requirement coverage derived from saved allocations.
 *
 * WHEN CHANGING THIS, ALSO CHECK:
 * shared/domain/jobPlanningFilmMatcher.mjs, frontend/src/features/inventory/utils/jobAllocationMatching.ts,
 * backend/scripts/verify-allocation-film-match-parity.mjs, and backend/scripts/verify-ordered-box-allocation-flow.mjs.
 *
 * COMMON FAILURE MODES:
 * Preview/apply drift, exterior rolls rejected for base requirements, base rolls accepted for
 * exterior requirements, stale shortage orders, or requirement coverage falling out of sync.
 */

create or replace function app_api.normalize_requirement_film_family_name(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns text
language plpgsql
stable
as $$
declare
  v_manufacturer text := app_api.normalize_requirement_match_manufacturer_label(p_manufacturer);
  v_manufacturer_key text := app_api.normalize_requirement_match_manufacturer_lookup_key(p_manufacturer);
  v_film_name text;
  v_night_vision_code text := '';
begin
  v_film_name := app_api.normalize_collapsed_catalog_label(
    app_api.resolve_canonical_film_name(p_org_id, v_manufacturer, p_film_name)
  );

  if v_film_name = '' then
    return '';
  end if;

  v_film_name := app_api.normalize_requirement_match_descriptor_tokens(
    app_api.strip_requirement_match_manufacturer_prefixes(v_manufacturer, v_film_name)
  );

  v_film_name := app_api.normalize_requirement_avery_natura_shade_film_name(
    v_manufacturer,
    v_film_name
  );

  if v_manufacturer_key = app_api.normalize_requirement_match_manufacturer_lookup_key('3M Solar') then
    v_night_vision_code := app_api.infer_requirement_night_vision_code(v_film_name);
    if v_night_vision_code <> '' then
      v_film_name := format('Night Vision %s', v_night_vision_code);
    end if;
  end if;

  if v_film_name ~* '(^|[[:space:]])Exterior[[:space:]]*$' then
    v_film_name := coalesce(
      nullif(
        app_api.normalize_collapsed_catalog_label(
          regexp_replace(v_film_name, '[[:space:]]+Exterior[[:space:]]*$', '', 'i')
        ),
        ''
      ),
      v_film_name
    );
  end if;

  return v_film_name;
end;
$$;

create or replace function app_api.normalize_requirement_film_family_key(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns text
language plpgsql
stable
as $$
declare
  v_manufacturer_key text := app_api.normalize_requirement_match_manufacturer_lookup_key(p_manufacturer);
  v_family_film_name text := app_api.normalize_requirement_film_family_name(
    p_org_id,
    p_manufacturer,
    p_film_name
  );
begin
  return v_manufacturer_key || '|' || app_api.normalize_requirement_match_compact_lookup_key(v_family_film_name);
end;
$$;

create or replace function app_api.requirement_film_is_exterior(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns boolean
language sql
stable
as $$
  select app_api.trim_text(
      app_api.resolve_canonical_film_name(
        p_org_id,
        app_api.normalize_requirement_match_manufacturer_label(p_manufacturer),
        p_film_name
      )
    ) ~* '(^|[[:space:]])Exterior[[:space:]]*$';
$$;

create or replace function app_api.extract_requirement_compact_base_code(
  p_compact_family text
)
returns text
language sql
immutable
as $$
  select coalesce(
    (regexp_match(coalesce(p_compact_family, ''), '^([a-z]{1,4}[0-9]{1,4})'))[1],
    ''
  );
$$;

create or replace function app_api.requirement_film_is_compatible(
  p_org_id uuid,
  p_candidate_manufacturer text,
  p_candidate_film_name text,
  p_requirement_manufacturer text,
  p_requirement_film_name text
)
returns boolean
language sql
stable
as $$
  with candidate as (
    select
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_candidate_manufacturer,
          p_candidate_film_name
        ),
        '|',
        1
      ) as manufacturer_key,
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_candidate_manufacturer,
          p_candidate_film_name
        ),
        '|',
        2
      ) as compact_family,
      app_api.extract_requirement_compact_base_code(
        split_part(
          app_api.normalize_requirement_film_family_key(
            p_org_id,
            p_candidate_manufacturer,
            p_candidate_film_name
          ),
          '|',
          2
        )
      ) as compact_base_code,
      app_api.requirement_film_is_exterior(
        p_org_id,
        p_candidate_manufacturer,
        p_candidate_film_name
      ) as is_exterior
  ),
  requirement as (
    select
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_requirement_manufacturer,
          p_requirement_film_name
        ),
        '|',
        1
      ) as manufacturer_key,
      split_part(
        app_api.normalize_requirement_film_family_key(
          p_org_id,
          p_requirement_manufacturer,
          p_requirement_film_name
        ),
        '|',
        2
      ) as compact_family,
      app_api.extract_requirement_compact_base_code(
        split_part(
          app_api.normalize_requirement_film_family_key(
            p_org_id,
            p_requirement_manufacturer,
            p_requirement_film_name
          ),
          '|',
          2
        )
      ) as compact_base_code,
      app_api.requirement_film_is_exterior(
        p_org_id,
        p_requirement_manufacturer,
        p_requirement_film_name
      ) as is_exterior
  )
  select
    candidate.manufacturer_key = requirement.manufacturer_key
    and (
      candidate.compact_family = requirement.compact_family
      or (
        requirement.compact_base_code <> ''
        and requirement.compact_family = requirement.compact_base_code
        and candidate.compact_base_code = requirement.compact_base_code
        and candidate.compact_family like requirement.compact_family || '%'
        and length(candidate.compact_family) > length(requirement.compact_family)
      )
    )
    and (
      not requirement.is_exterior
      or candidate.is_exterior
    )
  from candidate, requirement;
$$;

create or replace function public.api_allocations_apply(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_source app.boxes;
  v_candidate app.boxes;
  v_job_context jsonb;
  v_requested_feet integer := coalesce(floor(nullif(app_api.trim_text(p_payload->>'requestedFeet'), '')::numeric), 0);
  v_requested_width_in numeric := nullif(app_api.trim_text(p_payload->>'requestedWidthIn'), '')::numeric;
  v_requirement_id_text text := app_api.trim_text(p_payload->>'requirementId');
  v_should_validate_requirement boolean := false;
  v_requirement_id uuid;
  v_requirement app.job_requirements;
  v_source_film_key text;
  v_requirement_is_exterior boolean := false;
  v_remaining integer := 0;
  v_requirement_remaining_feet integer := 0;
  v_source_planning_feet integer := 0;
  v_source_suggested integer := 0;
  v_source_suggested_covered integer := 0;
  v_candidate_planning_feet integer := 0;
  v_candidate_suggested integer := 0;
  v_candidate_suggested_covered integer := 0;
  v_cross_warehouse boolean := coalesce((p_payload->>'crossWarehouse')::boolean, false);
  v_selected_box_ids text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'selectedSuggestionBoxIds', '[]'::jsonb))),
    array[]::text[]
  );
  v_extra_allocations jsonb := coalesce(p_payload->'extraAllocations', '[]'::jsonb);
  v_extra_entry jsonb;
  v_extra_box_id text;
  v_extra_feet integer;
  v_extra_processed_box_ids text[] := array[]::text[];
  v_allocation app.allocations;
  v_allocation_ids text[] := array[]::text[];
  v_film_order app.film_orders;
  v_cleanup_order app.film_orders;
  v_cleanup_link_count integer := 0;
  v_cleanup_allocation_count integer := 0;
  v_deleted_shortage_film_order_count integer := 0;
  v_conflict_count integer;
  v_job_warehouse text;
  v_source_transfer_destination text := '';
  v_candidate_transfer_destination text := '';
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_org_member(p_org_id);

  if v_requested_feet < 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be zero or greater.');
  end if;

  if coalesce(jsonb_typeof(v_extra_allocations), '') not in ('', 'array') then
    perform app_api.raise_http(400, 'extraAllocations must be an array.');
  end if;

  select *
  into v_source
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  v_job_context := app_api.resolve_job_context(
    p_org_id,
    p_payload->>'jobNumber',
    p_payload->>'jobDate',
    p_payload->>'crewLeader'
  );

  if app_api.trim_text(p_payload->>'jobWarehouse') <> '' then
    v_job_warehouse := app_api.require_org_warehouse(p_org_id, p_payload->>'jobWarehouse', 'Job warehouse');
  else
    select coalesce(j.warehouse::text, '')
    into v_job_warehouse
    from app.jobs j
    where j.org_id = p_org_id
      and upper(trim(j.job_number)) = upper(trim(v_job_context->>'jobNumber'))
    limit 1;
  end if;

  if coalesce(v_source.status::text, '') = 'TRANSFER' then
    select coalesce(t.destination_warehouse::text, '')
    into v_source_transfer_destination
    from app.box_transfers t
    where t.org_id = p_org_id
      and t.box_record_id = v_source.id
      and t.status = 'PENDING'
    order by t.created_at desc, t.id desc
    limit 1;

    if coalesce(v_job_warehouse, '') = '' then
      perform app_api.raise_http(
        400,
        format('Box %s is in transfer status and needs a job warehouse before it can be allocated.', v_source.box_id)
      );
    end if;

    if v_source_transfer_destination = '' then
      perform app_api.raise_http(
        400,
        format('Box %s is in transfer status but no pending transfer was found.', v_source.box_id)
      );
    end if;

    if upper(v_source_transfer_destination) <> upper(v_job_warehouse) then
      perform app_api.raise_http(
        400,
        format(
          'Box %s is transferring to %s and cannot be allocated to a job in %s.',
          v_source.box_id,
          v_source_transfer_destination,
          v_job_warehouse
        )
      );
    end if;
  elsif coalesce(v_source.status::text, '') not in ('IN_STOCK', 'ORDERED') then
    perform app_api.raise_http(400, 'Only in-stock, ordered, or matching transfer boxes can be allocated.');
  end if;

  v_source_film_key := app_api.normalize_requirement_film_key(
    p_org_id,
    v_source.manufacturer,
    v_source.film_name
  );

  v_should_validate_requirement := v_requested_feet > 0 or v_requirement_id_text <> '';

  if v_should_validate_requirement then
    if v_requirement_id_text = '' then
      perform app_api.raise_http(400, 'RequirementId is required for film allocations.');
    end if;

    begin
      v_requirement_id := v_requirement_id_text::uuid;
    exception
      when others then
        perform app_api.raise_http(400, 'RequirementId must be a valid UUID.');
    end;

    select r.*
    into v_requirement
    from app.job_requirements r
    where r.org_id = p_org_id
      and r.job_id = app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber')
      and r.id = v_requirement_id;

    if not found then
      perform app_api.raise_http(
        400,
        format('Requirement %s does not belong to job %s.', v_requirement_id, v_job_context->>'jobNumber')
      );
    end if;

    v_requirement_is_exterior := app_api.requirement_film_is_exterior(
      p_org_id,
      v_requirement.manufacturer,
      v_requirement.film_name
    );

    if not app_api.requirement_film_is_compatible(
      p_org_id,
      v_source.manufacturer,
      v_source.film_name,
      v_requirement.manufacturer,
      v_requirement.film_name
    ) then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    if v_source.width_in < v_requirement.width_in then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    v_requested_width_in := v_requirement.width_in;
  elsif v_requested_width_in is null or v_requested_width_in <= 0 then
    v_requested_width_in := v_source.width_in;
  end if;

  if v_source.width_in < v_requested_width_in then
    perform app_api.raise_http(400, 'Source box width must meet or exceed the requested width.');
  end if;

  v_remaining := greatest(v_requested_feet, 0);
  v_source_planning_feet := app_api.allocation_planning_feet_for_box(v_source);

  if v_requested_feet > 0 then
    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_source.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count = 0 then
      select
        p.allocated_feet,
        p.covered_feet,
        p.remaining_covered_feet
      into
        v_source_suggested,
        v_source_suggested_covered,
        v_remaining
      from app_api.plan_allocation_coverage(
        v_remaining,
        v_source_planning_feet,
        v_source.width_in,
        v_requested_width_in
      ) p;
    end if;
  end if;

  if v_source_suggested > 0 then
    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_source,
      v_job_context,
      v_source_suggested,
      v_source_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    if coalesce(v_source.status::text, '') in ('IN_STOCK', 'TRANSFER') then
      v_source.feet_available := greatest(v_source.feet_available - v_source_suggested, 0);
      v_source := app_api.save_box(v_source);
    end if;
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end if;

  for v_candidate in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id <> v_source.box_id
      and (
        coalesce(b.status::text, '') in ('IN_STOCK', 'ORDERED')
        or (
          coalesce(b.status::text, '') = 'TRANSFER'
          and coalesce(v_job_warehouse, '') <> ''
          and exists (
            select 1
            from app.box_transfers t
            where t.org_id = p_org_id
              and t.box_record_id = b.id
              and t.status = 'PENDING'
              and upper(coalesce(t.destination_warehouse, '')) = upper(v_job_warehouse)
          )
        )
      )
      and app_api.compute_allocation_planning_feet(
        coalesce(b.status::text, ''),
        b.initial_feet,
        b.feet_available,
        app_api.active_allocated_feet_for_box(p_org_id, b.box_id)
      ) > 0
      and case
        when v_requirement_id is not null then app_api.requirement_film_is_compatible(
          p_org_id,
          b.manufacturer,
          b.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        )
        else app_api.normalize_requirement_film_key(p_org_id, b.manufacturer, b.film_name) = v_source_film_key
      end
      and b.width_in >= v_requested_width_in
      and (v_cross_warehouse or b.warehouse = v_source.warehouse)
    order by
      case
        when coalesce(b.status::text, '') = 'IN_STOCK' then 0
        when coalesce(b.status::text, '') = 'TRANSFER' then 1
        when coalesce(b.status::text, '') = 'ORDERED' then 2
        else 3
      end,
      case
        when b.width_in = v_requested_width_in then 0
        when app_api.allocation_coverage_multiplier(b.width_in, v_requested_width_in) > 1 then 1
        else 2
      end,
      (b.width_in - v_requested_width_in),
      case
        when v_requirement_id is not null
          and not v_requirement_is_exterior
          and app_api.requirement_film_is_exterior(p_org_id, b.manufacturer, b.film_name)
        then 1
        else 0
      end,
      coalesce(b.received_date, b.order_date, '9999-12-31'::date),
      b.box_id
    for update
  loop
    exit when v_remaining <= 0;

    if coalesce(array_length(v_selected_box_ids, 1), 0) > 0 and array_position(v_selected_box_ids, v_candidate.box_id) is null then
      continue;
    end if;

    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_candidate.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count > 0 then
      continue;
    end if;

    v_candidate_planning_feet := app_api.allocation_planning_feet_for_box(v_candidate);

    select
      p.allocated_feet,
      p.covered_feet,
      p.remaining_covered_feet
    into
      v_candidate_suggested,
      v_candidate_suggested_covered,
      v_remaining
    from app_api.plan_allocation_coverage(
      v_remaining,
      v_candidate_planning_feet,
      v_candidate.width_in,
      v_requested_width_in
    ) p;

    if v_candidate_suggested <= 0 or v_candidate_suggested_covered <= 0 then
      continue;
    end if;

    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_candidate,
      v_job_context,
      v_candidate_suggested,
      v_candidate_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    if coalesce(v_candidate.status::text, '') in ('IN_STOCK', 'TRANSFER') then
      v_candidate.feet_available := greatest(v_candidate.feet_available - v_allocation.allocated_feet, 0);
      perform app_api.save_box(v_candidate);
    end if;
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end loop;

  if coalesce(jsonb_typeof(v_extra_allocations), '') = 'array' then
    for v_extra_entry in
      select value
      from jsonb_array_elements(v_extra_allocations)
    loop
      if coalesce(jsonb_typeof(v_extra_entry), '') <> 'object' then
        perform app_api.raise_http(400, 'Each extra allocation entry must be an object.');
      end if;

      v_extra_box_id := app_api.require_text(v_extra_entry->>'boxId', 'extraAllocations[].boxId');
      v_extra_feet := floor(nullif(app_api.trim_text(v_extra_entry->>'allocatedFeet'), '')::numeric);

      if v_extra_feet is null or v_extra_feet <= 0 then
        perform app_api.raise_http(400, format('Extra allocation for box %s must be greater than zero.', v_extra_box_id));
      end if;

      if array_position(v_extra_processed_box_ids, v_extra_box_id) is not null then
        perform app_api.raise_http(400, format('Duplicate extra allocation entry for box %s.', v_extra_box_id));
      end if;

      select *
      into v_candidate
      from app.boxes b
      where b.org_id = p_org_id
        and b.box_id = v_extra_box_id
      for update;

      if not found then
        perform app_api.raise_http(404, format('Box not found: %s', v_extra_box_id));
      end if;

      if coalesce(v_candidate.status::text, '') = 'TRANSFER' then
        select coalesce(t.destination_warehouse::text, '')
        into v_candidate_transfer_destination
        from app.box_transfers t
        where t.org_id = p_org_id
          and t.box_record_id = v_candidate.id
          and t.status = 'PENDING'
        order by t.created_at desc, t.id desc
        limit 1;

        if coalesce(v_job_warehouse, '') = '' then
          perform app_api.raise_http(
            400,
            format('Box %s is in transfer status and needs a job warehouse before it can be allocated.', v_candidate.box_id)
          );
        end if;

        if v_candidate_transfer_destination = '' then
          perform app_api.raise_http(
            400,
            format('Box %s is in transfer status but no pending transfer was found.', v_candidate.box_id)
          );
        end if;

        if upper(v_candidate_transfer_destination) <> upper(v_job_warehouse) then
          perform app_api.raise_http(
            400,
            format(
              'Box %s is transferring to %s and cannot be allocated to a job in %s.',
              v_candidate.box_id,
              v_candidate_transfer_destination,
              v_job_warehouse
            )
          );
        end if;
      elsif coalesce(v_candidate.status::text, '') not in ('IN_STOCK', 'ORDERED') then
        perform app_api.raise_http(400, format('Box %s is no longer allocatable.', v_candidate.box_id));
      end if;

      if v_requirement_id is not null then
        if not app_api.requirement_film_is_compatible(
          p_org_id,
          v_candidate.manufacturer,
          v_candidate.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        ) or v_candidate.width_in < v_requested_width_in then
          perform app_api.raise_http(
            400,
            format(
              'Extra box %s must use a compatible film and meet the requested width for this allocation.',
              v_candidate.box_id
            )
          );
        end if;
      elsif app_api.normalize_requirement_film_key(p_org_id, v_candidate.manufacturer, v_candidate.film_name) <> v_source_film_key
        or v_candidate.width_in < v_requested_width_in then
        perform app_api.raise_http(
          400,
          format(
            'Extra box %s must match film and meet the requested width for this allocation.',
            v_candidate.box_id
          )
        );
      end if;

      v_candidate_planning_feet := app_api.allocation_planning_feet_for_box(v_candidate);
      if v_candidate_planning_feet < v_extra_feet then
        perform app_api.raise_http(400, format('Box %s no longer has enough planning LF.', v_candidate.box_id));
      end if;

      v_allocation := app_api.create_allocation(
        p_org_id,
        v_candidate,
        v_job_context,
        v_extra_feet,
        p_actor,
        '',
        'EXTRA',
        null
      );
      if coalesce(v_candidate.status::text, '') in ('IN_STOCK', 'TRANSFER') then
        v_candidate.feet_available := greatest(v_candidate.feet_available - v_extra_feet, 0);
        perform app_api.save_box(v_candidate);
      end if;
      v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
      v_extra_processed_box_ids := array_append(v_extra_processed_box_ids, v_extra_box_id);
    end loop;
  end if;

  if v_requested_feet = 0 and coalesce(array_length(v_extra_processed_box_ids, 1), 0) = 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be greater than zero unless extraAllocations are provided.');
  end if;

  if v_requirement_id is not null and v_requested_feet > 0 then
    select greatest(
      coalesce(v_requirement.required_feet, 0) - least(
        coalesce(v_requirement.required_feet, 0),
        coalesce(sum(
          case
            when coalesce(a.covered_feet, 0) > 0 then a.covered_feet
            else a.allocated_feet
          end
        ), 0)
      ),
      0
    )::integer
    into v_requirement_remaining_feet
    from app.allocations a
    join app.boxes b
      on b.org_id = a.org_id
     and upper(b.box_id) = upper(a.box_id)
    where a.org_id = p_org_id
      and a.requirement_id = v_requirement_id
      and a.status <> 'CANCELLED'
      and coalesce(a.allocation_kind::text, 'REQUIREMENT') <> 'EXTRA'
      and not (
        a.status = 'ACTIVE'
        and coalesce(b.status::text, '') in ('ZEROED', 'RETIRED')
      )
      and app_api.requirement_film_is_compatible(
        p_org_id,
        b.manufacturer,
        b.film_name,
        v_requirement.manufacturer,
        v_requirement.film_name
      )
      and coalesce(b.width_in, 0) >= coalesce(v_requirement.width_in, 0);

    if v_requirement_remaining_feet <= 0 then
      for v_cleanup_order in
        select fo.*
        from app.film_orders fo
        where fo.org_id = p_org_id
          and upper(trim(fo.job_number)) = upper(trim(v_job_context->>'jobNumber'))
          and coalesce(fo.status::text, '') in ('FILM_ORDER', 'FILM_ON_THE_WAY')
          and coalesce(trim(fo.source_box_id), '') <> ''
          and app_api.normalize_job_requirement_lookup_key(
            fo.manufacturer,
            fo.film_name,
            fo.width_in
          ) = app_api.normalize_job_requirement_lookup_key(
            v_requirement.manufacturer,
            v_requirement.film_name,
            v_requirement.width_in
          )
      loop
        select count(*)
        into v_cleanup_link_count
        from app.film_order_box_links l
        where l.org_id = p_org_id
          and l.film_order_id = v_cleanup_order.film_order_id;

        if v_cleanup_link_count > 0 then
          continue;
        end if;

        select count(*)
        into v_cleanup_allocation_count
        from app.allocations a
        where a.org_id = p_org_id
          and a.film_order_id = v_cleanup_order.film_order_id;

        if v_cleanup_allocation_count > 0 then
          continue;
        end if;

        perform app_api.delete_film_order_links_by_film_order_id(p_org_id, v_cleanup_order.film_order_id);
        perform app_api.delete_film_order(p_org_id, v_cleanup_order.film_order_id);
        v_deleted_shortage_film_order_count := v_deleted_shortage_film_order_count + 1;
      end loop;
    end if;

    if v_deleted_shortage_film_order_count > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Removed %s stale shortage film order%s for job %s after fulfilling the selected requirement.',
          v_deleted_shortage_film_order_count,
          case when v_deleted_shortage_film_order_count = 1 then '' else 's' end,
          v_job_context->>'jobNumber'
        )
      );
    end if;
  end if;

  if v_remaining > 0 then
    if coalesce(v_job_warehouse, '') = '' then
      v_job_warehouse := v_source.warehouse;
    end if;

    v_film_order.id := gen_random_uuid();
    v_film_order.org_id := p_org_id;
    v_film_order.film_order_id := app_api.create_log_id();
    v_film_order.job_id := app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber');
    v_film_order.job_number := v_job_context->>'jobNumber';
    v_film_order.warehouse := v_job_warehouse;
    v_film_order.manufacturer := coalesce(v_requirement.manufacturer, v_source.manufacturer);
    v_film_order.film_name := coalesce(v_requirement.film_name, v_source.film_name);
    v_film_order.width_in := v_requested_width_in;
    v_film_order.requested_feet := v_remaining;
    v_film_order.covered_feet := 0;
    v_film_order.ordered_feet := 0;
    v_film_order.remaining_to_order_feet := v_remaining;
    v_film_order.job_date := nullif(v_job_context->>'jobDate', '')::date;
    v_film_order.crew_leader := coalesce(v_job_context->>'crewLeader', '');
    v_film_order.status := 'FILM_ORDER';
    v_film_order.source_box_id := v_source.box_id;
    v_film_order.resolved_at := null;
    v_film_order.resolved_by := '';
    v_film_order.notes := format('Created from a shortage while trying to allocate %s LF.', v_requested_feet);
    v_film_order.created_at := now();
    v_film_order.created_by := app_api.trim_text(p_actor);
    v_film_order := app_api.save_film_order(v_film_order);
    v_warnings := app_api.push_warning(
      v_warnings,
      format('Film Order %s was created for the remaining %s LF.', v_film_order.film_order_id, v_remaining)
    );
  end if;

  return jsonb_build_object(
    'allocationIds', to_jsonb(v_allocation_ids),
    'filmOrderId', coalesce(v_film_order.film_order_id, ''),
    'remainingUncoveredFeet', greatest(v_remaining, 0),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function public.api_acl_allocations_apply(p_org_id uuid, p_actor text, p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_result jsonb;
  v_allocation_id text;
  v_box_id text;
  v_job_number text := app_api.trim_text(p_payload->>'jobNumber');
  v_install_date text := app_api.trim_text(coalesce(p_payload->>'installDate', p_payload->>'jobDate'));
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');
  v_result := public.api_allocations_apply(p_org_id, p_actor, p_payload);
  v_warnings := coalesce(array(select jsonb_array_elements_text(coalesce(v_result->'warnings', '[]'::jsonb))), array[]::text[]);

  for v_allocation_id in
    select jsonb_array_elements_text(coalesce(v_result->'allocationIds', '[]'::jsonb))
  loop
    select a.box_id
    into v_box_id
    from app.allocations a
    where a.org_id = p_org_id
      and a.allocation_id = v_allocation_id
    limit 1;

    if coalesce(trim(v_box_id), '') <> '' then
      perform app_api.recalculate_physical_box_allocatable_now(p_org_id, v_box_id);
    end if;
  end loop;

  if v_install_date = '' and app_api.trim_text(v_result->>'filmOrderId') <> '' then
    perform app_api.delete_film_order_links_by_film_order_id(p_org_id, app_api.trim_text(v_result->>'filmOrderId'));
    perform app_api.delete_film_order(p_org_id, app_api.trim_text(v_result->>'filmOrderId'));
    v_result := jsonb_set(v_result, '{filmOrderId}', to_jsonb(''::text), true);
    v_warnings := array_append(
      v_warnings,
      'No shortage film order was created because this job does not have an install date yet.'
    );
  end if;

  if v_job_number <> '' then
    perform app_api.reconcile_auto_shortage_film_orders_for_job(
      p_org_id,
      p_actor,
      v_job_number,
      false
    );
  end if;

  v_result := jsonb_set(v_result, '{warnings}', to_jsonb(v_warnings), true);
  return v_result;
end;
$$;

/**
 * PURPOSE:
 * Keep allocation requirement matching resilient to catalog aliases that append trailing code
 * shorthands like "(PR40 Ext)" after the human-readable film label.
 *
 * AFFECTS:
 * /allocations/preview parity with /allocations/apply, requirement-bound allocation validation,
 * extra allocation compatibility checks, and any SQL workflow that derives requirement film
 * families or exterior status from canonicalized film names.
 *
 * WHEN CHANGING THIS, ALSO CHECK:
 * shared/domain/jobPlanningFilmMatcher.mjs, backend/scripts/verify-allocation-film-match-parity.mjs,
 * backend/scripts/verify-ordered-box-allocation-flow.mjs, and backend/scripts/check-schema-latest.mjs.
 *
 * COMMON FAILURE MODES:
 * Preview/apply drift, exterior rolls rejected for base requirements, non-exterior rolls accepted
 * for exterior requirements, or alias-heavy 3M Solar labels resolving to mismatched film families.
 */

create or replace function app_api.strip_requirement_match_trailing_code_alias(
  p_value text
)
returns text
language plpgsql
immutable
as $$
declare
  v_current text := app_api.normalize_collapsed_catalog_label(p_value);
  v_match text[];
  v_base text;
  v_alias text;
  v_alias_compact text;
  v_base_digits text;
begin
  while v_current <> '' loop
    v_match := regexp_match(v_current, '^(.*?)(?:\s*\(([^()]*)\))$');
    if v_match is null then
      return v_current;
    end if;

    v_base := app_api.normalize_collapsed_catalog_label(v_match[1]);
    v_alias := app_api.normalize_collapsed_catalog_label(v_match[2]);
    v_alias_compact := app_api.normalize_requirement_match_compact_lookup_key(v_alias);
    v_base_digits := regexp_replace(v_base, '[^0-9]+', '', 'g');
    v_base_digits := regexp_replace(v_base_digits, '^0+', '');

    if v_base = ''
      or v_alias_compact = ''
      or v_alias_compact !~ '[a-z]'
      or v_alias_compact !~ '[0-9]'
      or v_base_digits = ''
      or position(v_base_digits in v_alias_compact) = 0 then
      return v_current;
    end if;

    v_current := v_base;
  end loop;

  return '';
end;
$$;

create or replace function app_api.normalize_requirement_match_surface_film_name(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns text
language plpgsql
stable
as $$
declare
  v_manufacturer text := app_api.normalize_requirement_match_manufacturer_label(p_manufacturer);
  v_manufacturer_key text := app_api.normalize_requirement_match_manufacturer_lookup_key(p_manufacturer);
  v_film_name text;
  v_night_vision_code text := '';
begin
  v_film_name := app_api.normalize_collapsed_catalog_label(
    app_api.resolve_canonical_film_name(p_org_id, v_manufacturer, p_film_name)
  );

  if v_film_name = '' then
    return '';
  end if;

  v_film_name := app_api.normalize_requirement_match_descriptor_tokens(
    app_api.strip_requirement_match_manufacturer_prefixes(v_manufacturer, v_film_name)
  );

  v_film_name := app_api.normalize_requirement_avery_natura_shade_film_name(
    v_manufacturer,
    v_film_name
  );

  if v_manufacturer_key = app_api.normalize_requirement_match_manufacturer_lookup_key('3M Solar') then
    v_night_vision_code := app_api.infer_requirement_night_vision_code(v_film_name);
    if v_night_vision_code <> '' then
      v_film_name := format('Night Vision %s', v_night_vision_code);
    end if;
  end if;

  v_film_name := app_api.strip_requirement_match_trailing_code_alias(v_film_name);

  return v_film_name;
end;
$$;

create or replace function app_api.normalize_requirement_film_family_name(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns text
language plpgsql
stable
as $$
declare
  v_film_name text := app_api.normalize_requirement_match_surface_film_name(
    p_org_id,
    p_manufacturer,
    p_film_name
  );
begin
  if v_film_name = '' then
    return '';
  end if;

  if v_film_name ~* '(^|[[:space:]])Exterior[[:space:]]*$' then
    v_film_name := coalesce(
      nullif(
        app_api.normalize_collapsed_catalog_label(
          regexp_replace(v_film_name, '[[:space:]]+Exterior[[:space:]]*$', '', 'i')
        ),
        ''
      ),
      v_film_name
    );
  end if;

  return v_film_name;
end;
$$;

create or replace function app_api.requirement_film_is_exterior(
  p_org_id uuid,
  p_manufacturer text,
  p_film_name text
)
returns boolean
language sql
stable
as $$
  select app_api.trim_text(
      app_api.normalize_requirement_match_surface_film_name(
        p_org_id,
        p_manufacturer,
        p_film_name
      )
    ) ~* '(^|[[:space:]])Exterior[[:space:]]*$';
$$;

/**
 * PURPOSE:
 * Keep allocation status rules and ordered-box receipt behavior aligned across the local runtime,
 * Edge/RPC wrappers, and SQL mutation layer.
 *
 * BUSINESS RULE:
 * - TRANSFER boxes are allocatable
 * - ORDERED boxes are allocatable
 * - ZEROED boxes are not allocatable
 *
 * AFFECTS:
 * /allocations/add, /allocations/apply, /boxes/receive, shortage-order side effects during
 * allocation saves, and transfer/zeroed eligibility parity between localhost and Edge/RPC.
 *
 * WHEN CHANGING THIS, ALSO CHECK:
 * backend/src/app/core/helpers.mjs,
 * backend/src/app/services/runtime/runtimeAllocationApply.mjs,
 * backend/src/app/services/runtime/boxes/receiveOrdered.mjs,
 * frontend/src/features/inventory/utils/jobAllocationMatching.ts,
 * backend/scripts/verify-ordered-box-allocation-flow.mjs,
 * and backend/scripts/check-schema-latest.mjs.
 */

create or replace function public.api_allocations_apply(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_source app.boxes;
  v_candidate app.boxes;
  v_job_context jsonb;
  v_requested_feet integer := coalesce(floor(nullif(app_api.trim_text(p_payload->>'requestedFeet'), '')::numeric), 0);
  v_requested_width_in numeric := nullif(app_api.trim_text(p_payload->>'requestedWidthIn'), '')::numeric;
  v_requirement_id_text text := app_api.trim_text(p_payload->>'requirementId');
  v_should_validate_requirement boolean := false;
  v_requirement_id uuid;
  v_requirement app.job_requirements;
  v_source_film_key text;
  v_requirement_is_exterior boolean := false;
  v_remaining integer := 0;
  v_requirement_remaining_feet integer := 0;
  v_source_planning_feet integer := 0;
  v_source_suggested integer := 0;
  v_source_suggested_covered integer := 0;
  v_candidate_planning_feet integer := 0;
  v_candidate_suggested integer := 0;
  v_candidate_suggested_covered integer := 0;
  v_cross_warehouse boolean := coalesce((p_payload->>'crossWarehouse')::boolean, false);
  v_selected_box_ids text[] := coalesce(
    array(select jsonb_array_elements_text(coalesce(p_payload->'selectedSuggestionBoxIds', '[]'::jsonb))),
    array[]::text[]
  );
  v_extra_allocations jsonb := coalesce(p_payload->'extraAllocations', '[]'::jsonb);
  v_extra_entry jsonb;
  v_extra_box_id text;
  v_extra_feet integer;
  v_extra_processed_box_ids text[] := array[]::text[];
  v_allocation app.allocations;
  v_allocation_ids text[] := array[]::text[];
  v_cleanup_order app.film_orders;
  v_cleanup_link_count integer := 0;
  v_cleanup_allocation_count integer := 0;
  v_deleted_shortage_film_order_count integer := 0;
  v_conflict_count integer;
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_org_member(p_org_id);

  if v_requested_feet < 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be zero or greater.');
  end if;

  if coalesce(jsonb_typeof(v_extra_allocations), '') not in ('', 'array') then
    perform app_api.raise_http(400, 'extraAllocations must be an array.');
  end if;

  select *
  into v_source
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if coalesce(v_source.status::text, '') not in ('IN_STOCK', 'ORDERED', 'TRANSFER') then
    perform app_api.raise_http(400, 'Only in-stock, ordered, or transfer boxes can be allocated.');
  end if;

  v_job_context := app_api.resolve_job_context(
    p_org_id,
    p_payload->>'jobNumber',
    p_payload->>'jobDate',
    p_payload->>'crewLeader'
  );

  v_source_film_key := app_api.normalize_requirement_film_key(
    p_org_id,
    v_source.manufacturer,
    v_source.film_name
  );

  v_should_validate_requirement := v_requested_feet > 0 or v_requirement_id_text <> '';

  if v_should_validate_requirement then
    if v_requirement_id_text = '' then
      perform app_api.raise_http(400, 'RequirementId is required for film allocations.');
    end if;

    begin
      v_requirement_id := v_requirement_id_text::uuid;
    exception
      when others then
        perform app_api.raise_http(400, 'RequirementId must be a valid UUID.');
    end;

    select r.*
    into v_requirement
    from app.job_requirements r
    where r.org_id = p_org_id
      and r.job_id = app_api.get_or_resolve_job_id(p_org_id, v_job_context->>'jobNumber')
      and r.id = v_requirement_id;

    if not found then
      perform app_api.raise_http(
        400,
        format('Requirement %s does not belong to job %s.', v_requirement_id, v_job_context->>'jobNumber')
      );
    end if;

    v_requirement_is_exterior := app_api.requirement_film_is_exterior(
      p_org_id,
      v_requirement.manufacturer,
      v_requirement.film_name
    );

    if not app_api.requirement_film_is_compatible(
      p_org_id,
      v_source.manufacturer,
      v_source.film_name,
      v_requirement.manufacturer,
      v_requirement.film_name
    ) then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    if v_source.width_in < v_requirement.width_in then
      perform app_api.raise_http(
        400,
        format('Box %s does not match requirement %s.', v_source.box_id, v_requirement_id)
      );
    end if;

    v_requested_width_in := v_requirement.width_in;
  elsif v_requested_width_in is null or v_requested_width_in <= 0 then
    v_requested_width_in := v_source.width_in;
  end if;

  if v_source.width_in < v_requested_width_in then
    perform app_api.raise_http(400, 'Source box width must meet or exceed the requested width.');
  end if;

  v_remaining := greatest(v_requested_feet, 0);
  v_source_planning_feet := app_api.allocation_planning_feet_for_box(v_source);

  if v_requested_feet > 0 then
    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_source.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count = 0 then
      select
        p.allocated_feet,
        p.covered_feet,
        p.remaining_covered_feet
      into
        v_source_suggested,
        v_source_suggested_covered,
        v_remaining
      from app_api.plan_allocation_coverage(
        v_remaining,
        v_source_planning_feet,
        v_source.width_in,
        v_requested_width_in
      ) p;
    end if;
  end if;

  if v_source_suggested > 0 then
    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_source,
      v_job_context,
      v_source_suggested,
      v_source_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    if coalesce(v_source.status::text, '') in ('IN_STOCK', 'TRANSFER') then
      v_source.feet_available := greatest(v_source.feet_available - v_source_suggested, 0);
      v_source := app_api.save_box(v_source);
    end if;
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end if;

  for v_candidate in
    select *
    from app.boxes b
    where b.org_id = p_org_id
      and b.box_id <> v_source.box_id
      and coalesce(b.status::text, '') in ('IN_STOCK', 'ORDERED', 'TRANSFER')
      and app_api.compute_allocation_planning_feet(
        coalesce(b.status::text, ''),
        b.initial_feet,
        b.feet_available,
        app_api.active_allocated_feet_for_box(p_org_id, b.box_id)
      ) > 0
      and case
        when v_requirement_id is not null then app_api.requirement_film_is_compatible(
          p_org_id,
          b.manufacturer,
          b.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        )
        else app_api.normalize_requirement_film_key(p_org_id, b.manufacturer, b.film_name) = v_source_film_key
      end
      and b.width_in >= v_requested_width_in
      and (v_cross_warehouse or b.warehouse = v_source.warehouse)
    order by
      case
        when coalesce(b.status::text, '') = 'IN_STOCK' then 0
        when coalesce(b.status::text, '') = 'TRANSFER' then 1
        when coalesce(b.status::text, '') = 'ORDERED' then 2
        else 3
      end,
      case
        when b.width_in = v_requested_width_in then 0
        when app_api.allocation_coverage_multiplier(b.width_in, v_requested_width_in) > 1 then 1
        else 2
      end,
      (b.width_in - v_requested_width_in),
      case
        when v_requirement_id is not null
          and not v_requirement_is_exterior
          and app_api.requirement_film_is_exterior(p_org_id, b.manufacturer, b.film_name)
        then 1
        else 0
      end,
      coalesce(b.received_date, b.order_date, '9999-12-31'::date),
      b.box_id
    for update
  loop
    exit when v_remaining <= 0;

    if coalesce(array_length(v_selected_box_ids, 1), 0) > 0 and array_position(v_selected_box_ids, v_candidate.box_id) is null then
      continue;
    end if;

    select count(*)
    into v_conflict_count
    from app.allocations a
    where a.org_id = p_org_id
      and a.box_id = v_candidate.box_id
      and a.status = 'ACTIVE'
      and coalesce(to_char(a.job_date, 'YYYY-MM-DD'), '') = coalesce(v_job_context->>'jobDate', '')
      and upper(a.job_number) <> upper(v_job_context->>'jobNumber')
      and upper(coalesce(a.crew_leader, '')) <> upper(coalesce(v_job_context->>'crewLeader', ''));

    if v_conflict_count > 0 then
      continue;
    end if;

    v_candidate_planning_feet := app_api.allocation_planning_feet_for_box(v_candidate);

    select
      p.allocated_feet,
      p.covered_feet,
      p.remaining_covered_feet
    into
      v_candidate_suggested,
      v_candidate_suggested_covered,
      v_remaining
    from app_api.plan_allocation_coverage(
      v_remaining,
      v_candidate_planning_feet,
      v_candidate.width_in,
      v_requested_width_in
    ) p;

    if v_candidate_suggested <= 0 or v_candidate_suggested_covered <= 0 then
      continue;
    end if;

    v_allocation := app_api.create_allocation_with_coverage(
      p_org_id,
      v_candidate,
      v_job_context,
      v_candidate_suggested,
      v_candidate_suggested_covered,
      p_actor,
      '',
      'REQUIREMENT',
      v_requirement_id
    );
    if coalesce(v_candidate.status::text, '') in ('IN_STOCK', 'TRANSFER') then
      v_candidate.feet_available := greatest(v_candidate.feet_available - v_allocation.allocated_feet, 0);
      perform app_api.save_box(v_candidate);
    end if;
    v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
  end loop;

  if coalesce(jsonb_typeof(v_extra_allocations), '') = 'array' then
    for v_extra_entry in
      select value
      from jsonb_array_elements(v_extra_allocations)
    loop
      if coalesce(jsonb_typeof(v_extra_entry), '') <> 'object' then
        perform app_api.raise_http(400, 'Each extra allocation entry must be an object.');
      end if;

      v_extra_box_id := app_api.require_text(v_extra_entry->>'boxId', 'extraAllocations[].boxId');
      v_extra_feet := floor(nullif(app_api.trim_text(v_extra_entry->>'allocatedFeet'), '')::numeric);

      if v_extra_feet is null or v_extra_feet <= 0 then
        perform app_api.raise_http(400, format('Extra allocation for box %s must be greater than zero.', v_extra_box_id));
      end if;

      if array_position(v_extra_processed_box_ids, v_extra_box_id) is not null then
        perform app_api.raise_http(400, format('Duplicate extra allocation entry for box %s.', v_extra_box_id));
      end if;

      select *
      into v_candidate
      from app.boxes b
      where b.org_id = p_org_id
        and b.box_id = v_extra_box_id
      for update;

      if not found then
        perform app_api.raise_http(404, format('Box not found: %s', v_extra_box_id));
      end if;

      if coalesce(v_candidate.status::text, '') not in ('IN_STOCK', 'ORDERED', 'TRANSFER') then
        perform app_api.raise_http(400, format('Box %s is no longer allocatable.', v_candidate.box_id));
      end if;

      if v_requirement_id is not null then
        if not app_api.requirement_film_is_compatible(
          p_org_id,
          v_candidate.manufacturer,
          v_candidate.film_name,
          v_requirement.manufacturer,
          v_requirement.film_name
        ) or v_candidate.width_in < v_requested_width_in then
          perform app_api.raise_http(
            400,
            format(
              'Extra box %s must use a compatible film and meet the requested width for this allocation.',
              v_candidate.box_id
            )
          );
        end if;
      elsif app_api.normalize_requirement_film_key(p_org_id, v_candidate.manufacturer, v_candidate.film_name) <> v_source_film_key
        or v_candidate.width_in < v_requested_width_in then
        perform app_api.raise_http(
          400,
          format(
            'Extra box %s must match film and meet the requested width for this allocation.',
            v_candidate.box_id
          )
        );
      end if;

      v_candidate_planning_feet := app_api.allocation_planning_feet_for_box(v_candidate);
      if v_candidate_planning_feet < v_extra_feet then
        perform app_api.raise_http(400, format('Box %s no longer has enough planning LF.', v_candidate.box_id));
      end if;

      v_allocation := app_api.create_allocation(
        p_org_id,
        v_candidate,
        v_job_context,
        v_extra_feet,
        p_actor,
        '',
        'EXTRA',
        null
      );
      if coalesce(v_candidate.status::text, '') in ('IN_STOCK', 'TRANSFER') then
        v_candidate.feet_available := greatest(v_candidate.feet_available - v_extra_feet, 0);
        perform app_api.save_box(v_candidate);
      end if;
      v_allocation_ids := array_append(v_allocation_ids, v_allocation.allocation_id);
      v_extra_processed_box_ids := array_append(v_extra_processed_box_ids, v_extra_box_id);
    end loop;
  end if;

  if v_requested_feet = 0 and coalesce(array_length(v_extra_processed_box_ids, 1), 0) = 0 then
    perform app_api.raise_http(400, 'RequestedFeet must be greater than zero unless extraAllocations are provided.');
  end if;

  if v_requirement_id is not null and v_requested_feet > 0 then
    select greatest(
      coalesce(v_requirement.required_feet, 0) - least(
        coalesce(v_requirement.required_feet, 0),
        coalesce(sum(
          case
            when coalesce(a.covered_feet, 0) > 0 then a.covered_feet
            else a.allocated_feet
          end
        ), 0)
      ),
      0
    )::integer
    into v_requirement_remaining_feet
    from app.allocations a
    join app.boxes b
      on b.org_id = a.org_id
     and upper(b.box_id) = upper(a.box_id)
    where a.org_id = p_org_id
      and a.requirement_id = v_requirement_id
      and a.status <> 'CANCELLED'
      and coalesce(a.allocation_kind::text, 'REQUIREMENT') <> 'EXTRA'
      and not (
        a.status = 'ACTIVE'
        and coalesce(b.status::text, '') in ('ZEROED', 'RETIRED')
      )
      and app_api.requirement_film_is_compatible(
        p_org_id,
        b.manufacturer,
        b.film_name,
        v_requirement.manufacturer,
        v_requirement.film_name
      )
      and coalesce(b.width_in, 0) >= coalesce(v_requirement.width_in, 0);

    if v_requirement_remaining_feet <= 0 then
      for v_cleanup_order in
        select fo.*
        from app.film_orders fo
        where fo.org_id = p_org_id
          and upper(trim(fo.job_number)) = upper(trim(v_job_context->>'jobNumber'))
          and coalesce(fo.status::text, '') in ('FILM_ORDER', 'FILM_ON_THE_WAY')
          and coalesce(trim(fo.source_box_id), '') <> ''
          and app_api.normalize_job_requirement_lookup_key(
            fo.manufacturer,
            fo.film_name,
            fo.width_in
          ) = app_api.normalize_job_requirement_lookup_key(
            v_requirement.manufacturer,
            v_requirement.film_name,
            v_requirement.width_in
          )
      loop
        select count(*)
        into v_cleanup_link_count
        from app.film_order_box_links l
        where l.org_id = p_org_id
          and l.film_order_id = v_cleanup_order.film_order_id;

        if v_cleanup_link_count > 0 then
          continue;
        end if;

        select count(*)
        into v_cleanup_allocation_count
        from app.allocations a
        where a.org_id = p_org_id
          and a.film_order_id = v_cleanup_order.film_order_id;

        if v_cleanup_allocation_count > 0 then
          continue;
        end if;

        perform app_api.delete_film_order_links_by_film_order_id(p_org_id, v_cleanup_order.film_order_id);
        perform app_api.delete_film_order(p_org_id, v_cleanup_order.film_order_id);
        v_deleted_shortage_film_order_count := v_deleted_shortage_film_order_count + 1;
      end loop;
    end if;

    if v_deleted_shortage_film_order_count > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Removed %s stale shortage film order%s for job %s after fulfilling the selected requirement.',
          v_deleted_shortage_film_order_count,
          case when v_deleted_shortage_film_order_count = 1 then '' else 's' end,
          v_job_context->>'jobNumber'
        )
      );
    end if;
  end if;

  return jsonb_build_object(
    'allocationIds', to_jsonb(v_allocation_ids),
    'filmOrderId', ''::text,
    'remainingUncoveredFeet', greatest(v_remaining, 0),
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

-- Restore post-save linked film-order recalculation for receipt flows.
--
-- The original 0077 implementation relied on exact text replacement inside
-- existing function bodies. Production now shows that those functions are
-- semantically correct for 0076 but not text-identical to the snippet this
-- migration expected, so the pending migration must replace the functions
-- directly instead of mutating them by pattern.

create or replace function public.api_boxes_add(p_org_id uuid, p_actor text, p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_build jsonb;
  v_box app.boxes;
  v_public_box jsonb;
  v_log_id text;
  v_film_order_id text := app_api.trim_text(p_payload->>'filmOrderId');
  v_link app.film_order_box_links;
  v_order app.film_orders;
  v_receipt_result jsonb;
  v_warnings text[] := array[]::text[];
  v_requested_warehouse text := app_api.trim_text(p_payload->>'warehouse');
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if found then
    perform app_api.raise_http(400, 'A box with this BoxID already exists.');
  end if;

  if v_requested_warehouse <> '' then
    v_requested_warehouse := app_api.require_org_warehouse(p_org_id, v_requested_warehouse, 'Warehouse');
  end if;

  v_build := app_api.build_box_from_payload(p_org_id, p_payload, null);
  v_box := jsonb_populate_record(null::app.boxes, v_build->'box');
  v_box.dealer := app_api.trim_text(p_payload->>'dealer');
  v_warnings := coalesce(array(select jsonb_array_elements_text(v_build->'warnings')), array[]::text[]);

  if v_requested_warehouse <> '' and v_box.warehouse <> v_requested_warehouse then
    perform app_api.raise_http(
      400,
      format(
        'BoxID %s resolves to warehouse %s, not %s. Update the BoxID prefix or warehouse selection.',
        v_box.box_id,
        v_box.warehouse,
        v_requested_warehouse
      )
    );
  end if;

  v_box := app_api.save_box(v_box);

  if v_film_order_id <> '' then
    select *
    into v_order
    from app.film_orders f
    where f.org_id = p_org_id
      and f.film_order_id = v_film_order_id
    for update;

    if not found then
      perform app_api.raise_http(404, 'Film Order not found.');
    end if;

    if v_order.status = 'CANCELLED' then
      perform app_api.raise_http(400, 'Cancelled Film Orders cannot receive new boxes.');
    end if;

    v_link.id := gen_random_uuid();
    v_link.org_id := p_org_id;
    v_link.link_id := app_api.create_log_id();
    v_link.film_order_id := v_order.film_order_id;
    v_link.box_id := v_box.box_id;
    v_link.ordered_feet := v_box.initial_feet;
    v_link.auto_allocated_feet := 0;
    v_link.created_at := now();
    v_link.created_by := app_api.trim_text(p_actor);
    perform app_api.save_film_order_link(v_link);
    perform app_api.recalculate_film_order(p_org_id, v_order.film_order_id, p_actor);
    v_warnings := app_api.push_warning(
      v_warnings,
      format('Box %s was linked to Film Order %s for job %s.', v_box.box_id, v_order.film_order_id, v_order.job_number)
    );

    if v_box.received_date is not null and v_box.status = 'IN_STOCK' then
      v_receipt_result := app_api.process_linked_box_receipt(p_org_id, v_box, p_actor);
      v_box := jsonb_populate_record(null::app.boxes, v_receipt_result->'box');
      v_box := app_api.save_box(v_box);
      perform app_api.recalculate_film_orders_for_box_links(p_org_id, v_box.box_id, p_actor);
      v_warnings := array_cat(
        v_warnings,
        coalesce(array(select jsonb_array_elements_text(v_receipt_result->'warnings')), array[]::text[])
      );
    end if;
  end if;

  v_public_box := app_api.public_box_json(v_box);
  v_log_id := app_api.append_audit_entry(
    p_org_id,
    'ADD_BOX',
    v_box.box_id,
    null,
    v_public_box,
    p_actor,
    app_api.trim_text(p_payload->>'auditNote')
  );

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function public.api_boxes_update(p_org_id uuid, p_actor text, p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_existing app.boxes;
  v_build jsonb;
  v_box app.boxes;
  v_public_before jsonb;
  v_public_after jsonb;
  v_receipt_result jsonb;
  v_log_id text;
  v_warnings text[] := array[]::text[];
  v_move_to_zeroed boolean := coalesce((p_payload->>'moveToZeroed')::boolean, false);
  v_reactivate_from_zeroed boolean := coalesce((p_payload->>'reactivateFromZeroed')::boolean, false);
  v_has_submitted_current_feet_on_roll boolean := coalesce(p_payload, '{}'::jsonb) ? 'currentFeetOnRoll';
  v_current_feet_on_roll_input integer;
  v_requested_feet_available integer;
  v_confirmed_zero_feet_move boolean := false;
  v_confirmed_zero_weight_move boolean := false;
  v_confirmed_incomplete_history_move boolean := false;
  v_has_positive_reactivation_signal boolean := false;
  v_should_reactivate boolean := false;
  v_audit_action text := 'UPDATE_BOX';
begin
  perform app_api.require_org_member(p_org_id);

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = app_api.require_text(p_payload->>'boxId', 'BoxID')
  for update;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  v_build := app_api.build_box_from_payload(p_org_id, p_payload, v_existing.box_id);
  v_box := jsonb_populate_record(null::app.boxes, v_build->'box');
  v_box.dealer := case
    when coalesce(p_payload, '{}'::jsonb) ? 'dealer' then app_api.trim_text(p_payload->>'dealer')
    else coalesce(v_existing.dealer, '')
  end;
  v_warnings := coalesce(array(select jsonb_array_elements_text(v_build->'warnings')), array[]::text[]);

  if v_has_submitted_current_feet_on_roll and app_api.trim_text(p_payload->>'currentFeetOnRoll') <> '' then
    v_current_feet_on_roll_input := floor((app_api.trim_text(p_payload->>'currentFeetOnRoll'))::numeric);
  else
    v_current_feet_on_roll_input := null;
  end if;

  v_requested_feet_available := case
    when app_api.trim_text(p_payload->>'feetAvailable') = '' then null
    else floor((app_api.trim_text(p_payload->>'feetAvailable'))::numeric)
  end;

  if v_existing.status = 'ZEROED' then
    v_has_positive_reactivation_signal :=
      coalesce(v_box.feet_available, 0) > 0
      or coalesce(v_box.last_roll_weight_lbs, 0) > 0;

    if v_has_positive_reactivation_signal and not v_reactivate_from_zeroed then
      perform app_api.raise_http(
        400,
        'Zeroed boxes with new active inventory values must be confirmed before moving back to IN_STOCK.'
      );
    end if;

    v_should_reactivate := v_has_positive_reactivation_signal and v_reactivate_from_zeroed;

    if v_should_reactivate then
      v_box.status := 'IN_STOCK';
      v_box.zeroed_date := null;
      v_box.zeroed_reason := '';
      v_box.zeroed_by := '';
      v_warnings := app_api.push_warning(
        v_warnings,
        format('Box %s was moved back to active IN_STOCK inventory.', v_box.box_id)
      );
      v_audit_action := 'SET_STATUS';
    else
      v_box.status := 'ZEROED';
      v_box.zeroed_date := v_existing.zeroed_date;
      v_box.zeroed_reason := coalesce(v_existing.zeroed_reason, '');
      v_box.zeroed_by := coalesce(v_existing.zeroed_by, '');
    end if;

    v_box := app_api.save_box(v_box);
    v_public_before := app_api.public_box_json(v_existing);
    v_public_after := app_api.public_box_json(v_box);
    v_log_id := app_api.append_audit_entry(
      p_org_id,
      v_audit_action,
      v_box.box_id,
      v_public_before,
      v_public_after,
      p_actor,
      app_api.trim_text(p_payload->>'auditNote')
    );

    return jsonb_build_object(
      'boxId', v_box.box_id,
      'logId', v_log_id,
      'warnings', to_jsonb(v_warnings)
    );
  end if;

  v_confirmed_zero_feet_move :=
    v_move_to_zeroed
    and v_existing.received_date is not null
    and app_api.has_positive_physical_feet(v_existing)
    and (
      (
        v_has_submitted_current_feet_on_roll
        and v_current_feet_on_roll_input is not null
        and v_current_feet_on_roll_input <= 0
      )
      or (
        not v_has_submitted_current_feet_on_roll
        and v_requested_feet_available is not null
        and v_requested_feet_available <= 0
      )
    );

  if v_confirmed_zero_feet_move then
    v_box.feet_available := 0;
  end if;

  v_confirmed_zero_weight_move :=
    v_move_to_zeroed
    and v_existing.received_date is not null
    and app_api.has_positive_physical_feet(v_existing)
    and coalesce(v_box.last_roll_weight_lbs, 0) = 0;

  v_confirmed_incomplete_history_move :=
    v_move_to_zeroed
    and coalesce(v_box.last_roll_weight_lbs, 0) = 0
    and (
      v_existing.received_date is null
      or v_existing.initial_weight_lbs is null
      or v_existing.core_weight_lbs is null
      or v_existing.last_weighed_date is null
      or v_box.received_date is null
      or v_box.initial_weight_lbs is null
      or v_box.core_weight_lbs is null
      or v_box.last_weighed_date is null
    );

  if v_move_to_zeroed and not (
    v_confirmed_incomplete_history_move
    or v_confirmed_zero_feet_move
    or v_confirmed_zero_weight_move
  ) then
    perform app_api.raise_http(
      400,
      'Received boxes move to zeroed out inventory only after they have had Available Feet above 0 and then reach 0 Available Feet or 0 Last Roll Weight.'
    );
  end if;

  if v_confirmed_incomplete_history_move or v_confirmed_zero_feet_move or v_confirmed_zero_weight_move then
    v_box.status := 'ZEROED';
    v_box.feet_available := 0;
    v_box.zeroed_date := app_api.today_date();
    v_box.zeroed_reason := app_api.determine_zeroed_reason(v_box.feet_available, v_box.last_roll_weight_lbs);
    v_box.zeroed_by := app_api.trim_text(p_actor);
    if app_api.trim_text(p_payload->>'auditNote') <> '' then
      v_box.zeroed_reason := v_box.zeroed_reason || ' Additional note: ' || app_api.normalize_meaningful_zeroed_note(p_payload->>'auditNote');
    end if;
    perform app_api.cancel_active_allocations_for_box(
      p_org_id,
      v_box.box_id,
      p_actor,
      'Auto-cancelled because the box was moved to zeroed out inventory.'
    );
    if v_confirmed_incomplete_history_move then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was moved to zeroed out inventory after confirming a 0 Last Roll Weight save on a box with incomplete history.'
      );
    elsif v_confirmed_zero_feet_move then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was moved to zeroed out inventory after confirming a Current Linear Feet value of 0 on a received box with recorded physical feet.'
      );
    elsif v_confirmed_zero_weight_move then
      v_warnings := app_api.push_warning(
        v_warnings,
        'Box was moved to zeroed out inventory after confirming a Last Roll Weight value of 0 on a received box with recorded physical feet.'
      );
    end if;
    v_audit_action := 'ZERO_OUT_BOX';
  else
    v_receipt_result := app_api.process_linked_box_receipt(p_org_id, v_box, p_actor);
    v_box := jsonb_populate_record(null::app.boxes, v_receipt_result->'box');
    v_box.dealer := case
      when coalesce(p_payload, '{}'::jsonb) ? 'dealer' then app_api.trim_text(p_payload->>'dealer')
      else coalesce(v_existing.dealer, '')
    end;
    v_warnings := array_cat(
      v_warnings,
      coalesce(array(select jsonb_array_elements_text(v_receipt_result->'warnings')), array[]::text[])
    );
  end if;

  v_box := app_api.save_box(v_box);
  if v_box.status <> 'CHECKED_OUT' then
    perform app_api.recalculate_film_orders_for_box_links(p_org_id, v_box.box_id, p_actor);
  end if;
  v_public_before := app_api.public_box_json(v_existing);
  v_public_after := app_api.public_box_json(v_box);
  v_log_id := app_api.append_audit_entry(
    p_org_id,
    v_audit_action,
    v_box.box_id,
    v_public_before,
    v_public_after,
    p_actor,
    app_api.trim_text(p_payload->>'auditNote')
  );

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

create or replace function public.api_acl_boxes_receive_ordered(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_lookup_box_id text;
  v_existing app.boxes;
  v_box app.boxes;
  v_received_weight_text text := app_api.trim_text(v_payload->>'receivedWeightLbs');
  v_received_weight_lbs numeric := null;
  v_lot_run text := app_api.trim_text(v_payload->>'lotRun');
  v_locked_allocated_feet integer := 0;
  v_receipt_result jsonb := '{}'::jsonb;
  v_reconcile_result jsonb := '{}'::jsonb;
  v_warnings text[] := array[]::text[];
  v_log_id text := '';
  v_audit_note text;
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'write');
  v_lookup_box_id := app_api.resolve_box_id_alias(
    p_org_id,
    app_api.require_text(v_payload->>'boxId', 'BoxID')
  );

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = v_lookup_box_id
  limit 1;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if upper(coalesce(v_existing.status::text, '')) = 'TRANSFER' then
    perform app_api.raise_http(
      400,
      format(
        'Box %s has a pending transfer and can only be received or have the transfer cancelled.',
        v_lookup_box_id
      )
    );
  end if;

  if upper(coalesce(v_existing.status::text, '')) = 'ZEROED' then
    perform app_api.raise_http(400, 'Zeroed boxes cannot be received as ordered inventory.');
  end if;

  if upper(coalesce(v_existing.status::text, '')) = 'RETIRED' then
    perform app_api.raise_http(400, 'Retired boxes cannot be received as ordered inventory.');
  end if;

  if upper(coalesce(v_existing.status::text, '')) <> 'ORDERED' then
    perform app_api.raise_http(
      400,
      format(
        'Only boxes currently in ORDERED status can be received. %s is %s.',
        v_lookup_box_id,
        coalesce(v_existing.status::text, 'UNKNOWN')
      )
    );
  end if;

  if v_existing.received_date is not null then
    perform app_api.raise_http(
      400,
      format('Box %s already has a received date and cannot be received again.', v_lookup_box_id)
    );
  end if;

  if v_received_weight_text <> '' then
    begin
      v_received_weight_lbs := round((v_received_weight_text)::numeric, 2);
    exception
      when invalid_text_representation then
        perform app_api.raise_http(400, 'ReceivedWeightLbs must be a valid non-negative number.');
    end;

    if v_received_weight_lbs < 0 then
      perform app_api.raise_http(400, 'ReceivedWeightLbs must be a valid non-negative number.');
    end if;
  end if;

  if v_lot_run = '' then
    v_lot_run := coalesce(v_existing.lot_run, '');
  end if;

  v_locked_allocated_feet := app_api.locked_allocated_feet_for_box(p_org_id, v_lookup_box_id);
  v_box := v_existing;
  v_box.status := 'IN_STOCK';
  v_box.received_date := current_date;
  v_box.feet_available := greatest(coalesce(v_existing.initial_feet, 0) - coalesce(v_locked_allocated_feet, 0), 0);
  v_box.lot_run := v_lot_run;

  if v_received_weight_lbs is not null then
    v_box.initial_weight_lbs := v_received_weight_lbs;
    v_box.last_roll_weight_lbs := v_received_weight_lbs;
    v_box.last_weighed_date := current_date;
  end if;

  v_receipt_result := app_api.process_linked_box_receipt(p_org_id, v_box, p_actor);
  if coalesce(v_receipt_result, '{}'::jsonb) ? 'box' then
    v_box := jsonb_populate_record(null::app.boxes, v_receipt_result->'box');
  end if;
  if jsonb_typeof(coalesce(v_receipt_result->'warnings', '[]'::jsonb)) = 'array' then
    v_warnings := v_warnings || array(
      select jsonb_array_elements_text(coalesce(v_receipt_result->'warnings', '[]'::jsonb))
    );
  end if;

  v_box := app_api.save_box(v_box);
  perform app_api.recalculate_film_orders_for_box_links(p_org_id, v_box.box_id, p_actor);

  v_audit_note := format('Received ordered box %s', v_lookup_box_id);
  if v_received_weight_lbs is not null then
    v_audit_note := format(
      '%s at %s lbs',
      v_audit_note,
      trim(trailing '.' from trim(trailing '0' from v_received_weight_lbs::text))
    );
  end if;
  if v_lot_run <> '' then
    v_audit_note := format('%s with lot run %s', v_audit_note, v_lot_run);
  end if;

  v_log_id := app_api.append_audit_entry(
    p_org_id,
    'SET_STATUS',
    v_box.box_id,
    app_api.public_box_json(v_existing),
    app_api.public_box_json(v_box),
    p_actor,
    v_audit_note
  );

  if upper(coalesce(v_box.status::text, '')) in ('IN_STOCK', 'TRANSFER') then
    perform app_api.recalculate_physical_box_allocatable_now(p_org_id, v_lookup_box_id);
    v_reconcile_result := app_api.reconcile_auto_shortage_film_orders_for_box(
      p_org_id,
      p_actor,
      v_lookup_box_id,
      true
    );

    if coalesce((v_reconcile_result->>'createdCount')::integer, 0) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Created %s shortage film order%s after receiving the ordered box.',
          (v_reconcile_result->>'createdCount')::integer,
          case when coalesce((v_reconcile_result->>'createdCount')::integer, 0) = 1 then '' else 's' end
        )
      );
    end if;

    if coalesce((v_reconcile_result->>'deletedCount')::integer, 0) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Removed %s stale shortage film order%s after receiving the ordered box.',
          (v_reconcile_result->>'deletedCount')::integer,
          case when coalesce((v_reconcile_result->>'deletedCount')::integer, 0) = 1 then '' else 's' end
        )
      );
    end if;
  end if;

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;

do $$
declare
  v_candidate record;
  v_actor text := 'migration: restore linked receipt post-save recalc';
begin
  for v_candidate in
    select distinct fo.org_id, fo.film_order_id
    from app.film_orders fo
    join app.film_order_box_links l
      on l.org_id = fo.org_id
     and l.film_order_id = fo.film_order_id
    where fo.status <> 'CANCELLED'
  loop
    perform app_api.recalculate_film_order(
      v_candidate.org_id,
      v_candidate.film_order_id,
      v_actor
    );
  end loop;
end;
$$;

create or replace function app_api.compute_allocation_planning_feet(
  p_status text,
  p_initial_feet integer,
  p_feet_available integer,
  p_active_allocated_feet integer
)
returns integer
language sql
immutable
as $$
  select
    case upper(coalesce(app_api.trim_text(p_status), ''))
      when 'IN_STOCK' then greatest(coalesce(p_feet_available, 0), 0)
      when 'TRANSFER' then greatest(coalesce(p_feet_available, 0), 0)
      when 'ORDERED' then greatest(coalesce(p_initial_feet, 0) - coalesce(p_active_allocated_feet, 0), 0)
      else 0
    end;
$$;

create or replace function public.api_acl_allocations_apply(p_org_id uuid, p_actor text, p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_result jsonb;
  v_allocation_id text;
  v_box_id text;
  v_warnings text[] := array[]::text[];
begin
  perform app_api.require_effective_feature_access(p_org_id, 'allocations', 'write');
  v_result := public.api_allocations_apply(p_org_id, p_actor, p_payload);
  v_warnings := coalesce(array(select jsonb_array_elements_text(coalesce(v_result->'warnings', '[]'::jsonb))), array[]::text[]);

  for v_allocation_id in
    select jsonb_array_elements_text(coalesce(v_result->'allocationIds', '[]'::jsonb))
  loop
    select a.box_id
    into v_box_id
    from app.allocations a
    where a.org_id = p_org_id
      and a.allocation_id = v_allocation_id
    limit 1;

    if coalesce(trim(v_box_id), '') <> '' then
      perform app_api.recalculate_physical_box_allocatable_now(p_org_id, v_box_id);
    end if;
  end loop;

  v_result := jsonb_set(v_result, '{warnings}', to_jsonb(v_warnings), true);
  return v_result;
end;
$$;

create or replace function public.api_acl_boxes_update(p_org_id uuid, p_actor text, p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_lookup_box_id text;
  v_existing_status text := '';
  v_result jsonb;
  v_box app.boxes;
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'write');
  v_lookup_box_id := app_api.resolve_box_id_alias(
    p_org_id,
    app_api.require_text(v_payload->>'boxId', 'BoxID')
  );

  select upper(btrim(b.status::text))
  into v_existing_status
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = v_lookup_box_id;

  if v_existing_status = 'TRANSFER' then
    perform app_api.raise_http(
      400,
      format(
        'Box %s has a pending transfer and can only be received or have the transfer cancelled.',
        v_lookup_box_id
      )
    );
  end if;

  v_payload := jsonb_set(v_payload, '{boxId}', to_jsonb(v_lookup_box_id), true);
  v_result := public.api_boxes_update(p_org_id, p_actor, v_payload);

  select *
  into v_box
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = v_lookup_box_id
  limit 1;

  if found and upper(coalesce(v_box.status::text, '')) in ('IN_STOCK', 'TRANSFER') then
    perform app_api.recalculate_physical_box_allocatable_now(p_org_id, v_lookup_box_id);
    perform app_api.reconcile_auto_shortage_film_orders_for_box(
      p_org_id,
      p_actor,
      v_lookup_box_id,
      true
    );
  end if;

  return v_result;
end;
$$;

create or replace function public.api_acl_boxes_set_status(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_lookup_box_id text;
  v_existing_status text := '';
  v_result jsonb;
  v_box app.boxes;
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'write');
  v_lookup_box_id := app_api.resolve_box_id_alias(
    p_org_id,
    app_api.require_text(v_payload->>'boxId', 'BoxID')
  );

  select upper(btrim(b.status::text))
  into v_existing_status
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = v_lookup_box_id;

  if v_existing_status = 'TRANSFER' then
    perform app_api.raise_http(
      400,
      format(
        'Box %s has a pending transfer and can only be received or have the transfer cancelled.',
        v_lookup_box_id
      )
    );
  end if;

  v_payload := jsonb_set(v_payload, '{boxId}', to_jsonb(v_lookup_box_id), true);
  v_result := public.api_boxes_set_status(p_org_id, p_actor, v_payload);

  select *
  into v_box
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = v_lookup_box_id
  limit 1;

  if found and upper(coalesce(v_box.status::text, '')) in ('IN_STOCK', 'TRANSFER') then
    perform app_api.recalculate_physical_box_allocatable_now(p_org_id, v_lookup_box_id);
    perform app_api.reconcile_auto_shortage_film_orders_for_box(
      p_org_id,
      p_actor,
      v_lookup_box_id,
      true
    );
  end if;

  return v_result;
end;
$$;

create or replace function public.api_acl_boxes_receive_ordered(
  p_org_id uuid,
  p_actor text,
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, app, app_api
as $$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_lookup_box_id text;
  v_existing app.boxes;
  v_box app.boxes;
  v_received_weight_text text := app_api.trim_text(v_payload->>'receivedWeightLbs');
  v_received_weight_lbs numeric := null;
  v_lot_run text := app_api.trim_text(v_payload->>'lotRun');
  v_locked_allocated_feet integer := 0;
  v_receipt_result jsonb := '{}'::jsonb;
  v_reconcile_result jsonb := '{}'::jsonb;
  v_warnings text[] := array[]::text[];
  v_log_id text := '';
  v_audit_note text;
begin
  perform app_api.require_effective_feature_access(p_org_id, 'inventory', 'write');
  v_lookup_box_id := app_api.resolve_box_id_alias(
    p_org_id,
    app_api.require_text(v_payload->>'boxId', 'BoxID')
  );

  select *
  into v_existing
  from app.boxes b
  where b.org_id = p_org_id
    and b.box_id = v_lookup_box_id
  limit 1;

  if not found then
    perform app_api.raise_http(404, 'Box not found.');
  end if;

  if upper(coalesce(v_existing.status::text, '')) = 'TRANSFER' then
    perform app_api.raise_http(
      400,
      format(
        'Box %s has a pending transfer and can only be received or have the transfer cancelled.',
        v_lookup_box_id
      )
    );
  end if;

  if upper(coalesce(v_existing.status::text, '')) = 'ZEROED' then
    perform app_api.raise_http(400, 'Zeroed boxes cannot be received as ordered inventory.');
  end if;

  if upper(coalesce(v_existing.status::text, '')) = 'RETIRED' then
    perform app_api.raise_http(400, 'Retired boxes cannot be received as ordered inventory.');
  end if;

  if upper(coalesce(v_existing.status::text, '')) <> 'ORDERED' then
    perform app_api.raise_http(
      400,
      format(
        'Only boxes currently in ORDERED status can be received. %s is %s.',
        v_lookup_box_id,
        coalesce(v_existing.status::text, 'UNKNOWN')
      )
    );
  end if;

  if v_existing.received_date is not null then
    perform app_api.raise_http(
      400,
      format('Box %s already has a received date and cannot be received again.', v_lookup_box_id)
    );
  end if;

  if v_received_weight_text <> '' then
    begin
      v_received_weight_lbs := round((v_received_weight_text)::numeric, 2);
    exception
      when invalid_text_representation then
        perform app_api.raise_http(400, 'ReceivedWeightLbs must be a valid non-negative number.');
    end;

    if v_received_weight_lbs < 0 then
      perform app_api.raise_http(400, 'ReceivedWeightLbs must be a valid non-negative number.');
    end if;
  end if;

  if v_lot_run = '' then
    v_lot_run := coalesce(v_existing.lot_run, '');
  end if;

  v_locked_allocated_feet := app_api.locked_allocated_feet_for_box(p_org_id, v_lookup_box_id);
  v_box := v_existing;
  v_box.status := 'IN_STOCK';
  v_box.received_date := current_date;
  v_box.feet_available := greatest(coalesce(v_existing.initial_feet, 0) - coalesce(v_locked_allocated_feet, 0), 0);
  v_box.lot_run := v_lot_run;

  if v_received_weight_lbs is not null then
    v_box.initial_weight_lbs := v_received_weight_lbs;
    v_box.last_roll_weight_lbs := v_received_weight_lbs;
    v_box.last_weighed_date := current_date;
  end if;

  v_receipt_result := app_api.process_linked_box_receipt(p_org_id, v_box, p_actor);
  if coalesce(v_receipt_result, '{}'::jsonb) ? 'box' then
    v_box := jsonb_populate_record(null::app.boxes, v_receipt_result->'box');
  end if;
  if jsonb_typeof(coalesce(v_receipt_result->'warnings', '[]'::jsonb)) = 'array' then
    v_warnings := v_warnings || array(
      select jsonb_array_elements_text(coalesce(v_receipt_result->'warnings', '[]'::jsonb))
    );
  end if;

  v_box := app_api.save_box(v_box);

  v_audit_note := format('Received ordered box %s', v_lookup_box_id);
  if v_received_weight_lbs is not null then
    v_audit_note := format(
      '%s at %s lbs',
      v_audit_note,
      trim(trailing '.' from trim(trailing '0' from v_received_weight_lbs::text))
    );
  end if;
  if v_lot_run <> '' then
    v_audit_note := format('%s with lot run %s', v_audit_note, v_lot_run);
  end if;

  v_log_id := app_api.append_audit_entry(
    p_org_id,
    'SET_STATUS',
    v_box.box_id,
    app_api.public_box_json(v_existing),
    app_api.public_box_json(v_box),
    p_actor,
    v_audit_note
  );

  if upper(coalesce(v_box.status::text, '')) in ('IN_STOCK', 'TRANSFER') then
    perform app_api.recalculate_physical_box_allocatable_now(p_org_id, v_lookup_box_id);
    v_reconcile_result := app_api.reconcile_auto_shortage_film_orders_for_box(
      p_org_id,
      p_actor,
      v_lookup_box_id,
      true
    );

    if coalesce((v_reconcile_result->>'createdCount')::integer, 0) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Created %s shortage film order%s after receiving the ordered box.',
          (v_reconcile_result->>'createdCount')::integer,
          case when coalesce((v_reconcile_result->>'createdCount')::integer, 0) = 1 then '' else 's' end
        )
      );
    end if;

    if coalesce((v_reconcile_result->>'deletedCount')::integer, 0) > 0 then
      v_warnings := app_api.push_warning(
        v_warnings,
        format(
          'Removed %s stale shortage film order%s after receiving the ordered box.',
          (v_reconcile_result->>'deletedCount')::integer,
          case when coalesce((v_reconcile_result->>'deletedCount')::integer, 0) = 1 then '' else 's' end
        )
      );
    end if;
  end if;

  return jsonb_build_object(
    'boxId', v_box.box_id,
    'logId', v_log_id,
    'warnings', to_jsonb(v_warnings)
  );
end;
$$;
